# ── Curler-specific helpers ─────────────────────────────────────

def _cb_subtype_family(type_field: str) -> str:
    """Classify Τύπος συσκευής into one of three families used by the
    subtype-bias in the MULTISTYLERS slot:
       'BRUSH'     — Ηλεκτρική Βούρτσα (hot-air brush / volumizer)
       'CURL'      — Συσκευή για μπούκλες / Ψαλίδι / Πρέσα / wand
       'MULTI'     — combo devices (the semicolon-joined types)
       ''          — unrecognised / missing
    Returns the family code; callers compare trigger family vs pool family
    for the multistyler boost.
    """
    if not type_field or pd.isna(type_field):
        return ''
    t = str(type_field).strip().lower()
    if not t or t == '—':
        return ''

    has_brush = 'βούρτσ' in t  # Ηλεκτρική Βούρτσα / Ηλεκτρική βούρτσα
    has_curl = ('μπούκλ' in t or 'ψαλίδι' in t or 'ψαλλίδι' in t
                or 'κυματιστ' in t or 'πρέσα' in t or 'wand' in t)
    has_multi = 'multistyler' in t or 'πολυ' in t

    # Combo (semicolon) → MULTI
    if has_brush and has_curl:
        return 'MULTI'
    if has_multi:
        return 'MULTI'
    if has_brush:
        return 'BRUSH'
    if has_curl:
        return 'CURL'
    return ''


def _cb_title_subtype_family(title: str) -> str:
    """Same family classifier but operating on the product TITLE (used for
    MULTISTYLERS pool rows whose Τύπος συσκευής is always 'Multistyler' —
    not informative — so we read the title's descriptive Greek terms instead.
    """
    if not title or pd.isna(title):
        return ''
    t = str(title).lower()
    # Brush-leaning multistylers — include the model-name clues that real-world
    # listings actually use. Dyson Airwrap variants sometimes drop "airwrap"
    # from the title and ship with "STRAIGHT+ WAVY" or "COANDA" branding.
    has_brush = ('βούρτσ' in t or 'airwrap' in t or 'volumizer' in t
                 or 'flexstyle' in t or 'hairstyler' in t or 'air styler' in t
                 or 'coanda' in t or 'straight+ wavy' in t or 'straight+wavy' in t
                 or 'speedstyle' in t or 'iq style' in t)
    has_curl = ('μπούκλ' in t or 'curl' in t or 'wand' in t
                or 'κυματιστ' in t or 'wave' in t or 'ψαλίδι' in t)
    if has_brush and has_curl:
        return 'MULTI'
    if has_brush:
        return 'BRUSH'
    if has_curl:
        return 'CURL'
    return ''


def _cb_is_male_coded(title: str) -> bool:
    """Return True if the product title contains UNAMBIGUOUS male-coded keywords.
    Used to deprioritize male products in the EPILATORS pool when the trigger
    is a women's-leaning category (e.g. curlers).

    Deliberately CONSERVATIVE — we'd rather let an ambiguous unisex product
    through than blacklist legitimate women's products. Specifically:
      • "body hair trimmer" / "body trimmer" alone are NOT flagged — BRAUN's
        women's "Body Hair Trimmer" line (e.g. BHT250 "Delicates") uses
        exactly that phrasing.
      • "trimmer" / "shaver" alone are NOT flagged — face/body trimmers for
        women use these words too.
      • "bodygroomer" IS flagged — that compound is overwhelmingly male.
      • Greek "ανδρικ" / "ανδρών" / "γενιού" / "γενεί" IS flagged — these are
        unambiguous Greek male signals (men's / beard).

    Returns True if any of the unambiguous male keywords appear in title.
    """
    if not title or pd.isna(title):
        return False
    t = str(title).lower()
    # Word-boundary-aware patterns. We pad t with spaces so " men " / " men's"
    # match at start/end without false-positives on "women" or "regimen".
    padded = f" {t} "
    male_keywords_word = [
        ' men ', " men's", ' mens ',     # English men / men's
        ' beard ', 'beard ',              # English beard (start/middle)
    ]
    male_keywords_substring = [
        'bodygroomer', 'body groomer', 'bodygroom',  # always male
        'ανδρικ', 'ανδρών',                          # Greek "men's" / "of men"
        'άνδρες', 'άντρες', 'άνδρα', 'άντρα',        # men plural/singular noun forms
        'άνδρας', 'άντρας',                           # men singular nominative
        'γενιού', 'γενεί', 'γένι',                    # Greek "beard" forms
    ]
    for kw in male_keywords_word:
        if kw in padded:
            return True
    for kw in male_keywords_substring:
        if kw in t:
            return True
    return False


