def _ck_row_brand(row) -> str:
    """Κατασκευαστής, with title parse as fallback for the NaN-brand
    accessory rows (BOSCH HEZ638D00 / NEFF Z1608DX0 / BOSCH AOV433A00 all
    carry the brand only in the title). Token-guarded substring on the
    normalized title — 'LG' can't fire inside another word."""
    b = str(row.get('Κατασκευαστής', '') or '').strip().upper()
    if b and b != 'NAN':
        return b
    t = ' ' + _cm_norm(row.get('Title', '')) + ' '
    for brand in _CK_KNOWN_BRANDS:
        if f' {brand} ' in t:
            return brand
    return ''


def _ck_brand_family(brand: str) -> set:
    """Compatibility family for the HARD-gated pools (rails, BSH probes).
    BSH marques share the physical platform; everyone else is strict
    same-brand. Empty brand → empty family → gated pools cleanly empty."""
    if not brand:
        return set()
    if brand in _CK_BSH_FAMILY:
        return set(_CK_BSH_FAMILY)
    if brand in _CK_ELX_FAMILY:
        return set(_CK_ELX_FAMILY)
    return {brand}


def _ck_detect_hob(trigger_row) -> str:
    """'GAS' | 'CERAMIC' | 'INDUCTION' | 'ENAMEL' | 'MIXED' from
    Τύπος εστίας ≡ (NBSP header → fetched via _cm_attr), Hierarchy as
    fallback. ORDER MATTERS: combo values exist ('Εμαγιέ;Αερίου' → the
    gas component decides, regulator-relevant) and one row carries a
    Latin-E 'Eπαγωγική' → match 'ΠΑΓΩΓ' without the leading letter."""
    ht = _cm_norm(_cm_attr(trigger_row, 'Τύπος εστίας ≡', ''))
    if 'ΜΕΙΚΤ' in ht or 'ΜΙΚΤ' in ht:
        return 'MIXED'
    if 'ΑΕΡΙ' in ht:                      # ΑΕΡΙΟΥ + ΥΓΡΑΕΡΙΟΥ + 'Εμαγιέ;Αερίου'
        return 'GAS'
    if 'ΠΑΓΩΓ' in ht:                     # Επαγωγική + Latin-E Eπαγωγική
        return 'INDUCTION'
    if 'ΚΕΡΑΜ' in ht:
        return 'CERAMIC'
    if 'ΕΜΑΓΙΕ' in ht:
        return 'ENAMEL'
    # Fallback: hierarchy. Electric without a hob value → ENAMEL is the
    # conservative read (ceramic care stays OFF — a wrong scraper is worse
    # than a missing one).
    hier = _cm_norm(trigger_row.get('Hierarchy', ''))
    return 'GAS' if 'ΑΕΡΙΟΥ' in hier else 'ENAMEL'


def _ck_classify_kitchen_acc(title: str) -> str:
    """Functional type bucket for Αξεσουάρ Κουζινών + Αξεσουάρ Φούρνων
    rows (MDA). Title-driven — these hierarchies carry no structured spec
    columns. ORDER MATTERS (short-substring traps):
      • ΑΝΤΑΛΛΑΚΤΙΚ ΞΥΣΤΡΑΣ must land in care_ceramic with the scraper,
        BEFORE any generic rule could claim it
      • ΦΟΥΡΝΟ ΑΤΜΟΥ descaler tablets are steam-oven-specific → 'other'
        (a freestanding cooker is not a steam oven)
      • hood parts (ΑΠΟΡΡΟΦΗΤΗΡ / ΦΙΛΤΡΟ ΑΝΘΡΑΚΑ) → 'other', never
        recommendable against a cooker
    """
    t = _cm_norm(title)
    # ── 'excluded' bucket (v28.49.1): model-specific built-in parts that
    # are NEVER a valid cross-sell for a freestanding cooker OR a
    # dishwasher. Previously these fell into 'other' and resurfaced via
    # the overflow pools (NEFF Z9416X2 griddle on a dishwasher, Flex
    # Design trim kits, Twist Pad hob knobs…). 'excluded' ends the
    # exclusion-regex whack-a-mole: overflow only reads 'other'.
    _EXCLUDED_PATTERNS = (
        'ΑΠΟΡΡΟΦΗΤΗΡ', 'ΦΙΛΤΡΟ ΑΝΘΡΑΚΑ',          # hood parts
        'FLEX DESIGN',                              # ~50 NEFF trim kits
        'TWIST PAD',                                # hob control knobs
        'ΠΛΑΚΑ ΓΚΡΙΛ', 'ΠΛΑΚΑ ΨΗΣΙΜΑΤΟΣ',           # induction-hob griddles
        'ΣΥΡΤΑΡΙ',                                  # warming/vacuum drawers (built-in appliances)
        'ΚΑΠΑΚΙ ΓΙΑ', 'ΚΑΠΑΚΙ ΕΣΤΙΩΝ',              # dependent lids / model hob covers
        'ΣΥΝΔΕΤΙΚ', 'ΕΞΑΡΤΗΜΑ ΣΥΝΔΕΣΗΣ',            # Domino hob connectors
        'ΔΙΑΧΩΡΙΣΤΙΚ',                              # built-in trim strips
        'ΣΚΟΥΠΙΔΟΦΑΓ', 'ΑΝΑΚΥΚΛΩΣΗΣ',               # sink disposers / recycling sets
        'ΜΑΓΕΙΡΕΜΑΤΟΣ ΑΤΜΟΥ',                       # steam-OVEN cooking sets
    )
    for pat in _EXCLUDED_PATTERNS:
        if pat in t:
            return 'excluded'
    if 'ΦΟΥΡΝΟ ΑΤΜΟΥ' in t and 'ΤΑΜΠΛΕΤ' in t:
        return 'excluded'                           # steam-oven descaler tablets
    if ('ΞΥΣΤΡΑ' in t or 'ΞΥΣΤΡΑΣ' in t or 'ΚΑΘΑΡΙΣΤΙΚΟ ΚΕΡΑΜΙΚ' in t
            or 'ΥΑΛΟΚΕΡΑΜΙΚ' in t):  # SCANPART blades "για υαλοκεραμικό"
                                     # were leaking to overflow → could
                                     # surface on GAS triggers (v28.48.3)
        return 'care_ceramic'
    if 'ΚΑΘΑΡΙΣΤΙΚ' in t and 'ΦΟΥΡΝ' in t:
        return 'care_oven'
    # care_surface (v28.48.2): universal surface-care consumables that the
    # ΚΑΘΑΡΙΣΤΙΚ rule missed — ΚΡΕΜΑ/ΣΚΟΝΗ/ΠΑΝΙ/ΣΕΤ Καθαρισμού (AEG
    # M3SCC200 cream, BOSCH inox powders + grease cloth, MIELE care set).
    # They were falling to 'other'/overflow, which is why an AEG ceramic
    # trigger led with the MIELE cream instead of AEG's own (user-reported).
    if ('ΚΡΕΜΑ ΚΑΘΑΡΙΣΜ' in t or 'ΣΚΟΝΗ ΚΑΘΑΡΙΣΜ' in t or 'ΠΑΝΙ ΚΑΘΑΡΙΣΜ' in t
            or 'ΣΕΤ ΚΑΘΑΡΙΣΜ' in t or 'ΠΑΝΙ ΜΙΚΡΟΪΝ' in t or 'ΠΑΝΙ ΜΙΚΡΟΙΝ' in t):
        return 'care_surface'
    if 'ΡΥΘΜΙΣΤ' in t and ('ΠΙΕΣ' in t or 'ΥΓΡΑΕΡΙ' in t):
        return 'gas_regulator'
    if 'ΤΗΛΕΣΚΟΠΙΚ' in t or 'FLEXICLIP' in t or 'ΜΗΧΑΝΙΣΜΟΣ ΚΟΥΖΙΝΑΣ' in t:
        return 'rail'   # 'Διπλός Μηχανισμός Κουζίνας PITSOS PZ11TE24X0'
                        # carries no ΤΗΛΕΣΚΟΠΙΚ token — it leaked into the
                        # overflow of BOTH engines (v28.49 fix; also gives
                        # PITSOS cookers a second compatible rail)
    if 'ΘΕΡΜΟΜΕΤΡ' in t or 'ΑΙΣΘΗΤΗΡΑΣ ΘΕΡΜΟΚΡΑΣ' in t:
        return 'thermo'
    if 'ΣΚΕΥΗ' in t or 'ΣΚΕΥΩΝ' in t or 'ΤΗΓΑΝΙ' in t or 'ΚΑΤΣΑΡΟΛ' in t or 'ΧΥΤΡΑ' in t:
        return 'cookware'   # ΣΚΕΥΩΝ: 'Σετ Μαγειρικών Σκευών' (MIELE/Fiskars) was missed
    if 'ΤΑΨΙ' in t or 'TΑΨΙ' in t or 'ΓΚΡΙΛ' in t or 'ΠΕΤΡΑ ΨΗΣ' in t or 'PIZZA STONE' in t:
        return 'tray'   # 'TΑΨΙ' = LATIN-T variant ('MIELE Ορθογώνιο Tαψί
                        # Gourmet') — same lookalike trap as 'Eπαγωγική'.
                        # Griddles and lids are handled by the 'excluded'
                        # bucket above, which runs first.
    return 'other'


def _ck_price_tier(price: float) -> int:
    """0=Budget(<€450), 1=Mainstream(€450-700), 2=Premium(€700-1500),
    3=Pro(>€1500). Calibrated on the cooker catalog: OMNYS/εμαγιέ €339-449,
    PITSOS/BOSCH/LA GERMANIA core €450-700, large LA GERMANIA €700-1500,
    BERTAZZONI/LOFRA ranges €1500-8000."""
    if price < 450:    return 0
    if price < 700:    return 1
    if price < 1500:   return 2
    return 3






