PS5_TITLE_PATTERN = re.compile(
    r'\b(PS5|PlayStation\s*5|PlayStation|PSVR2?|DualSense|PS\s*Plus|FIFA|FUT)\b',
    re.IGNORECASE,
)

# Multi-controller bundle detector
