def _psg_merch_search_regex(title, franchise_key):
    """Return a regex that identifies the trigger's IP/series in merch titles.
    Uses the curated franchise map first. The title fallback is deliberately
    CONSERVATIVE: it requires the full multi-word game name as a phrase, so a
    single common word can't false-match (e.g. 'Crimson Desert' must not match
    'LEGO Star Wars The Crimson Firehawk'). Single-word titles match only if the
    word is distinctive (≥5 chars and not a generic word)."""
    if franchise_key in PSG_FRANCHISE_MERCH_REGEX:
        return PSG_FRANCHISE_MERCH_REGEX[franchise_key]
    base = re.split(r'\s*[-–:]\s*', str(title), maxsplit=1)[0]
    base = re.split(r'\s*ps5\b', base, flags=re.IGNORECASE)[0]
    base = re.sub(r'[^a-zA-Z0-9\s]', ' ', base).lower()
    skip = {'the', 'of', 'and', 'edition', 'day', 'one', 'deluxe', 'premium',
            'standard', 'ps5', 'ps4', 'remaster', 'remastered', 'hd', 'game',
            'ea', 'definitive', 'complete', 'goty', 'ultimate', 'gold'}
    words = [w for w in base.split() if len(w) >= 3 and w not in skip]
    if len(words) >= 2:
        # Require the first two distinctive words to appear in order (a phrase),
        # which makes the match specific to this game, not a stray adjective.
        return r'\b' + re.escape(words[0]) + r'\b\W+\b' + re.escape(words[1]) + r'\b'
    if len(words) == 1 and len(words[0]) >= 5:
        GENERIC = {'crimson', 'control', 'returnal', 'forspoken', 'starfield',
                   'avowed', 'concord', 'ghostwire', 'pragmata', 'atomfall'}
        # (these single-word titles have no merch in the catalog anyway; treating
        #  generic-looking words conservatively avoids accidental matches)
        if words[0] not in GENERIC:
            return r'\b' + re.escape(words[0]) + r'\b'
    return None


def _psg_merch_type(row):
    """Coarse merch *type* used to diversify the three merch slots so they don't
    all show near-identical products (e.g. three Panini card packs). Returns a
    bucket like 'cards', 'lego', 'boardgame', 'figure', 'plush', 'mug', …"""
    l2 = str(row.get('Level 2', '')).strip().lower()
    h  = str(row.get('Hierarchy', '')).strip().lower()
    t  = str(row.get('Title', '')).lower()
    if 'lego' in l2 or 'lego' in t:                                   return 'lego'
    if 'puzzle' in t or 'παζλ' in t:                                  return 'puzzle'
    if 'monopoly' in t or 'jenga' in t or 'trivial' in t or 'επιτραπ' in h or 'board game' in t:
        return 'boardgame'
    if any(k in t for k in ('λούτριν', 'plush', 'beanie')):           return 'plush'
    if any(k in t for k in ('μπρελ', 'keychain', 'keyring')):         return 'keychain'
    if any(k in t for k in ('funko', 'tubbz', 'φιγούρα', 'figure', 'amiibo',
                            'playset', 'κούκλα', 'hasbro', 'minix', 'banpresto')):
        return 'figure'
    if any(k in t for k in ('κάρτες', 'cards', 'adrenalyn', 'αυτοκόλλητ',
                            'sticker', 'panini', 'trading')):         return 'cards'
    if any(k in t for k in ('κούπα', 'mug', 'ποτήρι', 'glass')):      return 'mug'
    if any(k in t for k in ('μπλούζα', 't-shirt', 'tshirt', 'hoodie', 'φούτερ')):
        return 'apparel'
    return l2 or 'other'


# Hierarchies that span platforms — need a title-based PS5 filter.
PSG_CROSSPLATFORM_HIERARCHIES = {'STEERING WHEELS', 'PREPAID CARDS'}

# Modest budget ceilings (over-cap → −30 000). Game triggers are €20-80, so
# unlike the console engine we use a single, sensible ceiling per gear type.
PSG_BUDGET = {
    'controller': 110, 'headset': 200, 'cable': 60,
    'accessory': 260, 'steering': 460, 'driving': 200, 'prepaid': 60,
}


def _psg_classify_genre(title):
    """Map a game title to a genre token using franchise patterns first,
    then a keyword fallback. Returns 'unknown' when nothing matches."""
    if not title:
        return 'unknown'
    t = str(title).lower()
    for pat, genre in PSG_FRANCHISE_GENRE:
        if re.search(pat, t):
            return genre
    for pat, genre in PSG_GENRE_KW:
        if re.search(pat, t):
            return genre
    return 'unknown'


def _psg_extract_franchise(title):
    """Coarse franchise key for dedup so we never recommend two titles from
    the trigger's own series (e.g. trigger Spider-Man 2 → drop all Spider-Man,
    trigger EA Sports FC26 → drop all EA Sports FC / FIFA)."""
    if not title:
        return ''
    t = str(title).lower()
    # Strongest franchise signals first.
    FRANCHISE_KEYS = [
        (r'ea sports fc|\bfifa\b', 'ea_fc'),
        (r'\bnba 2k', 'nba2k'), (r'\bwwe 2k', 'wwe2k'),
        (r'spider.?man', 'spiderman'), (r'god of war', 'gow'),
        (r'\bhorizon\b', 'horizon'), (r'assassin', 'assassins_creed'),
        (r'grand theft auto|\bgta\b', 'gta'), (r'ghost of', 'ghost_of'),
        (r'the last of us|\btlou\b', 'tlou'), (r'\buncharted\b', 'uncharted'),
        (r'resident evil', 'resident_evil'), (r'final fantasy', 'final_fantasy'),
        (r'gran turismo', 'gran_turismo'), (r'\bf1®?\b|formula 1', 'f1'),
        (r'need for speed', 'nfs'), (r'call of duty|\bcod\b', 'cod'),
        (r'battlefield', 'battlefield'), (r'elden ring', 'elden_ring'),
        (r'dragon ball', 'dragon_ball'), (r'tekken', 'tekken'),
        (r'street fighter|\bsf6\b', 'street_fighter'), (r'mortal kombat|\bmk1\b', 'mortal_kombat'),
        (r'\bgran turismo\b', 'gran_turismo'), (r'hogwarts', 'hogwarts'),
        (r'crash bandicoot|crash team', 'crash'), (r'astro bot', 'astro_bot'),
        (r'\blego\b', 'lego'), (r'metal gear|\bmgs\b', 'metal_gear'),
        (r'\bratchet\b', 'ratchet'), (r'silent hill', 'silent_hill'),
        (r'monster hunter', 'monster_hunter'), (r'\bnioh\b', 'nioh'),
        (r'gears of war|gears reloaded', 'gears'), (r'starfield', 'starfield'),
        (r'death stranding', 'death_stranding'), (r'just dance', 'just_dance'),
        (r'ninja gaiden', 'ninja_gaiden'), (r'lies of p', 'lies_of_p'),
        (r'\bufc \d', 'ufc'), (r'split fiction', 'split_fiction'),
        (r'crimson desert', 'crimson_desert'), (r'stellar blade', 'stellar_blade'),
        (r'black myth', 'black_myth'), (r'\bsaros\b', 'saros'),
        (r'\bwitcher\b', 'witcher'), (r'\bsonic\b', 'sonic'),
        (r'zelda|tears of the kingdom|breath of the wild', 'zelda'),
        (r'super mario|mario kart|\bmario\b', 'mario'),
        (r'pokemon|pokémon', 'pokemon'), (r'minecraft', 'minecraft'),
        (r'\bnaruto\b', 'naruto'), (r'\bhalo\b', 'halo'),
    ]
    for pat, key in FRANCHISE_KEYS:
        if re.search(pat, t):
            return key
    # Fallback: first two distinctive words (drops platform/edition modifiers).
    txt = re.sub(r'[^a-z0-9\s]', ' ', t)
    skip = {'ps5', 'ps4', 'edition', 'day', 'one', 'deluxe', 'premium', 'standard',
            'the', 'of', 'and', 'a', 'code', 'in', 'box', 'game', 'greek', 'version',
            'lenticular', 'remaster', 'remastered', 'collection', 'hd', 'vol'}
    words = [w for w in txt.split() if len(w) >= 3 and w not in skip]
    return '_'.join(words[:2]) if words else t[:8]


def _psg_genre_gear_hierarchies(genre):
    """Ordered accessory hierarchies for the two genre-gear slots."""
    return PSG_GENRE_GEAR.get(genre, PSG_GENRE_GEAR['unknown'])


