def _sb_parse_age_range(v):
    """Parse a 'Προτεινόμενη Ηλικία' value into (min_age, max_age).
    Handles 'N+ ετών', 'N - M', 'N έως M ετών', 'N+', bare 'N'.
    Returns None if unparseable / placeholder."""
    if v is None:
        return None
    s = str(v).strip().lower()
    if s in ('-', 'none', 'nan', ''):
        return None
    s = s.replace('ετών', '').replace('έτη', '').replace('έως', '-').replace('εως', '-').strip()
    # "N+" (optionally with trailing text)
    m = re.match(r'^(\d+)\s*\+', s)
    if m:
        return (int(m.group(1)), 99)
    # "N - M"
    m = re.match(r'^(\d+)\s*-\s*(\d+)', s)
    if m:
        return (int(m.group(1)), int(m.group(2)))
    # bare "N"
    m = re.match(r'^(\d+)$', s)
    if m:
        return (int(m.group(1)), int(m.group(1)))
    return None

def _sb_age_overlaps(rng, lo, hi):
    """True if an age range (min,max) overlaps the target window [lo, hi]."""
    if rng is None:
        return False
    return rng[0] <= hi and rng[1] >= lo


# v28.30.2 — Τόμος / Τεύχος / Μέρος detection.
# Catches Greek volume markers: "Α' τόμος", "Α΄ Τεύχος", "Β' Μέρος",
# "(Α' Τεύχος)", "Α΄ ΤΟΜΟΣ", and reverse "Τόμος Α'". Used to group
# multi-volume helpers together at the top of same-subject tiers so a
# parent buying "Χημεία Γ' τόμος" sees Α', Β' (and other volumes of the
# same series) in adjacent slots.
SB_TOMOS_LETTER_RANK = {'Α': 1, 'Β': 2, 'Γ': 3, 'Δ': 4, 'Ε': 5,
                        'ΣΤ': 6, 'Ζ': 7, 'Η': 8, 'Θ': 9, 'Ι': 10}

# Two patterns: letter-then-marker ("Α' τόμος") and marker-then-letter ("Τόμος Α'").
# Greek typographic apostrophes: regular ' (U+0027), tonos ΄ (U+1FFD),
# Greek dasia ʹ (U+02B9), prime ′ (U+2032).
_SB_TOMOS_RX_LETTER_FIRST = re.compile(
    r'(?P<letter>ΣΤ|[ΑΒΓΔΕΖΗΘΙ])[\'΄ʹ\u2032]\s*'
    r'(?:τόμος|τεύχος|μέρος|Τόμος|Τεύχος|Μέρος|ΤΟΜΟΣ|ΤΕΥΧΟΣ|ΜΕΡΟΣ)',
    re.UNICODE
)
_SB_TOMOS_RX_MARKER_FIRST = re.compile(
    r'(?:τόμος|τεύχος|μέρος|Τόμος|Τεύχος|Μέρος|ΤΟΜΟΣ|ΤΕΥΧΟΣ|ΜΕΡΟΣ)\s*'
    r'(?P<letter>ΣΤ|[ΑΒΓΔΕΖΗΘΙ])[\'΄ʹ\u2032]?',
    re.UNICODE
)


def _sb_extract_volume(title):
    """Detect a Greek volume marker in a school-book title.
    
    Returns (rank, base_title) where:
      - rank: int 1-10 if a τόμος/τεύχος/μέρος marker is found, else None
      - base_title: the title with the volume marker stripped (used for
                    grouping siblings of the same series together)
    
    Examples:
      "Χημεία Γ' Λυκείου (Α' Τεύχος)" → (1, "Χημεία Γ' Λυκείου")
      "Βοήθημα Χημεία Γ΄ λυκείου Γ' τόμος" → (3, "Βοήθημα Χημεία Γ΄ λυκείου")
      "Ανόργανη Χημεία" → (None, "Ανόργανη Χημεία")
    
    Note: "Γ' Λυκείου" (class marker) is NOT mistaken for volume because the
    regex requires the marker word (τόμος/τεύχος/μέρος) to follow, and "Λυκείου"
    is not in the marker set.
    """
    if not title: return (None, '')
    s = str(title)
    m = _SB_TOMOS_RX_LETTER_FIRST.search(s) or _SB_TOMOS_RX_MARKER_FIRST.search(s)
    if not m: return (None, s)
    rank = SB_TOMOS_LETTER_RANK.get(m.group('letter'))
    # Strip the matched span PLUS any surrounding parens/commas/whitespace
    # so the remaining base title cleanly groups siblings.
    span_start, span_end = m.span()
    # Extend the strip range to consume wrapping ( ) , and adjacent spaces
    while span_start > 0 and s[span_start - 1] in ' (,':
        span_start -= 1
    while span_end < len(s) and s[span_end] in ' ),':
        span_end += 1
    base = (s[:span_start] + ' ' + s[span_end:]).strip()
    base = re.sub(r'\s+', ' ', base).strip(' ,()-')
    return (rank, base)


# v28.30.4 — Author surname extraction for school-book series matching.
# Greek author strings come in many formats:
#   "Γεώργιος Παναγιωτακόπουλος;Γεώργιος Μαθιουδάκης"  (firstname-first, semicolons)
#   "Παναγιωτακόπουλος Γεώργιος, Μαθιουδάκης Γεώργιος"  (surname-first, commas)
#   "Μαθιουδάκης Γ.;Παναγιωτακόπουλος Γιώργος"  (initials + name variants)
# We extract the surname per author by taking the LONGEST word (Greek
# surnames are typically longer than first names) and matching by set
# overlap. Common first names like "Γεώργιος" can still be among the
# tokens but the surnames dominate.
def _sb_extract_authors_surname_set(val):
    """Return a set of surname tokens (lowercase) from a multi-author string.
    Each author (semicolon-separated) contributes its longest word.
    "Συλλογικό έργο" (collective work) returns an empty set — no signal."""
    if val is None: return set()
    try:
        if pd.isna(val): return set()
    except (TypeError, ValueError):
        pass
    s = str(val).strip()
    if not s or s.lower() in ('0', '-', 'nan', 'n/a'):
        return set()
    if 'συλλογικό' in s.lower():
        return set()   # Collective work — no specific author
    
    # Split into individual authors (prefer semicolon, fallback to comma).
    if ';' in s:
        author_strs = [a.strip() for a in s.split(';')]
    else:
        # Heuristic: only split on commas if there are multiple word groups
        # that look like full names (i.e. multiple words per side).
        parts = [p.strip() for p in s.split(',')]
        if len(parts) > 1 and all(len(p.split()) >= 2 for p in parts):
            author_strs = parts
        else:
            author_strs = [s]
    
    surnames = set()
    for author_str in author_strs:
        cleaned = re.sub(r'[.,]', ' ', author_str.lower())
        # Keep tokens >= 4 chars (filters out "κ.", "γ.", short initials)
        words = [w for w in cleaned.split() if len(w) >= 4]
        if words:
            longest = max(words, key=len)
            surnames.add(longest)
    return surnames


# v28.30.4 — Helper / textbook classification from Hierarchy.
# - "ΣΧΟΛΙΚΑ ΒΟΗΘΗΜΑΤΑ - <class>" = helper book (the upper-case Greek text 
#   for "school helpers"). Recommendations are sibling helpers from same
#   publisher + same subject (companion volumes).
# - "Βιβλία Οργανισμού <class>" = main gov-issued textbook. Recommendations
#   are top-selling helpers for the same subject from any publisher, plus
#   other Διόφαντος textbooks for other subjects.
#
# Note: Python's str.upper() preserves Greek tonos accents ('Βιβλία' →
# 'ΒΙΒΛΊΑ' with tonos on the Ι), so a naive 'ΒΙΒΛΙΑ' substring match fails.
# We normalize via NFD decomposition + combining-mark stripping before
# matching.
def _sb_strip_accents_upper(text):
    """Uppercase + strip Greek tonos/diacritics for accent-insensitive match."""
    if text is None: return ''
    s = unicodedata.normalize('NFD', str(text))
    return ''.join(c for c in s if unicodedata.category(c) != 'Mn').upper()

def _sb_is_helper_hierarchy(hierarchy):
    return 'ΒΟΗΘΗΜΑΤΑ' in _sb_strip_accents_upper(hierarchy)

def _sb_is_textbook_hierarchy(hierarchy):
    return 'ΒΙΒΛΙΑ ΟΡΓΑΝΙΣΜΟΥ' in _sb_strip_accents_upper(hierarchy)


# v28.30.8 — Greek high-school Προσανατολισμός (orientation track) normalization.
# Books for Γ' Λυκείου especially are split into orientation tracks. A Θετικ
# student needs Θετικ Math/Physics/Chemistry/Biology — not Ανθρωπιστικών Αρχαία.
# Exact string match fails because the same conceptual orientation has variant
# wordings ("Προσανατολισμός Θετικών Σπουδών" vs "Προσανατολισμός Θετικών
# Σπουδών & Σπουδών Υγείας"). We canonicalize to a small set of tokens.
SB_ORIENT_TOKEN_KEYWORDS = (
    ('θετικ',     'θετικ'),       # Προσανατολισμός Θετικών Σπουδών
    ('υγει',      'υγει'),        # Σπουδών Υγείας
    ('ανθρωπ',    'ανθρωπ'),      # Ανθρωπιστικών Σπουδών
    ('οικον',     'οικον'),       # Οικονομίας
    ('πληροφορ',  'πληροφορ'),    # Πληροφορικής
    ('γενικ',     'γενικ'),       # Γενικής Παιδείας (treated as a wildcard for specialist triggers)
    ('επαλ',      'επαλ'),        # ΕΠΑ.Λ.
    ('τεχν',      'επαλ'),        # τεχνολογικής — fold into ΕΠΑ.Λ.
)

def _sb_orient_tokens(orient_value):
    """Extract canonical orientation tokens from a string OR list of strings.
    Returns a set; empty if no recognized orientation found."""
    if not orient_value:
        return set()
    if isinstance(orient_value, (list, set, tuple)):
        items = list(orient_value)
    else:
        items = [orient_value]
    out = set()
    for item in items:
        if not item: continue
        s = _sb_strip_accents_upper(str(item)).lower()
        for needle, token in SB_ORIENT_TOKEN_KEYWORDS:
            if needle in s:
                out.add(token)
    return out

def _sb_series_key(base_title):
    """Normalize a τόμος base-title into a fuzzy series key (set of word
    stems) for sibling matching. Catalog titles for the same series are
    formatted inconsistently ("...Θετικών Σπουδών - - Λύσεις των ασκήσεων"
    vs "...Θετικών Σπουδών, Λύσεις Ασκήσεων 22-0283" vs "Φυσική Γ' Λυκείου
    22-0282"), so an exact base match misses real siblings.
    
    We reduce to a bag of significant word stems: strip accents, lowercase,
    drop catalog codes (22-0282), numbers, punctuation, and noise words
    (λύσεις, ασκήσεων, τεύχος, σπουδών, class markers, etc.). What remains is
    the subject + any distinguishing words (e.g. {φυσικ-ish tokens, θετικ})."""
    if not base_title:
        return frozenset()
    s = _sb_strip_accents_upper(str(base_title)).lower()
    s = re.sub(r'\d+[-–]\d+', ' ', s)   # catalog codes "22-0282"
    s = re.sub(r'\d+', ' ', s)
    s = re.sub(r'[^\wά-ωα-ω\s]', ' ', s, flags=re.UNICODE)
    tokens = set(s.split())
    NOISE = {
        'λυσεις', 'ασκησεων', 'ασκησεωσ', 'τευχος', 'τομος', 'μερος',
        'βοηθημα', 'προσανατολισμου', 'προσανατολισμος', 'σπουδων',
        'λυκειου', 'λυκειο', 'γυμνασιου', 'δημοτικου', 'γενικου',
        'γενικης', 'και', 'των', 'τησ', 'της', 'στοιχεια',
    }
    return frozenset(t for t in tokens if t and t not in NOISE and len(t) >= 3)

# v28.30.14 — Kids' stationery theme/brand matching. Young children care that
# their supplies share a character/theme (a Unicorn gum wants a Unicorn pencil,
# not a generic one). We extract a theme token from a stationery item's title
# and bias the selection so, once a themed item is picked, sibling slots prefer
# the same theme. Token list curated from the retailer's Θέμα + Brand facets.
SB_KIDS_THEME_KEYWORDS = {
    # theme token : tuple of accent-stripped lowercase title substrings
    'unicorn':      ('unicorn', 'μονοκερ'),
    'frozen':       ('frozen', 'ελσα', 'elsa', 'anna'),
    'barbie':       ('barbie', 'μπαρμπι'),
    'bluey':        ('bluey',),
    'cars':         ('cars', 'mcqueen'),
    'disney':       ('disney', 'ντισνε'),
    'dora':         ('dora', 'ντορα'),
    'dragonball':   ('dragon ball', 'dragonball'),
    'gabby':        ('gabby', 'gabbys'),
    'hellokitty':   ('hello kitty', 'hellokitty'),
    'stitch':       ('lilo', 'stitch'),
    'littleprince': ('little prince', 'μικρος πριγκιπ', 'μικρος πριγκηπ'),
    'marvel':       ('marvel', 'avengers', 'spiderman', 'spider man', 'ironman'),
    'mymelody':     ('my melody', 'mymelody'),
    'onepiece':     ('one piece', 'onepiece', 'luffy'),
    'pawpatrol':    ('paw patrol', 'pawpatrol'),
    'peppa':        ('peppa',),
    'santoro':      ('santoro', 'gorjuss'),
    'sonic':        ('sonic',),
    'squishmallows':('squishmallows', 'squishmallow'),
    'supermario':   ('super mario', 'supermario', 'mario'),
    'yeti':         ('γετι', 'yeti'),
    'mrmen':        ('μικροι κυριοι', 'μικρες κυριες', 'mr men', 'little miss'),
    'olympiacos':   ('ολυμπιακος',),
    'panathinaikos':('παναθηναικος',),
    'rene':         ('rene', 'ρενε'),
    # generic themes (Θέμα facet)
    'animals':      ('ζωακι', 'ζωα ', 'animal'),
    'princess':     ('πριγκιπισσ', 'princess'),
    'superhero':    ('σουπερ ηρω', 'superhero', 'super hero'),
    'vehicles':     ('οχημα', 'αυτοκινητ', 'vehicle', 'truck'),
    'football':     ('ποδοσφαιρ', 'football', 'αθλημα'),
}

def _sb_kids_theme_tokens(title):
    """Return the set of kids' theme/brand tokens present in a title."""
    if not title:
        return frozenset()
    s = _sb_strip_accents_upper(str(title)).lower()
    out = set()
    for token, needles in SB_KIDS_THEME_KEYWORDS.items():
        if any(nd in s for nd in needles):
            out.add(token)
    return frozenset(out)

def _sb_orient_compatible(row_orient_value, trigger_tokens):
    """Decide whether a row is orientation-compatible with the trigger.
    
    Rules:
      * Trigger has no orientation tokens → no filter (compatible).
      * Row has no orientation data at all → compatible (general/uncategorized).
      * Row has tokens that intersect trigger's → compatible.
      * Row is Γενικής Παιδείας (token 'γενικ') → compatible with any specialist
        trigger (general track applies to everyone).
    For a Γενικής-trigger, the compatibility narrows to Γενικής rows only, because
    the wildcard branch checks the ROW for 'γενικ' (which only helps when trigger
    is specialized).
    """
    if not trigger_tokens:
        return True
    row_tokens = _sb_orient_tokens(row_orient_value)
    if not row_tokens:
        return True   # uncategorized — assumed general
    if row_tokens & trigger_tokens:
        return True
    if 'γενικ' in row_tokens and trigger_tokens != {'γενικ'}:
        # Wildcard: a non-Γενικής trigger accepts Γενικής rows alongside its own.
        return True
    return False


# Scoring constants for the "Other Books" deep-spec match.
# v28.29.1 — publishing-series + format signals added.
#
# Rationale for the ranking of magnitudes (Pub Series > Author > Publisher >
# Theme > Dimensions ≈ Language > Cover):
#   • Pub Series is a curated PUBLISHER LINE (Penguin Modern Classics, Loeb
#     Classical Library, Πυξίδα). When the trigger is in one, the customer
#     is likely collecting the line — that intent crosses authors and even
#     book series, so it should outrank Author affinity.
#   • Author next (people loyal to a writer cross genres).
#   • Publisher (Εκδότης) is broader — many lines/authors per publisher.
#   • Theme (Θέμα Βιβλίου) — genre-level match within hierarchy.
#   • Dimensions — shelf-uniformity. Stronger than cover because dimensions
#     define the physical "set" feel; cover is mostly binary soft/hard.
#   • Language — within-Level-2 pools are already mostly homogeneous, so
#     this fires for nearly all candidates and acts as a mild tiebreaker.
#   • Cover — last-resort tiebreaker; only 2-3 dominant values exist.
BOOKS_V2_S_SAME_PUB_SERIES = 100_000   # v28.29.1 — strongest: publisher product line
BOOKS_V2_S_SAME_AUTHOR     =  80_000   # author affinity
BOOKS_V2_S_SAME_PUBLISHER  =  30_000   # publisher catalog
BOOKS_V2_S_SAME_THEME      =  20_000   # Θέμα Βιβλίου
BOOKS_V2_S_SAME_DIMENSIONS =   5_000   # v28.29.1 — shelf cohesion (Διαστάσεις)
BOOKS_V2_S_SAME_LANGUAGE   =   5_000   # Γλώσσα Γραφής
BOOKS_V2_S_SAME_COVER      =   1_000   # v28.29.1 — soft vs hard cover tiebreaker
BOOKS_V2_S_AVAIL_BONUS     =       2   # matches AVAIL_BOOST elsewhere

def allocate_book_slots(series_books_available_count: int):
    """
    Map the count of available Same-Series books to a 10-slot allocation
    per the v28.29 two-set rule (see BOOKS_V2 doc block above).
    
    Returns a list of 10 strings — each one of 'SAME_SERIES' or 'OTHER_BOOKS' —
    indexed 0..9 for carousel slots 1..10.
    """
    n = max(0, int(series_books_available_count))
    
    # Front set (slots 1-7, 7 cells total)
    if   n >= 10: front_ss = 5
    elif n >=  6: front_ss = 4   # covers 6-7 AND 8-9 (back set differs)
    elif n >=  4: front_ss = 3   # covers 4-5
    elif n >=  3: front_ss = 2
    elif n >=  2: front_ss = 1
    else:         front_ss = 0
    
    # Slight correction for n in {8, 9}: front_ss must be 4 (not 5).
    # The chained-elif above already gives 4 for n in [6,9] so no override
    # needed — leaving this comment as a marker for the rule boundary.
    
    # Back set (slots 8-10, 3 cells total). All-or-nothing: deep series → all
    # SS, otherwise all OB.
    back_ss = 3 if n >= 8 else 0
    
    front_slots = ['SAME_SERIES'] * front_ss + ['OTHER_BOOKS'] * (7 - front_ss)
    back_slots  = ['SAME_SERIES'] * back_ss  + ['OTHER_BOOKS'] * (3 - back_ss)
    return front_slots + back_slots


def _books_v2_norm(s):
    """Normalize a string field for spec-match comparison: lowercase, strip,
    collapse common Greek/Latin variants. Handles None/NaN safely."""
    if s is None: return ''
    try:
        if pd.isna(s): return ''
    except (TypeError, ValueError):
        pass
    return str(s).strip().lower()


def _books_v2_extract_authors_set(authors_field):
    """Parse a Συγγραφέας field that may be semicolon-separated and return a
    SET of normalized author names. Returns empty set if blank/missing.
    Multi-author co-bylines are matched if ANY author overlaps."""
    raw = _books_v2_norm(authors_field)
    if not raw or raw in ('0', 'nan', 'n/a', 'none'):
        return set()
    parts = [p.strip() for p in re.split(r'[;,&]| και | and ', raw) if p.strip()]
    return {p for p in parts if p}


def _books_v2_normalize_language(lang):
    """Map known Γλώσσα Γραφής variants to a canonical token. Handles case
    differences ('ελληνικά' vs 'Ελληνικά'), Greek↔English duplicates
    ('αγγλικά' vs 'english'), and the trailing-whitespace pattern seen in
    Int Books ('english ')."""
    base = _books_v2_norm(lang)
    if not base: return ''
    # Strip multi-language semicolon lists down to the first language.
    if ';' in base:
        base = base.split(';')[0].strip()
    base = base.strip()
    # Bilingual normalization map
    eng_aliases = {'english', 'αγγλικά', 'αγγλικα'}
    gr_aliases  = {'greek', 'ελληνικά', 'ελληνικα'}
    if base in eng_aliases: return 'en'
    if base in gr_aliases:  return 'el'
    return base


def _books_v2_normalize_dimensions(dims):
    """Normalize a Διαστάσεις string to a canonical form for matching.
    
    Handles the real-world dirty variants observed in the data:
      • Latin 'x' vs Greek 'χ' vs '×': "21x14", "21χ14", "21×14"
      • Whitespace: "14 x 21", "14x21", "14 x 21 cm"
      • Units: "198 mm x 129 mm" stripped to "198x129"  
      • 2D vs 3D: "20x13" and "20x2x13" canonicalize to the same key by
        taking the two LARGEST numbers (the face dimensions, ignoring the
        spine thickness which varies between editions of the same book)
      • Order: "14x21" and "21x14" both → "14x21"
    
    Note: this normalizer does NOT convert between mm and cm — strings using
    mm match other mm strings, cm/unitless match cm/unitless. Most book sets
    are consistent in their unit usage so this is acceptable in practice.
    """
    if dims is None: return ''
    try:
        if pd.isna(dims): return ''
    except (TypeError, ValueError):
        pass
    s = str(dims).strip().lower()
    if not s or s in ('0', 'nan', 'n/a', 'none', '-'): return ''
    # Normalize separator characters
    s = s.replace('χ', 'x').replace('×', 'x')
    # Detect whether this is in mm (we preserve the unit so mm doesn't
    # cross-match cm). Default is treated as cm.
    is_mm = ('mm' in s)
    # Strip unit tokens
    s = re.sub(r'\s*(mm|cm|εκ\.?|in\.?)\s*', '', s)
    # Strip remaining whitespace
    s = re.sub(r'\s+', '', s)
    # Parse all numeric components (including decimals)
    parts = re.findall(r'\d+\.?\d*', s)
    if len(parts) < 2:
        return f"{s}|mm" if is_mm else s
    # Take the two LARGEST dimensions (face W×H, ignoring spine depth)
    nums = sorted((float(p) for p in parts), reverse=True)[:2]
    nums.sort()  # ascending for canonical order
    key = 'x'.join(f"{n:g}" for n in nums)
    return f"{key}|mm" if is_mm else key

def _books_v2_normalize_cover(cover):
    """Normalize Εξώφυλλο to a canonical token. Collapses the trailing-space
    duplicates and case variants seen in the data ('Μαλακό εξώφυλλο' vs
    'Μαλακό Εξώφυλλο' vs 'Μαλακό εξώφυλλο '; 'Paperback' vs 'Paperback ').
    Maps EN/GR equivalents to a shared key so a Greek-tagged soft cover
    matches an English-tagged soft cover."""
    base = _books_v2_norm(cover)
    if not base: return ''
    base = base.strip()
    # Family map — same physical binding type, multiple labels in the data
    softs = {'μαλακό εξώφυλλο', 'paperback', 'paperback / softback', 'softcover', 'χαρτόδετο'}
    hards = {'σκληρό εξώφυλλο', 'hardcover', 'hardback', 'σκληρόδετο'}
    boards = {'board book', 'σκληρό μωρικό', 'board'}
    if base in softs: return 'soft'
    if base in hards: return 'hard'
    if base in boards: return 'board'
    return base

