def get_tablet_tier(price):
    """Map a tablet's LIST PRICE (€) to a budget tier string.
    Returns one of: 'Pro' | 'Upper Medium' | 'Medium' | 'Low' | 'Budget'
    Matches the keys in TABLET_ACCESSORY_BUDGET and WATTAGE_TIER_PREFS.
    """
    try:
        p = float(price)
    except (TypeError, ValueError):
        return 'Budget'
    if p >= 1050: return 'Pro'
    if p >=  750: return 'Upper Medium'
    if p >=  550: return 'Medium'
    if p >=  250: return 'Low'
    return 'Budget'

def _norm_col_name(s):
    return (str(s).replace('\xa0', ' ').replace('≡', '').strip().lower())
 
 
def _col(df, name):
    target = _norm_col_name(name)
    for c in df.columns:
        if _norm_col_name(c) == target:
            return c
    return None
 
 
def _series(df, name, default=''):
    c = _col(df, name)
    if c is None:
        return pd.Series(default, index=df.index, dtype=object)
    return df[c].fillna(default).astype(str)
 
 
def _extract_size_from_title(title):
    """Fallback when Μέγεθος οθόνης column is empty/0. Parses inches from
    titles. Accepts multiple inch markers seen in Public.gr titles:
        '  one ASCII single quote
        '' two ASCII single quotes (the Greek title style: 'Universal 14''')
        "  ASCII double quote
        ″  Unicode double prime (U+2033)
        ''  Unicode typographic single quotes (U+2018/U+2019)
    """
    s = str(title)
    m = re.search(
        r'(\d+(?:\.\d+)?)\s*(?:["″\u2033]|[\'\u2018\u2019]{1,2})', s)
    return float(m.group(1)) if m else 0.0
 
 
def _compat_mask(pool, model):
    if not model:
        return pd.Series(False, index=pool.index)
    pat = re.escape(model)
    mask = pd.Series(False, index=pool.index)
    for col_name in ('Συμβατές συσκευές', 'Συμβατή συσκευή'):
        col = _col(pool, col_name)
        if col:
            mask = mask | pool[col].fillna('').astype(str).str.contains(
                pat, case=False, regex=True, na=False)
    return mask
 
 
def _exact_compat_match(pool, model):
    """Token-level EXACT match. Splits compat field on ; / , | newline,
    strips, lowercases, and checks if the trigger model equals one of the
    tokens. Used by CASE_FIT and APPLE_FOLIO_STRICT — substring matching is
    too loose ("iPad Pro" should NOT match "iPad Pro 12.9-inch 5th Gen")."""
    if not model:
        return pd.Series(False, index=pool.index)
    target = str(model).strip().lower()
 
    def matches(s):
        if not s:
            return False
        tokens = re.split(r'[;/,\n|]+', str(s).lower())
        return any(t.strip() == target for t in tokens)
 
    mask = pd.Series(False, index=pool.index)
    for col_name in ('Συμβατές συσκευές', 'Συμβατή συσκευή'):
        col = _col(pool, col_name)
        if col:
            mask = mask | pool[col].fillna('').apply(matches)
    return mask
 
 
def _compat_text(pool):
    text = pd.Series('', index=pool.index)
    for col_name in ('Συμβατές συσκευές', 'Συμβατή συσκευή'):
        col = _col(pool, col_name)
        if col:
            text = text + ' ' + pool[col].fillna('').astype(str)
    return text.str.upper()
 
 
def _brand_first_filter(pool, trigger_brand):
    if pool.empty or not trigger_brand:
        return pool
    same = _series(pool, 'Κατασκευαστής').str.upper().str.strip() == trigger_brand
    if same.any():
        return pool[same]
    return pool
 
 
def _brand_first_filter_case(pool, trigger_brand):
    if pool.empty or not trigger_brand:
        return pool
    brand_dev = _series(pool, 'Brand συσκευής σου').str.upper().str.strip()
    own_brand = brand_dev.eq(trigger_brand)
    universal = brand_dev.eq('UNIVERSAL') | brand_dev.eq('')
    if own_brand.any():
        return pool[own_brand]
    if universal.any():
        return pool[universal]
    return pool
 
 
def _brand_incompat_filter(pool, trigger_brand, known_brands=None,
                            also_check_title=False):
    """Drop accessories whose compat field (and optionally title) mentions
    a competitor brand but NOT the trigger brand.
 
    `also_check_title=True` catches "Tune Stylus για Apple iPad" cases
    where the brand is in the title, not the structured compat field."""
    if pool.empty or not trigger_brand:
        return pool
    if known_brands is None:
        known_brands = KNOWN_TABLET_BRANDS
    others = [b for b in known_brands if b != trigger_brand]
    if not others:
        return pool
 
    text = _compat_text(pool)
    if also_check_title:
        title = _series(pool, 'Title').str.upper()
        text = text + ' ' + title
 
    is_empty = text.str.strip().eq('')
    has_self = text.str.contains(re.escape(trigger_brand), na=False)
    has_other = pd.Series(False, index=pool.index)
    for ob in others:
        has_other = has_other | text.str.contains(re.escape(ob), na=False)
 
    keep = is_empty | has_self | (~has_other)
    return pool[keep]
 
 
def _port_mask_chargers(pool, trigger_port):
    if not trigger_port:
        return pd.Series(False, index=pool.index)
    s = _series(pool, 'Θύρα USB').str.lower()
    tp = trigger_port.lower()
    if 'type-c' in tp or 'usb-c' in tp:
        return s.str.contains('type-c', na=False) | s.str.contains('usb-c', na=False)
    if 'usb-a' in tp or 'micro' in tp or 'lightning' in tp:
        return s.str.contains('usb-a', na=False)
    return pd.Series(False, index=pool.index)
 
 
def _port_mask_cables(pool, trigger_port):
    if not trigger_port:
        return pd.Series(False, index=pool.index)
    s = _series(pool, 'Τύπος σύνδεσης').str.lower()
    tp = trigger_port.lower()
    if 'type-c' in tp or 'usb-c' in tp:
        return s.str.contains('type-c', na=False) | s.str.contains('usb-c', na=False)
    if 'lightning' in tp:
        return s.str.contains('lightning', na=False)
    if 'micro' in tp:
        return s.str.contains('micro', na=False)
    return pd.Series(False, index=pool.index)
 
 
def _port_mask_flash(pool, trigger_port):
    if not trigger_port:
        return pd.Series(False, index=pool.index)
    sigma = _series(pool, 'Σύνδεση').str.lower()
    tp = trigger_port.lower()
    if 'type-c' in tp or 'usb-c' in tp:
        return sigma.str.contains('usb-c', na=False)
    return sigma.str.contains('usb-a', na=False)
 
 
def _wattage_pref_mask(pool, ttier):
    prefs = WATTAGE_TIER_PREFS.get(ttier, WATTAGE_TIER_PREFS['Low'])
    s = _series(pool, 'Ισχύς (Watt)')
    if s.eq('').all():
        s = _series(pool, 'Ισχύς')
    return s.isin(prefs)
 
 
def _color_tokens(trigger_color):
    if not trigger_color:
        return []
    s = str(trigger_color).lower().strip()
    return [t for t in re.split(r'[\s/\-;,]+', s)
            if t and t not in TRANSPARENT_TOKENS]
 
 
def _apply_color_boost(pool, color_toks, with_transparent=True):
    """Add color-match boost to pool's Final_Score column. No filter — boost only."""
    if not color_toks:
        return pool
    acc_color = _series(pool, 'Χρώμα').str.lower()
    exact = acc_color.apply(lambda s: any(t in s for t in color_toks))
    pool.loc[exact, 'Final_Score'] += S_COLOR_EXACT
    if with_transparent:
        transp = acc_color.isin(TRANSPARENT_TOKENS)
        pool.loc[transp & ~exact, 'Final_Score'] += S_COLOR_TRANSPARENT
    return pool
 
 
def _size_band_matches(band, tablet_size_inches):
    if not band or tablet_size_inches <= 0:
        return False
    b = band.lower().replace('"', '').strip()
    m = re.match(r'^\s*(\d+(?:\.\d+)?)\s*\+\s*$', b)
    if m:
        return tablet_size_inches >= float(m.group(1))
    m = re.match(r'^\s*(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*$', b)
    if m:
        lo, hi = float(m.group(1)), float(m.group(2))
        return lo - 0.3 <= tablet_size_inches <= hi + 0.3
    m = re.match(r'^\s*έως\s+(\d+(?:\.\d+)?)\s*$', b)
    if m:
        return tablet_size_inches <= float(m.group(1))
    m = re.match(r'^\s*(\d+(?:\.\d+)?)\s*$', b)
    if m:
        # Single-size bag (e.g. '15.6"' or '14"'). Tablet must fit IN it,
        # so bag_size >= tablet_size with a small downward slack for marketing
        # rounding (some "11-inch" listings are actually 10.9").
        v = float(m.group(1))
        return v >= tablet_size_inches - 0.2 and v <= tablet_size_inches + 1.5
    return False
 
 
def _size_match_mask(pool, tablet_size_inches):
    s = _series(pool, 'Μέγεθος')
    return s.apply(lambda b: _size_band_matches(b, tablet_size_inches))
 
 
def _apply_budget_filter(pool, role, ttier):
    """Hard-filter to [min, max] for role × tier, with safety net."""
    if pool.empty:
        return pool
    min_p, max_p = _budget_range(role, ttier)
    in_range = (pool['_p'] >= min_p) & (pool['_p'] <= max_p)
    if in_range.any():
        return pool[in_range]
    soft = pool['_p'] <= max_p * 1.5
    if soft.any():
        return pool[soft]
    return pool
 
 
def _nb_bag_fallback_pool(c, used_materials, tb, tsize, is_premium):
    """Return an NB BAG / SLEEVE pool scored for fallback when no compat
    case exists. Hard-filters by tablet size when possible (safety net keeps
    the pool if no size-band match exists). Brand match boost + premium price
    scale. Caller checks if returned pool is empty before using."""
    # Case-insensitive hierarchy match — defensive against data feed casing
    hier_u = c['Hierarchy'].fillna('').astype(str).str.upper().str.strip()
    nb = c[hier_u.isin(['NB BAGS', 'ΘΗΚΕΣ SLEEVE LAPTOP'])].copy()
    nb = nb[~nb['Material'].isin(used_materials)]
    if nb.empty:
        return nb
    # Hard-filter by size band if any items match; safety net keeps all otherwise
    if tsize > 0:
        size_mask = _size_match_mask(nb, tsize)
        if size_mask.any():
            nb = nb[size_mask]
    nb['Final_Score'] = 0.0
    nb_brand = (_series(nb, 'Κατασκευαστής').str.upper().str.strip() == tb)
    nb.loc[nb_brand, 'Final_Score'] += S_BRAND_BOOST
    if is_premium:
        # Premium tablet → prefer pricier sleeves (proxy for quality)
        nb['Final_Score'] += nb['_p'].fillna(0) * 100
    return nb
 
 
def _universal_bag_size(row):
    """Extract size in inches from a Universal Tablet Bag.
    Tries the bag's Title first ('Universal 14"' / 'Universal 11''),
    then 'Συμβατή συσκευή' (e.g. 'Tablets up to 11"'), then 'Μέγεθος'.
    Returns 0.0 if nothing detectable."""
    for col_key in ('Title', 'Συμβατή συσκευή', 'Μέγεθος'):
        # row.get tolerates non-breaking-space variants because the engine
        # normalizes column reads via _series elsewhere; here we accept whatever
        # variant is present in the row dict.
        for k in row.index:
            if _norm_col_name(k) == _norm_col_name(col_key):
                v = row[k]
                if pd.notna(v):
                    sz = _extract_size_from_title(v)
                    if sz > 0:
                        return sz
                break
    return 0.0
 
 
def _universal_tablet_bag_pool(c, used_materials, tb, tsize, color_toks=None):
    """Return UNIVERSAL TABLET BAGS pool (Brand συσκευής σου = UNIVERSAL).
    Used as the middle fallback step between same-brand exact-model match
    and NB BAG.
 
    Hard-filters by size when the bag's title/compat declares a size
    (e.g. 'Universal 14"'). Tolerance ±1.5" — a Universal 12" bag fits a
    10.5–13.5" tablet; a Universal 14" bag does NOT fit an 11" tablet.
 
    Bags with no detectable size are kept (genuinely universal sleeves).
    Brand boost + color boost only."""
    hier_u = c['Hierarchy'].fillna('').astype(str).str.upper().str.strip()
    bags = c[hier_u.eq('TABLET BAGS')].copy()
    bags = bags[~bags['Material'].isin(used_materials)]
    if bags.empty:
        return bags
    brand_dev = _series(bags, 'Brand συσκευής σου').str.upper().str.strip()
    bags = bags[brand_dev.eq('UNIVERSAL')]
    if bags.empty:
        return bags
 
    # Size filter — ASYMMETRIC. The tablet has to fit INSIDE the bag, so:
    #   bag_size >= tablet_size  (no slack downward — a 10" bag DOES NOT fit
    #                              an 11" tablet, even though they're "close")
    #   bag_size <= tablet_size + 3.0  (generous upper bound — universals run
    #                                    large; a 14" sleeve for an 11" tablet
    #                                    is sloppy but won't damage it)
    # Bags with no declared size (genuine size-agnostic universals) are kept.
    if tsize > 0:
        bag_sizes = bags.apply(_universal_bag_size, axis=1)
        size_ok = (bag_sizes == 0) | (
            (bag_sizes >= tsize - 0.2) & (bag_sizes <= tsize + 1.5)
        )
        size_filtered = bags[size_ok]
        if not size_filtered.empty:
            bags = size_filtered
 
    bags['Final_Score'] = 0.0
    same_b = _series(bags, 'Κατασκευαστής').str.upper().str.strip() == tb
    bags.loc[same_b, 'Final_Score'] += S_BRAND_BOOST
    if color_toks:
        bags = _apply_color_boost(bags, color_toks)
    return bags
 

# ═════════════════════════════════════════════════════════════
# 🟢 SMARTWATCH HELPERS
# ═════════════════════════════════════════════════════════════

def parse_euro_price(raw) -> float:
    if isinstance(raw, (int, float)):
        return float(raw)
    try:
        cleaned = re.sub(r"[€\s]", "", str(raw))
        cleaned = cleaned.replace(".", "").replace(",", ".")
        return float(cleaned)
    except (ValueError, AttributeError):
        return 0.0
 
 
# ── Size-group tables for strap / screen-protector compatibility ──
# v7.1: Apple updated to include 46mm (Series 10/11) and 49mm (Ultra) in the
# larger group. Used only as FALLBACK; the wearables strict slots use EXACT
# size matching first.
_APPLE_WATCH_SIZE_GROUPS: list[set[str]] = [
    {"38MM", "40MM", "41MM", "42MM"},
    {"44MM", "45MM", "46MM", "49MM"},
]
_SAMSUNG_WATCH_SIZE_GROUPS: list[set[str]] = [
    {"40MM", "41MM", "42MM"},
    {"44MM", "45MM", "46MM", "47MM"},
]
_HUAWEI_WATCH_SIZE_GROUPS: list[set[str]] = [
    {"41MM", "42MM", "43MM"},
    {"46MM", "47MM", "48MM"},
]
_GARMIN_WATCH_SIZE_GROUPS: list[set[str]] = [
    {"40MM", "41MM", "42MM"},
    {"44MM", "45MM", "46MM", "47MM"},
]
_BRAND_SIZE_GROUPS: dict[str, list[set[str]]] = {
    "APPLE":   _APPLE_WATCH_SIZE_GROUPS,
    "SAMSUNG": _SAMSUNG_WATCH_SIZE_GROUPS,
    "HUAWEI":  _HUAWEI_WATCH_SIZE_GROUPS,
    "HONOR":   _HUAWEI_WATCH_SIZE_GROUPS,
    "GARMIN":  _GARMIN_WATCH_SIZE_GROUPS,
}

def _extract_sizes(text: str) -> set[str]:
    return {m.upper() for m in re.findall(r"\d{2}mm", text, re.IGNORECASE)}

def _extract_wearable_size_from_title(title: str) -> str:
    """Pull the watch case size out of a trigger title.
    'Apple Watch SE 3 GPS 40mm Starlight Aluminum...' → '40MM'
    'Smartwatch Huawei Watch GT 5 46mm - Black'      → '46MM'
    'Smartwatch Garmin Venu 4 45mm - Slate'          → '45MM'
    Returns '' if no size found."""
    m = re.search(r'(\d{2})\s*mm', str(title), re.IGNORECASE)
    return f"{m.group(1)}MM" if m else ""

# v7.1: Model-line signatures for cross-version rejection
#  • (SE, 3) means "SE generation 3" — reject straps for SE 2, SE 1.
#  • (GT, 5) means "Watch GT5" — reject straps for GT3, GT2 etc.
#  • (SERIES, 11) — reject straps for Series 9, Series 10.
# Patterns ordered longer → shorter so two-word matches win.
_WEARABLE_LINE_PATTERNS: list[tuple[str, str]] = [
    ("GALAXYWATCH", r"\bGALAXY\s*WATCH\s*(\d+)"),
    ("PIXELWATCH",  r"\bPIXEL\s*WATCH\s*(\d+)"),
    ("FORERUNNER",  r"\bFORERUNNER\s*(\d+)"),
    ("VIVOMOVE",    r"\bVIVOMOVE\s*(\d+)"),
    ("VIVOACTIVE",  r"\bVIVOACTIVE\s*(\d+)"),
    ("INSTINCT",    r"\bINSTINCT\s*(\d+)"),
    ("SERIES",      r"\bSERIES\s*(\d+)"),
    ("ULTRA",       r"\bULTRA\s*(\d+)"),
    ("FENIX",       r"\bFENIX\s*(\d+)"),
    ("EPIX",        r"\bEPIX\s*(\d+)"),
    ("VENU",        r"\bVENU\s*(\d+)"),
    ("BUDS",        r"\bBUDS\s*(\d+)"),
    ("SE",          r"\bSE\s*(\d+)"),
    ("GT",          r"\bGT\s*(\d+)"),
    ("FIT",         r"\bFIT\s*(\d+)"),
    ("WATCH",       r"\bWATCH\s*(\d+)"),
]

# Compat-side patterns capture digit blocks (e.g. "SERIES 9/10/11" → "9/10/11").
# v7.1 NOTE: "WATCH" intentionally NOT included here. Compat strings like
# "Apple Watch 40mm" would otherwise be falsely detected as model "Watch 40",
# making the signature filter reject every Apple strap (size mistaken for
# version). Brand-specific patterns (GALAXY WATCH, PIXEL WATCH, GT, SE,
# SERIES, ULTRA, VENU, etc.) are sufficient to catch real model-line
# mentions; "Watch 40mm" alone has no real version to enforce against.
_WEARABLE_LINE_COMPAT_PATTERNS: dict[str, str] = {
    "GALAXYWATCH": r"\bGALAXY\s*WATCH\s*(\d+(?:[/\\]\d+)*)",
    "PIXELWATCH":  r"\bPIXEL\s*WATCH\s*(\d+(?:[/\\]\d+)*)",
    "FORERUNNER":  r"\bFORERUNNER\s*(\d+(?:[/\\]\d+)*)",
    "VIVOMOVE":    r"\bVIVOMOVE\s*(\d+(?:[/\\]\d+)*)",
    "VIVOACTIVE":  r"\bVIVOACTIVE\s*(\d+(?:[/\\]\d+)*)",
    "INSTINCT":    r"\bINSTINCT\s*(\d+(?:[/\\]\d+)*)",
    "SERIES":      r"\bSERIES\s*(\d+(?:[/\\]\d+)*)",
    "ULTRA":       r"\bULTRA\s*(\d+(?:[/\\]\d+)*)",
    "FENIX":       r"\bFENIX\s*(\d+(?:[/\\]\d+)*)",
    "EPIX":        r"\bEPIX\s*(\d+(?:[/\\]\d+)*)",
    "VENU":        r"\bVENU\s*(\d+(?:[/\\]\d+)*)",
    "BUDS":        r"\bBUDS\s*(\d+(?:[/\\]\d+)*)",
    "SE":          r"\bSE\s*(\d+(?:[/\\]\d+)*)",
    "GT":          r"\bGT\s*(\d+(?:[/\\]\d+)*)",
    "FIT":         r"\bFIT\s*(\d+(?:[/\\]\d+)*)",
}

def _extract_model_signature(model_str: str) -> tuple[str, str]:
    """Returns (line, version) e.g. ('SE','3'), ('SERIES','11'), ('GT','5').
    Empty tuple ('','') if model has no parseable signature."""
    if not model_str:
        return ("", "")
    s = str(model_str).strip().upper()
    for line_label, pat in _WEARABLE_LINE_PATTERNS:
        m = re.search(pat, s)
        if m:
            return (line_label, m.group(1))
    return ("", "")

def _signature_in_compat(trigger_sig: tuple[str, str], compat_upper: str) -> bool:
    """True if compat is compatible with the trigger's (line, version).
       • No trigger signature → True (no filter)
       • Compat has NO model signatures → True (generic compat — accept)
       • Compat has signatures but NONE for trigger's line → False (different product)
       • Compat has signatures for trigger's line → True iff trigger version is listed
    """
    line, version = trigger_sig
    if not line or not version:
        return True
    # Does compat mention ANY model signature at all?
    has_any = any(re.search(p, compat_upper) for p in _WEARABLE_LINE_COMPAT_PATTERNS.values())
    if not has_any:
        return True
    pat = _WEARABLE_LINE_COMPAT_PATTERNS.get(line)
    if not pat:
        return False
    blocks = re.findall(pat, compat_upper)
    if not blocks:
        return False
    nums = set()
    for block in blocks:
        nums.update(re.findall(r"\d+", block))
    return version in nums

def _model_tokens(model_str: str) -> set[str]:
    _NOISE = {"AND", "OR", "WITH", "FOR", "THE", "GPS", "CELLULAR",
              "LTE", "NFC", "WIFI", "BT", "PLUS", "PRO", "MAX"}
    raw = re.split(r"[\s\-/,+&]+", model_str.strip().upper())
    return {t for t in raw if len(t) >= 2 and t not in _NOISE}

def _compatibility_score(model_str: str, compat_field, brand: str = "",
                          trigger_size: str = "",
                          trigger_signature: tuple[str, str] = ("", ""),
                          item_title: str = "") -> int:
    """Score how well a candidate's compat field matches the trigger.

    v7.1: Adds two HARD rejection filters BEFORE strict/partial scoring:
      1) trigger_size — if both trigger and compat have sizes and trigger's
         exact size string is NOT listed in compat → reject (return 0).
         No group fallback; user wants EXACT size match for the strict slots.
      2) trigger_signature — if trigger model has (line, version) AND compat
         OR ITEM TITLE mentions a different version of the same line (e.g.
         SE 2 vs SE 3, GT3 vs GT 5, Series 9 vs Series 11, Ultra 2 vs Ultra
         3) → reject.

    v7.2: signature check now scans `item_title` too. Real-world case:
    "PanzerGlass για Apple Watch Ultra/Ultra 2 49mm" has compat just
    "Apple Watch 49mm" (no version mention) so passes if we only check
    compat. The version conflict (Ultra 2 vs trigger Ultra 3) is in the
    title — must scan it.

    Returns SCORE_MODEL_MATCH_STRICT (model substring in compat),
            SCORE_MODEL_MATCH_PARTIAL (≥half tokens match), or 0."""
    if not model_str or pd.isna(compat_field):
        return 0
    compat_upper = str(compat_field).upper()
    model_upper  = model_str.strip().upper()

    # ── Filter 1: EXACT size match (no group fallback) ──
    if trigger_size:
        compat_sizes = _extract_sizes(compat_upper)
        if compat_sizes and trigger_size.upper() not in compat_sizes:
            return 0

    # ── Filter 2: Model-signature (line+version) ──
    # v7.2: scan title + compat together so titles like "Ultra/Ultra 2 49mm"
    # are caught even when the structured compat field is generic.
    if trigger_signature and trigger_signature[0]:
        sig_haystack = compat_upper
        if item_title:
            sig_haystack = compat_upper + " " + str(item_title).upper()
        if not _signature_in_compat(trigger_signature, sig_haystack):
            return 0

    # ── Standard strict / partial scoring ──
    if re.search(re.escape(model_upper), compat_upper):
        return SCORE_MODEL_MATCH_STRICT
    tokens = _model_tokens(model_str)
    if tokens:
        matched = sum(1 for t in tokens if t in compat_upper)
        if matched >= max(2, len(tokens) // 2):
            return SCORE_MODEL_MATCH_PARTIAL
    return 0
 
def _price_affinity_score(item_price: float, cap: float, trigger_price: float) -> int:
    if item_price <= 0 or cap <= 0:
        return 0
    ratio    = item_price / cap
    sweet_lo = _sweet_spot_min_ratio(trigger_price)
    if ratio <= sweet_lo: return SCORE_BELOW_SWEET
    if ratio <= 1.00:     return SCORE_IN_BUDGET_SWEET
    if ratio <= 1.50:     return PENALTY_OVER_CAP_SOFT
    if ratio <= 2.50:     return PENALTY_OVER_CAP_HARD
    return PENALTY_WAY_OVER_CAP
 
 
def _build_hierarchy_pool(
    candidates: pd.DataFrame,
    hierarchies: list[str],
    used_materials: set,
) -> pd.DataFrame:
    """Case-insensitive hierarchy filter. Excludes already-used materials."""
    hier_pattern = "|".join(re.escape(h) for h in hierarchies)
    mask = (
        candidates["Hierarchy"]
        .fillna("")
        .astype(str)
        .str.contains(hier_pattern, case=False, na=False, regex=True)
    )
    pool = candidates[mask].copy()
    return pool[~pool["Material"].isin(used_materials)]
 
 
def _score_pool(
    pool: pd.DataFrame,
    *,
    logic_key: str,
    budget_key: str,
    hierarchy: str,
    tmod: str,
    tb: str,
    trigger_price: float,
    brand_slot_count: dict,
    sales_p80: float,
    used_signatures: set,
    is_brand_locked: bool,
    ecosystem: set[str] | None = None,
    trigger_year: int | None = None,
    trigger_size: str = "",
    trigger_signature: tuple[str, str] = ("", ""),
) -> tuple[pd.DataFrame, list[str], bool]:
    """
    Apply all scoring layers. Returns (scored_pool, notes, has_compat_hit).
 
    `used_signatures` is the set of (hierarchy_signature_tuples) already chosen
    for this hierarchy across the run; matching signatures get a hard penalty.
 
    `is_brand_locked` means the pool was already filtered to the ecosystem —
    in that case we skip the universal brand boost (everyone is in-ecosystem)
    and skip the brand-diversity penalty against the trigger brand.
 
    `ecosystem` is the set of friendly brand names (e.g. {"APPLE","BEATS"}).
    When provided and the pool is NOT locked, items belonging to the ecosystem
    get a tiered boost: primary (trigger brand itself) > secondary (sister brands).
    This is what powers the "exclusive Apple boost" behaviour on SOFT slots.
    """
    notes: list[str] = [f"Logic={logic_key}", f"BudgetKey={budget_key}"]
    pool["_score"] = 0.0
    cap = get_dynamic_cap(trigger_price, budget_key)
    notes.append(f"Cap=€{cap:.0f} (dynamic from trigger €{trigger_price:.0f})")
 
    has_compat_hit = False
 
    # Layer 1 — Compatibility (Μοντέλο ↔ Συμβατό με)
    if logic_key == "MODEL_MATCH_STRICT" and tmod and "Συμβατό με" in pool.columns:
        # v7.2: pass each row's title too, so signature can catch version
        # conflicts like "Apple Watch Ultra/Ultra 2 49mm" that aren't in compat.
        compat_scores = pool.apply(
            lambda r: _compatibility_score(tmod, r.get("Συμβατό με", ""), brand=tb,
                                            trigger_size=trigger_size,
                                            trigger_signature=trigger_signature,
                                            item_title=r.get("Title", "")),
            axis=1,
        )
        pool["_score"] += compat_scores
        strict_hits  = int((compat_scores == SCORE_MODEL_MATCH_STRICT).sum())
        partial_hits = int((compat_scores == SCORE_MODEL_MATCH_PARTIAL).sum())
        rejected     = int((compat_scores == 0).sum())
        has_compat_hit = (strict_hits + partial_hits) > 0
        size_lbl = f" size={trigger_size}" if trigger_size else ""
        sig_lbl  = f" sig={trigger_signature[0]}{trigger_signature[1]}" if trigger_signature and trigger_signature[0] else ""
        notes.append(f"Compat strict={strict_hits} partial={partial_hits} rejected={rejected}{size_lbl}{sig_lbl}")
        # v7.1: HARD prune the pool to only items that score > 0 (i.e., passed
        # size + signature filters). Without this, rejected items with score 0
        # still get popularity / ecosystem boosts and can win the slot.
        pool = pool[compat_scores > 0].copy()
        if pool.empty:
            return pool, notes + ["⛔ All items rejected by size/signature filters"], has_compat_hit
 
    # Layer 2 — Use-case affinity (audio / mount)
    if logic_key == "AUDIO_USE_CASE":
        # In a unified flow, both TWS earbuds and sport audio are valid for slot 3.
        # Boost both patterns; tie-break later via brand/price/popularity.
        audio_mask = pool["Title"].str.contains(
            r"Buds|AirPods|FreeBuds|TWS|True\s*Wireless|Galaxy\s*Buds|"
            r"Sport|Run|Bone|Shokz|Neckband|IPX[567]",
            case=False, na=False, regex=True,
        )
        pool.loc[audio_mask, "_score"] += SCORE_USE_CASE_AFFINITY
        notes.append(f"Audio use-case boost: {int(audio_mask.sum())} items")
    elif logic_key == "MOUNT_USE_CASE":
        mount_mask = pool["Title"].str.contains(
            r"Dock|Stand|Station|Βάση|Bike|Ποδήλατο|Handlebar|Cycling|"
            r"Charging\s*Stand|Nightstand|GPS\s*Mount",
            case=False, na=False, regex=True,
        )
        pool.loc[mount_mask, "_score"] += SCORE_USE_CASE_AFFINITY
        notes.append(f"Mount use-case boost: {int(mount_mask.sum())} items")
 
    # Layer 3 — Brand / Ecosystem boost
    # When pool is NOT already locked to ecosystem, apply tiered boosts:
    #   • Primary brand (trigger brand itself, e.g. APPLE for Apple Watch)  → +500K
    #   • Secondary brand (sister brand inside ecosystem, e.g. BEATS)       → +300K
    # When pool IS locked, ALL items are already in-ecosystem; we still
    # differentiate primary vs secondary within the locked pool so the
    # trigger brand wins ties (e.g. AirPods > Beats for Apple Watch).
    brand_upper = pool["Κατασκευαστής"].fillna("").str.upper()
    if ecosystem:
        primary_mask = (brand_upper == tb)
        secondary_mask = brand_upper.isin(ecosystem - {tb})
        pool.loc[primary_mask, "_score"]   += SCORE_ECOSYSTEM_PRIMARY
        pool.loc[secondary_mask, "_score"] += SCORE_ECOSYSTEM_SECONDARY
        if not is_brand_locked:
            n_prim, n_sec = int(primary_mask.sum()), int(secondary_mask.sum())
            if n_prim or n_sec:
                notes.append(f"Ecosystem boost: {n_prim} primary ({tb}), {n_sec} secondary")
    elif not is_brand_locked:
        # No ecosystem defined → fall back to legacy same-brand boost
        same_brand_mask = brand_upper == tb
        pool.loc[same_brand_mask, "_score"] += SCORE_SAME_BRAND
 
    # Layer 4 — Brand diversity penalty (skip the locked brand)
    for brand, count in brand_slot_count.items():
        if count >= 2 and not (is_brand_locked and brand == tb):
            # Don't penalise ecosystem brands when ecosystem-locking is active
            if ecosystem and brand in ecosystem:
                continue
            over_mask = brand_upper == brand
            pool.loc[over_mask, "_score"] += PENALTY_BRAND_DIVERSITY * (count - 1)
 
    # Layer 5 — Price affinity (dynamic cap)
    pool["_score"] += pool["_p"].apply(
        lambda p: _price_affinity_score(p, cap, trigger_price)
    )
 
    # Layer 6 — Popularity tie-breaker
    popular_mask = pool["Sales_Tiebreaker"] >= sales_p80
    pool.loc[popular_mask, "_score"] += SCORE_POPULARITY_BOOST

    # Layer 6b — Year boost (smartphone-style, v7)
    # Score newer/same/previous-year accessories higher. Conservative values
    # keep year boost below the ecosystem-primary-vs-secondary gap (200K) so
    # year can never flip a primary brand to a secondary brand.
    if trigger_year is not None:
        acc_year = pool.apply(
            lambda r: _wearable_extract_year(str(r.get("Title", "")), str(r.get("Μοντέλο", ""))),
            axis=1,
        )
        n_newer = int((acc_year > trigger_year).sum())
        n_same  = int((acc_year == trigger_year).sum())
        n_prev  = int((acc_year == trigger_year - 1).sum())
        pool.loc[acc_year > trigger_year, "_score"] += SCORE_YEAR_NEWER
        pool.loc[acc_year == trigger_year, "_score"] += SCORE_YEAR_SAME
        pool.loc[acc_year == trigger_year - 1, "_score"] += SCORE_YEAR_PREV
        if n_newer or n_same or n_prev:
            notes.append(f"Year boost ({trigger_year}): {n_newer} newer, {n_same} same, {n_prev} prev")
 
    # Layer 7 — Spec-variety penalty (only active in overflow when used_signatures is non-empty)
    if used_signatures and SPEC_SIGNATURE_COLUMNS.get(hierarchy):
        sig_series = pool.apply(lambda r: _signature(r, hierarchy), axis=1)
        # Penalise rows whose signature exactly matches one already used
        dup_mask = sig_series.isin(used_signatures)
        pool.loc[dup_mask, "_score"] += PENALTY_SPEC_DUPLICATE
        notes.append(f"Spec-variety: {int(dup_mask.sum())} dup-signature items penalised")
 
    pool = pool.sort_values(["_score", "Sales_Tiebreaker"], ascending=[False, False])
    return pool, notes, has_compat_hit
 
 
def _assign_to_slot(
    chosen: pd.Series,
    *,
    assigned_slot: int,
    role: str,
    persona_label: str,
    fallback: bool,
    hierarchies: list[str],
) -> pd.Series:
    rc = chosen.copy()
    rc["Assigned_Slot"]  = assigned_slot
    rc["Slot_Role"]      = role
    rc["Persona"]        = persona_label
    rc["Final_Score"]    = chosen["_score"]
    rc["Fallback_Used"]  = fallback
    rc["Marketing_Copy"] = WEARABLE_MARKETING_COPY.get(
        hierarchies[0], "Ιδανική επιλογή για το smartwatch σου."
    )
    return rc
 
 
def _try_pick_for_slot(
    *,
    full_pool: pd.DataFrame,
    hierarchies: list[str],
    used_materials: set,
    logic_key: str,
    budget_key: str,
    tmod: str,
    tb: str,
    trigger_price: float,
    brand_slot_count: dict,
    sales_p80: float,
    used_signatures_by_hier: dict,
    enforce_brand_lock: bool,
    ecosystem_mode: str = "OFF",
    title_filter: dict | None = None,
    smartphone_style: str | None = None,
    overflow_brand_lock: str | None = None,
    trigger_year: int | None = None,
    trigger_size: str = "",
    trigger_signature: tuple[str, str] = ("", ""),
) -> tuple[pd.Series | None, list[str], bool, bool]:
    """
    Try to score & return the best candidate for a slot.

    Returns (chosen_row_or_None, notes, has_compat_hit, brand_locked_used).

    Ecosystem behaviour is controlled by `ecosystem_mode`:
      • "OFF"  → legacy: no ecosystem boost, no ecosystem-filtered pool.
                 (Brand-lock still applies if `enforce_brand_lock` is True,
                  using the trigger brand alone — same as the v5 engine.)
      • "SOFT" → ecosystem brands get a score boost in `_score_pool`,
                 but the pool stays open (no pre-filtering).
      • "LOCK" → pool filtered to the ecosystem set first; if non-empty
                 AND best score passes threshold, return from locked pool.
                 Otherwise fall back to full pool.

    `title_filter` (optional) prunes the hierarchy pool by title pattern
    BEFORE any ecosystem filtering or scoring. Used when a hierarchy mixes
    products that don't all fit the slot's intent (e.g. APPLE HEADPHONES
    contains both AirPods Max and legacy wired EarPods Jack).
        {"include": <regex>, "exclude": <regex>}

    `smartphone_style` (NEW in v7): "audio" / "power" / None. Enables the
    smartphone-engine recipe — price-tier floor, ultra-premium filter for
    flagship triggers (≥€700, audio slots only), and forwards `trigger_year`
    to `_score_pool` for the year-boost layer.

    `overflow_brand_lock` (NEW in v7): when set, hard-filters the pool to the
    given brand (case-insensitive) BEFORE any ecosystem logic. Used by PASS 2
    to guarantee that an overflow slot for hierarchy X picks the same brand
    that hierarchy X's first-pick used. Stops the "AirPods then JBL" problem.
    """
    hierarchy = hierarchies[0]
    used_sigs = used_signatures_by_hier.get(hierarchy, set())

    pool = _build_hierarchy_pool(full_pool, hierarchies, used_materials)
    if pool.empty:
        return None, [f"Logic={logic_key}", "⚪ Pool empty"], False, False

    notes_prefix: list[str] = []

    # ── Title filter (applied before ecosystem & scoring) ─────────────
    if title_filter:
        before_n = len(pool)
        titles = pool["Title"].fillna("").astype(str)
        if title_filter.get("include"):
            pool = pool[titles.str.contains(title_filter["include"], case=False, na=False, regex=True)].copy()
            titles = pool["Title"].fillna("").astype(str)
        if title_filter.get("exclude"):
            pool = pool[~titles.str.contains(title_filter["exclude"], case=False, na=False, regex=True)].copy()
        after_n = len(pool)
        notes_prefix.append(f"Title-filter pruned {before_n - after_n} items ({before_n}→{after_n})")
        if pool.empty:
            return None, [f"Logic={logic_key}"] + notes_prefix + ["⚪ Pool empty after title-filter"], False, False

    # ── Price-tier floor (smartphone-style, v7) ───────────────────────
    # Cuts cheap audio/charger junk that would never be a good upsell.
    # Applied BEFORE ecosystem so the lock operates on a cleaned pool.
    if smartphone_style in ("audio", "power"):
        min_price = get_min_price_for_slot(trigger_price, smartphone_style)
        if min_price > 0:
            before_n = len(pool)
            price_filtered = pool[pool["_p"] >= min_price]
            if not price_filtered.empty:
                pool = price_filtered.copy()
                notes_prefix.append(f"Price tier (€{trigger_price:.0f} watch, {smartphone_style}): min €{min_price:.0f} → {before_n}→{len(pool)}")
            else:
                notes_prefix.append(f"Price tier: no items ≥€{min_price:.0f}, keeping all {before_n}")

    # ── Ultra-premium filter is applied INSIDE the ecosystem-lock
    #    branch only (see Step 1 below). Rationale: outside the ecosystem,
    #    the Pro/Ultra/Max keywords can accidentally match weak brands
    #    whose name happens to contain "Pro" (e.g. Audio Pro) while
    #    cutting legitimate flagships like "JBL Charge 6" that don't use
    #    Pro/Max naming. Keeping the filter ecosystem-scoped matches the
    #    iPhone-15-Pro behaviour: filter operates on AirPods variants,
    #    not on every brand that happens to share the keyword.

    # ── Overflow brand-lock (v7) — HARD filter ─────────────────────────
    # When PASS 2 asks for a same-brand refill, restrict the pool to that
    # exact brand. Bypasses ecosystem because user wants brand match, not
    # ecosystem match (AirPods → AirPods, not AirPods → Beats).
    if overflow_brand_lock:
        before_n = len(pool)
        brand_target = overflow_brand_lock.strip().upper()
        pool = pool[pool["Κατασκευαστής"].fillna("").str.upper() == brand_target].copy()
        notes_prefix.append(f"🔁 Overflow brand-lock to {brand_target}: {before_n}→{len(pool)}")
        if pool.empty:
            return None, [f"Logic={logic_key}"] + notes_prefix + [f"⚪ No more {brand_target} items"], False, False

    # Resolve ecosystem set (empty if mode is OFF or trigger brand has no entry)
    ecosystem: set[str] = set()
    if enforce_brand_lock and tb in LOCKABLE_BRANDS and ecosystem_mode in ("SOFT", "LOCK"):
        ecosystem = get_wearable_ecosystem(tb)
 
    # ── Step 1: Ecosystem-locked attempt (mode == LOCK only) ──────────
    if ecosystem and ecosystem_mode == "LOCK":
        brand_pool = pool[pool["Κατασκευαστής"].fillna("").str.upper().isin(ecosystem)].copy()

        # Ultra-premium filter (v7) — applied INSIDE the locked pool only.
        # Audio slots ≥€700 trigger restricted to Pro/Ultra/Max/Studio/Elite
        # variants. Scoped to ecosystem so we don't accidentally cut JBL
        # Charge 6 when falling back outside Apple+Beats.
        if (smartphone_style == "audio"
                and trigger_price >= WEARABLE_ULTRA_PREMIUM_THRESHOLD
                and not brand_pool.empty):
            before_n = len(brand_pool)
            pattern = "|".join(WEARABLE_ULTRA_PREMIUM_KEYWORDS)
            premium_pool = brand_pool[brand_pool["Title"].fillna("").str.lower().str.contains(pattern, regex=True, na=False)]
            if not premium_pool.empty:
                brand_pool = premium_pool.copy()
                notes_prefix.append(f"Ultra-premium filter (€{trigger_price:.0f}): {before_n}→{len(brand_pool)} (Pro/Ultra/Max only)")

        if not brand_pool.empty:
            scored, notes, has_compat = _score_pool(
                brand_pool,
                logic_key=logic_key,
                budget_key=budget_key,
                hierarchy=hierarchy,
                tmod=tmod, tb=tb,
                trigger_price=trigger_price,
                brand_slot_count=brand_slot_count,
                sales_p80=sales_p80,
                used_signatures=used_sigs,
                is_brand_locked=True,
                ecosystem=ecosystem,
                trigger_year=trigger_year,
                trigger_size=trigger_size,
                trigger_signature=trigger_signature,
            )
            eco_label = "+".join(sorted(ecosystem))
            notes = notes_prefix + [f"🔒 Ecosystem-locked to [{eco_label}]"] + notes
            # Strict slot needs compat in the locked pool to count as success
            if logic_key == "MODEL_MATCH_STRICT" and tmod and (scored.empty or not has_compat):
                notes_prefix = notes_prefix + [f"Ecosystem-lock failed (no compat in [{eco_label}]) — falling back"]
            elif scored.empty:
                notes_prefix = notes_prefix + [f"Ecosystem-lock failed (pool emptied by filters) — falling back"]
            else:
                best_row    = scored.iloc[0]
                best_score  = best_row["_score"]
                # v7.2: Apple-boost / ecosystem unconditional lock.
                # Previously a price-ratio guard (2.0× mid / 2.5× premium /
                # ∞ flagship) could fail the lock and fall back to non-Apple
                # brands. User explicitly asked: "for apple I want apple boost,
                # to showcase apple first unless there's no apple products".
                # So whenever the locked pool is non-empty (i.e. ecosystem
                # items exist in this hierarchy), the locked pool wins —
                # even if AirPods Max €589 vastly exceeds the Apple Watch
                # SE 3 €94 dynamic cap. The threshold guard stays in place
                # to prevent absurdly-low scores from sneaking through.
                if best_score >= SCORE_MINIMUM_THRESHOLD:
                    return best_row, notes, has_compat, True
                notes_prefix = notes_prefix + [f"Ecosystem-lock failed (best score {int(best_score):,} below threshold) — falling back"]
        else:
            eco_label = "+".join(sorted(ecosystem))
            notes_prefix = notes_prefix + [f"Ecosystem-lock skipped (no [{eco_label}] in hierarchy) — falling back"]

    # ── Step 2: Fall back to full pool (with SOFT ecosystem boost if applicable) ──
    scored, notes, has_compat = _score_pool(
        pool,
        logic_key=logic_key,
        budget_key=budget_key,
        hierarchy=hierarchy,
        tmod=tmod, tb=tb,
        trigger_price=trigger_price,
        brand_slot_count=brand_slot_count,
        sales_p80=sales_p80,
        used_signatures=used_sigs,
        is_brand_locked=False,
        ecosystem=ecosystem if ecosystem_mode in ("SOFT", "LOCK") else None,
        trigger_year=trigger_year,
        trigger_size=trigger_size,
        trigger_signature=trigger_signature,
    )
    notes = notes_prefix + notes

    if logic_key == "MODEL_MATCH_STRICT" and tmod and (scored.empty or not has_compat):
        return None, notes + ["⬜ No compat in fallback pool"], False, False
    if scored.empty:
        return None, notes + ["⚪ Pool emptied by filters"], False, False

    best_score = scored["_score"].iloc[0]
    if best_score < SCORE_MINIMUM_THRESHOLD:
        return None, notes + [f"⛔ Below threshold ({best_score})"], has_compat, False

    return scored.iloc[0], notes, has_compat, False
 

 
