# ─────────────────────────────────────────────────────────────
# 🟢 KIDS BOOKS ENGINE (REWRITTEN FOR DYNAMIC ORDERING)
# ─────────────────────────────────────────────────────────────
def run_books_engine(trigger, df_all, df_history):
    diag = []
    slot_notes = {}
    all_recs = []
    used_materials = set()
    used_titles = set()
    
    # ══════════════════════════════════════════════════════════
    # 🟢 LOAD GENDER & ORDER CATEGORIES FROM FILE
    # ══════════════════════════════════════════════════════════
    SERIES_GENDER_MAP = {}
    SERIES_ORDER_MAP = {}
    try:
        import os
        gender_file_paths = [
            '/mnt/user-data/uploads/kids_books_categories.xlsx',
            'kids_books_categories.xlsx',
            '/mount/src/recommender-poc/kids_books_categories.xlsx',
        ]
        for gf_path in gender_file_paths:
            if os.path.exists(gf_path):
                gender_df = pd.read_excel(gf_path)
                for _, row in gender_df.iterrows():
                    series_name = str(row.get('Series Name', '')).strip()
                    category = str(row.get('Category', 'Universal')).strip()
                    
                    # Read Order logic from 3rd column
                    order_type = str(row.iloc[2]).strip() if len(row) > 2 else 'Standalone'
                    
                    if series_name:
                        series_lower = series_name.lower()
                        if category == 'Girls-leaning':
                            SERIES_GENDER_MAP[series_lower] = 'girl'
                        elif category == 'Boys-leaning':
                            SERIES_GENDER_MAP[series_lower] = 'boy'
                        else:
                            SERIES_GENDER_MAP[series_lower] = 'neutral'
                            
                        SERIES_ORDER_MAP[series_lower] = order_type
                break
    except Exception as e:
        pass 

    # 🟢 HARDCODED ORDER EXTRACTIONS
    HARRY_POTTER_ORDER = {
        'φιλοσοφική λίθος': 1, 'philosopher': 1, "sorcerer's stone": 1,
        'μυστικό δωμάτιο': 2, 'chamber of secrets': 2, 'κάμαρα': 2,
        'αιχμάλωτος': 3, 'αζκαμπάν': 3, 'prisoner of azkaban': 3,
        'κύπελλο φωτιάς': 4, 'goblet of fire': 4, 'κύπελλο της φωτιάς': 4,
        'τάγμα του φοίνικα': 5, 'order of the phoenix': 5, 'φοίνικα': 5,
        'ημίαιμος πρίγκιψ': 6, 'half-blood prince': 6, 'ημίαιμος': 6,
        'κλήροι του θανάτου': 7, 'deathly hallows': 7, 'θανάτου': 7,
        'καταραμένο παιδί': 8, 'cursed child': 8,
        'φανταστικά ζώα': 9, 'fantastic beasts': 9,
        'quidditch': 10, 'κουίντιτς': 10,
        'beedle': 11, 'μπιντλ': 11,
    }
    
    def get_hp_order(title):
        title_lower = str(title).lower()
        for keyword, order in HARRY_POTTER_ORDER.items():
            if keyword in title_lower: return order
        return 99 
    
    def is_harry_potter_series(series_name):
        series_lower = str(series_name).lower()
        return 'harry potter' in series_lower or 'χάρι πότερ' in series_lower or 'χαρι ποτερ' in series_lower

    def is_dog_man_series(series_name):
        return 'dog man' in str(series_name).lower()
    
    def get_dog_man_order(title):
        title_lower = str(title).lower()
        match = re.search(r'dog\s*man\s*(\d{1,2})(?:\s*[-:]|\s|$)', title_lower)
        if match: return int(match.group(1))
        if 'dog man' in title_lower and not re.search(r'dog\s*man\s*\d', title_lower):
            adv_match = re.search(r'adventures\s*of\s*dog\s*man\s*(\d)', title_lower)
            if adv_match: return int(adv_match.group(1))
            return 1
        known_titles = {
            'a tale of two kitties': 3, 'tale of two kitties': 3,
            'lord of the fleas': 5, 'brawl of the wild': 6,
            'for whom the ball rolls': 7, 'fetch-22': 8, 'fetch 22': 8,
            'grime and punishment': 9, 'mothering heights': 10,
            'twenty thousand fleas': 11, 'scarlet shedder': 12, 'big jim begins': 13,
        }
        for keyword, order in known_titles.items():
            if keyword in title_lower: return order
        return 99
    
    def is_mikroi_kyrioi_series(series_name):
        series_lower = str(series_name).lower()
        return 'μικροί κύριοι' in series_lower or 'μικρές κυρίες' in series_lower or 'mr. men' in series_lower or 'little miss' in series_lower
    
    def get_mikroi_kyrioi_order(title):
        title_lower = str(title).lower()
        match = re.search(r'(?:μικροί κύριοι|μικρές κυρίες|mr\.?\s*men|little miss)[^0-9]*(\d{1,3})', title_lower)
        if match: return int(match.group(1))
        return 99 

    def is_box_set(title):
        title_lower = str(title).lower()
        box_keywords = ['box set', 'boxset', 'box-set', 'κασετίνα', 'συλλογή', 'collection', 
                        'βαλιτσάκι', 'σετ βιβλίων', 'book set', 'complete series', 'books 1-']
        return any(kw in title_lower for kw in box_keywords)
    
    def is_complete_box_set(title):
        title_lower = str(title).lower()
        complete_keywords = ['complete', 'ολοκληρωμένη', 'πλήρης', 'all books', 'όλα τα βιβλία', 
                            'full collection', '1-7', '1-8', 'complete collection']
        return any(kw in title_lower for kw in complete_keywords)

    def get_canonical_book_name(title, orig_title=''):
        title_lower = str(title).lower().strip() if title and str(title) != 'nan' else ''
        orig_lower = ''
        if orig_title is not None and not pd.isna(orig_title):
            orig_str = str(orig_title).lower().strip()
            if orig_str and orig_str != 'nan':
                orig_lower = orig_str
        
        canonical = orig_lower if orig_lower else title_lower
        if not canonical or canonical == 'nan':
            return title_lower if title_lower and title_lower != 'nan' else ''
        
        prefixes = [
            'ο χάρι πότερ και ', 'ο χαρι ποτερ και ', 'harry potter and the ', 'harry potter and ',
            'fantastic beasts: ', 'φανταστικά ζώα: ', 'φανταστικά ζώα και ',
            'diary of a wimpy kid: ', 'diary of a wimpy kid ',
            'captain underpants: ', 'captain underpants ',
        ]
        for prefix in prefixes:
            if canonical.startswith(prefix):
                canonical = canonical[len(prefix):]
                break
        
        dm_patterns = [
            r'^adventures\s+of\s+dog\s*man\s*\d{0,2}\s*[-:]\s*',
            r'^dog\s*man\s*\d{1,2}\s*[-:]\s*',
            r'^dog\s*man\s*[-:]\s*',
            r'^dog\s*man\s+',
        ]
        for pattern in dm_patterns:
            dm_match = re.match(pattern, canonical)
            if dm_match:
                canonical = canonical[dm_match.end():]
                break
        
        edition_keywords = [
            'edition', 'έκδοση', 'illustrated', 'εικονογραφημένο', 'εικονογραφημένη',
            'collector', 'συλλεκτική', 'deluxe', 'anniversary', 'επετειακή',
            'special', 'gift', 'reissue', 'limited', 'platinum',
            'paperback', 'hardcover', 'hardback', 'softcover', 'minalima',
            'gryffindor', 'slytherin', 'hufflepuff', 'ravenclaw', 'rehearsal',
        ]
        
        paren_match = re.search(r'\s*\([^)]*(?:' + '|'.join(edition_keywords) + r')[^)]*\)\s*$', canonical)
        if paren_match: canonical = canonical[:paren_match.start()]
        
        # v28.29.7 — flexible delimiter list
        for delimiter in [' - ', ' – ', ' — ', ': ', '- ', '– ', '— ']:
            if delimiter in canonical:
                parts = canonical.split(delimiter)
                if len(parts) >= 2:
                    suffix_part = parts[-1].lower().strip()
                    words = suffix_part.split()
                    if len(words) <= 4 and any(kw in suffix_part for kw in edition_keywords):
                        canonical = delimiter.join(parts[:-1])
                        break
        
        for suffix in [' cd', ' audiobook', ' audio book', ' mp3', ' audio']:
            if canonical.endswith(suffix):
                canonical = canonical[:-len(suffix)]
                break
        
        for suffix in [' pb', ' hb', ' (pb)', ' (hb)']:
            if canonical.endswith(suffix):
                canonical = canonical[:-len(suffix)]
                break
        
        marketing_paren = re.search(r'\s*\([^)]*(?:new|graphic novel|book|novel)[^)]*\)\s*$', canonical, re.IGNORECASE)
        if marketing_paren: canonical = canonical[:marketing_paren.start()]
        
        for suffix in [': a graphic novel', ' - a graphic novel', ': graphic novel']:
            if canonical.endswith(suffix):
                canonical = canonical[:-len(suffix)]
                break
        
        if canonical.startswith('dog man: '): canonical = canonical[9:]
        canonical = canonical.replace("'", "'").replace("'", "'").replace("`", "'")
        
        return canonical.strip()

    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    used_materials.add(tm)
    
    t_series_raw = trigger.get('Σειρά βιβλίου', None)
    if t_series_raw is None:
        for col in trigger.index:
            if 'σειρά' in col.lower() or 'series' in col.lower():
                t_series_raw = trigger.get(col, None)
                break
    t_series = str(t_series_raw).strip() if t_series_raw is not None and not pd.isna(t_series_raw) else ''
    
    t_age = str(trigger.get('Ηλικία', '')).strip()
    t_rec_age = str(trigger.get('Προτεινόμενη Ηλικία', '')).strip()
    t_cover = str(trigger.get('Εξώφυλλο', '')).strip()
    t_dims = str(trigger.get('Διαστάσεις', '')).strip()
    t_illus = str(trigger.get('Λεπτομέρειες εικονογράφησης', '')).strip()
    t_pub_series = str(trigger.get('Εκδοτική Σειρά', '')).strip()
    t_orig_title = str(trigger.get('Τίτλος πρωτοτύπου', '')).strip()
    t_hierarchy = str(trigger.get('Hierarchy', '')).strip()
    t_level2 = str(trigger.get('Level 2', '')).strip()
    t_brand = str(trigger.get('Brand', '')).strip()
    t_price = parse_euro_price(trigger.get('LIST PRICE', 0))
    
    effective_age = t_age if t_age and t_age != 'nan' and t_age != '0' else t_rec_age
    allowed_ages = get_allowed_ages(effective_age)
    has_series = is_valid_series(t_series)
    
    trigger_is_box_set = is_box_set(tt)
    trigger_is_complete_box = trigger_is_box_set and is_complete_box_set(tt)
    trigger_canonical = get_canonical_book_name(tt, t_orig_title)
    used_titles.add(trigger_canonical)
    
    box_status = "complete box set" if trigger_is_complete_box else ("partial box set" if trigger_is_box_set else "individual book")
    diag.append(("0. Trigger", "", f"Series: '{t_series}' (valid: {has_series}), Age: '{effective_age}', Type: {box_status}"))
    
    # ══════════════════════════════════════════════════════════
    # PRIORITY 1: SERIES ENGINE (Up to 10 slots)
    # ══════════════════════════════════════════════════════════
    series_notes = ["=== PRIORITY 1: SERIES ENGINE ==="]
    series_count = 0
    max_series = 10
    
    if trigger_is_complete_box:
        series_notes.append("⚠ Complete box set detected - skipping series books")
        diag.append(("1. Series Engine", 0, "Skipped (complete box set)"))
    elif has_series:
        books_only = df_all[df_all['Level 1'] == 'Books'].copy()
        series_col = 'Σειρά βιβλίου'
        if series_col not in books_only.columns:
            for col in books_only.columns:
                if 'σειρά' in col.lower() or 'series' in col.lower():
                    series_col = col
                    break
        
        if series_col in books_only.columns:
            series_books = books_only[books_only[series_col].fillna('').astype(str).str.strip() == t_series].copy()
        else:
            series_books = pd.DataFrame()
        
        series_books = series_books[series_books['Material'] != tm]
        series_books['_canonical'] = series_books.apply(lambda r: get_canonical_book_name(r.get('Title', ''), r.get('Τίτλος πρωτοτύπου', '')), axis=1)
        series_books = series_books[series_books['_canonical'] != trigger_canonical]
        
        if not trigger_is_box_set and not series_books.empty:
            series_books = series_books[~series_books['Title'].apply(is_box_set)]
            
        if t_level2:
            series_books = series_books[series_books['Level 2'] == t_level2]
            
        def is_novelty_language(title):
            novelty_langs = ['(ancient greek)', '(latin)', '(irish)', '(scots)', '(welsh)', '(gaelic)', '(αρχαία ελληνικά)', '(λατινικά)']
            return any(lang in str(title).lower() for lang in novelty_langs)
        if not series_books.empty:
            series_books = series_books[~series_books['Title'].apply(is_novelty_language)]
            
        def is_audiobook(title):
            audiobook_keywords = [' cd', ' audiobook', ' audio book', ' mp3', 'ηχητικό', 'ακουστικό']
            return any(kw in str(title).lower() for kw in audiobook_keywords)
        if not series_books.empty:
            series_books = series_books[~series_books['Title'].apply(is_audiobook)]
            
        def get_edition_line(title):
            title_lower = str(title).lower()
            for house in ['gryffindor', 'slytherin', 'hufflepuff', 'ravenclaw']:
                if house in title_lower: return 'house_' + house
            edition_patterns = [
                ('minalima', 'minalima'), ('illustrated', 'illustrated'), ('20th anniversary', 'anniversary_20'),
                ('25th anniversary', 'anniversary_25'), ('anniversary', 'anniversary'), ('deluxe', 'deluxe'),
                ('collector', 'collector'), ('special', 'special'), ('gift', 'gift'),
            ]
            for pattern, line in edition_patterns:
                if pattern in title_lower: return line
            return 'standard'
        
        trigger_edition_line = get_edition_line(tt)
        
        # Base Format Score
        if not series_books.empty:
            series_books['Format_Score'] = 0
            series_books['_edition_line'] = series_books['Title'].apply(get_edition_line)
            series_books.loc[series_books['_edition_line'] == trigger_edition_line, 'Format_Score'] += 5000
            
            if t_cover and t_cover != 'nan' and t_cover != '0' and 'Εξώφυλλο' in series_books.columns:
                series_books.loc[series_books['Εξώφυλλο'].fillna('').astype(str).str.strip() == t_cover, 'Format_Score'] += 1000
            if t_dims and t_dims != 'nan' and t_dims != 'NaN' and 'Διαστάσεις' in series_books.columns:
                series_books.loc[series_books['Διαστάσεις'].fillna('').astype(str).str.strip() == t_dims, 'Format_Score'] += 1000
            if t_pub_series and t_pub_series != 'nan' and t_pub_series != '0' and 'Εκδοτική Σειρά' in series_books.columns:
                series_books.loc[series_books['Εκδοτική Σειρά'].fillna('').astype(str).str.strip() == t_pub_series, 'Format_Score'] += 1000
            if t_illus and t_illus != 'nan' and t_illus != '0' and 'Λεπτομέρειες εικονογράφησης' in series_books.columns:
                series_books.loc[series_books['Λεπτομέρειες εικονογράφησης'].fillna('').astype(str).str.strip() == t_illus, 'Format_Score'] += 1000
                
            series_books['Final_Score'] = SERIES_BOOST + series_books['Format_Score']
            if 'AVAILABILITY' in series_books.columns:
                series_books.loc[series_books['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST

        # 🟢 PREPARE PUBLISH DATE & SALES 
        if 'Ημερ/νία έκδοσης' in series_books.columns:
            series_books['Pub_Date'] = pd.to_datetime(series_books['Ημερ/νία έκδοσης'], errors='coerce')
        else:
            series_books['Pub_Date'] = pd.NaT
            
        t_pub_date = trigger.get('Ημερ/νία έκδοσης', '')
        t_pub_date_parsed = pd.to_datetime(t_pub_date, errors='coerce') if t_pub_date else pd.NaT
        
        if 'Sum of Sales' in series_books.columns:
            series_books['Sales_Score'] = pd.to_numeric(series_books['Sum of Sales'], errors='coerce').fillna(0)
        else:
            # Fallback to history frequency if Sum of Sales isn't attached
            tcust = df_history[df_history['Material']==tm]['customerEmail'].unique() if not df_history.empty else []
            bw = df_history[(df_history['customerEmail'].isin(tcust))&(df_history['Material']!=tm)] if not df_history.empty else pd.DataFrame()
            fdf = bw['Material'].value_counts().reset_index() if not bw.empty else pd.DataFrame(columns=['NID', 'Frequency'])
            if not fdf.empty:
                fdf.columns = ['NID', 'Frequency']
                series_books = series_books.merge(fdf, left_on='Material', right_on='NID', how='left')
                series_books['Sales_Score'] = series_books['Frequency'].fillna(0)
            else:
                series_books['Sales_Score'] = 0

        # 🟢 DETERMINE LOGIC (Ordered/Mixed vs Standalone)
        t_series_lower = t_series.lower()
        if is_harry_potter_series(t_series) or is_dog_man_series(t_series) or is_mikroi_kyrioi_series(t_series):
            order_logic = 'Ordered'
        else:
            order_logic = SERIES_ORDER_MAP.get(t_series_lower, 'Standalone')
        
        series_notes.append(f"Logic applied: {order_logic}")

        series_books_sorted = pd.DataFrame()
        
        if trigger_is_box_set and not trigger_is_complete_box:
            box_sets_in_series = series_books[series_books['Title'].apply(is_box_set)]
            if not box_sets_in_series.empty:
                for _, row in box_sets_in_series.head(2).iterrows():
                    if row['Material'] not in used_materials:
                        row_copy = row.copy()
                        row_copy['Assigned_Slot'] = series_count + 1
                        row_copy['Slot_Role'] = 'Other Box Set'
                        row_copy['Item_Rank'] = 1
                        all_recs.append(row_copy)
                        used_materials.add(row['Material'])
                        used_titles.add(get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', '')))
                        series_count += 1
                series_notes.append(f"Added other box sets: {series_count}")

        if series_count < max_series and not series_books.empty:
            if order_logic in ['Ordered', 'Mixed']:
                if is_harry_potter_series(t_series):
                    trigger_order = get_hp_order(tt)
                    series_books['_order'] = series_books['Title'].apply(get_hp_order)
                elif is_dog_man_series(t_series):
                    trigger_order = get_dog_man_order(tt)
                    series_books['_order'] = series_books['Title'].apply(get_dog_man_order)
                elif is_mikroi_kyrioi_series(t_series):
                    trigger_order = get_mikroi_kyrioi_order(tt)
                    series_books['_order'] = series_books['Title'].apply(get_mikroi_kyrioi_order)
                else:
                    trigger_order = t_pub_date_parsed
                    series_books['_order'] = series_books['Pub_Date']
                
                if pd.isna(trigger_order):
                    series_books_sorted = series_books.sort_values(['_order', 'Final_Score'], ascending=[True, False])
                else:
                    books_after = series_books[series_books['_order'] > trigger_order].sort_values(['_order', 'Final_Score'], ascending=[True, False])
                    books_before = series_books[series_books['_order'] < trigger_order].sort_values(['_order', 'Final_Score'], ascending=[True, False])
                    books_same = series_books[series_books['_order'] == trigger_order].sort_values('Final_Score', ascending=False)
                    series_books_sorted = pd.concat([books_after, books_before, books_same])
            else:
                # Standalone Logic: Sales first, fallback to Publish Date (Newest)
                series_books_sorted = series_books.sort_values(['Sales_Score', 'Pub_Date', 'Final_Score'], ascending=[False, False, False])
            
            for _, row in series_books_sorted.iterrows():
                if series_count >= max_series: break
                row_canonical = get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', ''))
                
                if row['Material'] not in used_materials and row_canonical not in used_titles:
                    row_copy = row.copy()
                    row_copy['Assigned_Slot'] = series_count + 1
                    row_copy['Slot_Role'] = 'Series Book'
                    row_copy['Item_Rank'] = 1
                    all_recs.append(row_copy)
                    used_materials.add(row['Material'])
                    used_titles.add(row_canonical)
                    series_count += 1
            
            series_notes.append(f"Filled {series_count} Series Books slots.")
    else:
        series_notes.append("No valid series found on trigger")
    
    slot_notes[1] = series_notes
    diag.append(("1. Series Engine", series_count, f"Filled {series_count} slots"))
    
    # ══════════════════════════════════════════════════════════
    # PRIORITY 2: CROSS-SELL (Toys & Stationery)
    # ══════════════════════════════════════════════════════════
    crosssell_notes = ["=== PRIORITY 2: CROSS-SELL ==="]
    crosssell_count = 0
    max_crosssell = min(4, 10 - series_count)
    crosssell_notes.append(f"Cross-sell: {max_crosssell} slots available")
    
    if max_crosssell > 0:
        toys = df_all[df_all['Level 1'] == 'Toys'].copy()
        stationery = df_all[df_all['Level 1'] == 'Stationery'].copy()
        
        age_bracket_str = get_age_bracket(t_age)
        age_bracket = int(age_bracket_str.replace('BRACKET_', '')) if 'BRACKET_' in age_bracket_str else 5
        def get_allowed_toy_ages(bracket):
            if bracket == 1: return ['0+ μηνών', '0+ ετών', '3+ μηνών', '5+ μηνών', '6+ μηνών', '']
            elif bracket == 2: return ['6+ μηνών', '9+ μηνών', '12+ μηνών', '1+ ετών', '']
            elif bracket == 3: return ['9+ μηνών', '12+ μηνών', '1+ ετών', '1.5+ ετών', '24+ μηνών', '2+ ετών', '']
            elif bracket == 4: return ['1.5+ ετών', '24+ μηνών', '2+ ετών', '3+ ετών', '']
            elif bracket == 5: return ['3+ ετών', '4+ ετών', '5+ ετών', '6+ ετών', '7+ ετών', '8+ ετών', '']
            elif bracket == 6: return ['6+ ετών', '7+ ετών', '8+ ετών', '9+ ετών', '10+ ετών', '11+ ετών', '12+ ετών', '13+ ετών', '14+ ετών', '']
            elif bracket == 7: return ['10+ ετών', '11+ ετών', '12+ ετών', '13+ ετών', '14+ ετών', '15+ ετών', '16+ ετών', '17+ ετών', '18+ ετών', '']
            return ['']
        bracket_allowed_ages = get_allowed_toy_ages(age_bracket)
        
        def detect_gender(trigger_row, series_name, title, hierarchy):
            series_lower = str(series_name).lower().strip()
            if series_lower in SERIES_GENDER_MAP: return SERIES_GENDER_MAP[series_lower]
            gender_field = str(trigger_row.get('Φύλο', '')).lower().strip()
            if gender_field:
                if any(x in gender_field for x in ['κορίτσι', 'girl', 'θηλυκό', 'female']): return 'girl'
                elif any(x in gender_field for x in ['αγόρι', 'boy', 'αρσενικό', 'male']): return 'boy'
            hier_lower = str(hierarchy).lower()
            if any(x in hier_lower for x in ['barbie', 'princess', 'πριγκίπισσα']): return 'girl'
            text = (str(series_name) + ' ' + str(title)).lower()
            girl_keywords = ['fairy', 'magic', 'princess', 'rainbow', 'unicorn', 'ballerina', 'barbie', 'frozen', 'elsa', 'anna', 'mermaid', 'kitty', 'doll', 'sparkle', 'glitter', 'flower', 'νεράιδα', 'πριγκίπισσα', 'κούκλα']
            boy_keywords = ['quest', 'warrior', 'beast', 'dragon', 'dinosaur', 'dino', 'monster', 'ninja', 'pirate', 'superhero', 'hero', 'battle', 'fight', 'soldier', 'robot', 'car', 'truck', 'spider-man', 'batman', 'marvel', 'avengers', 'star wars', 'minecraft', 'pokemon', 'δεινόσαυρος', 'πειρατής', 'ήρωας']
            if any(kw in text for kw in girl_keywords): return 'girl'
            elif any(kw in text for kw in boy_keywords): return 'boy'
            return 'neutral'
        
        detected_gender = detect_gender(trigger, t_series, tt, t_hierarchy)
        
        def get_hierarchy_category(hierarchy):
            hier_lower = str(hierarchy).lower()
            if any(x in hier_lower for x in ['ζωγραφικη', 'χειροτεχνι', 'αυτοκολλητ', 'δραστηριοτητ', 'τεχνη', 'μουσικ']): return 'arts'
            elif any(x in hier_lower for x in ['εφευρεσ', 'πειραμ', 'αστρονομ', 'φυσικ', 'χημ', 'βιολογ', 'επιστημ', 'τεχνολογ', 'γνωσ', 'εγκυκλοπαιδ', 'περιβαλλον', 'οικολογ', 'ζωα', 'ιστορ', 'γεωγραφ', 'ατλαντ', 'μυθολογ']): return 'stem'
            elif any(x in hier_lower for x in ['προσχολικ', 'χρωματα', 'σχηματα', 'αντιθετ', 'αναγνωση', 'γραφη']): return 'preschool'
            elif any(x in hier_lower for x in ['λογοτεχν', 'παραμυθ', 'μυθ', 'κομικ', 'χιουμορ', 'παιδικ']): return 'fiction'
            elif any(x in hier_lower for x in ['παζλ', 'σπαζοκεφαλ', 'αινιγμ', 'παιχνιδ', 'διαδραστικ']): return 'activity'
            return 'general'
        
        hierarchy_category = get_hierarchy_category(t_hierarchy)
        
        adult_brands = ['moleskine', 'leuchtturm', 'rhodia', 'field notes', 'midori']
        def is_adult_brand(title, brand=''):
            text = (str(title) + ' ' + str(brand)).lower()
            return any(ab in text for ab in adult_brands)
        stationery = stationery[~stationery.apply(lambda r: is_adult_brand(r.get('Title', ''), r.get('Brand', '')), axis=1)]
        
        adult_toy_hierarchies = ['TECHNIC', 'LEGO ICONS', 'ICONS', 'CREATOR EXPERT', 'ARCHITECTURE', 'LEGO ART', 'IDEAS', 'BOTANICS', 'LEGO BOTANICAL']
        toys = toys[~toys['Hierarchy'].str.upper().str.strip().isin([h.upper() for h in adult_toy_hierarchies])]
        
        if 'Προτεινόμενη Ηλικία' in toys.columns:
            if age_bracket <= 5: 
                toys = toys[toys['Προτεινόμενη Ηλικία'].fillna('').astype(str).str.strip().isin(bracket_allowed_ages)]
            else: 
                toys = toys[toys['Προτεινόμενη Ηλικία'].fillna('').astype(str).str.strip().isin(bracket_allowed_ages) | (toys['Προτεινόμενη Ηλικία'].fillna('') == '') | (toys['Προτεινόμενη Ηλικία'].fillna('').astype(str) == '0')]
        
        def toy_matches_gender(title, brand, gender):
            text = (str(title) + ' ' + str(brand)).lower()
            if gender == 'girl':
                boy_only = ['spider-man', 'batman', 'avengers', 'marvel', 'dinosaur', 'dino', 'monster truck', 'transformers', 'ninja', 'nerf', 'army', 'soldier']
                return not any(b in text for b in boy_only)
            elif gender == 'boy':
                girl_only = ['barbie', 'princess', 'frozen', 'elsa', 'anna', 'fairy', 'unicorn', 'my little pony', 'hello kitty', 'ballerina']
                return not any(g in text for g in girl_only)
            return True
        
        def stationery_matches_gender(title, brand, gender):
            text = (str(title) + ' ' + str(brand)).lower()
            if gender == 'girl':
                boy_only = ['spider-man', 'batman', 'avengers', 'marvel', 'dinosaur', 'cars', 'minecraft']
                return not any(b in text for b in boy_only)
            elif gender == 'boy':
                girl_only = ['barbie', 'princess', 'frozen', 'fairy', 'unicorn', 'hello kitty']
                return not any(g in text for g in girl_only)
            return True
        
        toys['Final_Score'] = 0
        stationery['Final_Score'] = 0
        if 'AVAILABILITY' in toys.columns: toys.loc[toys['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST
        if 'AVAILABILITY' in stationery.columns: stationery.loc[stationery['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST
        
        if has_series:
            for idx in toys.index:
                if ip_matches(t_series, str(toys.loc[idx, 'Brand']) if 'Brand' in toys.columns else '', str(toys.loc[idx, 'Ήρωες Παιχνιδιών']) if 'Ήρωες Παιχνιδιών' in toys.columns else '') or normalize_ip_name(t_series) in normalize_ip_name(str(toys.loc[idx, 'Title']) if 'Title' in toys.columns else ''):
                    toys.loc[idx, 'Final_Score'] += SMART_BOOST * 5
            for idx in stationery.index:
                if ip_matches(t_series, str(stationery.loc[idx, 'Brand']) if 'Brand' in stationery.columns else '', str(stationery.loc[idx, 'Ήρωες Παιχνιδιών']) if 'Ήρωες Παιχνιδιών' in stationery.columns else '') or normalize_ip_name(t_series) in normalize_ip_name(str(stationery.loc[idx, 'Title']) if 'Title' in stationery.columns else ''):
                    stationery.loc[idx, 'Final_Score'] += SMART_BOOST * 5
                    
        # Cross-Sell Slot 1: IP Toy or Age-Appropriate Fallback
        if crosssell_count < max_crosssell:
            item1_found = False
            ip_toys = toys[toys['Final_Score'] >= SMART_BOOST * 5].copy()
            if not ip_toys.empty:
                selected = get_rotated_selection(ip_toys, tm, 'ip_toy', n=1)
                if not selected.empty:
                    best = selected.iloc[0]
                    if best['Material'] not in used_materials:
                        row_copy = best.copy()
                        row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                        row_copy['Slot_Role'] = 'Cross-Sell: IP Toy'
                        row_copy['Item_Rank'] = 1
                        all_recs.append(row_copy)
                        used_materials.add(best['Material'])
                        crosssell_count += 1
                        item1_found = True
            
            if not item1_found:
                if age_bracket <= 4:
                    plush = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL['plush'])].copy()
                    plush = plush[plush.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                    if not plush.empty:
                        selected = get_rotated_selection(plush, tm, 'plush', n=1)
                        if not selected.empty:
                            best = selected.iloc[0]
                            if best['Material'] not in used_materials:
                                row_copy = best.copy()
                                row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                row_copy['Slot_Role'] = 'Cross-Sell: Plush'
                                row_copy['Item_Rank'] = 1
                                all_recs.append(row_copy)
                                used_materials.add(best['Material'])
                                crosssell_count += 1
                                item1_found = True
                elif age_bracket == 5 and not item1_found:
                    if detected_gender == 'girl':
                        dolls = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('dolls', []))].copy()
                        dolls = dolls[dolls.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                        if not dolls.empty:
                            selected = get_rotated_selection(dolls, tm, 'dolls', n=1)
                            if not selected.empty:
                                best = selected.iloc[0]
                                if best['Material'] not in used_materials:
                                    row_copy = best.copy()
                                    row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                    row_copy['Slot_Role'] = 'Cross-Sell: Doll'
                                    row_copy['Item_Rank'] = 1
                                    all_recs.append(row_copy)
                                    used_materials.add(best['Material'])
                                    crosssell_count += 1
                                    item1_found = True
                    else:
                        figures = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('action_figures', []))].copy()
                        figures = figures[figures.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                        if not figures.empty:
                            selected = get_rotated_selection(figures, tm, 'figures', n=1)
                            if not selected.empty:
                                best = selected.iloc[0]
                                if best['Material'] not in used_materials:
                                    row_copy = best.copy()
                                    row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                    row_copy['Slot_Role'] = 'Cross-Sell: Action Figure'
                                    row_copy['Item_Rank'] = 1
                                    all_recs.append(row_copy)
                                    used_materials.add(best['Material'])
                                    crosssell_count += 1
                                    item1_found = True
                elif age_bracket >= 6 and not item1_found:
                    games = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('board_puzzles', []))].copy()
                    games = games[games.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                    if not games.empty:
                        selected = get_rotated_selection(games, tm, 'games', n=1)
                        if not selected.empty:
                            best = selected.iloc[0]
                            if best['Material'] not in used_materials:
                                row_copy = best.copy()
                                row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                row_copy['Slot_Role'] = 'Cross-Sell: Board Game'
                                row_copy['Item_Rank'] = 1
                                all_recs.append(row_copy)
                                used_materials.add(best['Material'])
                                crosssell_count += 1
                                item1_found = True
                if not item1_found:
                    plush = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL['plush'])].copy()
                    plush = plush[plush.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                    if not plush.empty:
                        selected = get_rotated_selection(plush, tm, 'plush_fallback', n=1)
                        if not selected.empty:
                            best = selected.iloc[0]
                            if best['Material'] not in used_materials:
                                row_copy = best.copy()
                                row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                row_copy['Slot_Role'] = 'Cross-Sell: Plush'
                                row_copy['Item_Rank'] = 1
                                all_recs.append(row_copy)
                                used_materials.add(best['Material'])
                                crosssell_count += 1

        # Cross-Sell Slot 2: Hierarchy-Based Creative
        if crosssell_count < max_crosssell:
            item2_found = False
            if hierarchy_category == 'arts' and not item2_found:
                arts = stationery[stationery['Hierarchy'].isin(STATIONERY_HIERARCHIES_ACTUAL.get('arts_crafts', []))].copy()
                arts = arts[arts.apply(lambda r: stationery_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not arts.empty:
                    selected = get_rotated_selection(arts, tm, 'arts_direct', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Arts Supplies'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1
                            item2_found = True
            if hierarchy_category == 'fiction' and not item2_found:
                building = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('building', []))].copy()
                building = building[building.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not building.empty:
                    selected = get_rotated_selection(building, tm, 'building', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Building Set'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1
                            item2_found = True
            if hierarchy_category == 'stem' and not item2_found:
                educational = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('creative', []))].copy()
                educational = educational[educational.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not educational.empty:
                    selected = get_rotated_selection(educational, tm, 'educational', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Educational'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1
                            item2_found = True
            if not item2_found:
                if age_bracket <= 6:
                    paper = stationery[stationery['Hierarchy'].str.contains('ΜΠΛΟΚ|ΧΑΡΤ', case=False, na=False)].copy()
                    paper = paper[paper.apply(lambda r: stationery_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                    if not paper.empty:
                        selected = get_rotated_selection(paper, tm, 'paper', n=1)
                        if not selected.empty:
                            best = selected.iloc[0]
                            if best['Material'] not in used_materials:
                                row_copy = best.copy()
                                row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                row_copy['Slot_Role'] = 'Cross-Sell: Drawing Paper'
                                row_copy['Item_Rank'] = 1
                                all_recs.append(row_copy)
                                used_materials.add(best['Material'])
                                crosssell_count += 1
                                item2_found = True
                else:
                    squish = toys[toys['Title'].str.contains('SQUISHMALLOW|SQUISH', case=False, na=False)].copy()
                    if not squish.empty:
                        selected = get_rotated_selection(squish, tm, 'squish', n=1)
                        if not selected.empty:
                            best = selected.iloc[0]
                            if best['Material'] not in used_materials:
                                row_copy = best.copy()
                                row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                                row_copy['Slot_Role'] = 'Cross-Sell: Squishmallow'
                                row_copy['Item_Rank'] = 1
                                all_recs.append(row_copy)
                                used_materials.add(best['Material'])
                                crosssell_count += 1

        # Cross-Sell Slot 3: Puzzles/Games
        if crosssell_count < max_crosssell:
            item3_found = False
            if hierarchy_category == 'activity' and not item3_found:
                puzzles = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('board_puzzles', []))].copy()
                puzzles = puzzles[puzzles.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not puzzles.empty:
                    selected = get_rotated_selection(puzzles, tm, 'puzzles_activity', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Puzzle'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1
                            item3_found = True
            if not item3_found:
                puzzles = toys[toys['Hierarchy'].isin(TOY_HIERARCHIES_ACTUAL.get('board_puzzles', []))].copy()
                puzzles = puzzles[puzzles.apply(lambda r: toy_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not puzzles.empty:
                    selected = get_rotated_selection(puzzles, tm, 'puzzles_fallback', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Puzzle'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1

        # Cross-Sell Slot 4: Lifestyle
        if crosssell_count < max_crosssell:
            item4_found = False
            if age_bracket <= 6:
                lifestyle = stationery[stationery['Hierarchy'].str.contains('ΠΑΓΟΥΡ|ΦΑΓΗΤΟΔΟΧ', case=False, na=False)].copy()
                lifestyle = lifestyle[lifestyle.apply(lambda r: stationery_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not lifestyle.empty:
                    selected = get_rotated_selection(lifestyle, tm, 'waterbottle', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Water Bottle'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1
                            item4_found = True
            else:
                lifestyle = stationery[stationery['Hierarchy'].str.contains('ΣΗΜΕΙΩΜΑΤ', case=False, na=False)].copy()
                lifestyle = lifestyle[lifestyle.apply(lambda r: stationery_matches_gender(r.get('Title',''), r.get('Brand',''), detected_gender), axis=1)]
                if not lifestyle.empty:
                    selected = get_rotated_selection(lifestyle, tm, 'notebook', n=1)
                    if not selected.empty:
                        best = selected.iloc[0]
                        if best['Material'] not in used_materials:
                            row_copy = best.copy()
                            row_copy['Assigned_Slot'] = series_count + crosssell_count + 1
                            row_copy['Slot_Role'] = 'Cross-Sell: Notebook'
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(best['Material'])
                            crosssell_count += 1
                            item4_found = True
    
    slot_notes[2] = crosssell_notes
    diag.append(("2. Cross-Sell", crosssell_count, f"Filled {crosssell_count} slots"))
    
    # ══════════════════════════════════════════════════════════
    # PRIORITY 3: CATEGORY DISCOVERY (Fill remaining slots)
    # ══════════════════════════════════════════════════════════
    discovery_notes = ["=== PRIORITY 3: CATEGORY DISCOVERY ==="]
    total_filled = series_count + crosssell_count
    remaining = 10 - total_filled
    discovery_count = 0
    
    if not trigger_is_complete_box and remaining > 0:
        books_only = df_all[df_all['Level 1'] == 'Books'].copy()
        
        # Priority A: HP Spinoffs (keep hardcoded feature)
        if has_series and is_harry_potter_series(t_series):
            series_col = 'Σειρά βιβλίου'
            if series_col in books_only.columns:
                hp_all = books_only[books_only[series_col].fillna('').astype(str).str.strip() == t_series].copy()
                if t_level2: hp_all = hp_all[hp_all['Level 2'] == t_level2]
                hp_all['_hp_order'] = hp_all['Title'].apply(get_hp_order)
                spinoffs = hp_all[hp_all['_hp_order'] > 7].copy()
                spinoffs = spinoffs[~spinoffs['Material'].isin(used_materials)]
                spinoffs = spinoffs[spinoffs['Material'] != tm]
                if not trigger_is_box_set: spinoffs = spinoffs[~spinoffs['Title'].apply(is_box_set)]
                
                if not spinoffs.empty:
                    spinoffs['Final_Score'] = 0
                    if 'AVAILABILITY' in spinoffs.columns:
                        spinoffs.loc[spinoffs['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST
                    spinoffs = spinoffs.sort_values('Final_Score', ascending=False)
                    for _, row in spinoffs.iterrows():
                        if discovery_count >= remaining: break
                        row_canonical = get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', ''))
                        if row['Material'] not in used_materials and row_canonical not in used_titles:
                            row_copy = row.copy()
                            row_copy['Assigned_Slot'] = total_filled + discovery_count + 1
                            row_copy['Slot_Role'] = 'Explore Series' 
                            row_copy['Item_Rank'] = 1
                            all_recs.append(row_copy)
                            used_materials.add(row['Material'])
                            used_titles.add(row_canonical)
                            discovery_count += 1
        
        remaining_after_spinoffs = remaining - discovery_count
        
        # Priority B: Same category/hierarchy
        if remaining_after_spinoffs > 0:
            discovery_pool = books_only[books_only['Hierarchy'] == t_hierarchy].copy()
            discovery_pool = discovery_pool[~discovery_pool['Material'].isin(used_materials)]
            discovery_pool = discovery_pool[discovery_pool['Material'] != tm]
            if t_level2: discovery_pool = discovery_pool[discovery_pool['Level 2'] == t_level2]
            
            discovery_pool['_canonical'] = discovery_pool.apply(lambda r: get_canonical_book_name(r.get('Title', ''), r.get('Τίτλος πρωτοτύπου', '')), axis=1)
            discovery_pool = discovery_pool[discovery_pool['_canonical'] != trigger_canonical]
            discovery_pool = discovery_pool[~discovery_pool['_canonical'].isin(used_titles)]
            
            if not trigger_is_box_set: discovery_pool = discovery_pool[~discovery_pool['Title'].apply(is_box_set)]
            
            if 'Ηλικία' in discovery_pool.columns and allowed_ages:
                discovery_pool = discovery_pool[discovery_pool['Ηλικία'].fillna('').astype(str).str.strip().isin(allowed_ages) | (discovery_pool['Ηλικία'].fillna('') == '') | (discovery_pool['Ηλικία'].fillna('').astype(str) == '0')]
            
            if 'Sum of Sales' in discovery_pool.columns:
                discovery_pool['Sales_Score'] = pd.to_numeric(discovery_pool['Sum of Sales'], errors='coerce').fillna(0)
            else:
                tcust = df_history[df_history['Material']==tm]['customerEmail'].unique() if not df_history.empty else []
                bw = df_history[(df_history['customerEmail'].isin(tcust))&(df_history['Material']!=tm)] if not df_history.empty else pd.DataFrame()
                fdf = bw['Material'].value_counts().reset_index() if not bw.empty else pd.DataFrame(columns=['NID', 'Frequency'])
                if not fdf.empty:
                    fdf.columns = ['NID', 'Frequency']
                    discovery_pool = discovery_pool.merge(fdf, left_on='Material', right_on='NID', how='left')
                    discovery_pool['Sales_Score'] = discovery_pool['Frequency'].fillna(0)
                else:
                    discovery_pool['Sales_Score'] = 0
            
            discovery_pool['Final_Score'] = 0
            if 'AVAILABILITY' in discovery_pool.columns:
                discovery_pool.loc[discovery_pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST
            
            discovery_pool = discovery_pool.sort_values(['Sales_Score', 'Final_Score'], ascending=[False, False])
            discovery_notes.append(f"Sorting discovery pool by Sales (Best Sellers) and Availability.")
            
            for _, row in discovery_pool.head(remaining_after_spinoffs).iterrows():
                row_canonical = get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', ''))
                if row['Material'] not in used_materials and row_canonical not in used_titles:
                    row_copy = row.copy()
                    row_copy['Assigned_Slot'] = total_filled + discovery_count + 1
                    row_copy['Slot_Role'] = 'Category Discovery'
                    row_copy['Item_Rank'] = 1
                    all_recs.append(row_copy)
                    used_materials.add(row['Material'])
                    used_titles.add(row_canonical)
                    discovery_count += 1
    
    slot_notes[3] = discovery_notes
    diag.append(("3. Discovery", discovery_count, f"Filled {discovery_count} slots"))
    diag.append(("TOTAL", series_count + crosssell_count + discovery_count, f"out of 10"))
    
    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        recs_df = recs_df.sort_values('Assigned_Slot').reset_index(drop=True)
        return recs_df, diag, slot_notes, recs_df
    else:
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═════════════════════════════════════════════════════════════════════════════
# 🟢 v28.29 — UNIVERSAL BOOKS ENGINE (Kids / Greek / International)
# ═════════════════════════════════════════════════════════════════════════════
#
# This is a books-only carousel engine using the two-set slot allocation
# (see BOOKS_V2_CATEGORIES doc block earlier in the file for the slot rule
# and design rationale).
#
# Selection logic per slot type:
#   • SAME_SERIES — IDENTICAL to the previous Kids Books engine's Priority-1
#     series stage. All edition/format bonuses preserved (cover, dimensions,
#     pub-series, illustration), all hardcoded ordering rules preserved (HP
#     book order, Dog Man book order, Mikroi Kyrioi numeric order), and the
#     external Ordered/Mixed/Standalone map from kids_books_categories.xlsx
#     is honored.
#   • OTHER_BOOKS:
#       — KIDS path: same as the previous engine's Priority-3 Category
#         Discovery — same Hierarchy + Level 2 + allowed-ages filter + sort
#         by Sum of Sales.
#       — ADULT path (Greek/Int): same Hierarchy + Level 2 hard filter, then
#         layer DEEP-SPEC boosts on top of sales:
#             same Author    → +80,000  (strongest — author affinity)
#             same Publisher → +30,000
#             same Theme     → +20,000  (Θέμα Βιβλίου)
#             same Language  →  +5,000  (Γλώσσα Γραφής)
#         Final ranking: by composite score desc, then by Sum of Sales desc
#         as tiebreaker.
#
# The function reuses helpers defined inside `run_books_engine` (canonical
# name, HP / Dog Man / Mikroi Kyrioi orderings, box-set detection, etc.) by
# redefining them locally — they're not module-level so we can't import them.
# This keeps v28.28 behavior bit-perfect for the SAME_SERIES side.
# ═════════════════════════════════════════════════════════════════════════════
def run_books_v2_engine(trigger, df_pool, df_history, category_key):
    """
    Universal books engine (v28.29) — Kids Books / Greek Books / International Books.
    
    Parameters
    ----------
    trigger : pd.Series
        The trigger book row (with all its attribute columns).
    df_pool : pd.DataFrame
        The candidate pool. Should already be filtered to the category's
        Level 2 (i.e. for Kids Books → the 'Books' sheet rows with
        Level 2 ∈ KIDS_BOOKS_LEVEL2; for Greek/Int → the respective new sheet).
    df_history : pd.DataFrame
        Customer purchase history (fallback for sales when 'Sum of Sales' is
        missing). Kept for parity with run_books_engine.
    category_key : str
        One of "Kids Books", "Greek Books", "International Books".
    """
    config = BOOKS_V2_CATEGORIES[category_key]
    diag = []
    slot_notes = {}
    all_recs = []
    used_materials = set()
    used_titles = set()
    
    # ──────────────────────────────────────────────────────────
    # 🟢 LOAD GENDER & ORDER CATEGORIES FROM FILE (kids only)
    # ──────────────────────────────────────────────────────────
    # The kids_books_categories.xlsx file ships an Ordered/Mixed/Standalone
    # column per series — required to drive the series-engine sort. Adult
    # books fall back to Standalone (sales-first) by default.
    SERIES_GENDER_MAP = {}
    SERIES_ORDER_MAP = {}
    if config["is_kids"]:
        try:
            import os
            gender_file_paths = [
                '/mnt/user-data/uploads/kids_books_categories.xlsx',
                'kids_books_categories.xlsx',
                '/mount/src/recommender-poc/kids_books_categories.xlsx',
            ]
            for gf_path in gender_file_paths:
                if os.path.exists(gf_path):
                    gender_df = pd.read_excel(gf_path)
                    for _, row in gender_df.iterrows():
                        series_name = str(row.get('Series Name', '')).strip()
                        category = str(row.get('Category', 'Universal')).strip()
                        order_type = str(row.iloc[2]).strip() if len(row) > 2 else 'Standalone'
                        if series_name:
                            series_lower = series_name.lower()
                            if category == 'Girls-leaning':
                                SERIES_GENDER_MAP[series_lower] = 'girl'
                            elif category == 'Boys-leaning':
                                SERIES_GENDER_MAP[series_lower] = 'boy'
                            else:
                                SERIES_GENDER_MAP[series_lower] = 'neutral'
                            SERIES_ORDER_MAP[series_lower] = order_type
                    break
        except Exception:
            pass
    
    # ──────────────────────────────────────────────────────────
    # 🟢 HARDCODED ORDERINGS (apply to all 3 categories — series authors are
    # universal; Harry Potter is found in both Kids and Int)
    # ──────────────────────────────────────────────────────────
    HARRY_POTTER_ORDER = {
        'φιλοσοφική λίθος': 1, 'philosopher': 1, "sorcerer's stone": 1,
        'μυστικό δωμάτιο': 2, 'chamber of secrets': 2, 'κάμαρα': 2,
        'αιχμάλωτος': 3, 'αζκαμπάν': 3, 'prisoner of azkaban': 3,
        'κύπελλο φωτιάς': 4, 'goblet of fire': 4, 'κύπελλο της φωτιάς': 4,
        'τάγμα του φοίνικα': 5, 'order of the phoenix': 5, 'φοίνικα': 5,
        'ημίαιμος πρίγκιψ': 6, 'half-blood prince': 6, 'ημίαιμος': 6,
        'κλήροι του θανάτου': 7, 'deathly hallows': 7, 'θανάτου': 7,
        'καταραμένο παιδί': 8, 'cursed child': 8,
        'φανταστικά ζώα': 9, 'fantastic beasts': 9,
        'quidditch': 10, 'κουίντιτς': 10,
        'beedle': 11, 'μπιντλ': 11,
    }
    
    def get_hp_order(title):
        title_lower = str(title).lower()
        for keyword, order in HARRY_POTTER_ORDER.items():
            if keyword in title_lower: return order
        return 99
    
    def is_harry_potter_series(series_name):
        series_lower = str(series_name).lower()
        return 'harry potter' in series_lower or 'χάρι πότερ' in series_lower or 'χαρι ποτερ' in series_lower
    
    def is_dog_man_series(series_name):
        return 'dog man' in str(series_name).lower()
    
    def get_dog_man_order(title):
        title_lower = str(title).lower()
        match = re.search(r'dog\s*man\s*(\d{1,2})(?:\s*[-:]|\s|$)', title_lower)
        if match: return int(match.group(1))
        if 'dog man' in title_lower and not re.search(r'dog\s*man\s*\d', title_lower):
            adv_match = re.search(r'adventures\s*of\s*dog\s*man\s*(\d)', title_lower)
            if adv_match: return int(adv_match.group(1))
            return 1
        known_titles = {
            'a tale of two kitties': 3, 'tale of two kitties': 3,
            'lord of the fleas': 5, 'brawl of the wild': 6,
            'for whom the ball rolls': 7, 'fetch-22': 8, 'fetch 22': 8,
            'grime and punishment': 9, 'mothering heights': 10,
            'twenty thousand fleas': 11, 'scarlet shedder': 12, 'big jim begins': 13,
        }
        for keyword, order in known_titles.items():
            if keyword in title_lower: return order
        return 99
    
    def is_mikroi_kyrioi_series(series_name):
        series_lower = str(series_name).lower()
        return ('μικροί κύριοι' in series_lower or 'μικρές κυρίες' in series_lower
                or 'mr. men' in series_lower or 'little miss' in series_lower)
    
    def get_mikroi_kyrioi_order(title):
        title_lower = str(title).lower()
        match = re.search(r'(?:μικροί κύριοι|μικρές κυρίες|mr\.?\s*men|little miss)[^0-9]*(\d{1,3})', title_lower)
        if match: return int(match.group(1))
        return 99
    
    def is_box_set(title):
        title_lower = str(title).lower()
        box_keywords = ['box set', 'boxset', 'box-set', 'κασετίνα', 'συλλογή', 'collection',
                        'βαλιτσάκι', 'σετ βιβλίων', 'book set', 'complete series', 'books 1-']
        return any(kw in title_lower for kw in box_keywords)
    
    def is_complete_box_set(title):
        title_lower = str(title).lower()
        complete_keywords = ['complete', 'ολοκληρωμένη', 'πλήρης', 'all books', 'όλα τα βιβλία',
                            'full collection', '1-7', '1-8', 'complete collection']
        return any(kw in title_lower for kw in complete_keywords)
    
    def get_canonical_book_name(title, orig_title=''):
        title_lower = str(title).lower().strip() if title and str(title) != 'nan' else ''
        orig_lower = ''
        if orig_title is not None and not pd.isna(orig_title):
            orig_str = str(orig_title).lower().strip()
            if orig_str and orig_str != 'nan':
                orig_lower = orig_str
        canonical = orig_lower if orig_lower else title_lower
        if not canonical or canonical == 'nan':
            return title_lower if title_lower and title_lower != 'nan' else ''
        
        prefixes = [
            'ο χάρι πότερ και ', 'ο χαρι ποτερ και ', 'harry potter and the ', 'harry potter and ',
            'fantastic beasts: ', 'φανταστικά ζώα: ', 'φανταστικά ζώα και ',
            'diary of a wimpy kid: ', 'diary of a wimpy kid ',
            'captain underpants: ', 'captain underpants ',
        ]
        for prefix in prefixes:
            if canonical.startswith(prefix):
                canonical = canonical[len(prefix):]
                break
        
        dm_patterns = [
            r'^adventures\s+of\s+dog\s*man\s*\d{0,2}\s*[-:]\s*',
            r'^dog\s*man\s*\d{1,2}\s*[-:]\s*',
            r'^dog\s*man\s*[-:]\s*',
            r'^dog\s*man\s+',
        ]
        for pattern in dm_patterns:
            dm_match = re.match(pattern, canonical)
            if dm_match:
                canonical = canonical[dm_match.end():]
                break
        
        edition_keywords = [
            'edition', 'έκδοση', 'illustrated', 'εικονογραφημένο', 'εικονογραφημένη',
            'collector', 'συλλεκτική', 'deluxe', 'anniversary', 'επετειακή',
            'special', 'gift', 'reissue', 'limited', 'platinum',
            'paperback', 'hardcover', 'hardback', 'softcover', 'minalima',
            'gryffindor', 'slytherin', 'hufflepuff', 'ravenclaw', 'rehearsal',
        ]
        paren_match = re.search(r'\s*\([^)]*(?:' + '|'.join(edition_keywords) + r')[^)]*\)\s*$', canonical)
        if paren_match: canonical = canonical[:paren_match.start()]
        
        # v28.29.7 — Catch dash/colon-delimited edition suffixes even when
        # the catalog title has no leading space before the delimiter
        # (e.g. "Dune- Deluxe Edition" — dash glued to "Dune"). Order
        # matters: longer / more specific delimiters first, then less
        # specific ones. A break after a successful strip prevents
        # double-stripping.
        for delimiter in [' - ', ' – ', ' — ', ': ', '- ', '– ', '— ']:
            if delimiter in canonical:
                parts = canonical.split(delimiter)
                if len(parts) >= 2:
                    suffix_part = parts[-1].lower().strip()
                    words = suffix_part.split()
                    if len(words) <= 4 and any(kw in suffix_part for kw in edition_keywords):
                        canonical = delimiter.join(parts[:-1])
                        break
        for suffix in [' cd', ' audiobook', ' audio book', ' mp3', ' audio']:
            if canonical.endswith(suffix):
                canonical = canonical[:-len(suffix)]
                break
        for suffix in [' pb', ' hb', ' (pb)', ' (hb)']:
            if canonical.endswith(suffix):
                canonical = canonical[:-len(suffix)]
                break
        marketing_paren = re.search(r'\s*\([^)]*(?:new|graphic novel|book|novel)[^)]*\)\s*$', canonical, re.IGNORECASE)
        if marketing_paren: canonical = canonical[:marketing_paren.start()]
        for suffix in [': a graphic novel', ' - a graphic novel', ': graphic novel']:
            if canonical.endswith(suffix):
                canonical = canonical[:-len(suffix)]
                break
        if canonical.startswith('dog man: '): canonical = canonical[9:]
        canonical = canonical.replace("'", "'").replace("'", "'").replace("`", "'")
        canonical = canonical.strip()
        
        # v28.29.3 — collapse literal title doubling FIRST (before article
        # strip — "The X The X" must be detected with the articles intact).
        # Some catalog rows have "The Fellowship of the Ring The Fellowship
        # of the Ring" — same string repeated. Detect "X X" patterns where
        # the first half equals the second half and keep one copy.
        if len(canonical) > 10:
            half = len(canonical) // 2
            for split_pt in (half, half - 1, half + 1):
                left = canonical[:split_pt].strip()
                right = canonical[split_pt:].strip()
                if left and left == right:
                    canonical = left
                    break
        
        # v28.29.3 — strip leading articles so "Two Towers" ↔ "The Two Towers"
        # and "Hobbit" ↔ "The Hobbit" canonicalize to the same key.
        for art in ('the ', 'a ', 'an ', 'ο ', 'η ', 'το ', 'οι ', 'τα ', 'ένα ', 'μια ', 'έναν '):
            if canonical.startswith(art):
                canonical = canonical[len(art):]
                break
        
        return canonical.strip()
    
    # ──────────────────────────────────────────────────────────
    # TRIGGER ATTRIBUTES
    # ──────────────────────────────────────────────────────────
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    used_materials.add(tm)
    
    t_series_raw = trigger.get('Σειρά βιβλίου', None)
    if t_series_raw is None:
        for col in trigger.index:
            if 'σειρά' in col.lower() or 'series' in col.lower():
                t_series_raw = trigger.get(col, None)
                break
    t_series = str(t_series_raw).strip() if t_series_raw is not None and not pd.isna(t_series_raw) else ''
    
    t_age = str(trigger.get('Ηλικία', '')).strip()
    t_rec_age = str(trigger.get('Προτεινόμενη Ηλικία', '')).strip()
    t_cover = str(trigger.get('Εξώφυλλο', '')).strip()
    t_dims = str(trigger.get('Διαστάσεις', '')).strip()
    t_illus = str(trigger.get('Λεπτομέρειες εικονογράφησης', '')).strip()
    t_pub_series = str(trigger.get('Εκδοτική Σειρά', '')).strip()
    t_orig_title = str(trigger.get('Τίτλος πρωτοτύπου', '')).strip()
    t_hierarchy = str(trigger.get('Hierarchy', '')).strip()
    t_level2 = str(trigger.get('Level 2', '')).strip()
    t_price = parse_euro_price(trigger.get('LIST PRICE', 0))
    
    # Adult-books-only deep-spec attributes
    t_author_field = trigger.get('Συγγραφέας', '')
    t_authors_set = _books_v2_extract_authors_set(t_author_field) if config["use_author_signal"] else set()
    t_publisher = _books_v2_norm(trigger.get('Εκδότης', '')) if config["use_publisher_signal"] else ''
    t_theme = _books_v2_norm(trigger.get('Θέμα Βιβλίου', '')) if config["use_theme_signal"] else ''
    t_language = _books_v2_normalize_language(trigger.get('Γλώσσα Γραφής', '')) if config["use_language_signal"] else ''
    
    # v28.29.1 — shelf-cohesion signals (apply to all 3 categories)
    t_pub_series_norm = _books_v2_norm(t_pub_series) if config.get("use_pub_series_signal") else ''
    t_dims_norm = _books_v2_normalize_dimensions(t_dims) if config.get("use_dimensions_signal") else ''
    t_cover_norm = _books_v2_normalize_cover(t_cover) if config.get("use_cover_signal") else ''
    
    effective_age = t_age if t_age and t_age != 'nan' and t_age != '0' else t_rec_age
    allowed_ages = get_allowed_ages(effective_age) if config["apply_age_filter"] else []
    has_series = is_valid_series(t_series)
    
    trigger_is_box_set = is_box_set(tt)
    trigger_is_complete_box = trigger_is_box_set and is_complete_box_set(tt)
    trigger_canonical = get_canonical_book_name(tt, t_orig_title)
    used_titles.add(trigger_canonical)
    
    box_status = "complete box set" if trigger_is_complete_box else ("partial box set" if trigger_is_box_set else "individual book")
    diag.append(("0. Trigger", "", f"Cat: {category_key} | Series: '{t_series}' (valid: {has_series}) | Type: {box_status}"))
    if config["is_kids"]:
        diag.append(("   Trigger (kids)", "", f"Age: '{effective_age}' | Hierarchy: '{t_hierarchy}'"))
    else:
        author_preview = ", ".join(sorted(t_authors_set)[:3]) if t_authors_set else "—"
        diag.append(("   Trigger (adult)", "", f"Hierarchy: '{t_hierarchy}' | Author: '{author_preview}' | Publisher: '{t_publisher}' | Theme: '{t_theme[:50]}' | Lang: '{t_language}'"))
    # v28.29.1 — shelf-cohesion signals (applies to all 3 categories)
    diag.append(("   Trigger (format)", "",
                 f"Pub.Series: '{t_pub_series_norm}' | Dims: '{t_dims_norm}' | Cover: '{t_cover_norm}'"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 1 — BUILD SAME-SERIES POOL (ranked)
    # ──────────────────────────────────────────────────────────
    series_notes = ["=== STEP 1: SAME-SERIES POOL ==="]
    series_pool = pd.DataFrame()
    
    if trigger_is_complete_box:
        series_notes.append("⚠ Complete box set detected → skipping series pool (Other Books only)")
    elif has_series:
        # Hard filter: same Level 1 (always 'Books') and category Level 2
        books_only = df_pool[
            (df_pool['Level 1'] == 'Books') &
            (df_pool['Level 2'].isin(config["level2_filter"]))
        ].copy()
        
        # Find the series column dynamically (handles trailing-whitespace variants)
        series_col = 'Σειρά βιβλίου'
        if series_col not in books_only.columns:
            for col in books_only.columns:
                if 'σειρά' in col.lower() or 'series' in col.lower():
                    series_col = col
                    break
        
        if series_col in books_only.columns:
            sp = books_only[books_only[series_col].fillna('').astype(str).str.strip() == t_series].copy()
        else:
            sp = pd.DataFrame()
        
        # Exclude the trigger itself + same canonical (different editions of same book)
        sp = sp[sp['Material'] != tm]
        if not sp.empty:
            sp['_canonical'] = sp.apply(lambda r: get_canonical_book_name(r.get('Title', ''), r.get('Τίτλος πρωτοτύπου', '')), axis=1)
            sp = sp[sp['_canonical'] != trigger_canonical]
        
        # v28.29.3 — BOX SET RULE
        # If the trigger IS a box set (partial or complete), restrict the SS
        # pool to OTHER box sets only — the individual books are almost
        # certainly contained in the trigger box set itself, so recommending
        # them as separates is redundant and misleading. The remaining SS
        # candidates are: alternate-edition sibling box sets (e.g. hardcover
        # version of a paperback box set), or extended/complete box sets
        # that contain books beyond the original.
        if trigger_is_box_set and not sp.empty:
            sp_box = sp[sp['Title'].apply(is_box_set)]
            series_notes.append(
                f"⚙ Trigger IS a box set → SS pool restricted to sibling box sets "
                f"({len(sp)} → {len(sp_box)} candidates). Individual books from this "
                f"series are excluded (assumed contained in the box set).")
            sp = sp_box
        elif not trigger_is_box_set and not sp.empty:
            # Original v28.x behavior — exclude box sets when trigger isn't one
            sp = sp[~sp['Title'].apply(is_box_set)]
        
        # If trigger has an explicit Level 2 (always set after the filter above), keep it
        if t_level2 and not sp.empty:
            sp = sp[sp['Level 2'] == t_level2]
        
        # Optional kids-only quality filters
        if config["apply_novelty_lang_filter"] and not sp.empty:
            def is_novelty_language(title):
                novelty_langs = ['(ancient greek)', '(latin)', '(irish)', '(scots)', '(welsh)',
                                 '(gaelic)', '(αρχαία ελληνικά)', '(λατινικά)']
                return any(lang in str(title).lower() for lang in novelty_langs)
            sp = sp[~sp['Title'].apply(is_novelty_language)]
        if config["apply_audiobook_filter"] and not sp.empty:
            def is_audiobook(title):
                audiobook_keywords = [' cd', ' audiobook', ' audio book', ' mp3', 'ηχητικό', 'ακουστικό']
                return any(kw in str(title).lower() for kw in audiobook_keywords)
            sp = sp[~sp['Title'].apply(is_audiobook)]
        
        # v28.29.7 — Capture the "catalog truth" SS total BEFORE the cover
        # filter runs. The slot allocator should use this stable number so
        # the SS-slot count is determined by series depth as the user sees
        # it — not shrunken by the cover filter. Without this, a 7-book
        # series whose cover filter trims to 4 candidates would have the
        # allocator switch from "7 books → 4 SS slots" to "5 books → 3 SS
        # slots", leaving one valid candidate sitting unused.
        n_series_total_for_allocation = (len(sp) + 1) if has_series else 0
        
        # v28.29.3 — COVER HARD FILTER on SS pool. The trigger cover
        # (soft/hard/board) acts as a preference for the same-series pool.
        # v28.29.6 — Per user clarification: "if you have mixed then just
        # show mixed it's okay ... if we can't showcase only soft or hard,
        # the important thing is to show the series."
        #
        # The new rule: enforce cover purity ONLY when the matching-cover
        # pool is LARGE ENOUGH to fill all the SS slots the series would
        # be allocated. Otherwise, fall back to ALL same-series siblings
        # (mixed covers) so the carousel shows the full series depth the
        # image rule promises.
        #
        # Required SS slot count is computed from the slot allocator using
        # the pre-cover-filter catalog count — that's the natural "this
        # series deserves N SS slots" figure.
        ss_cover_filter_applied = False
        if config.get("use_cover_signal") and t_cover_norm and not sp.empty and 'Εξώφυλλο' in sp.columns:
            # Pre-cover-filter catalog math
            pre_filter_n_avail = len(sp)
            pre_filter_n_total = (pre_filter_n_avail + 1) if has_series else 0
            
            # Required SS slot count for THIS series depth (image rule)
            if trigger_is_box_set:
                # Box-set triggers use the specialized allocation: min(n_avail, 2)
                required_ss_slots = min(pre_filter_n_avail, 2)
            else:
                hypothetical_plan = allocate_book_slots(pre_filter_n_total)
                required_ss_slots = sum(1 for s in hypothetical_plan if s == 'SAME_SERIES')
            
            sp_cover_match = sp[sp['Εξώφυλλο'].apply(_books_v2_normalize_cover) == t_cover_norm]
            
            if len(sp_cover_match) >= required_ss_slots and required_ss_slots > 0:
                series_notes.append(
                    f"⚙ Cover hard filter '{t_cover_norm}' applied to SS pool "
                    f"({pre_filter_n_avail} → {len(sp_cover_match)} candidates; "
                    f"≥ {required_ss_slots} required SS slots → enforce cover purity)")
                sp = sp_cover_match
                ss_cover_filter_applied = True
            elif not sp.empty:
                # Matching pool too small to fill the SS slots this series
                # warrants. Per user rule, show ALL siblings (mixed covers)
                # so the carousel preserves series visibility.
                series_notes.append(
                    f"⚙ Cover filter '{t_cover_norm}' would leave only {len(sp_cover_match)} "
                    f"matching siblings (< {required_ss_slots} required SS slots) — "
                    f"showing MIXED siblings ({pre_filter_n_avail} kept) for series visibility")
        
        # ── Scoring layer (format/cover/edition bonuses) ──
        def get_edition_line(title):
            title_lower = str(title).lower()
            for house in ['gryffindor', 'slytherin', 'hufflepuff', 'ravenclaw']:
                if house in title_lower: return 'house_' + house
            edition_patterns = [
                ('minalima', 'minalima'), ('illustrated', 'illustrated'), ('20th anniversary', 'anniversary_20'),
                ('25th anniversary', 'anniversary_25'), ('anniversary', 'anniversary'), ('deluxe', 'deluxe'),
                ('collector', 'collector'), ('special', 'special'), ('gift', 'gift'),
            ]
            for pattern, line in edition_patterns:
                if pattern in title_lower: return line
            return 'standard'
        trigger_edition_line = get_edition_line(tt)
        
        if not sp.empty:
            sp['Format_Score'] = 0
            sp['_edition_line'] = sp['Title'].apply(get_edition_line)
            sp.loc[sp['_edition_line'] == trigger_edition_line, 'Format_Score'] += 5000
            if t_cover and t_cover != 'nan' and t_cover != '0' and 'Εξώφυλλο' in sp.columns:
                sp.loc[sp['Εξώφυλλο'].fillna('').astype(str).str.strip() == t_cover, 'Format_Score'] += 1000
            if t_dims and t_dims != 'nan' and t_dims != 'NaN' and 'Διαστάσεις' in sp.columns:
                sp.loc[sp['Διαστάσεις'].fillna('').astype(str).str.strip() == t_dims, 'Format_Score'] += 1000
            if t_pub_series and t_pub_series != 'nan' and t_pub_series != '0' and 'Εκδοτική Σειρά' in sp.columns:
                sp.loc[sp['Εκδοτική Σειρά'].fillna('').astype(str).str.strip() == t_pub_series, 'Format_Score'] += 1000
            if t_illus and t_illus != 'nan' and t_illus != '0' and 'Λεπτομέρειες εικονογράφησης' in sp.columns:
                sp.loc[sp['Λεπτομέρειες εικονογράφησης'].fillna('').astype(str).str.strip() == t_illus, 'Format_Score'] += 1000
            sp['Final_Score'] = SERIES_BOOST + sp['Format_Score']
            if 'AVAILABILITY' in sp.columns:
                sp.loc[sp['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST
            
            # Pub date + sales for sort
            if 'Ημερ/νία έκδοσης' in sp.columns:
                sp['Pub_Date'] = pd.to_datetime(sp['Ημερ/νία έκδοσης'], errors='coerce')
            else:
                sp['Pub_Date'] = pd.NaT
            t_pub_date = trigger.get('Ημερ/νία έκδοσης', '')
            t_pub_date_parsed = pd.to_datetime(t_pub_date, errors='coerce') if t_pub_date else pd.NaT
            
            if 'Sum of Sales' in sp.columns:
                sp['Sales_Score'] = pd.to_numeric(sp['Sum of Sales'], errors='coerce').fillna(0)
            else:
                # Sales fallback via customer history — matches v28.28 run_books_engine
                tcust = df_history[df_history['Material']==tm]['customerEmail'].unique() if not df_history.empty else []
                bw = df_history[(df_history['customerEmail'].isin(tcust))&(df_history['Material']!=tm)] if not df_history.empty else pd.DataFrame()
                fdf = bw['Material'].value_counts().reset_index() if not bw.empty else pd.DataFrame(columns=['NID', 'Frequency'])
                if not fdf.empty:
                    fdf.columns = ['NID', 'Frequency']
                    sp = sp.merge(fdf, left_on='Material', right_on='NID', how='left')
                    sp['Sales_Score'] = sp['Frequency'].fillna(0)
                else:
                    sp['Sales_Score'] = 0
            
            # Ordered / Mixed / Standalone — file-driven, with hardcoded
            # overrides for HP / Dog Man / Mikroi Kyrioi.
            t_series_lower = t_series.lower()
            if is_harry_potter_series(t_series) or is_dog_man_series(t_series) or is_mikroi_kyrioi_series(t_series):
                order_logic = 'Ordered'
            else:
                # Adult books default to 'Standalone' (sales-first) unless the
                # kids file explicitly maps the series. For kids categories
                # the file is the authority.
                order_logic = SERIES_ORDER_MAP.get(t_series_lower, 'Standalone')
            series_notes.append(f"Series order logic: {order_logic}")
            
            series_pool = pd.DataFrame()
            
            # If the trigger is a partial box set, surface OTHER box sets first
            # (collectors wanting completion). Matches v28.28 behavior.
            if trigger_is_box_set and not trigger_is_complete_box:
                box_sets_in_series = sp[sp['Title'].apply(is_box_set)]
                if not box_sets_in_series.empty:
                    series_pool = pd.concat([series_pool, box_sets_in_series.head(2)])
                    series_notes.append(f"Pre-pushed {len(box_sets_in_series.head(2))} sibling box set(s)")
            
            # Apply ordering for the remaining series books
            if order_logic in ['Ordered', 'Mixed']:
                if is_harry_potter_series(t_series):
                    trigger_order = get_hp_order(tt)
                    sp['_order'] = sp['Title'].apply(get_hp_order)
                elif is_dog_man_series(t_series):
                    trigger_order = get_dog_man_order(tt)
                    sp['_order'] = sp['Title'].apply(get_dog_man_order)
                elif is_mikroi_kyrioi_series(t_series):
                    trigger_order = get_mikroi_kyrioi_order(tt)
                    sp['_order'] = sp['Title'].apply(get_mikroi_kyrioi_order)
                else:
                    trigger_order = t_pub_date_parsed
                    sp['_order'] = sp['Pub_Date']
                
                if pd.isna(trigger_order):
                    sp_sorted = sp.sort_values(['_order', 'Final_Score'], ascending=[True, False])
                else:
                    books_after  = sp[sp['_order'] > trigger_order].sort_values(['_order', 'Final_Score'], ascending=[True, False])
                    books_before = sp[sp['_order'] < trigger_order].sort_values(['_order', 'Final_Score'], ascending=[True, False])
                    books_same   = sp[sp['_order'] == trigger_order].sort_values('Final_Score', ascending=False)
                    sp_sorted = pd.concat([books_after, books_before, books_same])
            else:
                # Standalone: sales-first, pub-date fallback
                sp_sorted = sp.sort_values(['Sales_Score', 'Pub_Date', 'Final_Score'], ascending=[False, False, False])
            
            series_pool = pd.concat([series_pool, sp_sorted]).drop_duplicates(subset='Material', keep='first')
            
            # Dedup by canonical title — different editions of the same book collapse
            seen_canonicals = {trigger_canonical}
            keep_mask = []
            for _, r in series_pool.iterrows():
                c = get_canonical_book_name(r.get('Title', ''), r.get('Τίτλος πρωτοτύπου', ''))
                if c in seen_canonicals or r['Material'] in used_materials:
                    keep_mask.append(False)
                else:
                    keep_mask.append(True)
                    seen_canonicals.add(c)
            series_pool = series_pool[keep_mask]
            series_notes.append(f"Same-series pool size (post-dedup): {len(series_pool)}")
    else:
        series_notes.append("No valid series on trigger → all slots will be Other Books")
    
    n_series_available = len(series_pool)
    slot_notes[1] = series_notes
    diag.append(("1. Same-Series Pool", n_series_available, f"{n_series_available} unique candidates"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 2 — BUILD OTHER-BOOKS POOL (ranked)
    # ──────────────────────────────────────────────────────────
    other_notes = ["=== STEP 2: OTHER-BOOKS POOL ==="]
    other_pool = pd.DataFrame()
    
    # Hard filter: same Level 1 + Level 2 (within category)
    other_pool = df_pool[
        (df_pool['Level 1'] == 'Books') &
        (df_pool['Level 2'].isin(config["level2_filter"]))
    ].copy()
    
    # Exclude trigger itself + series books already selected
    other_pool = other_pool[~other_pool['Material'].isin(used_materials)]
    other_pool = other_pool[other_pool['Material'] != tm]
    if not series_pool.empty:
        other_pool = other_pool[~other_pool['Material'].isin(series_pool['Material'])]
    
    # v28.29.3 — BOX SET RULE (OB-pool side).
    # When trigger IS a box set, also exclude OTHER individual books in the
    # same series from the OB pool. Those individuals are presumed contained
    # in the trigger box set and the user explicitly does not want them
    # showcased "again as separate ones". Sibling BOX SETS in the same series
    # are kept in series_pool (handled by the SS-pool box-set rule above).
    if trigger_is_box_set and t_series and not other_pool.empty:
        series_col_ob = 'Σειρά βιβλίου'
        if series_col_ob in other_pool.columns:
            same_series_mask = other_pool[series_col_ob].fillna('').astype(str).str.strip() == t_series
            same_series_individuals_mask = same_series_mask & (~other_pool['Title'].apply(is_box_set))
            n_excluded = int(same_series_individuals_mask.sum())
            if n_excluded > 0:
                other_pool = other_pool[~same_series_individuals_mask]
                other_notes.append(
                    f"⚙ Trigger IS a box set → excluded {n_excluded} same-series individual "
                    f"books from OB pool (presumed contained in the box set)")
    
    # Same Hierarchy hard filter (genre-aligned discovery). Falls back to the
    # whole Level-2 pool if the trigger's hierarchy yields too few candidates.
    if t_hierarchy and not other_pool.empty:
        same_hier = other_pool[other_pool['Hierarchy'] == t_hierarchy].copy()
        if len(same_hier) >= 10:
            other_pool = same_hier
            other_notes.append(f"Hierarchy filter: '{t_hierarchy}' → {len(other_pool)} candidates")
        else:
            other_notes.append(f"Hierarchy filter would leave {len(same_hier)} candidates (<10) — kept full Level 2 pool ({len(other_pool)})")
    
    # Canonical-title dedup (drops different editions of the same work)
    if not other_pool.empty:
        other_pool['_canonical'] = other_pool.apply(
            lambda r: get_canonical_book_name(r.get('Title', ''), r.get('Τίτλος πρωτοτύπου', '')), axis=1)
        other_pool = other_pool[other_pool['_canonical'] != trigger_canonical]
        other_pool = other_pool[~other_pool['_canonical'].isin(used_titles)]
    
    # Box-set exclusion when trigger isn't a box set (kids parity)
    if not trigger_is_box_set and not other_pool.empty:
        other_pool = other_pool[~other_pool['Title'].apply(is_box_set)]
    
    # Kids-only filters: age bracket + novelty languages + audiobooks
    if config["apply_age_filter"] and not other_pool.empty and 'Ηλικία' in other_pool.columns and allowed_ages:
        other_pool = other_pool[
            other_pool['Ηλικία'].fillna('').astype(str).str.strip().isin(allowed_ages)
            | (other_pool['Ηλικία'].fillna('') == '')
            | (other_pool['Ηλικία'].fillna('').astype(str) == '0')
        ]
    if config["apply_novelty_lang_filter"] and not other_pool.empty:
        def _is_novelty_lang(title):
            novelty_langs = ['(ancient greek)', '(latin)', '(irish)', '(scots)', '(welsh)',
                             '(gaelic)', '(αρχαία ελληνικά)', '(λατινικά)']
            return any(lang in str(title).lower() for lang in novelty_langs)
        other_pool = other_pool[~other_pool['Title'].apply(_is_novelty_lang)]
    if config["apply_audiobook_filter"] and not other_pool.empty:
        def _is_audiobook(title):
            return any(kw in str(title).lower() for kw in [' cd', ' audiobook', ' audio book', ' mp3', 'ηχητικό', 'ακουστικό'])
        other_pool = other_pool[~other_pool['Title'].apply(_is_audiobook)]
    
    # v28.29.3 — COVER HARD FILTER on OB pool. Same rule as the SS pool:
    # paperback trigger → only paperback recommendations; hardcover trigger
    # → only hardcover. Graceful fallback if filtering would leave too few
    # candidates to fill the carousel (need ≥10).
    ob_cover_filter_applied = False
    if config.get("use_cover_signal") and t_cover_norm and not other_pool.empty and 'Εξώφυλλο' in other_pool.columns:
        other_cover_match = other_pool[other_pool['Εξώφυλλο'].apply(_books_v2_normalize_cover) == t_cover_norm]
        if len(other_cover_match) >= 10:
            other_notes.append(
                f"⚙ Cover hard filter '{t_cover_norm}' applied to OB pool "
                f"({len(other_pool)} → {len(other_cover_match)} candidates)")
            other_pool = other_cover_match
            ob_cover_filter_applied = True
        else:
            other_notes.append(
                f"⚙ Cover filter '{t_cover_norm}' would leave {len(other_cover_match)} "
                f"candidates (<10) — kept OB pool unfiltered ({len(other_pool)})")
    
    # Sales (always primary signal)
    if not other_pool.empty:
        if 'Sum of Sales' in other_pool.columns:
            other_pool['Sales_Score'] = pd.to_numeric(other_pool['Sum of Sales'], errors='coerce').fillna(0)
        else:
            tcust = df_history[df_history['Material']==tm]['customerEmail'].unique() if not df_history.empty else []
            bw = df_history[(df_history['customerEmail'].isin(tcust))&(df_history['Material']!=tm)] if not df_history.empty else pd.DataFrame()
            fdf = bw['Material'].value_counts().reset_index() if not bw.empty else pd.DataFrame(columns=['NID', 'Frequency'])
            if not fdf.empty:
                fdf.columns = ['NID', 'Frequency']
                other_pool = other_pool.merge(fdf, left_on='Material', right_on='NID', how='left')
                other_pool['Sales_Score'] = other_pool['Frequency'].fillna(0)
            else:
                other_pool['Sales_Score'] = 0
        
        # ── Deep-spec scoring ──
        # The hybrid formula stacks tier-specific boosts atop Sales_Score so
        # that within the same Hierarchy pool, the most specifically-relevant
        # book bubbles up. For Kids Books the author/publisher/theme/language
        # signals are off (the Books sheet doesn't have those columns), but
        # the v28.29.1 shelf-cohesion signals (Pub Series / Dimensions / Cover)
        # ARE on for kids — they leverage the existing columns and give us
        # the "HP 2024-edition look-alike" recommendations the user asked for.
        other_pool['Spec_Score'] = 0
        spec_boosts_applied = []
        
        # v28.29.1 — Publishing Series match (strongest signal; cross-narrative
        # shelf cohesion — Penguin Modern Classics, Loeb, Πυξίδα HP line, etc.)
        if config.get("use_pub_series_signal") and t_pub_series_norm and 'Εκδοτική Σειρά' in other_pool.columns:
            mask = other_pool['Εκδοτική Σειρά'].apply(_books_v2_norm) == t_pub_series_norm
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_PUB_SERIES
            spec_boosts_applied.append(f"Pub.Series (+{BOOKS_V2_S_SAME_PUB_SERIES:,}): {mask.sum()} matches")
        
        if config["use_author_signal"] and t_authors_set and 'Συγγραφέας' in other_pool.columns:
            def _author_match(field):
                cand_authors = _books_v2_extract_authors_set(field)
                return bool(cand_authors & t_authors_set)
            mask = other_pool['Συγγραφέας'].apply(_author_match)
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_AUTHOR
            spec_boosts_applied.append(f"Author (+{BOOKS_V2_S_SAME_AUTHOR:,}): {mask.sum()} matches")
        
        if config["use_publisher_signal"] and t_publisher and 'Εκδότης' in other_pool.columns:
            mask = other_pool['Εκδότης'].apply(_books_v2_norm) == t_publisher
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_PUBLISHER
            spec_boosts_applied.append(f"Publisher (+{BOOKS_V2_S_SAME_PUBLISHER:,}): {mask.sum()} matches")
        
        if config["use_theme_signal"] and t_theme and 'Θέμα Βιβλίου' in other_pool.columns:
            mask = other_pool['Θέμα Βιβλίου'].apply(_books_v2_norm) == t_theme
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_THEME
            spec_boosts_applied.append(f"Theme (+{BOOKS_V2_S_SAME_THEME:,}): {mask.sum()} matches")
        
        # v28.29.1 — Dimensions match (shelf cohesion — same face W×H)
        if config.get("use_dimensions_signal") and t_dims_norm and 'Διαστάσεις' in other_pool.columns:
            mask = other_pool['Διαστάσεις'].apply(_books_v2_normalize_dimensions) == t_dims_norm
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_DIMENSIONS
            spec_boosts_applied.append(f"Dimensions (+{BOOKS_V2_S_SAME_DIMENSIONS:,}): {mask.sum()} matches")
        
        if config["use_language_signal"] and t_language and 'Γλώσσα Γραφής' in other_pool.columns:
            mask = other_pool['Γλώσσα Γραφής'].apply(_books_v2_normalize_language) == t_language
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_LANGUAGE
            spec_boosts_applied.append(f"Language (+{BOOKS_V2_S_SAME_LANGUAGE:,}): {mask.sum()} matches")
        
        # v28.29.1 — Cover match (last-resort tiebreaker)
        # Skip when the hard filter has already enforced cover match — every
        # candidate in the pool would qualify, so the +1k boost would be a
        # universal no-op. The boost is only meaningful when the pool is
        # mixed-cover (i.e. filter relaxed via fallback).
        if (config.get("use_cover_signal") and t_cover_norm
                and not ob_cover_filter_applied
                and 'Εξώφυλλο' in other_pool.columns):
            mask = other_pool['Εξώφυλλο'].apply(_books_v2_normalize_cover) == t_cover_norm
            other_pool.loc[mask, 'Spec_Score'] += BOOKS_V2_S_SAME_COVER
            spec_boosts_applied.append(f"Cover (+{BOOKS_V2_S_SAME_COVER:,}): {mask.sum()} matches")
        
        # Availability tiebreaker
        other_pool['Avail_Score'] = 0
        if 'AVAILABILITY' in other_pool.columns:
            other_pool.loc[other_pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Avail_Score'] = BOOKS_V2_S_AVAIL_BONUS
        
        # Composite ranking: Spec tier dominates, then Sales as tiebreaker.
        # For Kids Books, Spec_Score is always 0 so this collapses to pure sales-first.
        other_pool['Combined_Score'] = other_pool['Spec_Score'] + other_pool['Avail_Score']
        other_pool = other_pool.sort_values(
            ['Combined_Score', 'Sales_Score'],
            ascending=[False, False]
        )
        
        if spec_boosts_applied:
            other_notes.append("Deep-spec boosts applied: " + " | ".join(spec_boosts_applied))
        else:
            other_notes.append("Pure sales sort (kids categories or no deep-spec data)")
        
        other_notes.append(f"Other-books pool size (post-dedup, post-filter): {len(other_pool)}")
    else:
        other_notes.append("Empty Other-Books pool after filters")
    
    slot_notes[2] = other_notes
    diag.append(("2. Other-Books Pool", len(other_pool), f"{len(other_pool)} unique candidates"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 3 — ALLOCATE SLOTS PER v28.29 TWO-SET RULE
    # ──────────────────────────────────────────────────────────
    # v28.29.4 — Slot allocation now keys off the TOTAL number of books in
    # the series (including the trigger itself), not the count of OTHER
    # books available after excluding the trigger.
    #
    # Reason: the reference image labels its rows by total series depth —
    # "4 book(s)" means "the series contains 4 books in our catalog", which
    # gives 3 OTHER books that can fill SS slots, and the image expects 3
    # SS slots in that case. Previously the engine computed
    # n_series_available (= 3 for a 4-book series, after excluding trigger)
    # and looked up the rule for "3" → 2 SS slots — off by one from the
    # image specification.
    #
    # Adjustment: n_series_total = n_series_available + 1 (when the trigger
    # has a series). For no-series triggers, total stays 0 → all OB.
    # v28.29.7 — Use the pre-cover-filter total when available so the
    # slot allocator sees the "catalog truth" series depth rather than the
    # post-filter shrunken count. Falls back to post-filter computation
    # when no cover-filter block ran (no series on trigger, or complete
    # box set path that skips the entire SS pool construction).
    try:
        n_series_total = n_series_total_for_allocation
    except NameError:
        n_series_total = (n_series_available + 1) if has_series else 0
    
    # v28.29.3 — Box-set triggers use a different allocation strategy.
    # The two-set rule was designed for individual-book triggers and gives
    # 0 SS slots when n ≤ 1 — but for box-set triggers we want sibling
    # box sets (rare, usually only 1-2 exist) surfaced at the front of the
    # carousel rather than dropped entirely. Layout for box-set triggers:
    # at most n_series_available SS slots at the front (capped at 2 — there
    # are rarely more than 2 sibling box sets), rest is OB for cross-series
    # discovery.
    if trigger_is_box_set and n_series_available > 0:
        n_box_ss = min(n_series_available, 2)
        slot_plan = (['SAME_SERIES'] * n_box_ss + ['OTHER_BOOKS'] * (10 - n_box_ss))
        alloc_label = f"BOX-SET layout: {n_box_ss} SS (sibling box sets) + {10 - n_box_ss} OB (cross-series discovery)"
    else:
        slot_plan = allocate_book_slots(n_series_total)   # v28.29.4: total, not available
        alloc_label = "v28.29 two-set rule"
    
    n_ss_slots = sum(1 for s in slot_plan if s == 'SAME_SERIES')
    n_ob_slots = 10 - n_ss_slots
    
    alloc_notes = [
        f"=== STEP 3: SLOT ALLOCATION ({alloc_label}) ===",
        f"Total books in series (incl. trigger): {n_series_total} | Other-series-books available: {n_series_available}",
        f"Front set (1-7): " + " ".join(["SS" if s == 'SAME_SERIES' else 'OB' for s in slot_plan[:7]]),
        f"Back  set (8-10): " + " ".join(["SS" if s == 'SAME_SERIES' else 'OB' for s in slot_plan[7:]]),
        f"Total SAME_SERIES slots: {n_ss_slots} | Total OTHER_BOOKS slots: {n_ob_slots}",
    ]
    slot_notes[3] = alloc_notes
    diag.append(("3. Slot Plan", f"{n_ss_slots}/{n_ob_slots}", f"SS/OB: front={slot_plan[:7].count('SAME_SERIES')}/{slot_plan[:7].count('OTHER_BOOKS')} back={slot_plan[7:].count('SAME_SERIES')}/{slot_plan[7:].count('OTHER_BOOKS')} | total-in-series={n_series_total}"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 4 — FILL THE 10 SLOTS
    # ──────────────────────────────────────────────────────────
    fill_notes = ["=== STEP 4: SLOT FILLING ==="]
    
    # v28.29.2 — Diversity rule for the Other-Books pool.
    # When the trigger's series depth is shallow (≤ 5 books TOTAL — see
    # n_series_total above), the OB pool fills 6-10 slots. Without a
    # diversity rule the engine will happily fill multiple OB slots with
    # consecutive books from the same OTHER series (e.g. trigger=standalone
    # fantasy → OB slots = books 1-4 of a single Throne-of-Glass-style
    # series). That reads as redundant in a discovery carousel.
    #
    # Rule: when n_series_total ≤ 5, enforce "at most 1 book per other
    # series" in the OB pool. Standalone titles (no Σειρά βιβλίου) are
    # exempt — each standalone is its own discovery. If the constrained
    # pool runs out (rare — usually only when the hierarchy is dominated by
    # a single mega-series), fall back to allowing duplicate-series picks.
    #
    # v28.29.4 — Switched threshold to use n_series_total (counts trigger
    # itself) for consistency with the slot-allocation rule. A series with
    # 5 total books → 4 SS-available → was previously triggering diversity
    # at the n_avail=4 ≤ 5 mark anyway. A 6-book series → 5 SS-available
    # → previously ON; now OFF (n_total=6 > 5). This matches the user's
    # spec: "if we're in 5 or below books in the series".
    diversity_enabled = (n_series_total <= 5)
    used_other_series = set()
    used_other_authors = set()   # v28.29.7 — author-based diversity
    
    if diversity_enabled:
        fill_notes.append(f"⚙ Diversity enabled (n_total_in_series={n_series_total} ≤ 5): "
                          f"at most 1 OB pick per other-series AND per other-author")
    else:
        fill_notes.append(f"⚙ Diversity OFF (n_total_in_series={n_series_total} > 5): "
                          f"unrestricted OB picks")
    
    # Materialize pools as (idx, row) lists so we can iterate multiple times
    # for fallback passes without resetting cursors.
    series_list = list(series_pool.iterrows()) if not series_pool.empty else []
    other_list  = list(other_pool.iterrows())  if not other_pool.empty  else []
    series_consumed = set()   # indices into series_list that are exhausted
    other_consumed  = set()   # indices into other_list  that are exhausted
    
    def _series_value(row):
        """Return the normalized series value of a candidate row, or '' if
        the candidate has no series."""
        val = row.get('Σειρά βιβλίου', '')
        try:
            if pd.isna(val): return ''
        except (TypeError, ValueError):
            pass
        s = str(val).strip()
        if s.lower() in ('', '0', '-', 'nan', 'n/a', 'none'):
            return ''
        return s
    
    def _author_set(row):
        """Return the set of normalized author names for a candidate row.
        Empty set if author is missing — those rows are exempt from author
        diversity (treated like standalone titles).
        
        v28.29.7 — Normalize each author name by collapsing middle initials
        / middle names so 'Sarah J. Maas' and 'Sarah Maas' match. The
        normalization takes the first word + last word of the name (after
        stripping periods and extra whitespace). This handles common
        catalog inconsistencies: 'Sarah J. Maas' / 'Sarah Maas', 'J.R.R.
        Tolkien' / 'J. R. R. Tolkien'. Pure single-name authors are
        kept as-is.
        """
        val = row.get('Συγγραφέας', '')
        try:
            if pd.isna(val): return set()
        except (TypeError, ValueError):
            pass
        raw = _books_v2_extract_authors_set(val)
        normalized = set()
        for name in raw:
            if not name: continue
            cleaned = name.lower().replace('.', ' ').strip()
            words = [w for w in cleaned.split() if w]
            if len(words) >= 2:
                normalized.add(f"{words[0]} {words[-1]}")
            elif len(words) == 1:
                normalized.add(words[0])
        return normalized
    
    def _next_series():
        """Pull the next non-dup series candidate, skipping used materials/titles."""
        for i, (_, row) in enumerate(series_list):
            if i in series_consumed: continue
            canonical = get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', ''))
            if row['Material'] in used_materials or canonical in used_titles:
                series_consumed.add(i)
                continue
            series_consumed.add(i)
            return row
        return None
    
    def _next_other(enforce_diversity):
        """Pull the next eligible other candidate.
        
        If enforce_diversity is True, skip (do NOT consume) any candidate
        that would violate diversity — either by Σειρά βιβλίου or by author.
        Author diversity (v28.29.7) is the practical fallback for cases where
        the catalog tags the same narrative series with inconsistent Σειρά
        values (e.g. "Powerless" vs "Η Αδύναμη" vs blank for three books in
        one Lauren Roberts series). Same-author books are almost always
        same-narrative-series in romance/fantasy publishing.
        
        Candidates skipped due to diversity are NOT consumed — they remain
        available for a possible fallback pass with diversity off.
        
        Books with no Σειρά βιβλίου AND no author are always eligible — each
        is its own discovery. Books with no Σειρά but a known author DO
        participate in author diversity.
        """
        for i, (_, row) in enumerate(other_list):
            if i in other_consumed: continue
            canonical = get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', ''))
            if row['Material'] in used_materials or canonical in used_titles:
                other_consumed.add(i)
                continue
            # Diversity check — series AND author
            if enforce_diversity:
                cand_series = _series_value(row)
                if cand_series and cand_series in used_other_series:
                    continue  # same series as a previous OB pick — skip
                cand_authors = _author_set(row)
                if cand_authors and (cand_authors & used_other_authors):
                    continue  # at least one author overlaps a previous OB pick
            # Accept
            other_consumed.add(i)
            cand_series = _series_value(row)
            if cand_series:
                used_other_series.add(cand_series)
            cand_authors = _author_set(row)
            if cand_authors:
                used_other_authors.update(cand_authors)
            return row
        return None
    
    for slot_idx, slot_type in enumerate(slot_plan, start=1):
        primary, fallback = ('SAME_SERIES', 'OTHER_BOOKS') if slot_type == 'SAME_SERIES' else ('OTHER_BOOKS', 'SAME_SERIES')
        
        # Try primary pool first
        if primary == 'SAME_SERIES':
            row = _next_series()
            picked_from = 'series'
        else:
            row = _next_other(enforce_diversity=diversity_enabled)
            picked_from = 'other'
            # v28.29.2 — Diversity-relaxation pass. If the constrained OB
            # pool came up empty, retry without the diversity rule before
            # falling all the way back to the SS pool.
            if row is None and diversity_enabled:
                row = _next_other(enforce_diversity=False)
                if row is not None:
                    picked_from = 'other (diversity relaxed)'
        
        # Graceful degradation: if primary pool exhausted, try fallback pool.
        # This handles edge cases like a series with 8 known books but only 5
        # in the catalog (allocator says back_ss=3, only 5 SS available so the
        # back set partially falls back to OB).
        if row is None:
            if fallback == 'SAME_SERIES':
                row = _next_series()
                picked_from = 'series (fallback from OB)'
            else:
                row = _next_other(enforce_diversity=False)
                picked_from = 'other (fallback from SS)'
        
        if row is None:
            fill_notes.append(f"Slot {slot_idx} ({slot_type}): EMPTY — both pools exhausted")
            continue
        
        # Record the recommendation
        canonical = get_canonical_book_name(row['Title'], row.get('Τίτλος πρωτοτύπου', ''))
        row_copy = row.copy()
        row_copy['Assigned_Slot'] = slot_idx
        # Slot_Role label — used by the marketing-copy lookup downstream.
        # We keep the labels that v28.28 already understands for backward compat:
        #   "Series Book" for SS slots, "Category Discovery" for OB slots.
        if 'series' in picked_from:
            row_copy['Slot_Role'] = 'Series Book'
        else:
            row_copy['Slot_Role'] = 'Category Discovery'
        row_copy['Item_Rank'] = 1
        # v28.29.3 — Bulletproof Final_Score computation. Previously OB rows
        # showed up as NaN in the dashboard because `nan or 0` evaluates to
        # nan in Python (nan is truthy), and the row.get(..., 0) default
        # only fires when the COLUMN is absent — not when it's present-but-NaN.
        # This helper handles None / NaN / missing-column uniformly.
        def _safe_num(v):
            try:
                if v is None: return 0.0
                if pd.isna(v): return 0.0
                return float(v)
            except (TypeError, ValueError):
                return 0.0
        
        ss_final = _safe_num(row_copy.get('Final_Score', None))
        if ss_final > 0:
            # SS rows: keep the existing Final_Score (SERIES_BOOST + Format_Score)
            row_copy['Final_Score'] = ss_final
        else:
            # OB rows (or any row without a SS-style Final_Score): synthesize
            # from Sales + Spec + Avail. Sales is ALWAYS counted — the user
            # explicitly wants sales in the ranking signal.
            row_copy['Final_Score'] = (
                _safe_num(row_copy.get('Sales_Score', None))
                + _safe_num(row_copy.get('Spec_Score', None))
                + _safe_num(row_copy.get('Avail_Score', None))
            )
        all_recs.append(row_copy)
        used_materials.add(row['Material'])
        used_titles.add(canonical)
        
        title_preview = str(row.get('Title', ''))[:50]
        fill_notes.append(f"Slot {slot_idx} ({slot_type}) ← {picked_from}: {title_preview}")
    
    slot_notes[4] = fill_notes
    total_filled = len(all_recs)
    diag.append(("4. Slots Filled", total_filled, f"{total_filled} of 10"))
    
    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        recs_df = recs_df.sort_values('Assigned_Slot').reset_index(drop=True)
        return recs_df, diag, slot_notes, recs_df
    else:
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═════════════════════════════════════════════════════════════
# v28.30.27 — FOREIGN LANGUAGE LEARNING ENGINE
# ═════════════════════════════════════════════════════════════
# (Config constants LL_* and helpers _ll_* are defined earlier, before the
# sidebar trigger-picker, because that picker uses them at module load time.)
def run_lang_learning_engine(trigger, df_int_school, df_kids_books):
    """Ξενόγλωσσα Εκμάθηση recommender (foreign-language learning books)."""
    diag = []
    slot_notes = {1: [], 2: [], 3: [], 4: []}

    def _safe_num(v):
        try:
            if v is None or pd.isna(v):
                return 0.0
            return float(v)
        except (TypeError, ValueError):
            return 0.0

    import numpy as _np

    # ── STEP 0 — Trigger attributes ──────────────────────────────
    tm = trigger.get('Material', None)
    tt = str(trigger.get('Title', ''))
    t_series  = str(trigger.get('Σειρά βιβλίου', '') or '').strip()
    t_level   = str(trigger.get('Επίπεδο', '') or '').strip()
    t_class   = str(trigger.get('Τάξη', '') or '').strip()
    t_lang_raw = trigger.get('Γλώσσα Γραφής', '')
    t_lang    = _ll_canon_lang(t_lang_raw) or 'en'
    t_age_lo, t_age_hi = _ll_level_to_age(t_level, t_class)

    used_materials = {tm} if tm is not None else set()

    diag.append(("0. Trigger", "", "Cluster: Foreign Language Learning"))
    diag.append(("   Trigger (attrs)", "",
                 f"Series: '{t_series or '∅'}' | Level: '{t_level or '∅'}' | "
                 f"Class: '{t_class or '∅'}' | Lang: {t_lang} | "
                 f"Kids age band: {t_age_lo}-{t_age_hi}"))

    # ── STEP 1 — SAME-SERIES + SAME-LEVEL companions ─────────────
    series_pool = pd.DataFrame()
    s1_notes = ["=== STEP 1: SAME-SERIES + SAME-LEVEL POOL ==="]
    if df_int_school is not None and not df_int_school.empty and t_series:
        cat = df_int_school.copy()
        cat['_mat_i'] = pd.to_numeric(cat['Material'], errors='coerce')
        # Same series (exact, case-insensitive)
        ser_norm = cat['Σειρά βιβλίου'].astype(str).str.strip().str.lower()
        same_series = cat[ser_norm == t_series.lower()].copy()
        # Trigger's distinguishing signals: Τάξη is the MOST specific level
        # marker (e.g. Here We Go 1/2/3 all share Επίπεδο 'A1-A2' but differ by
        # Τάξη A/B/C Class). The volume NUMBER in the title is an extra guard.
        t_vol = _ll_series_volume(tt, t_series)
        def _level_match(row):
            rl = str(row.get('Επίπεδο', '') or '').strip().lower()
            rc = str(row.get('Τάξη', '') or '').strip().lower()
            rv = _ll_series_volume(row.get('Title', ''), t_series)
            # 1) If both trigger & row have a volume number, it MUST match
            #    (this is the real "same level/year" guard within a series).
            if t_vol is not None and rv is not None:
                if rv != t_vol:
                    return False
                # volume matches — accept (same year of the course)
                return True
            # 2) Else prefer Τάξη (more granular than Επίπεδο)
            if t_class and rc:
                return rc == t_class.lower()
            # 3) Else fall back to Επίπεδο
            if t_level and rl:
                return rl == t_level.lower()
            # 4) No level info anywhere → accept whole series
            return not (t_level or t_class)
        if t_level or t_class or t_vol is not None:
            same_series = same_series[same_series.apply(_level_match, axis=1)]
        series_pool = same_series[same_series['_mat_i'] != (int(tm) if tm is not None else -1)].copy()
        series_pool = series_pool.drop_duplicates(subset=['_mat_i'])
        # v28.30.29 — never recommend teacher's editions to students
        _n_teacher = 0
        if not series_pool.empty:
            _n_before = len(series_pool)
            series_pool = series_pool[~series_pool.apply(_ll_is_teacher_book, axis=1)].copy()
            _n_teacher = _n_before - len(series_pool)
        # Sales rank
        if 'Sum of Sales' in series_pool.columns:
            _s = pd.to_numeric(series_pool['Sum of Sales'].astype('object'),
                               errors='coerce').fillna(0.0)
            series_pool['_sales'] = _np.asarray(_s, dtype='float64')
        else:
            series_pool['_sales'] = 0.0
        series_pool['_tier_label'] = f"Same series · same level ({t_series})"
        series_pool = series_pool.sort_values('_sales', ascending=False).reset_index(drop=True)
        s1_notes.append(f"Series '{t_series}' + level '{t_level or t_class}': "
                        f"{len(series_pool)} companion book(s)"
                        + (f" (excluded {_n_teacher} teacher's edition(s))" if _n_teacher else ""))
    else:
        s1_notes.append("No series on trigger — skipping series companions")
    slot_notes[1] = s1_notes

    # ── STEP 2 — INTERNATIONAL KIDS BOOKS (age-scaled + language) ─
    kids_pool = pd.DataFrame()
    s2_notes = ["=== STEP 2: INTERNATIONAL KIDS BOOKS (age-scaled, language-matched) ==="]
    if df_kids_books is not None and not df_kids_books.empty:
        ik = df_kids_books.copy()
        if 'Level 2' in ik.columns:
            l2 = ik['Level 2'].astype(str).str.strip().str.lower()
            ik = ik[l2 == 'international kids books'].copy()
        s2_notes.append(f"International Kids Books rows: {len(ik)}")
        # Parse age (reuse the school-books parser) and apply the scaled window
        ik['_age'] = ik['Ηλικία'].apply(_sb_parse_age_range) if 'Ηλικία' in ik.columns else None
        WLO, WHI = t_age_lo - 2, t_age_hi + 1
        def _age_ok(r):
            if r is None:
                return False
            return WLO <= r[0] <= WHI and r[1] >= t_age_lo
        age_mask = ik['_age'].apply(_age_ok)
        ik_age = ik[age_mask].copy()
        s2_notes.append(f"Age-scaled window [{WLO}-{WHI}] (level → age {t_age_lo}-{t_age_hi}): "
                        f"{len(ik_age)} books")
        # Language: infer kids-book language, match to trigger language;
        # fall back to English ONLY if no matching-language kids books.
        ik_age['_klang'] = ik_age['Title'].apply(_ll_infer_kids_lang)
        lang_match = ik_age[ik_age['_klang'] == t_lang].copy()
        if len(lang_match) >= 1:
            kids_pool = lang_match
            s2_notes.append(f"Language match ({t_lang}): {len(kids_pool)} books")
        else:
            kids_pool = ik_age[ik_age['_klang'] == 'en'].copy()
            s2_notes.append(f"No {t_lang} kids' books → English fallback: {len(kids_pool)} books")
        # Sales rank within the age window
        if not kids_pool.empty:
            if 'Sum of Sales' in kids_pool.columns:
                _s = pd.to_numeric(kids_pool['Sum of Sales'].astype('object'),
                                   errors='coerce').fillna(0.0)
                kids_pool['_sales'] = _np.asarray(_s, dtype='float64')
            else:
                kids_pool['_sales'] = 0.0
            kids_pool['_tier_label'] = f"International kids book (age {t_age_lo}-{t_age_hi})"
            kids_pool = kids_pool.sort_values('_sales', ascending=False).reset_index(drop=True)
    slot_notes[2] = s2_notes

    # ── STEP 3 — SLOT ALLOCATION ─────────────────────────────────
    n_series = min(len(series_pool), LL_SERIES_MAX)
    n_kids = LL_TOTAL_SLOTS - n_series
    plan = ['SERIES'] * n_series + ['KIDS'] * n_kids
    slot_notes[3] = ["=== STEP 3: SLOT ALLOCATION ===",
                     f"Plan: {n_series} series + {n_kids} kids"]
    diag.append(("3. Slot Plan", f"{LL_TOTAL_SLOTS} slots",
                 f"{n_series} same-series + {n_kids} kids' books"))

    # ── STEP 4 — FILL ────────────────────────────────────────────
    fill_notes = ["=== STEP 4: SLOT FILLING ==="]
    series_iter = list(series_pool.iterrows()) if not series_pool.empty else []
    kids_iter   = list(kids_pool.iterrows())   if not kids_pool.empty   else []
    si = {'i': 0}
    ki = {'i': 0}

    def _next_series():
        while si['i'] < len(series_iter):
            _, row = series_iter[si['i']]; si['i'] += 1
            if row.get('Material', None) in used_materials:
                continue
            return row
        return None

    def _next_kids():
        while ki['i'] < len(kids_iter):
            _, row = kids_iter[ki['i']]; ki['i'] += 1
            if row.get('Material', None) in used_materials:
                continue
            return row
        return None

    all_recs = []
    for slot_idx, slot_type in enumerate(plan, start=1):
        if slot_type == 'SERIES':
            row = _next_series()
            picked = 'series'
            if row is None:
                row = _next_kids(); picked = 'kids (series exhausted)'
        else:
            row = _next_kids()
            picked = 'kids'
            if row is None:
                row = _next_series(); picked = 'series (kids exhausted)'
        if row is None:
            fill_notes.append(f"Slot {slot_idx}: EMPTY — pools exhausted")
            continue
        if picked.startswith('series'):
            role = 'Same series · same level'
        else:
            role = 'International kids book'
        label = str(row.get('_tier_label', '') or '')
        tier_note = f" [{label}]" if label else ''

        row_copy = row.copy()
        row_copy['Slot_Position'] = slot_idx
        row_copy['Assigned_Slot'] = slot_idx   # diagnostic display expects this
        row_copy['Slot_Role'] = role
        row_copy['Item_Rank'] = 1
        if 'Final_Score' not in row_copy.index or pd.isna(row_copy.get('Final_Score', None)):
            row_copy['Final_Score'] = _safe_num(row_copy.get('_sales', 0))
        all_recs.append(row_copy)
        used_materials.add(row_copy.get('Material', None))
        fill_notes.append(f"Slot {slot_idx} ({slot_type}) ← {picked}: "
                          f"{str(row.get('Title', ''))[:50]}{tier_note}")

    slot_notes[4] = fill_notes
    diag.append(("4. Slots Filled", len(all_recs), f"{len(all_recs)} of {LL_TOTAL_SLOTS}"))

    if not all_recs:
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()
    recs_df = pd.DataFrame(all_recs).reset_index(drop=True)
    return recs_df, diag, slot_notes, recs_df


# ═════════════════════════════════════════════════════════════
# v28.30 — GREEK SCHOOL BOOKS ENGINE
# ═════════════════════════════════════════════════════════════
def run_school_books_engine(trigger, df_school_pool, df_stationery_pool, df_history, df_greek_books=None, df_private_school=None, df_int_school=None):
    """Σχολικά Βιβλία recommender.
    
    Layout:
      - Slots 1-3 (primary):   school-book recs (same publisher + same class
                               + different subject; fallback chain when sparse)
      - Slots 4-6 (guaranteed): age-targeted stationery
      - Slots 7-10 (overflow):  more school books via fallback chain; if
                                exhausted, fill with more age-targeted stationery
    
    Per user spec:
      "showcase books from the same publisher, for the same age, but different
       classes [= subjects]; also show stationery at slots 4,5,6, and more
       stationery if you don't have matches for similar school books;
       stationery should be based on the kids age, not just sales."
    """
    diag = []
    slot_notes = {1: [], 2: [], 3: [], 4: []}
    
    # ── Helper: bulletproof numeric for scoring (matches v28.29.3 pattern)
    def _safe_num(v):
        try:
            if v is None: return 0.0
            if pd.isna(v): return 0.0
            return float(v)
        except (TypeError, ValueError):
            return 0.0
    
    # ──────────────────────────────────────────────────────────
    # STEP 0 — TRIGGER ATTRIBUTES
    # ──────────────────────────────────────────────────────────
    tm   = trigger.get('Material', None)
    tt   = str(trigger.get('Title', ''))
    
    # School Books sheet uses _sales-suffixed columns for the rich attributes;
    # the Stationery sheet uses plain ones. We always pull from _sales here.
    t_publisher_raw = trigger.get('Εκδότης_sales', trigger.get('Εκδότης', ''))
    t_class_raw     = trigger.get('Τάξη_sales',    trigger.get('Τάξη', ''))
    t_subject_raw   = trigger.get('Μάθημα_sales',  trigger.get('Μάθημα', ''))
    
    t_publisher = _sb_normalize_publisher(t_publisher_raw)
    t_classes   = _sb_parse_multi_value(t_class_raw)   # list — multi-grade workbooks
    t_subjects  = _sb_parse_multi_value(t_subject_raw)
    t_stage     = _sb_class_to_stage(t_class_raw) or SB_DEFAULT_STAGE
    
    # v28.30.4 — Hierarchy is the type signal (helper vs textbook).
    t_hierarchy = str(trigger.get('Hierarchy', '')).strip()
    trigger_is_helper   = _sb_is_helper_hierarchy(t_hierarchy)
    trigger_is_textbook = _sb_is_textbook_hierarchy(t_hierarchy)
    
    # v28.30.4 — Author surnames for companion-volume matching.
    t_author_raw = trigger.get('Συγγραφέας_sales', trigger.get('Συγγραφέας', ''))
    t_authors    = _sb_extract_authors_surname_set(t_author_raw)
    
    # v28.30.4 — Προσανατολισμός (high-school orientation track).
    # Note: the data lives in _catalog column; _sales is empty for all rows.
    t_orient_raw = trigger.get('Προσανατολισμός_catalog', '')
    t_orientation = _sb_parse_multi_value(t_orient_raw)
    
    # v28.30.10 — Trigger's volume / τεύχος / μέρος info (for series-companion detection).
    t_title = str(trigger.get('Title', ''))
    t_tomos_rank, t_tomos_base = _sb_extract_volume(t_title)
    # v28.30.16 — orientation tokens hoisted here (was only set inside the
    # phase-split block, but the series-companion block uses it for ALL
    # triggers — younger triggers skip phase split and previously hit a
    # NameError on t_orient_tokens).
    t_orient_tokens = _sb_orient_tokens(t_orientation)
    
    diag.append(("0. Trigger", "", f"Cluster: Greek School Books"))
    diag.append(("   Trigger (attrs)", "", 
                 f"Publisher: '{t_publisher_raw}' | Class: {t_classes or '∅'} | "
                 f"Subject: {t_subjects or '∅'} | Stage: '{t_stage}'"))
    diag.append(("   Trigger (type)", "",
                 f"Hierarchy: '{t_hierarchy}' | "
                 f"Type: {'helper' if trigger_is_helper else ('textbook' if trigger_is_textbook else 'other')} | "
                 f"Authors: {t_authors or '∅'} | "
                 f"Προσανατολισμός: {t_orientation or '∅'}"))
    
    used_materials = {tm} if tm is not None else set()
    
    # ──────────────────────────────────────────────────────────
    # STEP 0.5 — PRIVATE-SCHOOL CURRICULUM LIST (v28.30.21)
    # ──────────────────────────────────────────────────────────
    # If the trigger's Material (SAP) appears on a private-school curriculum
    # list, build a companion pool of the OTHER books on the SAME school+class
    # list(s). These take priority in the SCHOOL slots (slots 1-4 and the
    # overflow), because a parent buying a private-school list book almost
    # certainly needs the rest of that school's class list.
    #
    # Rules:
    #   * Only books that are SCHOOL BOOKS / HELPERS (resolved from the Greek
    #     School Books + International School Books catalogs). Never kids' books
    #     or other types — the kids'-book pool is untouched.
    #   * A list book that belongs to MULTIPLE schools/classes is matched by
    #     sales only (we still surface it, ranked by sales) rather than pinning
    #     a single school — handled naturally since the pool is sales-ranked.
    private_list_pool = pd.DataFrame()
    trigger_in_private_list = False
    if (df_private_school is not None and not df_private_school.empty
            and tm is not None and {'_sap', '_school', '_class'}.issubset(df_private_school.columns)):
        try:
            tm_int = int(tm)
        except (TypeError, ValueError):
            tm_int = None
        if tm_int is not None:
            trig_rows = df_private_school[df_private_school['_sap'] == tm_int]
            if not trig_rows.empty:
                trigger_in_private_list = True
                # All (school, class) pairs this trigger belongs to
                trig_pairs = set(zip(trig_rows['_school'], trig_rows['_class']))
                # Find every OTHER SAP sharing at least one of those pairs
                pair_mask = df_private_school.apply(
                    lambda r: (r['_school'], r['_class']) in trig_pairs, axis=1)
                companion_saps = set(df_private_school[pair_mask]['_sap'].unique())
                companion_saps.discard(tm_int)
                
                # Resolve those SAPs to catalog rows (school books / helpers
                # only) from the Greek School Books + International School Books
                # catalogs. This guarantees we never pull a kids' book here.
                resolve_frames = []
                if df_school_pool is not None and not df_school_pool.empty:
                    resolve_frames.append(df_school_pool)
                if df_int_school is not None and not df_int_school.empty:
                    resolve_frames.append(df_int_school)
                if resolve_frames:
                    cat = pd.concat(resolve_frames, ignore_index=True, sort=False)
                    cat['_mat_i'] = pd.to_numeric(cat['Material'], errors='coerce')
                    private_list_pool = cat[cat['_mat_i'].isin(companion_saps)].copy()
                    # De-dup (a SAP can be in both sheets) — keep first
                    private_list_pool = private_list_pool.drop_duplicates(subset=['_mat_i'])
                    # Exclude the trigger itself
                    private_list_pool = private_list_pool[private_list_pool['_mat_i'] != tm_int]
                    # Rank purely by sales (multi-school/class books fall out
                    # naturally to top-sellers, per spec).
                    # v28.30.26 — force plain float64 (not Arrow-backed) so the
                    # subsequent add doesn't raise on pandas 3.x / pyarrow.
                    import numpy as _np
                    if 'Sum of Sales' in private_list_pool.columns:
                        _s = pd.to_numeric(
                            private_list_pool['Sum of Sales'].astype('object'),
                            errors='coerce').fillna(0.0)
                        private_list_pool['_sales'] = _np.asarray(_s, dtype='float64')
                    else:
                        private_list_pool['_sales'] = 0.0
                    if 'AVAILABILITY' in private_list_pool.columns:
                        _av = private_list_pool['AVAILABILITY'].astype('object').apply(
                            lambda v: float(SB_S_AVAIL_BONUS) if str(v).strip() == 'Άμεσα Διαθέσιμο' else 0.0)
                        private_list_pool['_avail'] = _np.asarray(_av, dtype='float64')
                    else:
                        private_list_pool['_avail'] = 0.0
                    private_list_pool['Final_Score'] = (
                        private_list_pool['_sales'].to_numpy(dtype='float64')
                        + private_list_pool['_avail'].to_numpy(dtype='float64'))
                    private_list_pool['_tier_label'] = 'Private-school list (same school+class)'
                    private_list_pool = private_list_pool.sort_values(
                        '_sales', ascending=False).reset_index(drop=True)
        if trigger_in_private_list:
            schools = sorted({s for s, _ in trig_pairs if s})
            classes = sorted({c for _, c in trig_pairs if c})
            diag.append(("   Private-school list", "",
                         f"Trigger on list — schools: {schools[:3]}"
                         f"{'…' if len(schools) > 3 else ''} | classes: {classes[:3]}"
                         f"{'…' if len(classes) > 3 else ''} | "
                         f"companion books: {len(private_list_pool)}"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 1 — SCHOOL-BOOK CANDIDATE POOL (multi-tier filter)
    # ──────────────────────────────────────────────────────────
    sb_notes = ["=== STEP 1: SCHOOL-BOOK POOL (multi-tier filter) ==="]
    
    pool = df_school_pool.copy() if df_school_pool is not None else pd.DataFrame()
    if not pool.empty and 'Material' in pool.columns:
        pool = pool[pool['Material'] != tm].copy()
    
    # Cache normalized column extracts for repeated filtering
    if not pool.empty:
        pool['_pub_norm'] = pool['Εκδότης_sales'].apply(_sb_normalize_publisher) if 'Εκδότης_sales' in pool.columns else ''
        if 'Τάξη_sales' in pool.columns:
            pool['_classes'] = pool['Τάξη_sales'].apply(_sb_parse_multi_value)
        else:
            pool['_classes'] = [[] for _ in range(len(pool))]
        if 'Μάθημα_sales' in pool.columns:
            pool['_subjects'] = pool['Μάθημα_sales'].apply(_sb_parse_multi_value)
        else:
            pool['_subjects'] = [[] for _ in range(len(pool))]
        pool['_stage'] = pool['_classes'].apply(
            lambda lst: _sb_class_to_stage(';'.join(lst)) if lst else None)
        # v28.30.4 — Hierarchy + Authors + Orientation
        pool['_hier'] = pool['Hierarchy'].fillna('').astype(str) if 'Hierarchy' in pool.columns else ''
        if 'Συγγραφέας_sales' in pool.columns:
            pool['_authors'] = pool['Συγγραφέας_sales'].apply(_sb_extract_authors_surname_set)
        else:
            pool['_authors'] = [set() for _ in range(len(pool))]
        if 'Προσανατολισμός_catalog' in pool.columns:
            pool['_orientation'] = pool['Προσανατολισμός_catalog'].apply(_sb_parse_multi_value)
        else:
            pool['_orientation'] = [[] for _ in range(len(pool))]
    
    # Tier filters — produced as masks for transparency in the funnel
    def _mask_same_publisher(p): return (p['_pub_norm'] == t_publisher) & (t_publisher != '')
    def _mask_same_class(p):
        if not t_classes: return pd.Series([False] * len(p), index=p.index)
        t_set = set(t_classes)
        return p['_classes'].apply(lambda lst: bool(set(lst) & t_set))
    def _mask_same_subject(p):
        if not t_subjects:
            # No trigger subject → same-subject filter trivially fails (nothing matches)
            return pd.Series([False] * len(p), index=p.index)
        t_set = set(t_subjects)
        return p['_subjects'].apply(lambda lst: bool(lst) and bool(set(lst) & t_set))
    def _mask_different_subject(p):
        if not t_subjects:
            # No trigger subject → "different" is undefined; everything qualifies
            return pd.Series([True] * len(p), index=p.index)
        t_set = set(t_subjects)
        return p['_subjects'].apply(lambda lst: bool(lst) and not (set(lst) & t_set))
    def _mask_same_stage(p):
        return p['_stage'] == t_stage
    # v28.30.4 — hierarchy, author, orientation masks
    def _mask_same_hierarchy(p):
        if not t_hierarchy: return pd.Series([False] * len(p), index=p.index)
        return p['_hier'] == t_hierarchy
    def _mask_helper_hierarchy(p):
        return p['_hier'].apply(_sb_is_helper_hierarchy)
    def _mask_textbook_hierarchy(p):
        return p['_hier'].apply(_sb_is_textbook_hierarchy)
    def _mask_author_overlap(p):
        if not t_authors: return pd.Series([False] * len(p), index=p.index)
        return p['_authors'].apply(lambda s: isinstance(s, set) and bool(s & t_authors))
    def _mask_orient_overlap(p):
        if not t_orientation: return pd.Series([False] * len(p), index=p.index)
        t_orient_set = set(t_orientation)
        return p['_orientation'].apply(
            lambda lst: isinstance(lst, list) and bool(lst) and bool(set(lst) & t_orient_set))
    
    sb_notes.append(f"Total school-book catalog (excl. trigger): {len(pool)}")
    
    # v28.30.4 — TYPE-AWARE TIER ORDERING.
    # Routing depends on stage AND hierarchy type:
    #   * Older stage + helper trigger (Hierarchy = ΣΧΟΛΙΚΑ ΒΟΗΘΗΜΑΤΑ - …):
    #     Sibling helpers from same publisher + same subject + same author
    #     (companion volumes, the "συνήθως αγοράζονται μαζί" image pattern).
    #   * Older stage + textbook trigger (Hierarchy = Βιβλία Οργανισμού …):
    #     Top helpers for same subject + orientation, then other Διόφαντος
    #     textbooks for the kid's other subjects.
    #   * Younger stages (Δημοτικό/Προσχολική): keep different-subjects-led
    #     logic (cover all the kid's subjects), with same-publisher preference.
    is_older_stage = (t_stage in SB_OLDER_STAGES)
    # v28.30.12 — early-elementary flag (Ε' Δημοτικού and below + preschool)
    is_early_elementary = bool(t_classes) and any(
        c in SB_EARLY_ELEMENTARY_CLASSES for c in t_classes)
    # v28.30.13 — very-young flag (≤ ~7yo: preschool + Α'/Β' Δημοτικού) for
    # stationery item-safety filtering; and summer flag for holiday books.
    is_very_young = bool(t_classes) and any(
        c in SB_VERY_YOUNG_CLASSES for c in t_classes)
    is_holiday_eligible = bool(t_classes) and any(
        c in SB_HOLIDAY_ELIGIBLE_CLASSES for c in t_classes)
    import datetime as _dt
    is_summer = _dt.date.today().month in SB_SUMMER_MONTHS
    SB_S_SAME_SUBJECT     = 80_000   # v28.30.1 — same-subject bonus
    SB_S_AUTHOR_OVERLAP   = 60_000   # v28.30.4 — companion-volume signal
    SB_S_ORIENT_OVERLAP   = 40_000   # v28.30.4 — orientation match
    SB_S_HELPER_HIERARCHY = 25_000   # v28.30.4 — helper-vs-textbook signal

    if not pool.empty:
        m_same_pub  = _mask_same_publisher(pool)
        m_same_cls  = _mask_same_class(pool)
        m_same_sub  = _mask_same_subject(pool)
        m_diff_sub  = _mask_different_subject(pool)
        m_same_stg  = _mask_same_stage(pool)
        m_same_hier = _mask_same_hierarchy(pool)
        m_helper    = _mask_helper_hierarchy(pool)
        m_textbook  = _mask_textbook_hierarchy(pool)
        m_author    = _mask_author_overlap(pool)
        m_orient    = _mask_orient_overlap(pool)
        
        # Default — only the textbook branch sets this; carried out to the
        # phase-split block so the primary filter can lock to it.
        best_helper_pub = ''
        
        if is_older_stage and trigger_is_helper:
            # ── OLDER + HELPER trigger ──
            # User rule: "only show ΣΧΟΛΙΚΑ ΒΟΗΘΗΜΑΤΑ - <class> from the same
            # publisher". The trigger's publisher is the HARD anchor — every
            # school slot stays within that publisher. Slots 1-3 surface
            # same-subject companions (with author preference); slots 7-10
            # are same-publisher cross-subject helpers.
            tier1_mask = m_same_hier & m_same_pub & m_same_sub & m_author          # companions by SAME author
            tier2_mask = m_same_hier & m_same_pub & m_same_sub & (~tier1_mask)     # same-pub same-subject (other author)
            tier3_mask = m_same_hier & m_same_pub & m_diff_sub & (~tier1_mask) & (~tier2_mask)  # same-pub cross-subject helpers
            # The last 3 tiers are DEEP fallbacks for the rare case where the
            # trigger's publisher has fewer than 7 helpers in this class — they
            # let other publishers' helpers fill the carousel rather than leave
            # slots empty. In normal operation (Σαββάλας Χημεία trigger with
            # 4+ Σαββάλας Χημεία helpers + dozens of cross-subject helpers),
            # T1-T3 fill everything and T4-T6 stay at 0.
            tier4_mask = m_same_hier & m_same_sub & (~tier1_mask) & (~tier2_mask) & (~tier3_mask)         # rare: cross-pub same-subject helpers
            tier5_mask = m_same_hier & (~tier1_mask) & (~tier2_mask) & (~tier3_mask) & (~tier4_mask)      # rare: any-pub same-hier (cross-subject)
            tier6_mask = m_same_stg & (~tier1_mask) & (~tier2_mask) & (~tier3_mask) & (~tier4_mask) & (~tier5_mask)
            
            tier_labels = [
                "T1: same hierarchy + pub + subject + AUTHOR (companions)",
                "T2: same hierarchy + pub + subject (any author)",
                "T3: same hierarchy + pub (cross-subject same-pub helpers)",
                "T4: [deep fallback] same hierarchy + subject (other pub)",
                "T5: [deep fallback] same hierarchy (other pub, any subject)",
                "T6: [last resort] same stage",
            ]
            tier_bases = [
                SB_S_SAME_PUBLISHER + SB_S_SAME_CLASS + SB_S_SAME_SUBJECT + SB_S_AUTHOR_OVERLAP + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_PUBLISHER + SB_S_SAME_CLASS + SB_S_SAME_SUBJECT + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_PUBLISHER + SB_S_SAME_CLASS + SB_S_DIFFERENT_SUBJECT + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_CLASS + SB_S_SAME_SUBJECT + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_CLASS + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_STAGE,
            ]
            tomos_sort_tiers = {0, 1, 3}   # same-subject tiers benefit from τόμος sort
            ordering_strategy = f"OLDER + HELPER (LOCKED to publisher '{t_publisher_raw}')"
        
        elif is_older_stage and trigger_is_textbook:
            # ── OLDER + TEXTBOOK trigger (e.g., Διόφαντος Χημεία Γ' Λυκείου) ──
            # User rule: "show only the top selling helper books for this
            # Μάθημα and Προσανατολισμός, only from one publisher, not all
            # publishers. only 1 publisher and as many helper books this
            # publisher has". Then non-helper textbooks (Διόφαντος) for the
            # kid's other subjects.
            #
            # Step 1: find the BEST helper publisher for this subject+class.
            # Aggregate total sales of matching helpers per publisher; the
            # winner is the top-selling publisher for this subject's helpers.
            best_helper_pub = ''
            # v28.30.12 — A genuine subject helper covers just 1-2 subjects.
            # All-in-one "λυσάρι" books tag 8-10 subjects and would hijack
            # best_helper_pub via bulk sales even though they aren't a
            # subject-specific helper. We exclude helpers covering more than
            # SB_MAX_HELPER_SUBJECTS subjects from both the publisher race
            # AND the tier masks.
            SB_MAX_HELPER_SUBJECTS = 3
            def _is_focused_helper(lst):
                try:
                    n = len([s for s in lst if s])
                    return 1 <= n <= SB_MAX_HELPER_SUBJECTS
                except Exception:
                    return False
            if t_subjects:
                t_sub_set = set(t_subjects)
                helper_mask_sub = (m_helper & m_same_cls
                                   & pool['_subjects'].apply(
                                        lambda lst: bool(lst) and bool(set(lst) & t_sub_set))
                                   & pool['_subjects'].apply(_is_focused_helper))
                # Prefer orientation match when available
                if t_orientation:
                    helper_mask_sub_ori = helper_mask_sub & m_orient
                    if helper_mask_sub_ori.any():
                        helper_mask_sub = helper_mask_sub_ori
                cands = pool[helper_mask_sub]
                if not cands.empty:
                    cands = cands.copy()
                    cands['_sales_num'] = cands['Sum of Sales'].apply(_safe_num) if 'Sum of Sales' in cands.columns else 0
                    pub_totals = cands.groupby('_pub_norm')['_sales_num'].sum().sort_values(ascending=False)
                    # Skip empty publisher (e.g., catalog rows with no Εκδότης)
                    pub_totals = pub_totals[pub_totals.index != '']
                    if len(pub_totals) > 0:
                        best_helper_pub = pub_totals.index[0]
            
            # Lock T1+T2 to that single publisher
            m_best_helper_pub = pd.Series([False] * len(pool), index=pool.index)
            if best_helper_pub:
                m_best_helper_pub = (pool['_pub_norm'] == best_helper_pub)
            # v28.30.12 — Also require the helper be subject-FOCUSED (≤3 subjects)
            # so an all-in-one λυσάρι from the same publisher doesn't sneak in.
            m_focused = pool['_subjects'].apply(_is_focused_helper)
            
            tier1_mask = m_helper & m_best_helper_pub & m_focused & m_same_cls & m_same_sub & m_orient            # best-pub focused helpers + orientation
            tier2_mask = m_helper & m_best_helper_pub & m_focused & m_same_cls & m_same_sub & (~tier1_mask)        # best-pub focused helpers (any orientation)
            tier3_mask = m_textbook & m_same_pub & m_same_cls & m_diff_sub & (~tier1_mask) & (~tier2_mask)  # Διόφαντος cross-subject textbooks
            tier4_mask = m_textbook & m_same_cls & m_diff_sub & (~tier1_mask) & (~tier2_mask) & (~tier3_mask)  # any-pub cross-subject textbooks
            # Deep fallback only if the best-publisher pool exhausted: any helpers
            tier5_mask = m_helper & m_same_cls & m_same_sub & (~tier1_mask) & (~tier2_mask) & (~tier3_mask) & (~tier4_mask)
            tier6_mask = m_same_stg & (~tier1_mask) & (~tier2_mask) & (~tier3_mask) & (~tier4_mask) & (~tier5_mask)
            
            tier_labels = [
                f"T1: top helpers (pub='{best_helper_pub or '∅'}') + Προσανατολισμός",
                f"T2: top helpers (pub='{best_helper_pub or '∅'}') any orientation",
                "T3: same pub (Διόφαντος) textbooks, different subject",
                "T4: any-pub textbooks, different subject",
                "T5: [deep fallback] any helpers same subject (other pub)",
                "T6: [last resort] same stage",
            ]
            tier_bases = [
                SB_S_SAME_CLASS + SB_S_SAME_SUBJECT + SB_S_HELPER_HIERARCHY + SB_S_ORIENT_OVERLAP,
                SB_S_SAME_CLASS + SB_S_SAME_SUBJECT + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_PUBLISHER + SB_S_SAME_CLASS + SB_S_DIFFERENT_SUBJECT,
                SB_S_SAME_CLASS + SB_S_DIFFERENT_SUBJECT,
                SB_S_SAME_CLASS + SB_S_SAME_SUBJECT + SB_S_HELPER_HIERARCHY,
                SB_S_SAME_STAGE,
            ]
            tomos_sort_tiers = {0, 1, 4}
            ordering_strategy = (f"OLDER + TEXTBOOK (best helper publisher: '{best_helper_pub}'; "
                                 f"cross-subject overflow: trigger publisher)")
        
        else:
            # ── YOUNGER (Δημοτικό/Προσχολική) — keeps prior behavior ──
            # User's rule: "different subjects, same publishers (ideally)"
            # Hierarchy match is a soft preference (same-hierarchy boost) rather
            # than a hard filter, since helpers and textbooks are often mixed
            # at this level.
            tier1_mask = m_same_pub & m_same_cls & m_diff_sub
            tier2_mask = m_same_cls & m_diff_sub & (~tier1_mask)
            tier3_mask = m_same_pub & m_same_cls & m_same_sub & (~tier1_mask) & (~tier2_mask)
            tier4_mask = m_same_cls & m_same_sub & (~tier1_mask) & (~tier2_mask) & (~tier3_mask)
            tier5_mask = m_same_pub & m_same_stg & (~tier1_mask) & (~tier2_mask) & (~tier3_mask) & (~tier4_mask)
            tier6_mask = m_same_stg & (~tier1_mask) & (~tier2_mask) & (~tier3_mask) & (~tier4_mask) & (~tier5_mask)
            
            tier_labels = [
                "T1: same pub + class + different subject (ideal for younger)",
                "T2: same class + different subject (any pub)",
                "T3: same pub + class + same subject (companion — rare)",
                "T4: same class + same subject (any pub)",
                "T5: same pub + same stage",
                "T6: same stage (any pub)",
            ]
            tier_bases = [
                SB_S_SAME_PUBLISHER + SB_S_SAME_CLASS + SB_S_DIFFERENT_SUBJECT,
                SB_S_SAME_CLASS + SB_S_DIFFERENT_SUBJECT,
                SB_S_SAME_PUBLISHER + SB_S_SAME_CLASS + SB_S_SAME_SUBJECT,
                SB_S_SAME_CLASS + SB_S_SAME_SUBJECT,
                SB_S_SAME_PUBLISHER + SB_S_SAME_STAGE,
                SB_S_SAME_STAGE,
            ]
            tomos_sort_tiers = {2, 3}
            ordering_strategy = f"YOUNGER ({t_stage}) — different-subjects led"
        
        tier_masks = [tier1_mask, tier2_mask, tier3_mask, tier4_mask, tier5_mask, tier6_mask]
        tiers = [pool[m].copy() for m in tier_masks]
        
        sb_notes.append(f"Strategy: {ordering_strategy}")
        for i, (t, label) in enumerate(zip(tiers, tier_labels), start=1):
            sb_notes.append(f"  {label}: {len(t)} matches")
    else:
        tiers = [pd.DataFrame() for _ in range(6)]
        tier_labels = ['', '', '', '', '', '']
        tier_bases = [0] * 6
        tomos_sort_tiers = set()
        best_helper_pub = ''
        sb_notes.append("  No school-book catalog available")
    
    # Score & sort each tier (sales primary, availability tiebreaker)
    def _score_tier(t, tier_base, tier_label):
        if t.empty: return t
        t = t.copy()
        # v28.30.26 — force plain float64 (avoid Arrow add error on pandas 3.x)
        import numpy as _np
        if 'Sum of Sales' in t.columns:
            _s = pd.to_numeric(t['Sum of Sales'].astype('object'), errors='coerce').fillna(0.0)
            t['_sales'] = _np.asarray(_s, dtype='float64')
        else:
            t['_sales'] = 0.0
        if 'AVAILABILITY' in t.columns:
            _av = t['AVAILABILITY'].astype('object').apply(
                lambda v: float(SB_S_AVAIL_BONUS) if str(v).strip() == 'Άμεσα Διαθέσιμο' else 0.0)
            t['_avail'] = _np.asarray(_av, dtype='float64')
        else:
            t['_avail'] = 0.0
        t['Final_Score'] = (float(tier_base)
                            + t['_sales'].to_numpy(dtype='float64')
                            + t['_avail'].to_numpy(dtype='float64'))
        t['_tier_label'] = tier_label
        # v28.30.10 — Always compute τόμος metadata. Previously this only
        # happened inside _sort_with_tomos (gated by tomos_sort_tiers), so
        # T3/T4/T6 rows never got _tomos_base. The series-companion logic
        # later needs this to be set on all rows in school_pool.
        if 'Title' in t.columns:
            vols = t['Title'].apply(_sb_extract_volume)
            t['_tomos_rank'] = vols.apply(lambda v: v[0])
            t['_tomos_base'] = vols.apply(lambda v: v[1])
            t['_has_tomos']  = vols.apply(lambda v: v[0] is not None)
        else:
            t['_tomos_rank'] = None
            t['_tomos_base'] = ''
            t['_has_tomos']  = False
        return t.sort_values('Final_Score', ascending=False)
    
    def _sort_with_tomos(t):
        """Apply τόμος-aware ordering to a tier. Items with a τόμος marker
        are surfaced first, grouped by base title (so siblings of one series
        stay together), and within each group sorted by τόμος rank ASC
        (Α' before Β' before Γ'). Groups are ordered by max sales DESC so
        the best-selling series leads."""
        if t.empty or '_tomos_base' not in t.columns: return t
        t = t.copy()
        # Rank-for-sort: NaN → 999 to push non-τόμος items to the bottom
        t['_tomos_rank_sort'] = t['_tomos_rank'].apply(lambda v: v if v is not None and pd.notna(v) else 999)
        
        # Per-base-group max sales — drives which τόμος series leads
        if 'Sum of Sales' in t.columns:
            try:
                t['_group_max_sales'] = t.groupby('_tomos_base')['Sum of Sales'].transform(
                    lambda s: s.apply(_safe_num).max())
            except Exception:
                t['_group_max_sales'] = 0
        else:
            t['_group_max_sales'] = 0
        
        # Sort: τόμος items first; among them, best-selling group leads;
        # within group, Α' before Β' before Γ'. Non-τόμος items fall back
        # to Final_Score order.
        t = t.sort_values(
            ['_has_tomos', '_group_max_sales', '_tomos_base', '_tomos_rank_sort', 'Final_Score'],
            ascending=[False, False, True, True, False],
            na_position='last',
        )
        return t
    
    # Apply scoring + τόμος sort
    scored_tiers = []
    for i, (t, base, label) in enumerate(zip(tiers, tier_bases, tier_labels)):
        t = _score_tier(t, base, label)
        if i in tomos_sort_tiers and not t.empty:
            t = _sort_with_tomos(t)
        scored_tiers.append(t)
    
    tier1, tier2, tier3, tier4, tier5, tier6 = scored_tiers
    
    # Concatenate tier-ordered (high → low priority) for sequential consumption
    school_pool = pd.concat(scored_tiers, ignore_index=True) if any(len(t) > 0 for t in scored_tiers) else pd.DataFrame()
    sb_notes.append(f"  → Combined ordered pool: {len(school_pool)} candidates")
    
    slot_notes[1] = sb_notes
    diag.append(("1. School-Book Pool", len(school_pool),
                 f"T1={len(tier1)} T2={len(tier2)} T3={len(tier3)} T4={len(tier4)} T5={len(tier5)} T6={len(tier6)} | stage={'older' if is_older_stage else 'younger'}"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 2 — KIDS' TRADE-BOOKS POOL (age-targeted)
    # ──────────────────────────────────────────────────────────
    # v28.30.15 — DIRECTION CHANGE: stationery removed from this engine
    # (its logic is preserved in docs/stationery_slot_logic.md for a future
    # dedicated slot). This engine is now BOOKS-ONLY. For younger triggers
    # (up to ~12yo: Δημοτικό/Προσχολική + Α' Γυμνασίου), we additionally
    # surface age-appropriate best-selling KIDS' TRADE BOOKS (from the
    # 'Greek Books' catalog) using the 'Προτεινόμενη Ηλικία' field. High
    # school triggers stay school-books only (no kids-book pool).
    st_notes = ["=== STEP 2: KIDS' TRADE-BOOKS POOL (age-targeted) ==="]
    stat_pool = pd.DataFrame()   # legacy name kept empty (stationery retired here)
    kids_books_pool = pd.DataFrame()
    
    show_kids_books = bool(t_classes) and any(
        c in SB_KIDS_BOOKS_MAX_AGE_CLASSES for c in t_classes)
    
    if show_kids_books and df_greek_books is not None and not df_greek_books.empty:
        # Determine the child's age window from the trigger class(es)
        age_bands = [SB_CLASS_TO_AGE_BAND[c] for c in t_classes if c in SB_CLASS_TO_AGE_BAND]
        if age_bands:
            age_lo = min(b[0] for b in age_bands)
            age_hi = max(b[1] for b in age_bands)
        else:
            age_lo, age_hi = 3, 12   # safe default for "younger"
        child_age = (age_lo + age_hi) / 2.0
        
        gb = df_greek_books.copy()
        # v28.30.19 — Kids' books come from the 'Books' sheet of
        # Recommendations_GitHub.xlsx, where Level 2 == 'Greek Kids Books'
        # (15,814 rows, ~11.5k with a parseable 'Προτεινόμενη Ηλικία').
        # This is the proper kids'-books catalog (Dog Man, Ημερολόγιο ενός
        # σπασίκλα, picture books, etc.), not the adult-heavy 'Greek Books'
        # trade catalog. The caller passes df_books as df_greek_books; we
        # restrict to the Greek Kids Books Level 2 here.
        if 'Level 2' in gb.columns:
            lvl2 = gb['Level 2'].astype(str).str.strip()
            kids_l2_mask = lvl2.apply(
                lambda v: _sb_strip_accents_upper(v).lower() == 'greek kids books')
            gb = gb[kids_l2_mask].copy()
            st_notes.append(f"Level 2 = 'Greek Kids Books' rows: {len(gb)}")
        else:
            st_notes.append("⚠ 'Level 2' column not found — cannot restrict to Greek Kids Books")
        
        age_col = 'Προτεινόμενη Ηλικία' if 'Προτεινόμενη Ηλικία' in gb.columns else None
        if age_col and not gb.empty:
            gb['_age_range'] = gb[age_col].apply(_sb_parse_age_range)
            # v28.30.16 — Tight age matching. A book's RECOMMENDED MINIMUM age
            # must be appropriate for THIS child — i.e. within a window around
            # the child's age band: [age_lo - 2, age_hi + 1]. This stops a
            # "4+" best-seller from dominating every class (a 10yo shouldn't be
            # shown a 4+ picture book just because it overlaps and sells well).
            # We also require the book's range to actually cover the child
            # (max_age >= age_lo), so "3-6" doesn't show for a 10yo.
            MIN_WINDOW_LO = age_lo - 2
            MIN_WINDOW_HI = age_hi + 1
            def _age_appropriate(rng):
                if rng is None:
                    return False
                bmin, bmax = rng
                # book's min age must be near the child's band
                if not (MIN_WINDOW_LO <= bmin <= MIN_WINDOW_HI):
                    return False
                # book's range must cover the child (not end before they start)
                if bmax < age_lo:
                    return False
                return True
            gb['_age_ok'] = gb['_age_range'].apply(_age_appropriate)
            # v28.30.18 — Two tiers within the kids' category:
            #   Tier A: age-appropriate (min-age in the acceptance window)
            #   Tier B: kids'-category books with NO/odd age tag — still
            #           legitimate children's books (being in the category is
            #           itself a kid signal), ranked AFTER the age-matched ones.
            # This keeps the pool deep enough to fill 5 slots even when few
            # kids' books carry a 'Προτεινόμενη Ηλικία' value.
            gb['_has_age'] = gb['_age_range'].apply(lambda r: r is not None)
            tier_a = gb[gb['_age_ok']].copy()
            tier_b = gb[~gb['_age_ok']].copy()   # includes no-age + out-of-window
            # Keep tier_b to no-age only (don't pull clearly wrong ages like
            # an 16+ teen book into a preschool list)
            tier_b = tier_b[~tier_b['_has_age']].copy()
            tier_a['_age_tier'] = 0
            tier_b['_age_tier'] = 1
            kids_books_pool = pd.concat([tier_a, tier_b], ignore_index=True)
            st_notes.append(f"Child age window from class: {age_lo}-{age_hi} years "
                            f"(book min-age accepted in {MIN_WINDOW_LO}-{MIN_WINDOW_HI})")
            st_notes.append(f"Age-matched kids' books: {len(tier_a)}; "
                            f"untagged kids' books (fallback): {len(tier_b)}")
            if not kids_books_pool.empty:
                # v28.30.26 — force plain float64 (avoid Arrow add error on pandas 3.x)
                import numpy as _np
                if 'Sum of Sales' in kids_books_pool.columns:
                    _s = pd.to_numeric(kids_books_pool['Sum of Sales'].astype('object'),
                                       errors='coerce').fillna(0.0)
                    kids_books_pool['_sales'] = _np.asarray(_s, dtype='float64')
                else:
                    kids_books_pool['_sales'] = 0.0
                if 'AVAILABILITY' in kids_books_pool.columns:
                    _av = kids_books_pool['AVAILABILITY'].astype('object').apply(
                        lambda v: float(SB_S_AVAIL_BONUS) if str(v).strip() == 'Άμεσα Διαθέσιμο' else 0.0)
                    kids_books_pool['_avail'] = _np.asarray(_av, dtype='float64')
                else:
                    kids_books_pool['_avail'] = 0.0
                # PURE top-selling WITHIN each tier: age-matched books first
                # (tier 0), then untagged kids' books (tier 1); sales-ranked
                # within each tier.
                kids_books_pool['Final_Score'] = (
                    kids_books_pool['_sales'].to_numpy(dtype='float64')
                    + kids_books_pool['_avail'].to_numpy(dtype='float64'))
                kids_books_pool['_tier_label'] = 'Kids book (top-selling for age)'
                kids_books_pool = kids_books_pool.sort_values(
                    ['_age_tier', '_sales'], ascending=[True, False]).reset_index(drop=True)
                st_notes.append(f"Top kids' book: {str(kids_books_pool.iloc[0].get('Title',''))[:50]}")
        else:
            st_notes.append("⚠ 'Προτεινόμενη Ηλικία' column not found in Greek Books")
    elif not show_kids_books:
        st_notes.append(f"Kids' books OFF (trigger class older than ~12yo) — school books only")
    else:
        st_notes.append("⚠ Greek Books catalog not provided")
    
    slot_notes[2] = st_notes
    diag.append(("2. Kids' Books Pool", len(kids_books_pool),
                 f"show_kids_books={show_kids_books}"))
    
    # ──────────────────────────────────────────────────────────
    # STEP 3 — SLOT ALLOCATION
    # ──────────────────────────────────────────────────────────
    # ──────────────────────────────────────────────────────────
    # STEP 4 — FILL THE 10 SLOTS
    # ──────────────────────────────────────────────────────────
    fill_notes = ["=== STEP 4: SLOT FILLING ==="]
    
    # v28.30.7 — PHASE SPLIT + DYNAMIC LAYOUT for older modes.
    #
    # Primary phase (front of carousel) = "author-matched companion volumes"
    #   For helper trigger with known author(s): same-subject + author overlap
    #   For helper trigger without author OR textbook trigger: same-subject only
    #
    # Secondary phase (back of carousel) = DIFFERENT-subject coverage
    #
    # Same-subject candidates that don't make it into primary (e.g. T2
    # Σαββάλας brothers Φυσική when trigger's author team is Παναγιωτακόπουλος)
    # are intentionally dropped — they're neither author-matched companions
    # (so don't belong in primary) nor different-subject (so don't belong
    # in secondary).
    #
    # The number of primary slots is DYNAMIC: if 4+ author-matched companions
    # exist, expand the primary section, push stationery down, and keep at
    # least 1 secondary slot. Cap at PRIMARY_MAX = 6 so the carousel never
    # loses all different-subject discovery.
    PRIMARY_MIN = 3   # at least 3 school slots in front (deficit from secondary if needed)
    PRIMARY_MAX = 6   # at most 6 same-subject slots (preserves 1+ secondary slot)
    STAT_SLOTS  = 3
    TOTAL_SLOTS = 10
    
    should_phase_split = (is_older_stage and t_subjects and not school_pool.empty
                          and (trigger_is_helper or trigger_is_textbook))
    
    if should_phase_split:
        t_sub_set = set(t_subjects)
        sp_same_subj = school_pool['_subjects'].apply(
            lambda lst: isinstance(lst, list) and bool(lst) and bool(set(lst) & t_sub_set))
        
        # v28.30.8 — Προσανατολισμός (orientation track) compatibility.
        # For Γ' Λυκείου especially, the student is committed to a track (Θετικ,
        # Ανθρωπ, Οικον, Γενικ, ΕΠΑ.Λ.). All recommended books — both primary
        # (same-subject companions) and secondary (cross-subject discovery) —
        # must be track-compatible. We token-normalize because exact wording
        # varies ("Θετικών Σπουδών" vs "Θετικών Σπουδών & Σπουδών Υγείας").
        # Empty trigger orientation (e.g. Διόφαντος core textbooks) skips the
        # filter; Γενικής Παιδείας books are accepted by any specialist trigger
        # since the general subjects apply to all tracks.
        if t_orient_tokens:
            sp_orient_ok = school_pool['_orientation'].apply(
                lambda v: _sb_orient_compatible(v, t_orient_tokens))
        else:
            sp_orient_ok = pd.Series([True] * len(school_pool), index=school_pool.index)
        
        # v28.30.7 — Tight primary filter, varies by trigger type.
        #   * Helper trigger: same Hierarchy (= same class + helper type) +
        #     same publisher + same subject + author overlap (if trigger has
        #     known author). Strict: rules out helpers from other classes
        #     (Α'/Β' Λυκείου) that happened to share author.
        #   * Textbook trigger: helper-hierarchy + best_helper_pub + same
        #     class + same subject. Strict: rules out other publishers'
        #     helpers (Ελληνοεκδοτική when best_helper_pub is Σαββάλας).
        sp_same_hier_strict = school_pool['_hier'] == t_hierarchy
        sp_same_pub = school_pool['_pub_norm'] == t_publisher if t_publisher else pd.Series([False] * len(school_pool), index=school_pool.index)
        
        if trigger_is_helper:
            primary_filter = sp_same_hier_strict & sp_same_pub & sp_same_subj
            if t_authors:
                sp_author = school_pool['_authors'].apply(
                    lambda s: isinstance(s, set) and bool(s & t_authors))
                primary_filter = primary_filter & sp_author
            primary_filter_desc = (
                f"same hier='{t_hierarchy}' + pub='{t_publisher_raw}' + subj"
                + (f" + author{t_authors}" if t_authors else "")
            )
        elif trigger_is_textbook:
            sp_helper_hier = school_pool['_hier'].apply(_sb_is_helper_hierarchy)
            sp_best_pub    = (school_pool['_pub_norm'] == best_helper_pub) if best_helper_pub else pd.Series([False] * len(school_pool), index=school_pool.index)
            # Class match — textbook hierarchy doesn't always cleanly align with
            # the helper hierarchy for the same class, so check Τάξη directly.
            if t_classes:
                t_cls_set = set(t_classes)
                sp_same_cls = school_pool['_classes'].apply(
                    lambda lst: isinstance(lst, list) and bool(set(lst) & t_cls_set))
            else:
                sp_same_cls = pd.Series([True] * len(school_pool), index=school_pool.index)
            primary_filter = sp_helper_hier & sp_best_pub & sp_same_cls & sp_same_subj
            primary_filter_desc = (
                f"helper-hierarchy + pub='{best_helper_pub}' (best helper publisher) "
                f"+ class + subj"
            )
        else:
            # Should not reach here (should_phase_split is True only for helper/textbook)
            primary_filter = sp_same_subj
            primary_filter_desc = "same subject (fallback)"
        
        # Apply Προσανατολισμός to BOTH phases — a Θετικ student doesn't want
        # Ανθρωπ Αρχαία in overflow either.
        primary_filter   = primary_filter   & sp_orient_ok
        secondary_filter = (~sp_same_subj)  & sp_orient_ok
        
        primary_pool   = school_pool[primary_filter].reset_index(drop=True)
        secondary_pool = school_pool[secondary_filter].reset_index(drop=True)
        # Same-subject rows that didn't pass the strict primary filter are
        # dropped from view.
        dropped_same_subj_n = int(sp_same_subj.sum() - primary_filter.sum())
        # Different-subject rows removed by orientation filter
        dropped_orient_n    = int((~sp_same_subj).sum() - secondary_filter.sum())
        
        if t_orient_tokens:
            orient_desc = f", Προσανατολισμός tokens={sorted(t_orient_tokens)}"
        else:
            orient_desc = ", Προσανατολισμός=∅ (no filter)"
        fill_notes.append(
            f"⚙ Phase split ON: primary ({primary_filter_desc}){orient_desc}")
        fill_notes.append(
            f"   primary={len(primary_pool)}, secondary={len(secondary_pool)}, "
            f"dropped (same-subj, filter mismatch)={dropped_same_subj_n}, "
            f"dropped (diff-subj, wrong orientation)={dropped_orient_n}")
    else:
        primary_pool   = school_pool if not school_pool.empty else pd.DataFrame()
        secondary_pool = pd.DataFrame()
        if not is_older_stage:
            fill_notes.append(f"⚙ Phase split OFF (younger stage '{t_stage}' — single pool)")
    
    # v28.30.10 — SERIES COMPANIONS at the front.
    # When the trigger is part of a multi-volume series (Τεύχος Α/Β/Γ,
    # Μέρος, τόμος), pull the other volumes of the SAME series and prepend
    # them to primary. They take priority over generic helpers because the
    # customer almost certainly wants the companion volume.
    #
    # v28.30.11 — Fuzzy series matching. Catalog titles for one series are
    # formatted inconsistently, so an exact base-title match misses real
    # siblings. We instead match on a normalized "series key" (set of subject
    # + distinguishing word stems) + same publisher + same class + same
    # orientation. A candidate is a sibling if its key shares the trigger's
    # subject token(s) and (when both have orientation) the orientation
    # tokens agree. The trigger itself is excluded by Material id.
    series_companion_count = 0
    t_series_key = _sb_series_key(t_tomos_base) if t_tomos_base else frozenset()
    if (t_tomos_rank is not None and t_series_key
            and not school_pool.empty
            and '_tomos_base' in school_pool.columns):
        sp_has_tomos = school_pool.get('_has_tomos', pd.Series([False] * len(school_pool), index=school_pool.index)).fillna(False).astype(bool)
        sp_same_pub_for_series = school_pool['_pub_norm'] == (t_publisher or '')
        # Same class as trigger
        if t_classes:
            t_cls_set_series = set(t_classes)
            sp_same_cls_series = school_pool['_classes'].apply(
                lambda lst: isinstance(lst, list) and bool(set(lst) & t_cls_set_series))
        else:
            sp_same_cls_series = pd.Series([True] * len(school_pool), index=school_pool.index)
        # Orientation agreement (token-based; empty trigger orientation = no constraint)
        if t_orient_tokens:
            sp_orient_series = school_pool['_orientation'].apply(
                lambda v: _sb_orient_compatible(v, t_orient_tokens))
        else:
            sp_orient_series = pd.Series([True] * len(school_pool), index=school_pool.index)
        # Series-key overlap: candidate's key must contain ALL of the trigger's
        # NON-orientation tokens (i.e. the subject). We compute per-row key
        # and test subset on the subject-bearing tokens.
        # Trigger subject tokens = series key minus orientation-ish tokens.
        orient_word_stems = {'θετικων', 'ανθρωπιστικων', 'οικονομιας', 'πληροφορικης', 'υγειας'}
        t_subject_tokens = frozenset(tok for tok in t_series_key if tok not in orient_word_stems)
        def _series_key_match(base):
            cand_key = _sb_series_key(base)
            if not cand_key: return False
            # Require all trigger subject tokens present in candidate
            return t_subject_tokens.issubset(cand_key)
        sp_key_match = school_pool['_tomos_base'].apply(_series_key_match)
        
        series_mask = sp_has_tomos & sp_same_pub_for_series & sp_same_cls_series & sp_orient_series & sp_key_match
        series_rows = school_pool[series_mask]
        if not series_rows.empty:
            # Sort siblings by τόμος rank (Α=1 → Β=2 → Γ=3 ...)
            series_rows = series_rows.sort_values('_tomos_rank', na_position='last').reset_index(drop=True)
            series_companion_count = len(series_rows)
            # De-dup: remove these rows from primary and secondary first
            if not primary_pool.empty and 'Material' in primary_pool.columns:
                primary_pool = primary_pool[~primary_pool['Material'].isin(series_rows['Material'])].reset_index(drop=True)
            if not secondary_pool.empty and 'Material' in secondary_pool.columns:
                secondary_pool = secondary_pool[~secondary_pool['Material'].isin(series_rows['Material'])].reset_index(drop=True)
            # Prepend siblings to primary so they fill the FIRST slots
            primary_pool = pd.concat([series_rows, primary_pool], ignore_index=True)
            fill_notes.append(
                f"⚙ Series companions: trigger is τόμος-rank {t_tomos_rank}, "
                f"series-key {sorted(t_subject_tokens)} → "
                f"{series_companion_count} sibling volume(s) prepended to primary")
    
    # v28.30.13 — SUMMER HOLIDAY BOOKS (ΒΙΒΛΙΑ ΔΙΑΚΟΠΩΝ).
    # In summer (Jun-Aug) for young kids (preschool → Ε' Δημοτικού), holiday
    # activity books are the natural cross-sell. We detect them by hierarchy /
    # series / title keyword across the full catalog (same class), and prepend
    # them to the primary pool so they lead the school slots. Degrades to a
    # no-op when no such books exist in the catalog (current state).
    holiday_book_count = 0
    if (is_summer and is_holiday_eligible and not school_pool.empty
            and 'Material' in school_pool.columns):
        def _is_holiday_book(row):
            for col in ('Hierarchy', 'Σειρά βιβλίου_sales', 'Title'):
                v = _sb_strip_accents_upper(str(row.get(col, ''))).lower()
                if any(kw in v for kw in SB_HOLIDAY_BOOK_KEYWORDS):
                    return True
            return False
        hol_mask = school_pool.apply(_is_holiday_book, axis=1)
        holiday_rows = school_pool[hol_mask]
        if not holiday_rows.empty:
            # Sort by sales desc (best-selling holiday book leads)
            if 'Sum of Sales' in holiday_rows.columns:
                holiday_rows = holiday_rows.copy()
                holiday_rows['_hsales'] = holiday_rows['Sum of Sales'].apply(_safe_num)
                holiday_rows = holiday_rows.sort_values('_hsales', ascending=False)
            holiday_book_count = len(holiday_rows)
            # De-dup from primary + secondary, then prepend to primary
            if not primary_pool.empty and 'Material' in primary_pool.columns:
                primary_pool = primary_pool[~primary_pool['Material'].isin(holiday_rows['Material'])].reset_index(drop=True)
            if not secondary_pool.empty and 'Material' in secondary_pool.columns:
                secondary_pool = secondary_pool[~secondary_pool['Material'].isin(holiday_rows['Material'])].reset_index(drop=True)
            primary_pool = pd.concat([holiday_rows, primary_pool], ignore_index=True)
            fill_notes.append(
                f"⚙ Summer holiday books (ΒΙΒΛΙΑ ΔΙΑΚΟΠΩΝ): {holiday_book_count} "
                f"holiday book(s) prepended to primary (summer + young class)")
        else:
            fill_notes.append(
                f"⚙ Summer + young class: no ΒΙΒΛΙΑ ΔΙΑΚΟΠΩΝ found in catalog "
                f"(feature ready; add holiday books to surface them)")
    
    # v28.30.21 — PRIVATE-SCHOOL LIST is handled via dedicated PRIVATE_LIST
    # slots in the layout below (not prepended to primary), because the
    # private-list books — especially from International School Books — lack
    # the _subjects/_classes/_orientation columns the school picker's
    # subject-diversity machinery expects. The dedicated picker ranks purely
    # by sales and bypasses that machinery. The KIDS' BOOK pool is untouched.
    private_list_count = len(private_list_pool) if (trigger_in_private_list and not private_list_pool.empty) else 0
    
    # ── Dynamic layout based on primary pool size ──
    # v28.30.15 — BOOKS-ONLY. The middle "extra" slots that previously held
    # stationery now hold KIDS' TRADE BOOKS (age-appropriate best-sellers)
    # when available (younger triggers). When no kids' books are available
    # (e.g. high school, or empty pool), those slots fall back to more
    # school books so the carousel always fills with books.
    n_primary_avail = len(primary_pool)
    # Number of NON-sibling helpers in primary pool — used to decide whether
    # the scarce-helpers fallback applies (sibling presence overrides it).
    n_helpers_in_primary = n_primary_avail - series_companion_count
    has_kids_books = (not kids_books_pool.empty)
    # The "extra" book slots (previously stationery): KIDS_BOOK if available,
    # else more SCHOOL books.
    EXTRA = 'KIDS_BOOK' if has_kids_books else ('SCHOOL_PRIMARY' if not should_phase_split else 'SCHOOL_SECONDARY')
    N_EXTRA = STAT_SLOTS   # keep the 3-slot middle band by default
    
    if should_phase_split:
        # OLDER stage (Γυμνάσιο/Λύκειο). High school → no kids books, so the
        # EXTRA band is school books. Α' Γυμνασίου (≤12yo) MAY have kids books.
        if (trigger_is_textbook
                and series_companion_count == 0
                and n_helpers_in_primary < 3):
            n_boost = 4 if n_helpers_in_primary <= 1 else 3
            n_overflow_primary   = n_helpers_in_primary
            n_overflow_secondary = TOTAL_SLOTS - n_boost - N_EXTRA - n_overflow_primary
            base_plan = (
                ['SCHOOL_SECONDARY']   * n_boost
                + [EXTRA]              * N_EXTRA
                + ['SCHOOL_PRIMARY']   * n_overflow_primary
                + ['SCHOOL_SECONDARY'] * n_overflow_secondary
            )
            fill_notes.append(
                f"⚙ Scarce-helpers layout (textbook, {n_helpers_in_primary} helper(s)): "
                f"{n_boost} textbooks + {N_EXTRA} {EXTRA.lower()} + "
                f"{n_overflow_primary} helper(s) + {n_overflow_secondary} textbooks")
        else:
            n_primary_slots = min(max(n_primary_avail, PRIMARY_MIN), PRIMARY_MAX)
            n_secondary_slots = TOTAL_SLOTS - n_primary_slots - N_EXTRA
            base_plan = (
                ['SCHOOL_PRIMARY']   * n_primary_slots
                + [EXTRA]            * N_EXTRA
                + ['SCHOOL_SECONDARY'] * n_secondary_slots
            )
            fill_notes.append(
                f"⚙ Dynamic layout: {n_primary_slots} school + {N_EXTRA} {EXTRA.lower()} + "
                f"{n_secondary_slots} school-overflow (cap on primary = {PRIMARY_MAX})")
    else:
        # YOUNGER stage (Δημοτικό/Προσχολική) — kids' books available.
        # v28.30.20 — School books occupy slots 1-4; kids' trade books start
        # AFTER slot 4 (the "rest of the books that aren't school" go later).
        if is_early_elementary and has_kids_books:
            base_plan = (
                ['SCHOOL_PRIMARY'] * 4     # slots 1-4: school books for the class
                + ['KIDS_BOOK']    * 5     # slots 5-9: age-appropriate kids' trade books
                + ['SCHOOL_PRIMARY'] * 1   # slot 10: one more school book
            )
            fill_notes.append("⚙ Early-elementary books-only layout: 4 school + 5 kids' books + 1 school")
        else:
            # Standard younger layout: 4 school + extra + remaining school
            base_plan = (
                ['SCHOOL_PRIMARY'] * 4
                + [EXTRA]          * N_EXTRA
                + ['SCHOOL_PRIMARY'] * (TOTAL_SLOTS - 4 - N_EXTRA)
            )
            fill_notes.append(f"⚙ Younger books-only layout: 4 school + {N_EXTRA} {EXTRA.lower()} + "
                              f"{TOTAL_SLOTS - 4 - N_EXTRA} school")
    
    alloc_notes = [
        "=== STEP 3: SLOT ALLOCATION ===",
    ]
    
    # v28.30.21 — PRIVATE-SCHOOL LIST substitution. When the trigger is on a
    # private-school list, the leading SCHOOL slots become PRIVATE_LIST slots
    # (filled from the same school+class companion books, sales-ranked). We
    # replace as many leading SCHOOL_PRIMARY/SECONDARY slots as we have list
    # books for — but NEVER the KIDS_BOOK slots (kids' logic is untouched).
    # If the list runs short, the remaining leading slots stay school books.
    if private_list_count > 0:
        n_to_replace = min(private_list_count, base_plan.count('SCHOOL_PRIMARY') + base_plan.count('SCHOOL_SECONDARY'))
        replaced = 0
        new_plan = []
        for slot in base_plan:
            if slot in ('SCHOOL_PRIMARY', 'SCHOOL_SECONDARY') and replaced < n_to_replace:
                new_plan.append('PRIVATE_LIST')
                replaced += 1
            else:
                new_plan.append(slot)
        base_plan = new_plan
        fill_notes.append(
            f"⚙ Private-school list: {replaced} slot(s) filled from the same "
            f"school+class list (sales-ranked); kids' slots preserved")
    
    alloc_notes.append(f"Plan: {' '.join(s[:5] for s in base_plan)}")
    slot_notes[3] = alloc_notes
    diag.append(("3. Slot Plan", f"{len(base_plan)} slots",
                 f"{base_plan.count('PRIVATE_LIST')} private-list + "
                 f"{base_plan.count('SCHOOL_PRIMARY')} primary + "
                 f"{base_plan.count('KIDS_BOOK')} kids + "
                 f"{base_plan.count('SCHOOL_SECONDARY')} secondary"))
    
    primary_list   = list(primary_pool.iterrows())   if not primary_pool.empty   else []
    secondary_list = list(secondary_pool.iterrows()) if not secondary_pool.empty else []
    kids_list      = list(kids_books_pool.iterrows()) if not kids_books_pool.empty else []
    private_list   = list(private_list_pool.iterrows()) if not private_list_pool.empty else []
    stat_list      = []   # stationery retired in this engine
    primary_consumed   = set()
    secondary_consumed = set()
    kids_consumed      = set()
    private_consumed   = set()
    
    # v28.30.7 — Diversity sets per phase.
    # Primary phase: no diversity tracking (same-subject companions WANTED).
    # Secondary phase: diversity ON — each overflow slot picks a DIFFERENT subject.
    # Younger stages (single pool): diversity ON throughout.
    primary_used_subjects   = set()   # tracks subjects in primary slots (younger only)
    secondary_used_subjects = set()   # tracks subjects in secondary slots (older split)
    
    if is_older_stage and should_phase_split:
        fill_notes.append(
            f"⚙ Subject diversity: OFF in primary (companion volumes), "
            f"ON in secondary (each overflow slot a different subject)")
    elif not is_older_stage:
        fill_notes.append(
            f"⚙ Subject diversity ON (younger stage '{t_stage}'): "
            f"each school slot picks a different subject")
    
    def _next_from(rows, consumed, enforce_diversity, used_subjects_set):
        """Generic pool consumer.
        When enforce_diversity is True and used_subjects_set is provided,
        skip rows whose subject overlaps with already-picked subjects."""
        for i, (_, row) in enumerate(rows):
            if i in consumed: continue
            mat = row.get('Material', None)
            if mat in used_materials:
                consumed.add(i); continue
            if enforce_diversity and used_subjects_set is not None:
                row_subjects = _sb_parse_multi_value(row.get('Μάθημα_sales', ''))
                if row_subjects and any(s in used_subjects_set for s in row_subjects):
                    continue   # subject already covered — save for relaxation pass
            # Accept
            consumed.add(i)
            if enforce_diversity and used_subjects_set is not None:
                for s in _sb_parse_multi_value(row.get('Μάθημα_sales', '')):
                    used_subjects_set.add(s)
            return row
        return None
    
    def _next_school(slot_type):
        """Pull the next eligible school candidate based on slot type.
        
        SCHOOL_PRIMARY (front slots):
          * Older + split: same-subject + author-matched pool.
            Diversity OFF (we want companion volumes piled up).
            Deficit fall to secondary if primary exhausted.
          * Younger: single pool, diversity ON (cover different subjects).
        SCHOOL_SECONDARY (overflow slots, older + split only):
          * Different-subject pool, diversity ON (each slot a different subject).
          * Relaxation pass if diversity exhausts the pool.
        """
        if slot_type == 'SCHOOL_PRIMARY':
            if is_older_stage and should_phase_split:
                # Older + split: companion volumes, no diversity needed
                row = _next_from(primary_list, primary_consumed,
                                 enforce_diversity=False, used_subjects_set=None)
                if row is None:
                    # Primary exhausted — fall to secondary with diversity ON
                    row = _next_from(secondary_list, secondary_consumed,
                                     enforce_diversity=True,
                                     used_subjects_set=secondary_used_subjects)
                return row
            else:
                # Younger: diversity ON
                row = _next_from(primary_list, primary_consumed,
                                 enforce_diversity=True,
                                 used_subjects_set=primary_used_subjects)
                if row is None:
                    # Relaxation pass without diversity
                    row = _next_from(primary_list, primary_consumed,
                                     enforce_diversity=False, used_subjects_set=None)
                return row
        else:  # SCHOOL_SECONDARY (only used in older + split mode)
            row = _next_from(secondary_list, secondary_consumed,
                             enforce_diversity=True,
                             used_subjects_set=secondary_used_subjects)
            if row is None:
                # Diversity-relaxation fallback
                row = _next_from(secondary_list, secondary_consumed,
                                 enforce_diversity=False, used_subjects_set=None)
            return row
    
    # v28.30.21 — Private-school list picker. Pulls the same school+class
    # companion books (sales-ranked), de-duped against already-shown books.
    def _next_private_list():
        for i, (_, row) in enumerate(private_list):
            if i in private_consumed: continue
            mat = row.get('Material', None)
            if mat in used_materials:
                private_consumed.add(i); continue
            private_consumed.add(i)
            return row
        return None
    
    # v28.30.15 — Kids' trade-book picker. Pulls age-appropriate best-selling
    # books from the kids_books_pool (sorted by sales). De-dups against books
    # already shown. No theme/hierarchy logic — these are trade books, ranked
    # purely by sales within the child's age window.
    def _next_kids_book():
        for i, (_, row) in enumerate(kids_list):
            if i in kids_consumed: continue
            mat = row.get('Material', None)
            if mat in used_materials:
                kids_consumed.add(i); continue
            kids_consumed.add(i)
            return row
        return None
    
    def _next_stationery():
        """Retired in this engine (books-only). Always returns None so any
        legacy fallback path degrades to school/kids books."""
        return None
    
    all_recs = []
    for slot_idx, slot_type in enumerate(base_plan, start=1):
        row = None
        picked_from = None
        
        if slot_type == 'PRIVATE_LIST':
            row = _next_private_list()
            picked_from = 'private_list'
            if row is None:
                # List exhausted — fall back to normal school books
                row = _next_school('SCHOOL_PRIMARY')
                picked_from = 'school (private-list exhausted)'
        elif slot_type in ('SCHOOL_PRIMARY', 'SCHOOL_SECONDARY'):
            row = _next_school(slot_type)
            picked_from = 'school'
            if row is None:
                # School pools exhausted — try a kids' book to fill
                row = _next_kids_book()
                picked_from = 'kids (school exhausted)'
        else:  # KIDS_BOOK
            row = _next_kids_book()
            picked_from = 'kids'
            if row is None:
                # Kids' books exhausted — fall back to school books.
                fallback_type = 'SCHOOL_SECONDARY' if slot_idx > 3 else 'SCHOOL_PRIMARY'
                row = _next_school(fallback_type)
                picked_from = 'school (kids exhausted)'
        
        if row is None:
            fill_notes.append(f"Slot {slot_idx}: EMPTY — pools exhausted")
            continue
        
        # Slot_Role label downstream
        if picked_from.startswith('private_list'):
            role = 'School Book (private-school list)'
            label = str(row.get('_tier_label', '') or '')
            tier_note = f" [{label}]" if label else ''
        elif picked_from.startswith('kids'):
            role = 'Kids Book (age-appropriate)'
            label = str(row.get('_tier_label', '') or '')
            tier_note = f" [{label}]" if label else ''
            age_val = str(row.get('Προτεινόμενη Ηλικία', '') or '')
            if age_val and age_val not in ('-', 'nan', 'none'):
                tier_note += f" (ηλικία {age_val})"
        elif picked_from.startswith('school'):
            # Use the slot_type to determine the role label so the carousel
            # reflects the dynamic primary/secondary boundary.
            if slot_type == 'SCHOOL_PRIMARY':
                role = 'School Book'
            elif slot_type == 'SCHOOL_SECONDARY':
                role = 'School Book (overflow)'
            else:
                role = 'School Book' if slot_idx <= 3 else 'School Book (overflow)'
            # v28.30.2 — Read the tier label directly from the row (stored
            # during _score_tier). Robust across both older-stage and
            # younger-stage tier orderings.
            label = str(row.get('_tier_label', '') or '')
            tier_note = f" [{label}]" if label else ''
            # If a τόμος was detected, append volume info so the diagnostic
            # makes the grouping reason visible.
            tomos_rank = row.get('_tomos_rank', None)
            try:
                if tomos_rank is not None and not pd.isna(tomos_rank) and int(tomos_rank) < 999:
                    letter = {1:'Α', 2:'Β', 3:'Γ', 4:'Δ', 5:'Ε', 6:'ΣΤ',
                              7:'Ζ', 8:'Η', 9:'Θ', 10:'Ι'}.get(int(tomos_rank), '')
                    if letter: tier_note += f" τόμος {letter}'"
            except (TypeError, ValueError):
                pass
        else:
            role = 'Book'
            tier_note = ''
        
        row_copy = row.copy()
        row_copy['Assigned_Slot'] = slot_idx
        row_copy['Slot_Role']     = role
        row_copy['Item_Rank']     = 1
        if 'Final_Score' not in row_copy.index or pd.isna(row_copy.get('Final_Score', None)):
            row_copy['Final_Score'] = _safe_num(row_copy.get('_sales', 0))
        
        all_recs.append(row_copy)
        used_materials.add(row_copy.get('Material', None))
        fill_notes.append(f"Slot {slot_idx} ({slot_type}) ← {picked_from}: "
                          f"{str(row.get('Title', ''))[:50]}{tier_note}")
    
    slot_notes[4] = fill_notes
    diag.append(("4. Slots Filled", len(all_recs), f"{len(all_recs)} of 10"))
    
    if not all_recs:
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()
    
    recs_df = pd.DataFrame(all_recs).reset_index(drop=True)
    return recs_df, diag, slot_notes, recs_df



def run_engine(trigger, df_products, df_history, df_slots):
    diag, slot_diag, slot_notes = [], [], {}

    tm   = trigger['Material']
    tt   = str(trigger.get('Title',''))
    tb   = str(trigger.get('Κατασκευαστής','')).strip().upper()
    tmod = str(trigger.get('Μοντέλο','')).strip()
    tpr  = str(trigger.get('Θύρα USB','')).strip()
    tport= extract_base_port(tpr)
    tcol = str(trigger.get('Χρώμα','')).strip()
    tex  = str(trigger.get('Extra Χαρακτηριστικά','')).lower()
    tos  = str(trigger.get('Λειτουργικό σύστημα','')).lower()
    thier= str(trigger.get('Hierarchy',''))
    tl1  = str(trigger.get('Level 1',''))
    tprice=parse_euro_price(trigger.get('LIST PRICE',0))
    ccols= get_case_colors(tcol)

    strict_tmod = ""
    if tmod:
        strict_tmod = rf"(?<![a-zA-Z0-9]){re.escape(tmod)}(?![a-zA-Z0-9])(?!\s*(Max|Plus|\+|Ultra|Pro))"

    brand_kws = {
        "SAMSUNG": ["samsung", "galaxy"], "APPLE": ["apple", "iphone", "ipad"],
        "XIAOMI": ["xiaomi", "redmi", "poco"], "OPPO": ["oppo"],
        "MOTOROLA": ["motorola", "moto"], "HUAWEI": ["huawei"],
        "HONOR": ["honor"], "REALME": ["realme"], "ONEPLUS": ["oneplus"],
        "VIVO": ["vivo"], "NOTHING": ["nothing", "cmf"]
    }
    rival_kws = []
    for k, v in brand_kws.items():
        if k != tb: rival_kws.extend(v)
    rival_regex = r"\b(" + "|".join(rival_kws) + r")\b" if rival_kws else ""

    c = df_products[df_products['Material']!=tm].copy()
    diag.append(("0. Start", len(c), ""))

    if 'Sum of Sales' in c.columns:
        c['Sales_Tiebreaker'] = pd.to_numeric(c['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c['Sales_Tiebreaker'] = 0

    c = c[c['Title']!=tt]; diag.append(("1. Title dedup", len(c), ""))


    mask = (c['Hierarchy']==thier) & (c['Κατασκευαστής'].fillna('').str.strip().str.upper()==tb)
    ns = mask.sum()
    if ns > 0:
        sims = c.loc[mask,'Title'].apply(lambda t: title_sim(tt,str(t)))
        dupes = sims[sims>=70].index; c=c.drop(dupes)
        diag.append(("3. Siblings", len(c), f"Checked {ns}, removed {len(dupes)}"))
    else: diag.append(("3. Siblings", len(c), "No siblings"))

    b4=len(c)
    if tl1 in TECH_CATS: c=c[~c['Level 1'].isin(APPL_CATS)]
    elif tl1 in APPL_CATS: c=c[~c['Level 1'].isin(TECH_CATS)]
    diag.append(("4a. Macro wall", len(c), f"Removed {b4-len(c)}"))

    b4eco = len(c)
    if tb == "APPLE":
        c = c[~c['Κατασκευαστής'].fillna('').str.strip().str.upper().isin(ANDROID_OEMS)]
    elif tb in ANDROID_OEMS:
        c = c[c['Κατασκευαστής'].fillna('').str.strip().str.upper() != "APPLE"]
    diag.append(("4b. Ecosystem wall (manufacturer)", len(c), f"Removed {b4eco-len(c)}"))
    
    b4hier = len(c)
    if tb == "APPLE":
        android_hier_keywords = ['samsung', 'xiaomi', 'huawei', 'oppo', 'oneplus', 'realme', 'android']
        hier_pattern = '|'.join(android_hier_keywords)
        c = c[~c['Hierarchy'].fillna('').str.lower().str.contains(hier_pattern, regex=True, na=False)]
    elif tb in ANDROID_OEMS:
        apple_hier_keywords = ['iphone', 'apple', 'ipad', 'macbook', 'airpods']
        hier_pattern = '|'.join(apple_hier_keywords)
        c = c[~c['Hierarchy'].fillna('').str.lower().str.contains(hier_pattern, regex=True, na=False)]
    diag.append(("4c. Ecosystem wall (hierarchy)", len(c), f"Removed {b4hier-len(c)}"))

    b4jack = len(c)
    jack_keywords = ['3.5mm', '3,5mm', 'aux', 'jack', 'btmusicreceiver', 'music receiver', 'audio receiver']
    jack_pattern = '|'.join(jack_keywords)
    c = c[~c['Title'].fillna('').str.lower().str.contains(jack_pattern, regex=True, na=False)]
    diag.append(("4d. Jack/Aux filter", len(c), f"Removed {b4jack-len(c)}"))

    tcust = df_history[df_history['Material']==tm]['customerEmail'].unique()
    bw = df_history[(df_history['customerEmail'].isin(tcust))&(df_history['Material']!=tm)]
    fdf = bw['Material'].value_counts().reset_index(); fdf.columns=['NID','Frequency']
    c = c.merge(fdf, left_on='Material', right_on='NID', how='left')
    c['Frequency']=c['Frequency'].fillna(0).astype(int)
    c['History_Score']=c['Frequency'].apply(lambda f: HISTORY_BOOST if f>=HISTORY_FREQ_MIN else 0)
    
    c['Next_Price']=c['LIST PRICE'].apply(parse_euro_price)

    hm=c['History_Score']>0
    if hm.any():
        ok=c.loc[hm].apply(lambda r: price_ok(tprice,r['Next_Price'],tl1), axis=1)
        c.loc[ok[~ok].index,'History_Score']=0

    c['Avail_Boost']=0; c.loc[c['AVAILABILITY']=='Άμεσα Διαθέσιμο','Avail_Boost']=AVAIL_BOOST
    c['Smart_Boost'] = 0.0
    
    if strict_tmod:
        c.loc[c['Μοντέλο'].fillna('').astype(str).str.contains(strict_tmod, case=False, regex=True, na=False), 'Smart_Boost'] += SMART_BOOST

    # 🟢 NEW: Premium phone absolute brand preference & High-End Best Seller Fallback
    PREMIUM_PRICE_THRESHOLD = 850
    PREMIUM_BRAND_BOOST = 5000000.0  # Massive absolute boost to guarantee brand matches win
    BEST_SELLER_BOOST = 200000.0
    EXPENSIVE_BOOST = 100000.0
    PREMIUM_ACC_MIN_PRICE = 25.0
    
    is_premium = tprice >= PREMIUM_PRICE_THRESHOLD
    if is_premium:
        is_same_brand = c['Κατασκευαστής'].fillna('').str.strip().str.upper() == tb
        is_best_seller = c['Sales_Tiebreaker'].fillna(0.0) > 0
        is_expensive = c['Next_Price'].fillna(0.0) >= PREMIUM_ACC_MIN_PRICE
        
        # Tier 0: Absolute Priority: Exact Brand Match in every slot (e.g., Apple on Apple)
        c.loc[is_same_brand, 'Smart_Boost'] += PREMIUM_BRAND_BOOST
        
        # Tier 1: Fallback Priority 1: Best Sellers for slots without brand match
        c.loc[~is_same_brand & is_best_seller, 'Smart_Boost'] += BEST_SELLER_BOOST
        
        # Tier 2: Fallback Priority 2: Expensive items
        c.loc[~is_same_brand & ~is_best_seller & is_expensive, 'Smart_Boost'] += EXPENSIVE_BOOST
        
        # Intra-tier sorting: scale everything by price so the PRICIEST item floats to the top of its respective tier
        c['Smart_Boost'] += c['Next_Price'].fillna(0.0) * 1000.0
        
        diag.append(("Premium High-End Strategy", f"€{tprice:.0f} >= €{PREMIUM_PRICE_THRESHOLD}", "1. Exact Brand, 2. Priciest Best-Sellers, 3. Priciest Fallbacks"))
    else:
        # 🟢 LOWER-END STRATEGY
        # Rule 2: Exclude other major brands from being recommended entirely to avoid cross-contamination
        MAJOR_BRANDS = ["APPLE", "SAMSUNG", "XIAOMI", "HUAWEI", "OPPO"]
        other_majors = [b for b in MAJOR_BRANDS if b != tb]
        b4_major = len(c)
        c = c[~c['Κατασκευαστής'].fillna('').str.strip().str.upper().isin(other_majors)]
        diag.append(("Lower-End Major Brand Filter", len(c), f"Removed {b4_major - len(c)} cross-brand items"))
        
        # Base smart boost for exact brand matches globally
        c.loc[c['Κατασκευαστής'].fillna('').str.strip().str.upper()==tb,'Smart_Boost'] += SMART_BOOST
    
    def extract_year_from_model(model_str):
        model = str(model_str).lower()
        year_match = re.search(r'\b(202[3-9])\b', model)
        if year_match: return int(year_match.group(1))
        s_match = re.search(r'galaxy\s*s\s*(\d{2})', model)
        if s_match:
            num = int(s_match.group(1))
            if 20 <= num <= 30: return 2000 + num
        a_match = re.search(r'galaxy\s*a\s*(\d{2})', model)
        if a_match:
            num = int(a_match.group(1))
            if num >= 50: return 2019 + (num - 50)
        z_match = re.search(r'(flip|fold)\s*(\d)', model)
        if z_match: return 2019 + int(z_match.group(2))
        iphone_match = re.search(r'iphone\s*(\d{1,2})', model)
        if iphone_match:
            num = int(iphone_match.group(1))
            if num >= 12: return 2008 + num 
            elif num >= 10: return 2017 
        return None
    
    def extract_year_from_accessory(title_str, model_str=''):
        text = f"{title_str} {model_str}".lower()
        year_match = re.search(r'\b(202[3-9])\b', text)
        if year_match: return int(year_match.group(1))
        buds_match = re.search(r'buds\s*(\d|fe|pro|live)', text)
        if buds_match:
            v = buds_match.group(1)
            if v == '4': return 2025
            if v == '3': return 2024
            if v == '2': return 2022
            if v == 'fe': return 2023
            if v == 'pro': return 2022
            if v == 'live': return 2020
        watch_match = re.search(r'(galaxy\s*)?watch\s*(\d)', text)
        if watch_match: return 2018 + int(watch_match.group(2))
        fit_match = re.search(r'(galaxy\s*)?fit\s*(\d)', text)
        if fit_match: return 2021 + int(fit_match.group(2))
        return None
    
    phone_year = extract_year_from_model(tmod) or extract_year_from_model(tt)
    
    c['Final_Score'] = c['History_Score'] + c['Frequency'] + c['Avail_Boost'] + c['Smart_Boost'] + c['Sales_Tiebreaker']

    b4u5=len(c)
    nhm=c['History_Score']==0
    if nhm.any():
        ok2=c.loc[nhm].apply(lambda r: price_ok(tprice,r['Next_Price'],tl1), axis=1)
        c=c.drop(ok2[~ok2].index)
    diag.append(("5. Price ceiling", len(c), f"Removed {b4u5-len(c)}"))

    all_slot = []
    for _, sr in df_slots.iterrows():
        sn = sr['Slot_Number']
        role = str(sr.get('Slot_Role',''))
        lk = detect_logic_key(role)
        ah = [h.strip() for h in str(sr['Allowed_Hierarchies']).split(",")]
        sc = c[c['Hierarchy'].isin(ah)].copy()
        afh = len(sc)
        notes = [f"Logic: {lk}"]

        model_specific_slots = ["PRIMARY_CASE", "SCREEN_GLASS", "CAMERA_GLASS", "ALT_CASE"]
        
        if lk in model_specific_slots:
            if strict_tmod:
                b4 = len(sc)
                cv = sc[CC].fillna('').astype(str).str.lower()
                m = sc[cv.str.contains(strict_tmod, case=False, regex=True, na=False)]
                if m.empty:
                    m = sc[sc['Title'].fillna('').astype(str).str.lower().str.contains(strict_tmod, case=False, regex=True, na=False)]
                if rival_regex and not m.empty:
                    m = m[~m[CC].fillna('').astype(str).str.lower().str.contains(rival_regex, regex=True, na=False)]
                    m = m[~m['Title'].fillna('').astype(str).str.lower().str.contains(rival_regex, regex=True, na=False)]
                notes.append(f"Model '{tmod}': {b4}→{len(m)}")
                sc = m  
            else:
                sc = sc.head(0)
            
            if lk == "PRIMARY_CASE":
                if not sc.empty:
                    b4=len(sc)
                    f=sc[sc['Τύπος Θήκης'].fillna('').astype(str).str.contains("Back Cover", case=False, na=False)]
                    notes.append(f"Back Cover: {b4}→{len(f)}")
                    sc = f  
                if not sc.empty and tcol:
                    b4=len(sc)
                    exact_colors = [clr for clr in ccols if clr != 'διάφανο' and clr != 'transparent']
                    sc_exact = sc[sc['Χρώμα'].fillna('').astype(str).str.strip().str.lower().isin(exact_colors)]
                    if not sc_exact.empty:
                        sc = sc_exact
                        notes.append(f"Color (exact): {b4}→{len(sc)}")
                    else:
                        sc_transparent = sc[sc['Χρώμα'].fillna('').astype(str).str.strip().str.lower().isin(['διάφανο', 'transparent', 'clear'])]
                        if not sc_transparent.empty:
                            sc = sc_transparent
                            notes.append(f"Color (transparent fallback): {b4}→{len(sc)}")
                        else:
                            notes.append(f"Color: no match, keeping all {b4}")
            
            # 🟢 LOWER-END PROTECTION RULE (Rule 1)
            # Prioritize Brand+Sales, then TUNE, then Brand w/o Sales
            if not is_premium and not sc.empty:
                is_same_brand_slot = sc['Κατασκευαστής'].fillna('').str.strip().str.upper() == tb
                has_sales_slot = sc['Sales_Tiebreaker'].fillna(0.0) > 0
                is_tune_slot = sc['Κατασκευαστής'].fillna('').str.strip().str.upper() == "TUNE"
                
                # Apply custom score hierarchy
                sc.loc[is_same_brand_slot & has_sales_slot, 'Final_Score'] += 200000.0
                sc.loc[is_tune_slot, 'Final_Score'] += 100000.0
                sc.loc[is_same_brand_slot & ~has_sales_slot, 'Final_Score'] += 50000.0
                
                # Standard sales tiebreaker within the tiers
                sc['Final_Score'] += sc['Sales_Tiebreaker'].fillna(0.0) * 10.0
                notes.append("Applied Lower-End Protection Rule: 1. Brand+Sales, 2. TUNE")

        if lk == "CROSS_SELL" and not sc.empty:
            b4_brand = len(sc)
            samsung_only_keywords = ['smarttag', 'galaxy smart']
            apple_only_keywords = ['airtag']
            
            def is_compatible_accessory(row):
                title_lower = str(row.get('Title', '')).lower()
                if any(kw in title_lower for kw in samsung_only_keywords): return tb == "SAMSUNG" 
                if any(kw in title_lower for kw in apple_only_keywords): return tb == "APPLE" 
                return True
            
            sc = sc[sc.apply(is_compatible_accessory, axis=1)]
            if len(sc) < b4_brand: notes.append(f"Brand filter (trackers): {b4_brand}→{len(sc)}")

        has_wireless_charging = 'ασύρματη φόρτιση' in tex
        has_fast_charging = 'γρήγορη φόρτιση' in tex
        
        charger_slots = ["WALL_CHARGER", "POWERBANK"]
        if lk in charger_slots and not sc.empty:
            WIRELESS_BOOST = 30000 
            FAST_CHARGE_BOOST = 20000 
            HIGH_WATT_BOOST = 15000 
            
            # Apply dynamic wattage boosts
            for idx in sc.index:
                item_title = str(sc.loc[idx, 'Title']).lower()
                item_watt = str(sc.loc[idx, 'Ισχύς (Watt)']) if 'Ισχύς (Watt)' in sc.columns else ''
                
                if has_fast_charging or is_premium:
                    watt_match = re.search(r'(\d+)\s*w', item_title)
                    watt_from_col = re.search(r'(\d+)', str(item_watt)) if item_watt else None
                    
                    wattage = 0
                    if watt_match: wattage = int(watt_match.group(1))
                    elif watt_from_col: wattage = int(watt_from_col.group(1))
                    elif '21 - 60' in str(item_watt): wattage = 45 
                    
                    if is_premium:
                        if wattage >= 45: sc.loc[idx, 'Final_Score'] += FAST_CHARGE_BOOST + HIGH_WATT_BOOST
                        elif wattage >= 25: sc.loc[idx, 'Final_Score'] += FAST_CHARGE_BOOST
                        elif wattage >= 20: sc.loc[idx, 'Final_Score'] += FAST_CHARGE_BOOST // 2
                    else: # Lower-end phone with fast charge
                        if 20 <= wattage <= 35: 
                            sc.loc[idx, 'Final_Score'] += FAST_CHARGE_BOOST + HIGH_WATT_BOOST
                        elif wattage >= 45: 
                            sc.loc[idx, 'Final_Score'] += FAST_CHARGE_BOOST // 2
                        elif wattage >= 15:
                            sc.loc[idx, 'Final_Score'] += FAST_CHARGE_BOOST // 3

            # 🟢 STRICT STRUCTURAL LOOPING FOR WALL_CHARGER 
            if lk == "WALL_CHARGER":
                is_cable = sc['Title'].fillna('').str.lower().str.contains(r'καλώδιο|cable') & ~sc['Title'].fillna('').str.lower().str.contains(r'φορτισ|charger|adapt|αντάπτ')
                is_wireless_item = sc['Title'].fillna('').str.lower().str.contains(r'wireless|ασύρματ|magsafe')
                is_brick = (~is_cable) & (~is_wireless_item)
                
                if has_wireless_charging:
                    # 1. Wireless, 2. Brick, 3. Cable
                    sc.loc[is_wireless_item, 'Final_Score'] += 3000000.0
                    sc.loc[is_brick, 'Final_Score'] += 2000000.0
                    sc.loc[is_cable, 'Final_Score'] += 1000000.0
                    notes.append("Charger Order: 1st Wireless, 2nd Brick, 3rd Cable")
                else:
                    # 1. Brick, 2. Cable
                    sc.loc[is_brick, 'Final_Score'] += 3000000.0
                    sc.loc[is_cable, 'Final_Score'] += 2000000.0
                    sc.loc[is_wireless_item, 'Final_Score'] -= 1000000.0
                    notes.append("Charger Order: 1st Brick, 2nd Cable (No Wireless)")
                
                # Filter strictly for cable port match
                if tport:
                    wrong_port = is_cable & ~sc['Title'].fillna('').str.lower().str.contains(tport.lower())
                    sc.loc[wrong_port, 'Final_Score'] -= 5000000.0

            sc = sc.sort_values('Final_Score', ascending=False)
            
            features = []
            if has_wireless_charging: features.append("Wireless")
            if has_fast_charging: features.append("FastCharge")
            if is_premium:
                notes.append(f"Phone features: {', '.join(features)} (Premium 45W+ preferred)")
            else:
                notes.append(f"Phone features: {', '.join(features)} (Standard 25W preferred)")

        year_match_slots = ["EARBUDS", "SMARTWATCH"]
        ULTRA_PREMIUM_THRESHOLD = 1700 
        
        if lk in year_match_slots and not sc.empty:
            # 1. Price Threshold Logic
            if lk == "EARBUDS":
                if tprice >= 1500: min_price = 100
                elif tprice >= 1000: min_price = 60
                elif tprice >= 600: min_price = 30
                elif tprice >= 300: min_price = 15
                else: min_price = 0
            else: 
                if tprice >= 1500: min_price = 200
                elif tprice >= 1000: min_price = 150
                elif tprice >= 600: min_price = 80
                elif tprice >= 300: min_price = 40
                else: min_price = 0
            
            if min_price > 0:
                b4_price = len(sc)
                sc['Acc_Price'] = sc['LIST PRICE'].apply(lambda x: parse_euro_price(x))
                price_filtered = sc[sc['Acc_Price'] >= min_price]
                if not price_filtered.empty:
                    sc = price_filtered
                    notes.append(f"Price tier (€{tprice:.0f} phone): min €{min_price} → {b4_price}→{len(sc)}")
                else:
                    notes.append(f"Price tier: No items ≥€{min_price}, keeping all {b4_price}")
            
            # 2. UNIVERSAL BRAND PRIORITY
            is_same_brand_wearable = sc['Κατασκευαστής'].fillna('').str.strip().str.upper() == tb
            sc.loc[is_same_brand_wearable, 'Final_Score'] += 5000000.0
            notes.append(f"Universal Wearable Brand Priority (+5M for {tb})")
            
            # 3. Ultra-Premium Filter (>= 1700€)
            is_ultra_premium = tprice >= ULTRA_PREMIUM_THRESHOLD
            if is_ultra_premium:
                b4_ultra = len(sc)
                premium_keywords = ['pro', 'ultra', 'classic', 'studio', 'max', 'elite']
                premium_pattern = '|'.join(premium_keywords)
                premium_sc = sc[sc['Title'].fillna('').str.lower().str.contains(premium_pattern, regex=True, na=False)]
                if not premium_sc.empty:
                    sc = premium_sc
                    notes.append(f"Ultra-premium filter (€{tprice:.0f}): {b4_ultra}→{len(sc)} (Pro/Ultra only)")
                else:
                    notes.append(f"Ultra-premium filter: No Pro/Ultra found, keeping all {b4_ultra}")
            
            # 4. Universal Year Matching
            if phone_year:
                sc['Accessory_Year'] = sc.apply(lambda r: extract_year_from_accessory(str(r.get('Title', '')), str(r.get('Μοντέλο', ''))), axis=1)
                
                # Add year boost directly to Final_Score so it respects Brand/Tier hierarchy
                sc.loc[sc['Accessory_Year'] > phone_year, 'Final_Score'] += 800000.0 
                sc.loc[sc['Accessory_Year'] == phone_year, 'Final_Score'] += 600000.0 
                sc.loc[sc['Accessory_Year'] == phone_year - 1, 'Final_Score'] += 400000.0 
                
                newer_count = (sc['Accessory_Year'] > phone_year).sum()
                same_year_count = (sc['Accessory_Year'] == phone_year).sum()
                prev_year_count = (sc['Accessory_Year'] == phone_year - 1).sum()
                notes.append(f"Year boost ({phone_year}): {newer_count} newer, {same_year_count} same, {prev_year_count} prev")

        if lk == "HOLDER" and not sc.empty:
            if has_wireless_charging or tb == "APPLE":
                for idx in sc.index:
                    item_title = str(sc.loc[idx, 'Title']).lower()
                    if 'magsafe' in item_title or 'magnetic' in item_title or 'mag' in item_title:
                        sc.loc[idx, 'Final_Score'] += 10000
                notes.append("Boosted MagSafe/magnetic holders for wireless phone")
            
            sc = sc.sort_values('Final_Score', ascending=False).copy()
            top_holders = sc.head(10)
            
            if len(top_holders) > 1:
                seed = hash(str(tm) + "_holder") % len(top_holders)
                rotated_indices = [(seed + i) % len(top_holders) for i in range(len(top_holders))]
                sc = top_holders.iloc[rotated_indices].copy()
                notes.append(f"Holder rotation: showing #{seed + 1} of {len(top_holders)}")

        afa = len(sc)
        slot_diag.append((sn, role, lk, afh, afa))
        slot_notes[sn] = notes

        if not sc.empty:
            skip_resort = (lk == "HOLDER" or lk == "WALL_CHARGER")
            if not skip_resort:
                sc = sc.sort_values('Final_Score', ascending=False).copy()
            else:
                sc = sc.copy() 
            sc['Assigned_Slot']=sn; sc['Slot_Role']=role
            sc['Item_Rank']=range(1,len(sc)+1)
            sc['Draft_Score']=sc['Item_Rank']*100+sn
            all_slot.append(sc)

    if not all_slot: return pd.DataFrame(), diag, slot_diag, slot_notes, pd.DataFrame()

    full = pd.concat(all_slot, ignore_index=True).sort_values('Draft_Score').reset_index(drop=True)

    sel, hc, seen = [], {}, set()
    for _, r in full.iterrows():
        h, mat = r['Hierarchy'], r['Material']
        if mat in seen: continue
        if hc.get(h,0)>=2: continue
        sel.append(r); hc[h]=hc.get(h,0)+1; seen.add(mat)
        if len(sel)>=10: break

    diag.append(("6. Final", len(sel), "Hierarchy cap=2"))
    return (pd.DataFrame(sel) if sel else pd.DataFrame()), diag, slot_diag, slot_notes, full

# ═══════════════════════════════════════════════════════════════════════════════
# SCORING CONSTANTS
# ═══════════════════════════════════════════════════════════════════════════════
 
SCORE_MODEL_MATCH   = 1_000_000   # Exact model compatibility
SCORE_USB_PORT      =   500_000   # USB port compatibility
SCORE_WATTAGE       =   300_000   # 30W+ charger
SCORE_SD_CARD       =   500_000   # Micro SD (Android)
SCORE_SD_CAPACITY   =   100_000   # 64 / 128 GB capacity
SCORE_OTG_ADAPTER   =   500_000   # OTG/Adapter (iOS)
SCORE_CABLE_LENGTH  =   200_000   # Cable ≥ 2 m
 
 
# ═══════════════════════════════════════════════════════════════════════════════
# TABLET ENGINE
# ═══════════════════════════════════════════════════════════════════════════════


def run_tablets_engine(trigger, df_products, df_history):
    diag, slot_notes, all_recs = [], {}, []
 
    # ----- Trigger -----
    tm     = trigger['Material']
    tt     = str(trigger.get('Title', ''))
    tb     = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmod   = str(trigger.get('Μοντέλο', '')).strip()
    trat   = str(trigger.get('Experts Rating', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier  = get_tablet_tier(tprice)
    tos    = str(trigger.get('Λειτουργικό σύστημα', '')).lower()
    tsize  = parse_screen_size(trigger.get('Μέγεθος οθόνης', 0))
    if tsize <= 0:
        tsize = _extract_size_from_title(tt)   # title fallback
    tport  = str(extract_base_port(trigger.get('Θύρα USB', ''))).strip()
    tcolor = str(trigger.get('Χρώμα', '')).strip()
    color_toks = _color_tokens(tcolor)
 
    is_premium    = tb in TABLET_PREMIUM_BRANDS and (
                      ttier in ('Pro', 'Upper Medium')
                      or trat in ('Excellent', 'Top Quality'))
    is_apple_ipad = tb == 'APPLE'
    is_kiddoboo   = tb == 'KIDDOBOO'
 
    diag.append(("0. Trigger",
                 f"Brand={tb}, Tier={ttier}, Model={tmod}",
                 f"OS={tos}, Size={tsize}\", Port={tport}, Color={tcolor or '-'}"))
 
    # ----- Pool prep -----
    c = df_products[df_products['Material'] != tm].copy()
    c['Sales_Tiebreaker'] = pd.to_numeric(c.get('Sum of Sales', 0),
                                          errors='coerce').fillna(0)
    c['_p'] = c['LIST PRICE'].apply(parse_euro_price)
 
    apple_hier = ('APPLE ORIGINAL TABLET ACCESSORIES',
                  'APPLE ORIGINAL TABLET BAGS')
    c['_apple_cat'] = ''
    apple_mask = c['Hierarchy'].isin(apple_hier)
    if apple_mask.any():
        c.loc[apple_mask, '_apple_cat'] = (
            c.loc[apple_mask].apply(_apple_orig_categorize, axis=1)
        )
 
    has_kb_match = False
    if tmod:
        kb_pool = c[c['Hierarchy'] == 'TABLETS KEYBOARDS']
        if not kb_pool.empty:
            has_kb_match = _compat_mask(kb_pool, tmod).any()
    diag.append(("1. KB Compat", f"has_kb_match={has_kb_match}",
                 f"premium={is_premium}"))
 
    # ----- Persona -----
    if is_kiddoboo:
        slots, persona = _build_kiddoboo_slots(), 'KIDDOBOO'
    elif is_apple_ipad:
        slots, persona = _build_apple_ipad_slots(), 'IPAD'
    else:
        slots = _build_standard_slots(has_kb_match, is_premium)
        persona = 'STANDARD_PREMIUM' if is_premium else 'STANDARD'
    slots = _renumber(slots)
    diag.append(("2. Persona", persona, f"{len(slots)} slots planned"))
 
    # ----- Main pass -----
    used_materials  = {tm}
    used_apple_cats = set()
    failed_slots    = []
 
    for slot_num, role, hierarchies, logic_key in slots:
        notes = [f"Logic: {logic_key}"]
        pool = c[c['Hierarchy'].isin(hierarchies)].copy()
        pool = pool[~pool['Material'].isin(used_materials)]
        if pool.empty:
            slot_notes[slot_num] = notes + ['EMPTY_POOL']
            failed_slots.append((slot_num, role, hierarchies, logic_key, 'EMPTY_POOL'))
            continue
 
        pool['Final_Score'] = 0.0
        same_brand = (_series(pool, 'Κατασκευαστής')
                      .str.upper().str.strip() == tb)
        pool.loc[same_brand, 'Final_Score'] += S_BRAND_BOOST
 
        if tmod:
            mm = _compat_mask(pool, tmod)
            pool.loc[mm, 'Final_Score'] += S_MODEL_MATCH
 
        base = logic_key.split(':', 1)[0]
 
        # ───── APPLE TARGET (iPad slots 1, 4) ─────
        if base in ('APPLE_TARGET', 'APPLE_TARGET_STRICT'):
            target_cats = set(logic_key.split(':', 1)[1].split(','))
            in_target = pool['_apple_cat'].isin(target_cats)
            if in_target.any():
                pool = pool[in_target]
            else:
                slot_notes[slot_num] = notes + ['NO_APPLE_TARGET']
                failed_slots.append((slot_num, role, hierarchies, logic_key, 'NO_APPLE_TARGET'))
                continue
            pool.loc[pool['_apple_cat'].isin(used_apple_cats),
                     'Final_Score'] += S_CATEGORY_REPEAT
            if base == 'APPLE_TARGET_STRICT' and tmod:
                # Exact match — substring would let "iPad Pro" match
                # "iPad Pro 11" 2024 (M4)" cross-listings on Air keyboards.
                mm2 = _exact_compat_match(pool, tmod)
                if mm2.any():
                    pool = pool[mm2]
                else:
                    slot_notes[slot_num] = notes + ['NO_MODEL_COMPAT']
                    failed_slots.append((slot_num, role, hierarchies, logic_key, 'NO_MODEL_COMPAT'))
                    continue
 
        # ───── APPLE FOLIO STRICT — 3-tier chain ─────
        # Tier 1: Apple Original Folio with EXACT model match
        # Tier 2: Universal Tablet Bag (Brand συσκευής σου = UNIVERSAL)
        # Tier 3: NB BAG with size match
        elif base == 'APPLE_FOLIO_STRICT':
            in_target = pool['_apple_cat'].isin(['Folio'])
            apple_folio_ok = False
            if in_target.any():
                folio_pool = pool[in_target].copy()
                folio_pool.loc[folio_pool['_apple_cat'].isin(used_apple_cats),
                               'Final_Score'] += S_CATEGORY_REPEAT
                if tmod:
                    em = _exact_compat_match(folio_pool, tmod)
                    if em.any():
                        pool = folio_pool[em]
                        pool = _apply_color_boost(pool, color_toks)
                        apple_folio_ok = True
                        notes.append('APPLE_FOLIO_EXACT')
            if not apple_folio_ok:
                # Tier 2: Universal Tablet Bag
                univ = _universal_tablet_bag_pool(c, used_materials, tb, tsize, color_toks)
                if not univ.empty:
                    pool = univ
                    role = 'Tablet Bag (Universal)'
                    notes.append('UNIVERSAL_TABLET_BAG')
                else:
                    # Tier 3: NB BAG
                    nb = _nb_bag_fallback_pool(c, used_materials, tb, tsize, is_premium)
                    if nb.empty:
                        slot_notes[slot_num] = notes + ['NO_FOLIO_NO_UNIV_NO_NB']
                        failed_slots.append((slot_num, role, hierarchies, logic_key, 'NO_FOLIO_NO_NB'))
                        continue
                    pool = nb
                    role = 'NB Bag'
                    notes.append('NB_BAG_FALLBACK')
 
        # ───── BRAND-FIRST hard filter ─────
        elif base == 'BRAND_FIRST':
            pool = _brand_first_filter(pool, tb)
 
        # ───── TABLET BAG / CASE fit — 3-tier chain ─────
        # Tier 1: Same-brand TABLET BAG with EXACT model match
        # Tier 2: Universal Tablet Bag (Brand συσκευής σου = UNIVERSAL)
        # Tier 3: NB BAG with size match
        elif base == 'CASE_FIT':
            exact_match_found = False
            # Tier 1: own-brand pool only (NOT universals — those go to Tier 2
            # without the exact-match requirement)
            brand_dev_full = _series(pool, 'Brand συσκευής σου').str.upper().str.strip()
            own_brand_pool = pool[brand_dev_full.eq(tb)].copy()
            if tmod and not own_brand_pool.empty:
                em = _exact_compat_match(own_brand_pool, tmod)
                if em.any():
                    pool = own_brand_pool[em].copy()
                    exact_match_found = True
                    notes.append('CASE_BRAND_EXACT')
                    ttype = _series(pool, 'Τύπος Θήκης').str.lower()
                    if is_premium or is_apple_ipad:
                        pool.loc[ttype.isin(['folio', 'book cover']),
                                 'Final_Score'] += S_CASE_TYPE_PRIMARY
                    else:
                        pool.loc[ttype.eq('back cover'),
                                 'Final_Score'] += S_CASE_TYPE_PRIMARY
                    pool = _apply_color_boost(pool, color_toks)
            if not exact_match_found:
                # Tier 2: Universal Tablet Bag
                univ = _universal_tablet_bag_pool(c, used_materials, tb, tsize, color_toks)
                if not univ.empty:
                    pool = univ
                    role = 'Tablet Bag (Universal)'
                    notes.append('UNIVERSAL_TABLET_BAG')
                else:
                    # Tier 3: NB BAG
                    nb = _nb_bag_fallback_pool(c, used_materials, tb, tsize, is_premium)
                    if nb.empty:
                        slot_notes[slot_num] = notes + ['NO_CASE_NO_UNIV_NO_NB']
                        failed_slots.append((slot_num, role, hierarchies, logic_key, 'NO_CASE_NO_NB'))
                        continue
                    pool = nb
                    role = 'NB Bag'
                    notes.append('NB_BAG_FALLBACK')
 
        # ───── TABLET KEYBOARD fit ─────
        elif base == 'KEYBOARD_TABLET_FIT':
            if tmod:
                mm = _compat_mask(pool, tmod)
                if mm.any():
                    pool = pool[mm]
            extra = _series(pool, 'Πρόσθετα χαρακτηριστικά').str.lower()
            pool.loc[extra.str.contains('touchpad', na=False),
                     'Final_Score'] += S_TOUCHPAD_BOOST
            pool = _apply_color_boost(pool, color_toks, with_transparent=False)
 
        # ───── WIRELESS KEYBOARD fit (brand-first + Bluetooth req) ─────
        elif base == 'KEYBOARD_WIRELESS_FIT':
            pool = _brand_first_filter(pool, tb)   # NEW: Samsung kbd if any exist
            conn = _series(pool, 'Συνδεσιμότητα').str.lower()
            pool.loc[conn.str.contains('bluetooth', na=False),
                     'Final_Score'] += S_BLUETOOTH_REQ
            if is_premium:
                extra = _series(pool, 'Πρόσθετα χαρακτηριστικά').str.lower()
                pool.loc[extra.str.contains('touchpad', na=False),
                         'Final_Score'] += S_TOUCHPAD_BOOST
            pool = _apply_color_boost(pool, color_toks, with_transparent=False)
 
        # ───── NB BAG size fit ─────
        elif base == 'NB_SIZE_FIT':
            if tsize > 0:
                pool.loc[_size_match_mask(pool, tsize),
                         'Final_Score'] += S_SIZE_MATCH
 
        # ───── WALL CHARGER fit ─────
        elif base == 'CHARGER_FIT':
            t3 = _series(pool, 'Τύπος3').str.lower()
            wall = t3.str.contains('φορτιστής πρίζας|σετ φόρτισης',
                                    regex=True, na=False)
            if wall.any():
                pool = pool[wall]
            # Brand-first BEFORE any other scoring/filtering
            pool = _brand_first_filter(pool, tb)
            pool.loc[_port_mask_chargers(pool, tport),
                     'Final_Score'] += S_PORT_MATCH
            pool.loc[_wattage_pref_mask(pool, ttier),
                     'Final_Score'] += S_WATTAGE_TIER
 
        # ───── APPLE CHARGER fit (iPad) ─────
        elif base == 'APPLE_CHARGER_FIT':
            t3 = _series(pool, 'Τύπος3').str.lower()
            ypod = _series(pool, 'Υποδοχές').str.lower()
            is_charger = (t3.str.contains('φορτιστής πρίζας', na=False)
                          | t3.str.contains('σετ φόρτισης', na=False)
                          | ypod.str.contains('usb-c|magsafe',
                                              regex=True, na=False))
            if is_charger.any():
                pool = pool[is_charger]
            # Brand-first BEFORE budget — Apple charger wins even at €25
            pool = _brand_first_filter(pool, tb)
            in_apple = pool['Hierarchy'].isin(
                ['APPLE ORIGINAL POWER SUPPLY',
                 'APPLE ORIGINAL IPHONE CABLE-ADAPTORS',
                 'APPLE ORIGINAL IPHONE CABLE-ADA'])
            pool.loc[in_apple, 'Final_Score'] += S_HIERARCHY_TARGET
            wattage = _series(pool, 'Ισχύς (Watt)')
            if wattage.eq('').all():
                wattage = _series(pool, 'Ισχύς')
            pool.loc[wattage.isin(['Έως 20 Watt', '21 - 60 Watt']),
                     'Final_Score'] += S_WATTAGE_TIER
            macbook_hi = wattage.str.contains(r'\b(7\d|9\d|1[0-4]\d)\s*W',
                                               regex=True, na=False)
            pool.loc[macbook_hi, 'Final_Score'] -= S_WATTAGE_TIER
 
        # ───── APPLE CABLE fit ─────
        elif base == 'APPLE_CABLE_FIT':
            t3 = _series(pool, 'Τύπος3').str.lower()
            is_cable = (t3.str.contains('καλώδιο', na=False)
                        & ~t3.str.contains('φορτιστής', na=False))
            if is_cable.any():
                pool = pool[is_cable]
            pool = _brand_first_filter(pool, tb)   # brand-first BEFORE budget
            in_apple = pool['Hierarchy'].isin(
                ['APPLE ORIGINAL IPHONE CABLE-ADAPTORS',
                 'APPLE ORIGINAL IPHONE CABLE-ADA'])
            pool.loc[in_apple, 'Final_Score'] += S_HIERARCHY_TARGET
            pool.loc[_port_mask_cables(pool, tport),
                     'Final_Score'] += S_PORT_MATCH
 
        # ───── GENERIC CABLE ─────
        elif base == 'CABLE_FIT':
            t3 = _series(pool, 'Τύπος3').str.lower()
            is_cable = (t3.str.contains('καλώδιο', na=False)
                        & ~t3.str.contains('φορτιστής', na=False))
            if is_cable.any():
                pool = pool[is_cable]
            pool = _brand_first_filter(pool, tb)
            pool.loc[_port_mask_cables(pool, tport),
                     'Final_Score'] += S_PORT_MATCH
 
        # ───── STORAGE fit (USB-C hard filter for Type-C triggers) ─────
        elif base == 'STORAGE_FIT':
            tp_l = tport.lower()
            if 'android' in tos:
                pool.loc[pool['Hierarchy'] == 'MICRO SD',
                         'Final_Score'] += S_PORT_MATCH
            sigma = _series(pool, 'Σύνδεση').str.lower()
            if 'type-c' in tp_l or 'usb-c' in tp_l:
                is_typec_flash = sigma.str.contains('usb-c', na=False)
                if is_typec_flash.any():
                    # Hard-filter — no USB-A flash drives on a Type-C iPad
                    flash_pool = pool[pool['Hierarchy'] != 'MICRO SD']
                    typec_in_flash = flash_pool['Σύνδεση'].fillna('').str.lower().str.contains('usb-c', na=False) if 'Σύνδεση' in flash_pool.columns else None
                    keep = (pool['Hierarchy'] != 'USB FLASH DISK') | is_typec_flash
                    pool = pool[keep]
            pool.loc[_port_mask_flash(pool, tport),
                     'Final_Score'] += S_PORT_MATCH
            pool.loc[pool['Hierarchy'].eq('ΚΑΛΩΔΙΑ-ADAPTORS'),
                     'Final_Score'] += S_OTG_BONUS
            # Premium boost: bigger capacity sticks (proxy = price)
            if is_premium:
                pool.loc[pool['_p'] >= 30, 'Final_Score'] += S_PREMIUM_VARIANT // 2
 
        # ───── MOUSE fit ─────
        elif base == 'MOUSE_FIT':
            conn = _series(pool, 'Συνδεσιμότητα').str.lower()
            has_bt = conn.str.contains('bluetooth', na=False)
            has_usb_only = (conn.str.contains('usb', na=False)
                            | conn.str.contains('2.4', na=False)) & ~has_bt
            pool.loc[has_bt, 'Final_Score'] += S_BLUETOOTH_REQ
            pool.loc[has_usb_only, 'Final_Score'] += S_USB_RECEIVER_PEN
            if is_apple_ipad and has_bt.any():
                pool = pool[has_bt]
 
        # ───── AIRPODS / Bluetooth audio (brand-first + premium variant) ─────
        elif base == 'AIRPODS_BOOST':
            # Hard filter — iPad slot 7 always gets Apple Bluetooth (whichever
            # variant is in the dataset). Was a soft boost; JBL Tour Pro 3 was
            # winning over AirPods 4 because of the premium-variant boost.
            pool = _brand_first_filter(pool, tb)
            if is_premium:
                # Among Apple options, boost expensive variants (Pro/Max)
                pool.loc[pool['_p'] >= 200, 'Final_Score'] += S_PREMIUM_VARIANT
 
        # ───── BRAND match (Apple Watch on iPad, Smartwatch on standard) ─────
        elif base == 'BRAND_MATCH':
            pool = _brand_first_filter(pool, tb)
            # Color boost — match watch color to tablet color
            pool = _apply_color_boost(pool, color_toks, with_transparent=False)
            # Premium tier → boost expensive watches (Series/Ultra)
            if is_premium:
                pool.loc[pool['_p'] >= 400, 'Final_Score'] += S_PREMIUM_VARIANT
 
        # ───── SCREEN PROTECTOR fit (skip-on-failure) ─────
        elif base == 'SCREEN_PROTECTOR_FIT':
            pool = _brand_incompat_filter(pool, tb, also_check_title=True)
            if tmod:
                mm = _compat_mask(pool, tmod)
                if mm.any():
                    pool = pool[mm]
                else:
                    # Skip the slot entirely — no fallback (drop to user)
                    slot_notes[slot_num] = notes + ['NO_MODEL_COMPAT_SKIP']
                    continue   # NOT added to failed_slots → no fallback
            else:
                slot_notes[slot_num] = notes + ['NO_MODEL_TO_MATCH_SKIP']
                continue
 
        # ───── STYLUS fit (brand-first + title-aware incompat) ─────
        elif base == 'STYLUS_FIT':
            # Drop styluses that mention competitor brands in compat OR title
            pool = _brand_incompat_filter(pool, tb, also_check_title=True)
            # If trigger is a major brand and any same-brand stylus exists, hard-filter
            if tb in TABLET_PREMIUM_BRANDS:
                pool = _brand_first_filter(pool, tb)
            if tmod:
                mm = _compat_mask(pool, tmod)
                pool.loc[mm, 'Final_Score'] += S_MODEL_MATCH
            tport_l = tport.lower()
            if 'type-c' in tport_l or 'usb-c' in tport_l:
                stylus_port = _series(pool, 'Θύρα USB').str.lower()
                pool.loc[stylus_port.str.contains('usb-c|type-c',
                                                   regex=True, na=False),
                         'Final_Score'] += S_PORT_MATCH
            sb = _series(pool, 'Κατασκευαστής').str.upper().str.strip() == tb
            pool.loc[~sb, 'Final_Score'] += S_UNBRANDED_STYLUS
 
        # ─── Budget hard filter ───
        if not pool.empty:
            pool = _apply_budget_filter(pool, role, ttier)
 
        if pool.empty:
            slot_notes[slot_num] = notes + ['EMPTY_AFTER_FILTER']
            failed_slots.append((slot_num, role, hierarchies, logic_key, 'EMPTY_AFTER_FILTER'))
            continue
 
        pool = pool.sort_values(['Final_Score', 'Sales_Tiebreaker'],
                                ascending=[False, False])
        chosen = pool.iloc[0]
 
        if base in ('APPLE_TARGET', 'APPLE_TARGET_STRICT', 'APPLE_FOLIO_STRICT'):
            cat = str(chosen.get('_apple_cat', ''))
            if cat:
                used_apple_cats.add(cat)
                notes.append(f"AppleCat={cat}")
 
        rc = chosen.copy()
        rc['Assigned_Slot']  = slot_num
        rc['Slot_Role']      = role
        rc['Marketing_Copy'] = TABLET_MARKETING_COPY.get(role, "Ιδανική επιλογή.")
        all_recs.append(rc)
        used_materials.add(chosen['Material'])
 
        notes.append(f"score={chosen['Final_Score']:.0f}")
        notes.append(f"brand={str(chosen.get('Κατασκευαστής', ''))[:20]}")
        slot_notes[slot_num] = notes
 
    # ----- Fallback pass -----
    # Failures fall into three categories:
    #
    #  A. COMPAT_FAIL  — main loop correctly rejected because no model match
    #                    exists in this hierarchy. Re-running with relaxed
    #                    filters here would just bring the wrong-model items
    #                    back. Either redirect to a different hierarchy
    #                    (e.g. Folio failure → NB BAG) or skip the slot.
    #
    #  B. NO_FALLBACK  — slot's logic key explicitly opts out (e.g. screen
    #                    protector). Always skip.
    #
    #  C. POOL_FAIL    — original hierarchy pool was empty / over-filtered
    #                    by budget. Safe to relax to brand+sales over the
    #                    same hierarchy or FALLBACK_HIERARCHIES.
 
    COMPAT_FAIL_REASONS = {'NO_MODEL_COMPAT', 'NO_APPLE_TARGET',
                            'NO_FOLIO_NO_NB', 'NO_CASE_NO_NB'}
 
    if failed_slots:
        diag.append(("3. Fallback Pass",
                     f"{len(failed_slots)} unfilled",
                     "Compat→NB Bag/skip; Pool→brand+sales"))
 
        for slot_num, role, hierarchies, logic_key, reason in failed_slots:
            # B. NO_FALLBACK — explicit skip
            if logic_key in LOGIC_NO_FALLBACK:
                continue
 
            # A. COMPAT_FAIL — don't re-search the same hierarchy
            if reason in COMPAT_FAIL_REASONS:
                # For case-y slots (Folio / Tablet Bag / Smart Folio), redirect
                # to NB BAG fallback instead of picking a wrong-model brand
                # match from the same hierarchy.
                role_l = role.lower()
                is_case_role = any(k in role_l for k in
                                    ('case', 'bag', 'folio', 'cover', 'sleeve'))
                if is_case_role:
                    # 3-tier chain: Universal Tablet Bag → NB BAG → skip
                    univ = _universal_tablet_bag_pool(c, used_materials, tb, tsize, color_toks)
                    chosen_pool = univ if not univ.empty else None
                    chosen_role = 'Tablet Bag (Universal)' if chosen_pool is not None else None
                    chosen_marker = 'FALLBACK_TO_UNIVERSAL' if chosen_pool is not None else None
 
                    if chosen_pool is None:
                        nb = _nb_bag_fallback_pool(c, used_materials, tb,
                                                    tsize, is_premium)
                        if not nb.empty:
                            chosen_pool = nb
                            chosen_role = 'NB Bag'
                            chosen_marker = 'FALLBACK_TO_NB_BAG'
 
                    if chosen_pool is None:
                        slot_notes[slot_num] = (slot_notes.get(slot_num, [])
                                                + ['FALLBACK_NB_EMPTY'])
                        continue
 
                    chosen_pool = chosen_pool.sort_values(
                        ['Final_Score', 'Sales_Tiebreaker'],
                        ascending=[False, False])
                    chosen = chosen_pool.iloc[0]
                    rc = chosen.copy()
                    rc['Assigned_Slot']  = slot_num
                    rc['Slot_Role']      = chosen_role
                    rc['Marketing_Copy'] = TABLET_MARKETING_COPY.get(
                        chosen_role, 'Εναλλακτική επιλογή.')
                    all_recs.append(rc)
                    used_materials.add(chosen['Material'])
                    slot_notes[slot_num] = (slot_notes.get(slot_num, [])
                                            + [chosen_marker,
                                               f"score={chosen['Final_Score']:.0f}",
                                               f"brand={str(chosen.get('Κατασκευαστής', ''))[:20]}"])
                    continue
 
                # For non-case compat failures (e.g. keyboard with no model
                # compat), skip the slot rather than push an incompatible
                # accessory. The user said "if not a match, dont show it".
                slot_notes[slot_num] = (slot_notes.get(slot_num, [])
                                        + ['FALLBACK_SKIPPED_COMPAT'])
                continue
 
            # C. POOL_FAIL — safe to relax to brand+sales
            pool = c[c['Hierarchy'].isin(hierarchies)].copy()
            pool = pool[~pool['Material'].isin(used_materials)]
            if used_apple_cats and '_apple_cat' in pool.columns:
                pool = pool[~pool['_apple_cat'].isin(used_apple_cats)]
 
            if pool.empty:
                pool = c[c['Hierarchy'].isin(FALLBACK_HIERARCHIES)].copy()
                pool = pool[~pool['Material'].isin(used_materials)]
                if used_apple_cats and '_apple_cat' in pool.columns:
                    pool = pool[~pool['_apple_cat'].isin(used_apple_cats)]
 
            if pool.empty:
                slot_notes[slot_num] = (slot_notes.get(slot_num, [])
                                        + ['FALLBACK_EXHAUSTED'])
                continue
 
            pool['Final_Score'] = 0.0
            sb = _series(pool, 'Κατασκευαστής').str.upper().str.strip() == tb
            pool.loc[sb, 'Final_Score'] += S_BRAND_PRIMARY
 
            min_p, max_p = _budget_range(role, ttier)
            out_range = (pool['_p'] < min_p * 0.5) | (pool['_p'] > max_p * 2.0)
            pool.loc[out_range, 'Final_Score'] -= 500_000
 
            pool = pool.sort_values(['Final_Score', 'Sales_Tiebreaker'],
                                    ascending=[False, False])
            chosen = pool.iloc[0]
 
            rc = chosen.copy()
            rc['Assigned_Slot']  = slot_num
            rc['Slot_Role']      = role + ' (Fallback)'
            rc['Marketing_Copy'] = TABLET_MARKETING_COPY.get(
                role, "Εναλλακτική επιλογή.")
            all_recs.append(rc)
            used_materials.add(chosen['Material'])
 
            slot_notes[slot_num] = (slot_notes.get(slot_num, [])
                                    + ['FALLBACK',
                                       f"score={chosen['Final_Score']:.0f}",
                                       f"brand={str(chosen.get('Κατασκευαστής', ''))[:20]}"])
 
    recs_df = (pd.DataFrame(all_recs).sort_values('Assigned_Slot')
               if all_recs else pd.DataFrame())
    return recs_df, diag, slot_notes, recs_df
 

