# ─────────────────────────────────────────────────────────────
# v7.2: Kiddoboo wearables persona (rewrite)
#
# Slot template per user spec — 7 slots, then repeat for overflow:
#   1. Overhead              (BRAND_MATCH — Kiddoboo only)
#   2. Smartphone            (BRAND_MATCH — Kiddoboo only)
#   3. Wall Charger          (ANY_BRAND   — any vendor, sorted by sales)
#   4. Karaoke               (BRAND_MATCH — Kiddoboo only)
#   5. Film Camera           (BRAND_MATCH — hierarchy doesn't exist yet,
#                                            slot stays empty until catalog
#                                            adds 'FILM CAMERAS' items)
#   6. Tablet                (BRAND_MATCH — Kiddoboo only)
#   7. Kick-scooter          (BRAND_MATCH — hierarchy doesn't exist yet)
#
# "Brand match only" (user wording): if no Kiddoboo item exists in the
# slot's hierarchy, the slot stays EMPTY. No fallback to other brands.
# This is stricter than the v7.1 BRAND_FIRST which fell back to popular
# items when Kiddoboo had nothing.
#
# Overflow: after one pass through the 7 slots, repeat the cycle as slots
# 8-14, 15-21, etc. Picks the next-best item for each category that hasn't
# been used yet. Stops when no slot can produce a new item.
# ─────────────────────────────────────────────────────────────

# Hierarchy mapping. "Karaoke" → PARTY SPEAKERS (catalog has 49). 
# FILM CAMERAS and KICK SCOOTERS hierarchies don't exist in the current
# catalog; they're placeholders that will populate once items are added.
KIDDOBOO_WEARABLE_SLOTS: list[tuple[int, str, list[str], str]] = [
    (1, 'Overhead',     ['OVERHEAD'],         'BRAND_MATCH'),
    (2, 'Smartphone',   ['Smartphones'],      'BRAND_MATCH'),
    (3, 'Wall Charger', ['WALL CHARGERS'],    'ANY_BRAND'),   # explicit per user — no brand match
    (4, 'Karaoke',      ['PARTY SPEAKERS'],   'BRAND_MATCH'),
    (5, 'Film Camera',  ['FILM CAMERAS'],     'BRAND_MATCH'),
    (6, 'Tablet',       ['TABLET PC'],        'BRAND_MATCH'),
    (7, 'Kick-scooter', ['KICK SCOOTERS'],    'BRAND_MATCH'),
]
KIDDOBOO_TARGET_SLOTS = 10   # Try to fill at least 10 slots overall


def _kiddoboo_pick(pool: pd.DataFrame, logic: str) -> pd.Series | None:
    """Pick the best item from a hierarchy pool per Kiddoboo logic.

    BRAND_MATCH: keep only KIDDOBOO items; return None if empty.
    ANY_BRAND:   keep all items; return None if empty.
    Always sorts by Sales_Tiebreaker (best-sellers first), then price desc.
    """
    if pool.empty:
        return None
    if logic == 'BRAND_MATCH':
        kb_mask = pool['Κατασκευαστής'].fillna('').str.upper().str.strip() == 'KIDDOBOO'
        if not kb_mask.any():
            return None
        pool = pool[kb_mask].copy()
    pool = pool.sort_values(['Sales_Tiebreaker', '_p'], ascending=[False, False])
    pool['_score'] = pool['Sales_Tiebreaker'].fillna(0).astype(float)
    return pool.iloc[0]


def _run_kiddoboo_wearables_engine(
    *,
    trigger: dict,
    tm, tt: str, tb: str, tmod: str, tprice: float, ttier: str,
    persona_label: str,
    df_products: pd.DataFrame,
    diag: list,
    slot_notes: dict,
    score_breakdown: dict,
) -> tuple[pd.DataFrame, list, dict, dict]:
    """Kiddoboo-only wearables engine. See block comment above."""
    diag.append((
        "0. Trigger (KIDDOBOO)",
        f"Brand={tb}  Tier={ttier}  Persona=Kiddoboo Wearable Template (v7.2)",
        f"Price=€{tprice:.2f}  Model={tmod or '—'}",
    ))

    c = df_products[df_products["Material"] != tm].copy()
    c["Sales_Tiebreaker"] = pd.to_numeric(c.get("Sum of Sales", 0), errors="coerce").fillna(0)
    c["_p"] = c["LIST PRICE"].apply(parse_euro_price)

    used_materials: set    = {tm}
    all_recs_by_slot: dict = {}
    overflow_slot_id       = 8   # First overflow slot starts at 8 (after 7 base slots)

    # ── PASS 1: try each of the 7 template slots once ──
    for slot_num, role, hierarchies, logic in KIDDOBOO_WEARABLE_SLOTS:
        notes = [f"Logic={logic} (Kiddoboo)"]
        pool = c[c["Hierarchy"].isin(hierarchies)].copy()
        pool = pool[~pool["Material"].isin(used_materials)]

        if pool.empty:
            diag.append((f"Slot {slot_num} ⬜", role, f"No items in {hierarchies[0]}"))
            slot_notes[slot_num] = notes + [f"⬜ Hierarchy {hierarchies[0]} has no items in catalog"]
            continue

        chosen = _kiddoboo_pick(pool, logic)
        if chosen is None:
            empty_marker = "⬜"
            reason = f"⬜ No KIDDOBOO items in {hierarchies[0]} (brand-match required)" if logic == 'BRAND_MATCH' \
                     else f"⬜ Pool empty for {hierarchies[0]}"
            diag.append((f"Slot {slot_num} {empty_marker}", role, reason))
            slot_notes[slot_num] = notes + [reason]
            continue

        chosen_brand = str(chosen.get("Κατασκευαστής", "")).strip().upper()
        all_recs_by_slot[slot_num] = _assign_to_slot(
            chosen,
            assigned_slot=slot_num,
            role=role,
            persona_label=persona_label,
            fallback=False,
            hierarchies=hierarchies,
        )
        used_materials.add(chosen["Material"])
        slot_notes[slot_num] = notes
        score_breakdown[slot_num] = {
            "slot_role":   role,
            "material":    chosen["Material"],
            "title":       str(chosen.get("Title", ""))[:60],
            "brand":       chosen_brand,
            "final_score": round(float(chosen.get("Sales_Tiebreaker", 0))),
            "price":       round(float(chosen.get("_p", 0)), 2),
        }
        diag.append((
            f"Slot {slot_num} ✅",
            f"{role}  →  {str(chosen.get('Title', ''))[:50]}",
            f"Brand={chosen_brand}  Price=€{float(chosen.get('_p', 0)):.2f}",
        ))

    # ── PASS 2: overflow — repeat the cycle until target reached or no more items ──
    MAX_OVERFLOW_PASSES = 5
    for pass_n in range(MAX_OVERFLOW_PASSES):
        if len(all_recs_by_slot) >= KIDDOBOO_TARGET_SLOTS:
            break
        progress_made = False
        for slot_num, role, hierarchies, logic in KIDDOBOO_WEARABLE_SLOTS:
            if len(all_recs_by_slot) >= KIDDOBOO_TARGET_SLOTS:
                break
            pool = c[c["Hierarchy"].isin(hierarchies)].copy()
            pool = pool[~pool["Material"].isin(used_materials)]
            if pool.empty:
                continue
            chosen = _kiddoboo_pick(pool, logic)
            if chosen is None:
                continue

            chosen_brand = str(chosen.get("Κατασκευαστής", "")).strip().upper()
            all_recs_by_slot[overflow_slot_id] = _assign_to_slot(
                chosen,
                assigned_slot=overflow_slot_id,
                role=f"{role} (extra)",
                persona_label=persona_label,
                fallback=True,
                hierarchies=hierarchies,
            )
            used_materials.add(chosen["Material"])
            slot_notes[overflow_slot_id] = [f"🔁 Cycle {pass_n+1}: extra {role} (Logic={logic})"]
            score_breakdown[overflow_slot_id] = {
                "slot_role":   f"{role} (extra)",
                "material":    chosen["Material"],
                "title":       str(chosen.get("Title", ""))[:60],
                "brand":       chosen_brand,
                "final_score": round(float(chosen.get("Sales_Tiebreaker", 0))),
                "price":       round(float(chosen.get("_p", 0)), 2),
            }
            diag.append((
                f"Slot {overflow_slot_id} 🔁",
                f"Extra from base slot {slot_num} ({role})  →  {str(chosen.get('Title',''))[:45]}",
                f"Brand={chosen_brand}  Price=€{float(chosen.get('_p', 0)):.2f}",
            ))
            overflow_slot_id += 1
            progress_made = True
        if not progress_made:
            break  # Nothing left to add

    print("\n" + "═" * 72)
    print("  WEARABLES ENGINE v7.2 — DIAGNOSTICS (KIDDOBOO persona)")
    print("═" * 72)
    print(f"  Trigger: {tt}")
    for sn in sorted(all_recs_by_slot):
        rec = all_recs_by_slot[sn]
        marker = "🔁" if "extra" in str(rec.get('Slot_Role', '')).lower() else "  "
        print(f"   {marker} Slot {sn:2d}: [{str(rec.get('Slot_Role',''))[:20]:20s}] "
              f"{str(rec.get('Κατασκευαστής',''))[:12]:12s} "
              f"€{float(rec.get('_p',0) or 0):7.2f}  {str(rec.get('Title',''))[:55]}")

    recs_df = (pd.DataFrame(list(all_recs_by_slot.values())).sort_values("Assigned_Slot")
               if all_recs_by_slot else pd.DataFrame())
    return recs_df, diag, slot_notes, score_breakdown


def run_wearables_engine(
    trigger: dict,
    df_products: pd.DataFrame,
    df_history: pd.DataFrame,
) -> tuple[pd.DataFrame, list, dict, dict]:
 
    diag: list             = []
    slot_notes: dict       = {}
    score_breakdown: dict  = {}
    all_recs_by_slot: dict = {}
 
    # ── Parse Trigger ────────────────────────────────────────
    tm     = trigger["Material"]
    tt     = str(trigger.get("Title", ""))
    tb     = str(trigger.get("Κατασκευαστής", "")).strip().upper()
    tmod   = str(trigger.get("Μοντέλο", "")).strip()
    tprice = parse_euro_price(trigger.get("LIST PRICE", 0))
    ttier  = get_wearable_tier(tprice)
 
    is_lockable = tb in LOCKABLE_BRANDS
    eco_set = get_wearable_ecosystem(tb) if is_lockable else set()
    eco_label_full = "+".join(sorted(eco_set)) if eco_set else "—"
    persona_label = f"{tb} ({ttier})" if is_lockable else f"Cross-brand ({ttier})"
 
    diag.append((
        "0. Trigger",
        f"Brand={tb}  Tier={ttier}  Brand-lock={'ON' if is_lockable else 'OFF'}  Ecosystem=[{eco_label_full}]",
        f"Price=€{tprice:.2f}  Model={tmod or '—'}",
    ))
 
    # ── Prepare Candidate Pool ───────────────────────────────
    c = df_products[df_products["Material"] != tm].copy()
    c["Sales_Tiebreaker"] = (
        pd.to_numeric(c.get("Sum of Sales", 0), errors="coerce").fillna(0)
    )
    c["_p"] = c["LIST PRICE"].apply(parse_euro_price)

    # v7.3: Kids-brand segregation. Kiddoboo is a kids-only brand whose
    # OVERHEAD items (Kiddoboo P13, Delulu, etc.) kept winning the slot 7
    # / slot 13 (Over-Ear) overflow for adult smartwatch triggers like
    # Xiaomi Redmi Watch and Apple Watch — they scored well on price
    # affinity + year boost in fallback pools that had no ecosystem
    # over-ear items. Recommending children's headphones to an adult
    # watch buyer is wrong. So: when the trigger isn't itself a kids
    # brand, drop all kids-brand items from the candidate pool entirely.
    KIDS_BRANDS = {"KIDDOBOO"}   # extend as new kids brands appear
    if tb not in KIDS_BRANDS:
        before_n = len(c)
        c = c[~c["Κατασκευαστής"].fillna("").str.upper().str.strip().isin(KIDS_BRANDS)].copy()
        # (No diag entry; the filter applies uniformly across every slot.)

    sales_p80 = c["Sales_Tiebreaker"].quantile(0.80) if not c.empty else 0
 
    used_materials: set    = {tm}
    brand_slot_count: dict = {}
    # Track per-hierarchy spec signatures we've already used (for variety in overflow)
    used_signatures_by_hier: dict[str, set] = {}
    # NEW (v7): track per-hierarchy first-pick brand IFF that pick was made
    # under successful ecosystem-lock — used to keep overflow refills on the
    # same brand (Galaxy Buds FE → Galaxy Buds 3 FE, not Galaxy Buds → JBL).
    first_pick_brand_by_hier: dict[str, str] = {}
    # NEW (v7): year for the trigger (Galaxy Watch8 → 2026, Buds-style models).
    # For Apple Watch the extractor returns None and year-boost simply doesn't fire.
    trigger_year = _wearable_extract_year(tt, tmod)

    # NEW (v7.1): size + model-line signature for strict-match slots.
    # Size comes from the TITLE (model field rarely has "40mm" embedded).
    # Signature is the (line, version) tuple used to reject cross-version
    # accessories (e.g. Huawei GT3 strap won't match Watch GT 5 trigger).
    tsize       = _extract_wearable_size_from_title(tt)
    tsignature  = _extract_model_signature(tmod) if tmod else ("", "")
    if not tsignature[0]:
        tsignature = _extract_model_signature(tt)  # fallback to title

    # NEW (v7.1): Kiddoboo branch — kids smartwatches use the kiddoboo
    # 10-slot template (same as kiddoboo tablets, but with Smartphone in
    # slot 2 and Smartwatch in slot 7 — swapped because trigger is a watch).
    if tb == "KIDDOBOO":
        return _run_kiddoboo_wearables_engine(
            trigger=trigger,
            tm=tm, tt=tt, tb=tb, tmod=tmod, tprice=tprice,
            ttier=ttier, persona_label=f"KIDDOBOO ({ttier})",
            df_products=df_products,
            diag=diag, slot_notes=slot_notes, score_breakdown=score_breakdown,
        )

    # ═══════════════════════════════════════════════════════════
    # PASS 1 — Main slot loop
    # ═══════════════════════════════════════════════════════════
    for slot_num, role, hierarchies, logic_key, budget_key, ecosystem_mode, title_filter, smartphone_style in SLOTS:
        hierarchy = hierarchies[0]

        chosen, notes, has_compat, locked = _try_pick_for_slot(
            full_pool=c,
            hierarchies=hierarchies,
            used_materials=used_materials,
            logic_key=logic_key,
            budget_key=budget_key,
            tmod=tmod, tb=tb,
            trigger_price=tprice,
            brand_slot_count=brand_slot_count,
            sales_p80=sales_p80,
            used_signatures_by_hier=used_signatures_by_hier,
            enforce_brand_lock=is_lockable,
            ecosystem_mode=ecosystem_mode,
            title_filter=title_filter,
            smartphone_style=smartphone_style,
            trigger_year=trigger_year,
            trigger_size=tsize,
            trigger_signature=tsignature,
        )

        if chosen is None:
            # Strict slot stays empty; non-strict slot just had an empty pool / threshold miss
            empty_marker = "⬜" if logic_key == "MODEL_MATCH_STRICT" else "⚪"
            diag.append((
                f"Slot {slot_num} {empty_marker}",
                role,
                f"Left empty — will compensate via slot 11+",
            ))
            slot_notes[slot_num] = notes + [f"{empty_marker} Left empty"]
            continue

        chosen_brand = str(chosen.get("Κατασκευαστής", "")).strip().upper()
        brand_slot_count[chosen_brand] = brand_slot_count.get(chosen_brand, 0) + 1

        # Track signature for variety
        used_signatures_by_hier.setdefault(hierarchy, set()).add(_signature(chosen, hierarchy))

        # NEW (v7): if this pick was made under a successful ecosystem-lock,
        # remember its brand so PASS 2 overflow refills the same brand.
        # We DON'T track when the pick came via fallback (e.g. slot 1
        # Catalyst for Apple Watch — Apple has no protection items, so
        # fallback picks freely → overflow stays free for diversity).
        if locked and chosen_brand and hierarchy not in first_pick_brand_by_hier:
            first_pick_brand_by_hier[hierarchy] = chosen_brand

        all_recs_by_slot[slot_num] = _assign_to_slot(
            chosen,
            assigned_slot=slot_num,
            role=role,
            persona_label=persona_label,
            fallback=False,
            hierarchies=hierarchies,
        )
        used_materials.add(chosen["Material"])
        slot_notes[slot_num] = notes
 
        cap_used = get_dynamic_cap(tprice, budget_key)
        score_breakdown[slot_num] = {
            "slot_role":   role,
            "material":    chosen["Material"],
            "title":       str(chosen.get("Title", ""))[:60],
            "brand":       chosen_brand,
            "final_score": round(chosen["_score"]),
            "price":       round(chosen["_p"], 2),
            "cap":         round(cap_used, 2),
            "price_ratio": round(chosen["_p"] / cap_used, 2) if cap_used else None,
            "fallback":    False,
            "locked":      locked,
            "logic":       logic_key,
            "signature":   _signature(chosen, hierarchy),
        }
        lock_flag = "🔒" if locked else ""
        diag.append((
            f"Slot {slot_num} ✅{lock_flag}",
            f"{role}  →  {str(chosen.get('Title', ''))[:50]}",
            f"Score={round(chosen['_score']):,}  Price=€{chosen['_p']:.2f}  Cap=€{cap_used:.0f}",
        ))
 
    # ═══════════════════════════════════════════════════════════
    # PASS 2 — Overflow at slot 11+, with spec variety enforced.
    # ═══════════════════════════════════════════════════════════
    overflow_slot_id = 11
    cursor = 0
    safety_counter = 0
    MAX_OVERFLOW_ATTEMPTS = len(SLOTS) * 3
 
    while len(all_recs_by_slot) < TARGET_FILLED_SLOTS and safety_counter < MAX_OVERFLOW_ATTEMPTS:
        safety_counter += 1
        found = False
 
        for attempt in range(len(SLOTS)):
            idx  = (cursor + attempt) % len(SLOTS)
            sdef = SLOTS[idx]
            src_slot_num, src_role, src_hierarchies, src_logic, src_budget, src_eco_mode, src_title_filter, src_smartphone_style = sdef
            hierarchy = src_hierarchies[0]

            # NEW (v7): if PASS 1 picked a same-ecosystem brand for this
            # hierarchy, force the overflow refill to that exact brand.
            # Bridges the "AirPods then JBL" gap.
            overflow_lock = first_pick_brand_by_hier.get(hierarchy)

            chosen, notes, has_compat, locked = _try_pick_for_slot(
                full_pool=c,
                hierarchies=src_hierarchies,
                used_materials=used_materials,
                logic_key=src_logic,
                budget_key=src_budget,
                tmod=tmod, tb=tb,
                trigger_price=tprice,
                brand_slot_count=brand_slot_count,
                sales_p80=sales_p80,
                used_signatures_by_hier=used_signatures_by_hier,
                enforce_brand_lock=is_lockable,
                ecosystem_mode=src_eco_mode,
                title_filter=src_title_filter,
                smartphone_style=src_smartphone_style,
                overflow_brand_lock=overflow_lock,
                trigger_year=trigger_year,
                trigger_size=tsize,
                trigger_signature=tsignature,
            )
 
            if chosen is None:
                continue
 
            chosen_brand = str(chosen.get("Κατασκευαστής", "")).strip().upper()
            brand_slot_count[chosen_brand] = brand_slot_count.get(chosen_brand, 0) + 1
            used_signatures_by_hier.setdefault(hierarchy, set()).add(_signature(chosen, hierarchy))
 
            all_recs_by_slot[overflow_slot_id] = _assign_to_slot(
                chosen,
                assigned_slot=overflow_slot_id,
                role=f"{src_role} (extra)",
                persona_label=persona_label,
                fallback=True,
                hierarchies=src_hierarchies,
            )
            used_materials.add(chosen["Material"])
 
            cap_used = get_dynamic_cap(tprice, src_budget)
            score_breakdown[overflow_slot_id] = {
                "slot_role":   f"{src_role} (extra)",
                "material":    chosen["Material"],
                "title":       str(chosen.get("Title", ""))[:60],
                "brand":       chosen_brand,
                "final_score": round(chosen["_score"]),
                "price":       round(chosen["_p"], 2),
                "cap":         round(cap_used, 2),
                "price_ratio": round(chosen["_p"] / cap_used, 2) if cap_used else None,
                "fallback":    True,
                "locked":      locked,
                "logic":       src_logic,
                "signature":   _signature(chosen, hierarchy),
            }
            slot_notes[overflow_slot_id] = (
                [f"🔁 Extra from slot {src_slot_num} ({src_role})"]
                + notes
            )
            lock_flag = "🔒" if locked else ""
            diag.append((
                f"Slot {overflow_slot_id} 🔁{lock_flag}",
                f"Extra from slot {src_slot_num} ({src_role})  →  {str(chosen.get('Title', ''))[:40]}",
                f"Score={round(chosen['_score']):,}  Price=€{chosen['_p']:.2f}  Sig={_signature(chosen, hierarchy)}",
            ))
 
            cursor = idx + 1
            overflow_slot_id += 1
            found = True
            break
 
        if not found:
            diag.append((
                "Overflow",
                "Could not add more recommendations — candidate pool exhausted",
                f"Final count: {len(all_recs_by_slot)} / {TARGET_FILLED_SLOTS}",
            ))
            break
 
    # ── Assemble Final DataFrame ────────────────────────────
    if all_recs_by_slot:
        recs_df = pd.DataFrame(
            [all_recs_by_slot[n] for n in sorted(all_recs_by_slot.keys())]
        )
    else:
        recs_df = pd.DataFrame()
 
    return recs_df, diag, slot_notes, score_breakdown
 
 
# ═══════════════════════════════════════════════════════════════
# 6.  DIAGNOSTIC PRETTY-PRINT HELPER
# ═══════════════════════════════════════════════════════════════
 
def print_wearables_diag(diag: list, slot_notes: dict, score_breakdown: dict) -> None:
    print("\n" + "═" * 72)
    print("  WEARABLES ENGINE v7.2 — DIAGNOSTICS (Apple-boost + title-signature filter)")
    print("═" * 72)
    for label, main, detail in diag:
        print(f"  [{label}]  {main}")
        if detail:
            print(f"            {detail}")
 
    print("\n" + "─" * 72)
    print("  SLOT NOTES")
    print("─" * 72)
    for slot_num, notes in sorted(slot_notes.items()):
        print(f"  Slot {slot_num:>2}:  {' | '.join(notes)}")
 
    print("\n" + "─" * 72)
    print("  SCORE BREAKDOWN")
    print("─" * 72)
    for slot_num, bd in sorted(score_breakdown.items()):
        lock = "🔒" if bd.get("locked") else "  "
        print(
            f"  Slot {slot_num:>2} {lock} [{bd['slot_role']:<32}]  "
            f"Score={bd['final_score']:>10,}  "
            f"€{bd['price']:<7} cap€{bd['cap']:<6}  "
            f"Fb={bd['fallback']}  Sig={bd.get('signature', '')}"
        )
    print("═" * 72 + "\n")

# ═════════════════════════════════════════════════════════════
# 🟢 LAPTOPS ENGINE — Mainstream / Road Warrior
# ═════════════════════════════════════════════════════════════

def run_laptops_engine(trigger, df_products, df_history):
    diag = []
    slot_notes = {}
    all_recs = []
 
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    tscreen = parse_screen_size(trigger.get('Μέγεθος οθόνης', ''))
    tports = str(trigger.get('Θύρες', '')).lower()
    tusage = str(trigger.get('Προτεινόμενη χρήση', '')).lower()
    
    # ---PERSONA VARIABLES ---
    is_premium = tprice >= 1000 or 'premium' in tusage
    is_apple = tb == 'APPLE'
    is_gaming = 'gaming' in tusage or 'gamer' in tusage
    # Microsoft Surface devices all have USB-C + Surface Connect, but your
    # Ports column sometimes only lists DisplayPort. Treat Surface as USB-C.
    is_surface = tb == 'MICROSOFT' and 'surface' in tt.lower()

    # 2-in-1 convertibles: touchscreen + hinge laptops. Coolers don't fit these 
    # (often used in tablet mode, detached from desk), and a Surface 2-in-1 
    # benefits from a dedicated Surface Keyboard + Pen setup.
    is_2in1 = '2 σε 1' in tusage or '2-in-1' in tusage or '2 in 1' in tusage or 'convertible' in tusage or 'συνδυαστικ' in tusage or '2σε1' in tusage
    is_ms_2in1 = is_surface or (tb == 'MICROSOFT' and is_2in1)

    # OLED screen detection — for OLED-laptop buyers we should prefer OLED monitors
    # (color-accurate creative work, HDR media, etc.)
    tscreen_tech = str(trigger.get('Τεχνολογία Οθόνης', '')).lower() + ' ' + str(trigger.get('Τύπος Οθόνης', '')).lower() + ' ' + tt.lower() + ' ' + tusage
    trigger_is_oled = 'oled' in tscreen_tech or 'amoled' in tscreen_tech
    # Retina detection (Apple). Retina laptops are premium — we should only pair with
    # monitors that have a proper panel technology (IPS/VA/OLED/etc.), not generic TN.
    trigger_is_retina = 'retina' in tscreen_tech

    # --- 2026 GR Market Tier (Performance Pairing) ---
    laptop_tier = get_laptop_tier(tprice)
    tier_names = {1: "Budget/Entry", 2: "Mid-Range/AI-Ready", 3: "High-End/Pro", 4: "Extreme/Workstation"}
    tier_label = tier_names.get(laptop_tier, "Sub-Entry")

    # --- Get Laptop Resolution Tier ---
    tres_str = str(trigger.get('Ανάλυση Οθόνης', ''))
    tres_tier = get_resolution_tier(tres_str)
 
    diag.append(("0. Trigger", f"Brand={tb}, €{tprice:.0f}", f"Tier {laptop_tier} ({tier_label}), Screen={tscreen}\", 2-in-1={is_2in1}, OLED={trigger_is_oled}, Retina={trigger_is_retina}, Ports={tports[:60]}"))
 
    # ── Build candidate pool ──
    c = df_products[df_products['Material'] != tm].copy()
    b4 = len(c)
    # Remove laptops/ themselves from candidates
    c = c[~((c['Level 1'] == 'IT') & (c['Level 2'].isin(LAPTOP_L2_VALUES)))]
    diag.append(("1. Excl laptops", len(c), f"Removed {b4 - len(c)}"))
 
    # Remove smartphones from candidates
    b4 = len(c)
    c = c[~((c['Level 2'] == 'Mobiles') & (c['Hierarchy'] == 'Smartphones'))]
    diag.append(("1b. Excl phones", len(c), f"Removed {b4 - len(c)}"))

    # 🚫 Global Apple-ban for non-Apple laptops. AirPods/Magic Mouse/Apple
    # chargers should NEVER appear on a Windows/Microsoft/Dell/etc. laptop —
    # wrong ecosystem, mostly wrong connector, and visually off-brand.
    if not is_apple:
        b4 = len(c)
        c = c[c['Κατασκευαστής'].fillna('').astype(str).str.strip().str.upper() != 'APPLE']
        diag.append(("1c. Apple ban", len(c), f"Removed {b4 - len(c)} Apple items (non-Apple trigger)"))
 
    # Stock filter
    if 'CW Stock Units' in c.columns:
        stv = pd.to_numeric(c['CW Stock Units'], errors='coerce').fillna(0)
        pct = (stv > 0).sum() / len(c) if len(c) > 0 else 0
        if pct >= 0.10:
            c = c[stv > 0]
            diag.append(("2. Stock filter", len(c), f"Applied ({pct:.0%})"))
        else:
            diag.append(("2. Stock filter", len(c), f"⚠ SKIPPED ({pct:.0%})"))
    else:
        diag.append(("2. Stock filter", len(c), "⚠ SKIPPED (no col)"))
 
    # Macro wall — no appliances
    b4 = len(c)
    if 'Level 1' in c.columns:
        c = c[~c['Level 1'].isin(APPL_CATS)]
    diag.append(("3. Macro wall", len(c), f"Removed {b4 - len(c)}"))
 
    # Sales tiebreaker
    if 'Sum of Sales' in c.columns:
        c['Sales_Tiebreaker'] = pd.to_numeric(c['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c['Sales_Tiebreaker'] = 0
 
    # ── Iterate slots ──
    used_materials = {tm}
    used_hierarchies_count = {}
    selected_mouse_row = None 
    for slot_num, role, hierarchies, logic_key in LAPTOP_MAINSTREAM_SLOTS:
        notes = [f"Logic: {logic_key}", f"Target: {hierarchies}"]

       # ── 2-in-1 override: skip Cooler slot entirely (useless for convertibles) ──
        if is_2in1 and logic_key == 'STAND_SIZE':
            notes.append("🚫 2-in-1 → skip Cooler (useless for convertibles)")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Skipped (2-in-1)"))
            continue

        # ── NEW RULE: Skip cooler if laptop is smaller than 14" ──
        if logic_key == 'STAND_SIZE' and tscreen > 0 and tscreen < 14.0:
            notes.append("🚫 Small laptop (<14\") → skip Cooler")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Skipped (<14\" laptop)"))
            continue

        # ── Microsoft 2-in-1 overrides: Surface Keyboard (slot 1), Surface Pen (slot 3) ──
        if is_ms_2in1 and slot_num == 1:
            # Slot 1 normally = "Τσάντα Laptop" → hijack to Surface Keyboard
            hierarchies = ['KEYBOARDS WIRELESS', 'KEYBOARDS']
            role = 'Microsoft Surface Keyboard'
            notes.append("🪟 MS 2-in-1 → Slot 1 = Surface Keyboard")
        elif is_ms_2in1 and slot_num == 3:
            # Slot 3 normally = "Powerbank" → hijack to Surface Pen (stylus)
            hierarchies = ['ΓΡΑΦΙΔΕΣ']
            role = 'Microsoft Surface Pen'
            notes.append("🪟 MS 2-in-1 → Slot 3 = Surface Pen")
 
        # Hierarchy match — exact first, substring fallback
        hier_upper = [h.upper().strip() for h in hierarchies]
        pool = c[c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
 
        if pool.empty:
            hier_col = c['Hierarchy'].fillna('').astype(str).str.upper().str.strip()
            mask = pd.Series(False, index=c.index)
            for hk in hier_upper:
                if hk:
                    mask |= hier_col.str.contains(re.escape(hk), regex=True, na=False)
            pool = c[mask].copy()
            if not pool.empty:
                notes.append(f"⚠ Substring fallback: {len(pool)}")
 
        notes.append(f"Pool: {len(pool)}")
        pool = pool[~pool['Material'].isin(used_materials)]

        # ── Non-gaming laptop: hide RGB-titled products globally ──
        # Gaming keyboards/mice with RGB don't fit professional/student/MS Surface laptops.
        if not is_gaming and not pool.empty:
            rgb_mask = pool['Title'].fillna('').str.contains(r'\brgb\b', case=False, regex=True, na=False)
            if rgb_mask.any():
                b4_rgb = len(pool)
                pool = pool[~rgb_mask]
                if b4_rgb > len(pool):
                    notes.append(f"🚫 Non-gaming: removed {b4_rgb - len(pool)} RGB-titled items")

        # ── Microsoft 2-in-1 slot 1/3 overrides: filter brand to MICROSOFT first ──
        if is_ms_2in1 and slot_num in (1, 3) and not pool.empty:
            ms_brand_mask = pool['Κατασκευαστής'].fillna('').astype(str).str.strip().str.upper() == 'MICROSOFT'
            if ms_brand_mask.any():
                pool = pool[ms_brand_mask]
                notes.append(f"🪟 Filtered to Microsoft brand: {len(pool)}")
            else:
                notes.append(f"⚠ No Microsoft-brand items in {hierarchies}")
 
        if pool.empty:
            notes.append("❌ Empty after dedup")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Empty"))
            continue
 
        # Base scoring
        pool['Final_Score'] = 0.0
        if 'AVAILABILITY' in pool.columns:
            pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AVAIL_BOOST * 100
        pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * 0.1
 
        # ══════════════════════════════════════════════════════
        # SLOT-SPECIFIC LOGIC
        # ══════════════════════════════════════════════════════
 
        # ── Logic 1: Bag/Sleeve Size (Cinderella Fit) ──
        if logic_key in ('BAG_SIZE', 'SLEEVE_SIZE'):
            if tscreen > 0:
                size_col = None
                for candidate_col in ['Μέγεθος', 'Μέγεθος οθόνης']:
                    if candidate_col in pool.columns:
                        size_col = candidate_col
                        break
                if size_col:
                    pool['_acc_size'] = pool[size_col].apply(parse_screen_size)
                    
                    # Target 1: Strict fit (up to +0.8 inches larger)
                    strict_fit = pool[(pool['_acc_size'] >= tscreen - 0.2) & (pool['_acc_size'] <= tscreen + 0.8)]
                    if not strict_fit.empty:
                        pool = strict_fit
                        notes.append(f"Strict size fit {tscreen}\" (+0.8\"): {len(pool)}")
                    else:
                        # Target 2: Loose fit (up to +1.5 inches larger)
                        loose_fit = pool[(pool['_acc_size'] >= tscreen - 0.5) & (pool['_acc_size'] <= tscreen + 1.5)]
                        if not loose_fit.empty:
                            pool = loose_fit
                            notes.append(f"Loose size fit {tscreen}\" (+1.5\"): {len(pool)}")
                        else:
                            # Target 3: Only keep sizeless bags. Ban known wrong sizes!
                            sizeless = pool[pool['_acc_size'] == 0]
                            pool = sizeless
                            notes.append(f"⚠ No size match for {tscreen}\", keeping ONLY sizeless items")

            # ── Bag TYPE priority by size and persona ──
            # Big laptops (≥15") → Backpack (Πλάτης); gaming → Gaming-themed bags first;
            # small laptops (<14") → Sleeve; fallback → Shoulder (Ώμου-χειρός)
            if logic_key == 'BAG_SIZE' and 'Τύπος τσάντας' in pool.columns:
                btype = pool['Τύπος τσάντας'].fillna('').astype(str)
                is_backpack = btype.str.contains('Πλάτης|Backpack', case=False, regex=True, na=False)
                is_sleeve = btype.str.contains('Sleeve|Θήκη|Μανικ', case=False, regex=True, na=False)
                is_shoulder = btype.str.contains('Ώμου|Χειρός|Shoulder|Messenger|Hand', case=False, regex=True, na=False)
                is_gaming_bag = pool['Title'].fillna('').str.lower().str.contains(
                    r'gaming|razer|asus rog|rog ranger|rog backpack|msi\b|hp omen|lenovo legion|predator',
                    regex=True, na=False
                )

                if is_gaming:
                    # Gaming → gaming-themed first, then backpacks, then shoulder
                    pool.loc[is_gaming_bag, 'Final_Score'] += 250000
                    pool.loc[is_backpack & ~is_gaming_bag, 'Final_Score'] += 80000
                    pool.loc[is_shoulder & ~is_backpack & ~is_gaming_bag, 'Final_Score'] += 20000
                    notes.append(f"🎮 Gaming bag: Gaming+250k({is_gaming_bag.sum()}) / Backpack+80k({(is_backpack & ~is_gaming_bag).sum()})")
                elif tscreen and tscreen >= 15.0:
                    # Large laptop → Backpack first (Πλάτης), then Shoulder, then Sleeve
                    pool.loc[is_backpack, 'Final_Score'] += 200000
                    pool.loc[is_shoulder & ~is_backpack, 'Final_Score'] += 60000
                    pool.loc[is_sleeve & ~is_backpack & ~is_shoulder, 'Final_Score'] += 10000
                    notes.append(f"📏 Large ({tscreen}\"): Backpack+200k({is_backpack.sum()}) / Shoulder+60k")
                elif tscreen and tscreen < 14.0:
                    # Small laptop → Sleeve first, then Shoulder, then Backpack
                    pool.loc[is_sleeve, 'Final_Score'] += 200000
                    pool.loc[is_shoulder & ~is_sleeve, 'Final_Score'] += 60000
                    pool.loc[is_backpack & ~is_sleeve & ~is_shoulder, 'Final_Score'] += 20000
                    notes.append(f"📏 Small ({tscreen}\"): Sleeve+200k({is_sleeve.sum()}) / Shoulder+60k")
                else:
                    # Mid-size (14-15") or unknown → Shoulder first
                    pool.loc[is_shoulder, 'Final_Score'] += 150000
                    pool.loc[is_backpack, 'Final_Score'] += 100000
                    pool.loc[is_sleeve, 'Final_Score'] += 50000
                    notes.append("Mid-size: Shoulder-priority")

                # Mainstream usage also wants backpacks (student/commute)
                if 'mainstream' in tusage and not is_gaming:
                    pool.loc[is_backpack, 'Final_Score'] += 40000

            # FLAT-RATE BUDGET: Bags/sleeves are roughly static (€30-€80). Don't
            # show €200 leather sleeves with a €4k laptop — feels like upselling.
            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)
            slot_role_key = 'BAG' if logic_key == 'BAG_SIZE' else 'SLEEVE'
            pool, trap_note = apply_cheap_trap(pool, tprice, slot_role_key)
            if trap_note: notes.append(trap_note)
            if laptop_tier > 0:
                bag_min, bag_max = get_accessory_budget(slot_role_key, laptop_tier)
                # Gaming bags legitimately run €50-€120 even on mid-tier laptops
                if is_gaming and logic_key == 'BAG_SIZE':
                    bag_max = max(bag_max, 120)
                in_band = (pool['_p'] >= bag_min) & (pool['_p'] <= bag_max)
                pool.loc[in_band, 'Final_Score'] += 40000
                notes.append(f"Flat budget: Boost €{bag_min:.0f}–€{bag_max:.0f} {slot_role_key.lower()}s")
 
        # ── Logic 2: Charger Port Compatibility (Brand+Port = Top Priority) ──
        elif logic_key == 'CHARGER_PORT':
            # Apple & Microsoft Surface imply USB-C/PD even if the Ports column is empty.
            has_usbc = is_apple or is_surface or any(k in tports for k in ['usb-c', 'type-c', 'usb c', 'thunderbolt', 'usb 4'])
            has_dcin_only = 'dc' in tports and not has_usbc

            # ── ALWAYS-ON #1: Wattage filter (laptop chargers are ≥45W period) ──
            # This fires regardless of port detection — a <45W brick is a phone
            # charger, wrong tool for any laptop.
            watts = pool['Title'].fillna('').apply(extract_wattage_from_text)
            pool.loc[watts >= 45, 'Final_Score'] += 50000
            pool.loc[(watts > 0) & (watts < 45), 'Final_Score'] -= 20000
            notes.append("≥45W boost, <45W deprioritized (always-on)")

            # ── ALWAYS-ON #2: Brand match (fires even with no port info) ──
            # Rationale: if the user's laptop is a Microsoft Surface and a
            # Microsoft charger exists in the catalog, it should beat Hama even
            # if the Ports column is incomplete. Brand = correct connector by
            # construction.
            if tb:
                is_same_brand = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == tb
                same_brand_laptop_watt = is_same_brand & (watts >= 45)
                pool.loc[same_brand_laptop_watt, 'Final_Score'] += 200000
                if same_brand_laptop_watt.any():
                    notes.append(f"Brand match (always-on): {tb} ≥45W → +200k, {same_brand_laptop_watt.sum()} items")

            if has_usbc:
                usbc_mask = pool['Title'].fillna('').str.lower().str.contains('usb-c|type-c|usb c|pd|power delivery', regex=True, na=False)
                if 'Υποδοχές' in pool.columns:
                    usbc_mask |= pool['Υποδοχές'].fillna('').astype(str).str.lower().str.contains('usb-c|type-c', regex=True, na=False)
                pool.loc[usbc_mask, 'Final_Score'] += 100000
                trig_label = "USB-C trigger" if not is_surface else "Surface (implicit USB-C)"
                notes.append(f"{trig_label} → USB-C charger boost")

                # ⭐ TOP PRIORITY: Same-brand charger AND matching port AND ≥45W
                if tb:
                    is_same_brand = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == tb
                    brand_port_match = is_same_brand & usbc_mask & (watts >= 45)
                    pool.loc[brand_port_match, 'Final_Score'] += 500000
                    if brand_port_match.any():
                        notes.append(f"⭐ TOP: Same-brand ({tb}) + USB-C + ≥45W → {brand_port_match.sum()} items")

                # Brand Ecosystem fallback for chargers
                if is_apple:
                    # 🍎 STRICT: Apple laptops get Apple chargers ONLY.
                    apple_mask = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == 'APPLE'
                    if apple_mask.any():
                        b4 = len(pool)
                        pool = pool[apple_mask].copy()
                        notes.append(f"🍎 Apple-only charger filter: {b4}→{len(pool)}")
                    else:
                        # No Apple chargers in catalog → boost premium PD brands
                        # (Anker/Belkin/UGREEN are what Apple Store stocks as 3rd-party)
                        premium_pd = pool['Κατασκευαστής'].fillna('').str.upper().isin(['ANKER', 'BELKIN', 'UGREEN'])
                        pool.loc[premium_pd & usbc_mask, 'Final_Score'] += 80000
                        notes.append("⚠ No Apple chargers in catalog → fallback: premium PD brands boosted +80k")

            elif has_dcin_only:
                universal = pool['Title'].fillna('').str.lower().str.contains('universal|γενικής|πολλαπλ', regex=True, na=False)
                pool.loc[universal, 'Final_Score'] += 50000
                notes.append("DC-in → Universal charger boost")

                # ⭐ Same-brand DC charger wins if available
                if tb:
                    is_same_brand = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == tb
                    dc_mask = pool['Title'].fillna('').str.lower().str.contains('dc|barrel|τροφοδοτικό', regex=True, na=False)
                    brand_dc_match = is_same_brand & (dc_mask | universal)
                    pool.loc[brand_dc_match, 'Final_Score'] += 500000
                    if brand_dc_match.any():
                        notes.append(f"⭐ TOP: Same-brand ({tb}) DC charger → {brand_dc_match.sum()} items")
            else:
                notes.append("⚠ No port info detected → relying on brand+wattage only")
 
        # ── Logic: High-Wattage Powerbank ──
        elif logic_key == 'HIGH_WATT_PB':
            watts = pool['Title'].fillna('').apply(extract_wattage_from_text)
            high = pool[watts >= 45]
            if not high.empty:
                pool = high
                notes.append(f"Laptop PD (≥45W): {len(pool)}")
            else:
                pd_mask = pool['Title'].fillna('').str.lower().str.contains('pd|power delivery|laptop', regex=True, na=False)
                if pd_mask.any():
                    pool = pool[pd_mask]
                    notes.append(f"PD fallback: {len(pool)}")
                else:
                    notes.append("⚠ No ≥45W or PD powerbanks, keeping all")
 

        # ── Logic: Smart Mouse Selection (Performance Pairing — Tier-Driven) ──
        elif logic_key == 'MOUSE_LOGIC':
            if not is_gaming:
                # STRICT BAN on gaming pads/brands (HyperX, Razer, Corsair, etc.)
                not_gaming_mask = ~pool['Title'].fillna('').str.lower().str.contains(r'rgb|gaming|hyperx|razer|corsair|steelseries|rog\b|predator|legion', regex=True, na=False)
                pool, note = filter_or_penalize(pool, not_gaming_mask, "Persona: Hard banned gaming/RGB/HyperX pads")
                notes.append(note)
            else:
                # 🎮 GAMING LAPTOP: actively BOOST gaming mice (high-DPI sensors,
                # low-latency wireless). Just not excluding them is not enough to
                # win on sales volume vs. office mice.
                gaming_mask = pool['Title'].fillna('').str.lower().str.contains(
                    r'gaming|rgb|razer|logitech g\b|logitech g\d|g pro|g305|g502|viper|deathadder|basilisk|corsair|steelseries|hyperx|glorious|asus rog|rog gladius',
                    regex=True, na=False
                )
                pool.loc[gaming_mask, 'Final_Score'] += 200000
                notes.append(f"🎮 Gaming: Boosted gaming mice +200k ({gaming_mask.sum()} items)")

            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)

            # Cheap-trap: no <€30 mice on ≥€800 laptops
            pool, trap_note = apply_cheap_trap(pool, tprice, 'MOUSE')
            if trap_note: notes.append(trap_note)

            # Tier-based budget boost (the 20% rule, mouse = 25% of bundle)
            mouse_min, mouse_max = get_accessory_budget('MOUSE', laptop_tier)
            if laptop_tier > 0:
                in_band = (pool['_p'] >= mouse_min) & (pool['_p'] <= mouse_max)
                # Boost raised to 150k so it beats the ecosystem +100k
                pool.loc[in_band, 'Final_Score'] += 150000

                # ANTI-OVERBUY: a €150 mouse on a €798 laptop feels like upselling
                overbuy_threshold = mouse_max * 2.0
                pool.loc[pool['_p'] > overbuy_threshold, 'Final_Score'] -= 250000

                # Tier 4 anti-cheap-trap penalty (don't pair €15 mouse with €4k laptop)
                if laptop_tier == 4:
                    pool.loc[pool['_p'] < mouse_min * 0.5, 'Final_Score'] -= 100000
                notes.append(f"Tier {laptop_tier} ({tier_label}): Boost €{mouse_min:.0f}–€{mouse_max:.0f} (+150k), overbuy >€{overbuy_threshold:.0f} (-250k)")

            # Apple ecosystem: HARD FILTER to Magic Mouse or explicitly Mac-compatible mice.
            # User rule: Apple laptop → only show Magic Mouse or mice that say "for Mac"/"για Mac".
            if is_apple:
                apple_mice = pool['Κατασκευαστής'].fillna('').str.upper() == 'APPLE'
                mac_title = pool['Title'].fillna('').str.lower().str.contains(
                    r'για mac|for mac|mac edition|magic mouse',
                    regex=True, na=False
                )
                mac_compatible = apple_mice | mac_title
                if mac_compatible.any():
                    b4 = len(pool)
                    pool = pool[mac_compatible].copy()
                    notes.append(f"🍎 Apple-only mouse filter: Magic Mouse OR 'for Mac': {b4}→{len(pool)}")
                    
                    # ========================================================
                    # NEW: Peripheral Color Match for Apple Mice
                    # ========================================================
                    color_match_found = False # Track if we found a matching color
                    tlaptop_color = str(trigger.get('Χρώμα', '')).strip()
                    
                    # Fallback: Extract color from title if column is empty
                    if not tlaptop_color:
                        color_matches = re.search(r'\b(silver|space gray|space grey|midnight|starlight|gold|rose gold|indigo|black|white|μαύρο|λευκό|γκρι|ασημί)\b', _tt_lower)
                        if color_matches: tlaptop_color = color_matches.group(1)

                    if tlaptop_color and tlaptop_color.lower() not in ('nan', 'n/a', '', 'none'):
                        t_col_upper = tlaptop_color.upper()
                        synonyms = [t_col_upper]
                        
                        if t_col_upper in ['GRAPHITE', 'ΓΡΑΦΙΤΗΣ', 'GREY', 'GRAY', 'ΓΚΡΙ', 'SPACE GRAY', 'SPACE GREY']:
                            synonyms.extend(['GRAPHITE', 'ΓΡΑΦΙΤΗΣ', 'ΓΚΡΙ', 'GREY', 'GRAY'])
                        elif t_col_upper in ['BLACK', 'ΜΑΥΡΟ', 'MIDNIGHT']:
                            synonyms.extend(['BLACK', 'ΜΑΥΡΟ', 'MIDNIGHT'])
                        elif t_col_upper in ['WHITE', 'ΛΕΥΚΟ', 'ΑΣΠΡΟ', 'PALE GREY', 'STARLIGHT', 'SILVER', 'ΑΣΗΜΙ']:
                            synonyms.extend(['WHITE', 'ΛΕΥΚΟ', 'PALE GREY', 'SILVER', 'ΑΣΗΜΙ'])
                        elif t_col_upper in ['ROSE', 'ΡΟΖ', 'PINK', 'ROSE GOLD']:
                            synonyms.extend(['ROSE', 'ΡΟΖ', 'PINK'])
                        elif t_col_upper in ['BLUE', 'ΜΠΛΕ', 'INDIGO']:
                            synonyms.extend(['BLUE', 'ΜΠΛΕ', 'INDIGO'])
                        
                        if 'Χρώμα' in pool.columns:
                            attr_match = pool['Χρώμα'].fillna('').astype(str).str.strip().str.upper().isin(synonyms)
                            title_match = pool['Title'].fillna('').str.upper().str.contains('|'.join(synonyms), regex=True, na=False)
                            color_hit = attr_match | title_match
                            if color_hit.any():
                                pool.loc[color_hit, 'Final_Score'] += 150000
                                color_match_found = True
                                notes.append(f"🎨 Mouse Color match ({tlaptop_color}): +150k to {color_hit.sum()} Mac mice")
                    
                    # FIX: Premium Fallback if color match fails
                    if not color_match_found:
                        premium_mice = pool['Κατασκευαστής'].fillna('').str.strip().str.upper().isin(['LOGITECH', 'APPLE'])
                        pool.loc[premium_mice, 'Final_Score'] += 80000
                        notes.append(f"🍎 Premium mouse fallback: Boosted {premium_mice.sum()} Apple/Logitech mice (+80k)")
                    # ========================================================
                else:
                    notes.append("⚠ No Magic Mouse / Mac-compatible mouse in catalog — falling back to all")
           
            # Microsoft Surface ecosystem — mirror the Apple pattern
            elif is_surface:
                # Match by brand OR by title (Surface Arc, Microsoft Designer, Sculpt)
                ms_mice = (pool['Κατασκευαστής'].fillna('').str.upper() == 'MICROSOFT') | \
                          pool['Title'].fillna('').str.lower().str.contains(
                              r'microsoft|surface (arc|mobile|precision)|designer mouse|sculpt ergonomic',
                              regex=True, na=False
                          )
                if ms_mice.any():
                    if tprice >= 1200:
                        pool.loc[ms_mice, 'Final_Score'] += 100000
                        notes.append(f"🪟 Surface Ecosystem (premium): Microsoft mice boosted +100k ({ms_mice.sum()} items)")
                    else:
                        pool.loc[ms_mice, 'Final_Score'] += 50000
                        notes.append(f"🪟 Surface Ecosystem: Microsoft mice boosted +50k ({ms_mice.sum()} items)")
                else:
                    notes.append("🪟 Surface: No Microsoft mice in pool — no boost applied")

        # ── Logic: Smart Mousepad (FLAT RATE — does NOT scale with laptop price) ──
        elif logic_key == 'MOUSEPAD_LOGIC':
            
            # ========================================================
            # FIX 1: Ban ugly Gel/Wrist pads from the main mousepad slot
            # ========================================================
            gel_mask = pool['Title'].fillna('').str.contains(r'Gel|Wrist|Καρπού|Μαξιλαράκι', case=False, regex=True, na=False)
            pool, gel_note = filter_or_penalize(pool, ~gel_mask, "Aesthetics: Exclude Gel/Wrist pads")
            notes.append(gel_note)

            if not is_gaming:
                not_gaming_mask = ~pool['Title'].fillna('').str.lower().str.contains('rgb|gaming', regex=True, na=False)
                pool, note = filter_or_penalize(pool, not_gaming_mask, "Persona: Exclude gaming/RGB pads")
                notes.append(note)

            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)

            if is_gaming:
                # 🎮 GAMING LAPTOP: boost XL/gaming pads, relax the €30 cap (XL pads run €25-50)
                gaming_mask = pool['Title'].fillna('').str.lower().str.contains(
                    r'gaming|rgb|xl|xxl|qck|mm\d|razer goliathus|corsair mm|steelseries|hyperx|glorious|logitech g',
                    regex=True, na=False
                )
                pool.loc[gaming_mask, 'Final_Score'] += 200000
                # For gaming: boost €15-€45 (covers XL/gaming range)
                pool.loc[(pool['_p'] >= 15) & (pool['_p'] <= 45), 'Final_Score'] += 50000
                notes.append(f"🎮 Gaming: Boosted gaming/XL pads +200k ({gaming_mask.sum()} items), price band €15-€45")
            else:
                # FLAT RATE: A €15-€25 desk mat is sufficient for ANY setup.
                mp_min, mp_max = get_accessory_budget('MOUSEPAD', laptop_tier or 1)
                in_band = (pool['_p'] >= mp_min) & (pool['_p'] <= mp_max)
                pool.loc[in_band, 'Final_Score'] += 50000
                # Hard cap: penalise anything above €30 regardless of laptop price
                pool.loc[pool['_p'] > 30, 'Final_Score'] -= 80000
                notes.append(f"Flat Rate: Boost €{mp_min:.0f}–€{mp_max:.0f}, penalty >€30 (anti-gouging)")

            # ========================================================
            # UPDATED: Mousepad Color Match (reads from winning MOUSE)
            # ========================================================
            color_match_found = False
            
            if selected_mouse_row is not None:
                mouse_title = str(selected_mouse_row.get('Title', '')).lower()
                mouse_attr_color = str(selected_mouse_row.get('Χρώμα', '')).lower()
                combined_mouse_color_text = f"{mouse_title} {mouse_attr_color}"
                
                # Define core colors and their synonyms
                target_colors_map = {
                    'μαύρο': ['μαύρο', 'black', 'γραφίτη', 'γραφίτης', 'graphite', 'midnight'],
                    'λευκό': ['λευκό', 'white', 'άσπρο', 'starlight', 'pale grey'],
                    'γκρι': ['γκρι', 'grey', 'gray', 'silver', 'ασημί'],
                    'ροζ': ['ροζ', 'pink', 'rose'],
                    'μπλε': ['μπλε', 'blue', 'γαλάζιο', 'indigo', 'blue grey'],
                    'κόκκινο': ['κόκκινο', 'red']
                }
                
                detected_color_group = None
                for base_color, synonyms in target_colors_map.items():
                    # Look for any of the synonyms in the mouse's text
                    if any(re.search(rf'\b{re.escape(syn)}\b', combined_mouse_color_text) for syn in synonyms):
                        detected_color_group = synonyms
                        break
                
                if detected_color_group:
                    # Found a color in the mouse, now look for it in the mousepads
                    if 'Χρώμα' in pool.columns:
                        attr_match = pool['Χρώμα'].fillna('').astype(str).str.lower().isin(detected_color_group)
                        title_match = pool['Title'].fillna('').str.lower().str.contains('|'.join(detected_color_group), regex=True, na=False)
                        color_hit = attr_match | title_match
                        
                        # Ensure the color match isn't an ugly wrist pad
                        color_hit = color_hit & ~gel_mask
                        
                        if color_hit.any():
                            # Overrides the flat rate price bands so the colored pad wins
                            pool.loc[color_hit, 'Final_Score'] += 150000
                            color_match_found = True
                            notes.append(f"🎨 Matched Mouse Color ({detected_color_group[0]}): +150k to {color_hit.sum()} mousepads")
                else:
                    notes.append("🎨 No distinct color found in winning Mouse, skipped color matching.")
            
            # Premium Fallback: If no color match was found, boost Logitech pads
            if not color_match_found and (is_apple or laptop_tier >= 3) and not is_gaming:
                logi_pads = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == 'LOGITECH'
                pool.loc[logi_pads, 'Final_Score'] += 80000
                notes.append("🍎 Premium pad fallback: Boosted Logitech pads")
                # ========================================================

        # ── Logic: Persona-Driven Monitor (20-25% of Laptop Value) ──
        elif logic_key == 'MONITOR_LOGIC':

            # ── NEW RULE: Only suggest monitors 27" and higher ──
            title_sizes = pool['Title'].fillna('').apply(parse_screen_size)
            if 'Μέγεθος οθόνης' in pool.columns:
                col_sizes = pool['Μέγεθος οθόνης'].apply(parse_screen_size)
                pool['_mon_size'] = pd.concat([col_sizes, title_sizes], axis=1).max(axis=1)
            else:
                pool['_mon_size'] = title_sizes
                
            # Filter out monitors < 27" (we keep 0.0 as a fallback so we don't accidentally drop items missing size data)
            size_mask = (pool['_mon_size'] >= 27.0) | (pool['_mon_size'] == 0.0)
            pool, note = filter_or_penalize(pool, size_mask, "Size rule: Exclude monitors under 27\"")
            notes.append(note)

            # ── Req 8: Match laptop Προτεινόμενη χρήση ↔ monitor Χρήση ──
            # Gaming laptop → Gaming monitor. Επαγγελματική → Business. Mainstream → Mainstream.
            # Non-gaming laptop → HARD EXCLUDE Χρήση=Gaming.
            if 'Χρήση' in pool.columns:
                mon_usage = pool['Χρήση'].fillna('').astype(str).str.lower()

                # Determine target usage from laptop tusage (already lowercased above)
                if is_gaming:
                    matching_use = mon_usage.str.contains('gaming', regex=False, na=False)
                    # Hard boost for matching use
                    pool.loc[matching_use, 'Final_Score'] += 200000
                    notes.append(f"🎯 Χρήση match (Gaming): +200k to {matching_use.sum()} monitors")
                elif 'επαγγελματική' in tusage or 'premium' in tusage:
                    matching_use = mon_usage.str.contains('business|επαγγελ', regex=True, na=False)
                    # Non-gaming: hard-exclude gaming monitors
                    gaming_use = mon_usage.str.contains('gaming', regex=False, na=False)
                    if (~gaming_use).any():
                        b4 = len(pool)
                        pool = pool[~gaming_use]
                        mon_usage = pool['Χρήση'].fillna('').astype(str).str.lower()
                        matching_use = mon_usage.str.contains('business|επαγγελ', regex=True, na=False)
                        notes.append(f"🚫 Χρήση=Gaming excluded: {b4}→{len(pool)}")
                    pool.loc[matching_use, 'Final_Score'] += 150000
                    notes.append(f"🎯 Χρήση match (Business/Επαγγελματική): +150k to {matching_use.sum()}")
                elif 'mainstream' in tusage or 'καθημερινή' in tusage:
                    matching_use = mon_usage.str.contains('mainstream|καθημερινή', regex=True, na=False)
                    # Non-gaming: hard-exclude gaming monitors
                    gaming_use = mon_usage.str.contains('gaming', regex=False, na=False)
                    if (~gaming_use).any():
                        b4 = len(pool)
                        pool = pool[~gaming_use]
                        mon_usage = pool['Χρήση'].fillna('').astype(str).str.lower()
                        matching_use = mon_usage.str.contains('mainstream|καθημερινή', regex=True, na=False)
                        notes.append(f"🚫 Χρήση=Gaming excluded: {b4}→{len(pool)}")
                    pool.loc[matching_use, 'Final_Score'] += 150000
                    notes.append(f"🎯 Χρήση match (Mainstream): +150k to {matching_use.sum()}")
                else:
                    # Unknown usage → still exclude gaming monitors unless the laptop is gaming
                    gaming_use = mon_usage.str.contains('gaming', regex=False, na=False)
                    if gaming_use.any() and (~gaming_use).any():
                        b4 = len(pool)
                        pool = pool[~gaming_use]
                        notes.append(f"🚫 Non-gaming laptop: Χρήση=Gaming excluded: {b4}→{len(pool)}")

            # Fallback for items without Χρήση attribute: title-based check
            if not is_gaming:
                gaming_mon = pool['Title'].fillna('').str.lower().str.contains('gaming|odyssey|predator|144hz|165hz|180hz|240hz', regex=True, na=False)
                pool, note = filter_or_penalize(pool, ~gaming_mon, "Non-gaming: Exclude gaming-branded monitors (title)")
                notes.append(note)
            else:
                gaming_mon_mask = pool['Title'].fillna('').str.lower().str.contains(
                    r'gaming|odyssey|predator|aorus|rog swift|rog strix|ultragear|nitro|mag\b|viewsonic elite',
                    regex=True, na=False
                )
                pool.loc[gaming_mon_mask, 'Final_Score'] += 200000
                notes.append(f"🎮 Gaming: Boosted gaming-branded monitors +200k ({gaming_mon_mask.sum()} items)")

            if tres_tier > 0:
                pool['_res_tier'] = pool['Ανάλυση Οθόνης'].apply(get_resolution_tier)
                keep = (pool['_res_tier'] >= tres_tier) | (pool['_res_tier'] == 0)
                pool, note = filter_or_penalize(pool, keep, f"Resolution ≥ tier {tres_tier}")
                notes.append(note)

            if (is_apple or is_premium) and laptop_tier >= 3:
                fhd_mon = pool['Title'].fillna('').str.lower().str.contains('fhd|1080p|1920x1080', regex=True, na=False)
                pool, note = filter_or_penalize(pool, ~fhd_mon, "Tier 3+ premium: Exclude FHD monitors")
                notes.append(note)

            # ── Req 7: Monitor budget = 20-25% of laptop price (replaces tier-based budget) ──
            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)
            apple_monitors = pool['Κατασκευαστής'].fillna('').str.upper() == 'APPLE'

            pool, trap_note = apply_cheap_trap(pool, tprice, 'MONITOR')
            if trap_note: notes.append(trap_note)

            if tprice > 0:
                mon_min = tprice * 0.20
                mon_max = tprice * 0.25
                # Widen sweet-spot band slightly to ±5% around the 20-25% range so the
                # in-band pool isn't too tiny for budget laptops. Sweet spot is 15-30%.
                sweet_min = tprice * 0.15
                sweet_max = tprice * 0.30
                in_sweet = (pool['_p'] >= sweet_min) & (pool['_p'] <= sweet_max)
                in_band  = (pool['_p'] >= mon_min) & (pool['_p'] <= mon_max)
                pool.loc[in_sweet, 'Final_Score'] += 100000
                pool.loc[in_band, 'Final_Score'] += 100000  # stacks → 200k for the 20-25% core
                # Overbuy penalty: monitor >50% of laptop price
                overbuy_threshold = tprice * 0.50
                pool.loc[pool['_p'] > overbuy_threshold, 'Final_Score'] -= 250000
                # Cheap penalty for high-tier laptops only
                if laptop_tier >= 3:
                    pool.loc[pool['_p'] < sweet_min * 0.5, 'Final_Score'] -= 100000
                notes.append(f"💶 Monitor budget 20-25% of €{tprice:.0f}: €{mon_min:.0f}-€{mon_max:.0f} (+200k sweet, overbuy >€{overbuy_threshold:.0f} -250k)")

            # High-refresh boost for gaming / Tier 3+
            if laptop_tier >= 3 or is_gaming:
                high_refresh = pool['Title'].fillna('').str.lower().str.contains('144hz|165hz|180hz|240hz|360hz', regex=True, na=False)
                pool.loc[high_refresh, 'Final_Score'] += 30000
                notes.append("High-refresh boost (≥144Hz) — match GPU performance")

            # ── Retina laptop → premium panel technology only (HARD FILTER) ──
            # A Retina MacBook is a color-accurate device. Pairing it with a generic TN (terrible colors)
            # or VA (color shifting) panel undermines the quality. Allow only the BEST premium panels.
            GOOD_PANEL_PAT = r'\bips\b|\boled\b|\bamoled\b|\bqd-oled\b|nano\s*ips|\bretina\b|\bads\b|micro\s*led|mini\s*led'
            
            if trigger_is_retina:
                tech_mask = pd.Series(False, index=pool.index)
                if 'Τεχνολογία Οθόνης' in pool.columns:
                    tech_mask = pool['Τεχνολογία Οθόνης'].fillna('').astype(str).str.lower().str.contains(GOOD_PANEL_PAT, regex=True, na=False)
                # Also check title as fallback — many monitors spell the panel tech in the title
                tech_mask = tech_mask | pool['Title'].fillna('').str.lower().str.contains(GOOD_PANEL_PAT, regex=True, na=False)
                
                if tech_mask.any():
                    b4 = len(pool)
                    pool = pool[tech_mask]
                    notes.append(f"🖼️ Retina laptop → premium panel tech filter (IPS/OLED/MiniLED only): {b4}→{len(pool)}")
                else:
                    notes.append("⚠ Retina laptop but no premium panels found in catalog — keeping all")
                    
            # ── Req 6: OLED laptop → Soft preference for OLED monitors ──
            if trigger_is_oled:
                oled_mon = pool['Title'].fillna('').str.lower().str.contains(r'\boled\b|\bamoled\b|\bqd-oled\b', regex=True, na=False)
                if 'Τεχνολογία Οθόνης' in pool.columns:
                    oled_mon = oled_mon | pool['Τεχνολογία Οθόνης'].fillna('').astype(str).str.lower().str.contains(r'oled|amoled', regex=True, na=False)
                
                if oled_mon.any():
                    # 1. Base boost for being OLED
                    pool.loc[oled_mon, 'Final_Score'] += 150000
                    
                    # 2. Deboost extremely expensive OLEDs (> 60% of the laptop price)
                    # (This stacks on top of the standard overbuy penalty to nuke it completely)
                    extreme_price_threshold = tprice * 0.60
                    extreme_oled = oled_mon & (pool['_p'] > extreme_price_threshold)
                    pool.loc[extreme_oled, 'Final_Score'] -= 400000
                    
                    # 3. Slight deboost for gaming OLEDs if the user's laptop isn't specifically gaming
                    if not is_gaming:
                        gaming_oled = oled_mon & pool['Title'].fillna('').str.lower().str.contains(r'gaming|odyssey|predator|rog|alienware|aorus', regex=True, na=False)
                        pool.loc[gaming_oled, 'Final_Score'] -= 80000
                    
                    notes.append(f"🌈 OLED laptop → Soft Boost to {oled_mon.sum()} OLEDs (+150k), Heavy penalty if >€{extreme_price_threshold:.0f}")
                else:
                    notes.append("⚠ OLED laptop but no OLED monitors found — standard IPS/VA applies")

            vesa_mon = pool['Title'].fillna('').str.lower().str.contains('vesa|ergonomic|pivot', regex=True, na=False)
            pool.loc[vesa_mon, 'Final_Score'] += 10000

            if is_apple:
                usbc_mon = pool['Title'].fillna('').str.lower().str.contains('usb-c|type-c|thunderbolt|mac', regex=True, na=False)
                pool.loc[usbc_mon, 'Final_Score'] += 50000
                if tprice >= 1400:
                    pool.loc[apple_monitors, 'Final_Score'] += 500000
                else:
                    pool.loc[apple_monitors, 'Final_Score'] -= 300000

            elif is_surface:
                usbc_mon = pool['Title'].fillna('').str.lower().str.contains('usb-c|type-c|thunderbolt', regex=True, na=False)
                if usbc_mon.any():
                    pool.loc[usbc_mon, 'Final_Score'] += 50000
                    notes.append("🪟 Surface: USB-C monitor boost (single-cable docking)")



                
        # ── Logic: Office / Headset Ecosystem ──
        elif logic_key == 'OFFICE_HEADSET_LOGIC':
            if is_apple:
                office_software = pool['Hierarchy'].fillna('').str.upper() == 'OFFICE SUITES'
                pool = pool[~office_software]
                notes.append("Brand Ecosystem: Banned Microsoft Office for Mac users")

            # 🪟 Microsoft Surface: boost MS-branded Office & peripherals
            if is_surface:
                ms_brand = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == 'MICROSOFT'
                office_software = pool['Hierarchy'].fillna('').str.upper() == 'OFFICE SUITES'
                pool.loc[ms_brand | office_software, 'Final_Score'] += 80000
                if (ms_brand | office_software).any():
                    notes.append(f"🪟 Surface Ecosystem: Microsoft brand + Office suites boosted +80k")

            is_headset = ~pool['Hierarchy'].fillna('').str.upper().str.contains('OFFICE')
            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)

            if is_headset.any():
                # ══════════════════════════════════════════════════════
                # SIZE-BASED HIERARCHY + TYPE FILTER (HARD RULE)
                #   <15": Bluetooth hierarchy  OR  Overhead hierarchy + ON EAR type
                #   ≥15": Overhead hierarchy + OVER EAR type
                # Office Suites are preserved regardless (they aren't headsets).
                # ══════════════════════════════════════════════════════
                hier_upper = pool['Hierarchy'].fillna('').str.upper()
                is_bluetooth_hier = hier_upper.str.contains('BLUETOOTH')
                is_overhead_hier  = hier_upper.str.contains('OVERHEAD')
                is_office         = hier_upper.str.contains('OFFICE')

                if 'Τύπος ακουστικών' in pool.columns:
                    type_col = pool['Τύπος ακουστικών'].fillna('').str.upper()
                else:
                    type_col = pd.Series('', index=pool.index)

                is_onear  = is_overhead_hier & type_col.str.contains('ON EAR')
                is_overear = is_overhead_hier & type_col.str.contains('OVER EAR')

                if tscreen > 0:
                    # Build the two rule masks up front
                    under15_mask = is_bluetooth_hier | is_onear   # <15" rule
                    over15_mask  = is_overear                      # ≥15" rule

                    if tscreen < 15:
                        primary_mask, primary_label   = under15_mask, "<15\" rule: Bluetooth OR Overhead+ON-EAR"
                        fallback_mask, fallback_label = over15_mask,  "fallback to Overhead+OVER-EAR"
                    else:
                        primary_mask, primary_label   = over15_mask,  "≥15\" rule: Overhead+OVER-EAR"
                        # ≥15" fallback = the <15" rule itself (On-Ear OR Bluetooth)
                        # — consistent with what a 14.9" laptop would get, instead of
                        # leaving the pool unfiltered.
                        fallback_mask, fallback_label = under15_mask, "fallback to Bluetooth OR Overhead+ON-EAR"

                    # ========================================================
                    # NEW: Protect Apple audio from being wiped out by the size filter
                    apple_protect = (pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == 'APPLE') | \
                                    pool['Title'].fillna('').str.lower().str.contains(r'airpods|earpods', regex=True, na=False)
                    # ========================================================

                    
                    # Cascade: primary → fallback → skip
                    b4 = len(pool)
                    primary_keep = pool[primary_mask | is_office]
                    if not primary_keep[primary_mask].empty:
                        pool = primary_keep
                        notes.append(f"🎧 {primary_label}: {b4}→{len(pool)}")
                    else:
                        fallback_keep = pool[fallback_mask | is_office]
                        if not fallback_keep[fallback_mask].empty:
                            pool = fallback_keep
                            notes.append(f"🎧 {primary_label} empty → {fallback_label}: {b4}→{len(pool)}")
                        else:
                            notes.append(f"⚠ Both primary and fallback headset rules empty — no filter applied")

                    # Recompute masks on filtered pool for downstream boosts
                    hier_upper = pool['Hierarchy'].fillna('').str.upper()
                    is_bluetooth_hier = hier_upper.str.contains('BLUETOOTH')
                    is_overhead_hier  = hier_upper.str.contains('OVERHEAD')
                    is_office         = hier_upper.str.contains('OFFICE')
                    is_headset        = ~is_office
                    if 'Τύπος ακουστικών' in pool.columns:
                        type_col = pool['Τύπος ακουστικών'].fillna('').str.upper()
                    else:
                        type_col = pd.Series('', index=pool.index)
                    is_onear   = is_overhead_hier & type_col.str.contains('ON EAR')
                    is_overear = is_overhead_hier & type_col.str.contains('OVER EAR')
                    is_earbud  = is_bluetooth_hier
                    is_overhead = is_overhead_hier
                else:
                    is_earbud = is_bluetooth_hier
                    is_overhead = is_overhead_hier

                # ── Persona boosts (all on top of the filtered pool) ──
                if is_gaming:
                    gaming_mask = pool['Title'].fillna('').str.lower().str.contains(
                        r'gaming|razer|corsair|steelseries|hyperx|logitech g\b|astro|asus rog|rog delta|kraken|cloud ii|arctis|blackshark',
                        regex=True, na=False
                    )
                    pool.loc[is_headset & gaming_mask, 'Final_Score'] += 250000
                    pool.loc[is_headset & gaming_mask & is_overhead, 'Final_Score'] += 50000
                    notes.append(f"🎮 Gaming: Boosted gaming headsets +250k ({(is_headset & gaming_mask).sum()} items)")
                elif 'Προτεινόμενη χρήση' in pool.columns:
                    if is_premium or is_apple:
                        prem_use = pool['Προτεινόμενη χρήση'].fillna('').str.lower().str.contains('premium|επαγγελματική', regex=True, na=False)
                        pool.loc[is_headset & prem_use, 'Final_Score'] += 50000
                        notes.append("Persona: Boosted Premium/Professional headsets")
                    else:
                        standard_use = pool['Προτεινόμενη χρήση'].fillna('').str.lower().str.contains('ομιλία|καθημερινή', regex=True, na=False)
                        pool.loc[is_headset & standard_use, 'Final_Score'] += 50000
                        notes.append("Persona: Boosted standard Voice/Daily headsets")
                else:
                    notes.append("Persona: Boost skipped ('Προτεινόμενη χρήση' column missing from candidates)")

                apple_hp = pd.Series(False, index=pool.index)
                
                # Apple ecosystem — HARD PREFER Apple-branded headphones (AirPods family)
                # and color-match the laptop color when possible.
                if is_apple:
                    # First, expand search to APPLE HEADPHONES hierarchy — these are
                    # the AirPods listings and they should dominate the slot for Apple users.
                    apple_brand = pool['Κατασκευαστής'].fillna('').str.strip().str.upper() == 'APPLE'
                    airpods_title = pool['Title'].fillna('').str.lower().str.contains(
                        r'airpods',
                        regex=True, na=False
                    )
                    apple_hp_hier = hier_upper.str.contains('APPLE HEADPHONES|APPLE ORIGINAL HEADPHONES', regex=True, na=False)
                    apple_hp = (apple_brand | airpods_title | apple_hp_hier) & is_headset

                    if apple_hp.any():
                        # ========================================================
                        # SUPER HARD boost — force Apple earbuds to the absolute top (+500k)
                        # ========================================================
                        pool.loc[apple_hp, 'Final_Score'] += 500000
                        notes.append(f"🍎 Apple HEADPHONES hard-boost +500k ({apple_hp.sum()} items)")


                        # ========================================================
                        # NEW: Ensure budget Macs get standard AirPods instead of Pros
                        if tprice < 1200:
                            pro_apple = apple_hp & (pool['_p'] > 180)
                            pool.loc[pro_apple, 'Final_Score'] -= 150000
                            if pro_apple.any():
                                notes.append(f"🍎 Apple: <€1200 laptop → Preferred standard AirPods over Pro (-150k to {pro_apple.sum()} items)")
                        # ========================================================

                        
                        # Color match: if laptop has a Χρώμα, boost same-color headphones
                        tlaptop_color = str(trigger.get('Χρώμα', '')).strip()
                        if tlaptop_color and tlaptop_color.lower() not in ('nan', 'n/a', '', 'none'):
                            if 'Χρώμα' in pool.columns:
                                color_match_mask = apple_hp & (
                                    pool['Χρώμα'].fillna('').astype(str).str.strip().str.lower() == tlaptop_color.lower()
                                )
                                if color_match_mask.any():
                                    pool.loc[color_match_mask, 'Final_Score'] += 150000
                                    notes.append(f"🎨 Color match ({tlaptop_color}): +150k to {color_match_mask.sum()} Apple headphones")
                                else:
                                    # Fall back to title-based color match
                                    color_title = apple_hp & pool['Title'].fillna('').str.lower().str.contains(
                                        re.escape(tlaptop_color.lower()), regex=True, na=False
                                    )
                                    if color_title.any():
                                        pool.loc[color_title, 'Final_Score'] += 100000
                                        notes.append(f"🎨 Color match via title ({tlaptop_color}): +100k to {color_title.sum()}")
                    else:
                        # Fallback to premium audio brands only if no Apple headphones exist
                        premium_overhead = pool['Title'].fillna('').str.lower().str.contains(
                            r'wh-1000xm|wh1000xm|quietcomfort|qc\d|momentum \d|bose 700|audio-technica',
                            regex=True, na=False
                        )
                        pool.loc[is_headset & premium_overhead, 'Final_Score'] += 100000
                        if (is_headset & premium_overhead).any():
                            notes.append(f"🍎 Apple fallback: Premium audio brands +100k ({(is_headset & premium_overhead).sum()} items)")
                            
                # Headset Sane Price Tiering — stricter for budget laptops
                if tprice >= 2000:
                    pass
                elif tprice >= 1000:
                    # Added & ~apple_hp so Apple earbuds don't get penalized
                    pool.loc[is_headset & (pool['_p'] > 250) & ~apple_hp, 'Final_Score'] -= 100000
                elif tprice > 0:
                    # Sub-€1000 laptop: cap headsets at ~15% of laptop price
                    max_hs_price = max(50, tprice * 0.15)
                    # Added & ~apple_hp so Apple earbuds don't get penalized
                    pool.loc[is_headset & (pool['_p'] > max_hs_price) & ~apple_hp, 'Final_Score'] -= 200000
                    notes.append(f"Price Tiering: Hard penalty (-200k) for standard headsets >€{max_hs_price:.0f} (Apple HPs exempt)")
 


                    
 
        # ── Logic: Cooler / Stand Size Match ──
        # Coolers are printed with a supported size. A 15.6" cooler is too small
        # for a 16" laptop (overhangs) and ridiculous for a 13" laptop (wasted space).
        elif logic_key == 'STAND_SIZE':
            # 🚫 EXCLUDE monitor mounts/arms/desk-mounts — they live in the same
            # hierarchy (ΒΑΣΕΙΣ ΓΡΑΦΕΙΟΥ) but are NOT laptop stands. Titles like
            # "Βάση Οθόνης Επιτραπέζια με Βραχίονα" (monitor desk mount with arm)
            # or SBOX LCD-352 (monitor arm 17"-32") should never appear here.
            title_lower = pool['Title'].fillna('').str.lower()
            monitor_mount_mask = title_lower.str.contains(
                r'βάση οθόν|monitor (arm|mount|stand)|βραχίον|lcd arm|desk mount|wall mount|επιτοίχι',
                regex=True, na=False
            )
            b4 = len(pool)
            pool = pool[~monitor_mount_mask]
            if b4 > len(pool):
                notes.append(f"🚫 Excluded monitor mounts/arms: {b4}→{len(pool)}")

            if tscreen > 0:
                size_col = None
                for candidate_col in ['Μέγεθος', 'Μέγεθος οθόνης']:
                    if candidate_col in pool.columns:
                        size_col = candidate_col
                        break

                # Compute effective size: max of field value AND title-parsed size.
                # Catches products where Μέγεθος=0 but title says "15.6 inch" — we
                # want the title size to count so they can be correctly filtered.
                title_size = pool['Title'].fillna('').apply(parse_screen_size)
                if size_col:
                    field_size = pool[size_col].apply(parse_screen_size)
                    pool['_acc_size'] = pd.concat([field_size, title_size], axis=1).max(axis=1)
                else:
                    pool['_acc_size'] = title_size

                # Coolers for laptops: size must be within reasonable fit range.
                # Tightened from +2.0 to +1.5 so a 15.6" cooler can't win on a 12" laptop.
                strict_fit = pool[(pool['_acc_size'] >= tscreen - 0.5) & (pool['_acc_size'] <= tscreen + 1.5)]
                if not strict_fit.empty:
                    pool = strict_fit
                    notes.append(f"Cooler strict size fit {tscreen}\" (-0.5/+1.5\"): {len(pool)}")
                else:
                    loose_fit = pool[(pool['_acc_size'] >= tscreen - 1.0) & (pool['_acc_size'] <= tscreen + 3.0)]
                    if not loose_fit.empty:
                        pool = loose_fit
                        notes.append(f"Cooler loose size fit {tscreen}\" (-1.0/+3.0\"): {len(pool)}")
                    else:
                        # Only truly sizeless (universal) pass — products that claim a specific
                        # size via title but don't match are NOT eligible.
                        sizeless = pool[pool['_acc_size'] == 0]
                        if not sizeless.empty:
                            pool = sizeless
                            notes.append(f"⚠ No cooler size match for {tscreen}\", kept {len(pool)} sizeless (universal)")

            # Gaming laptops benefit from active (fan) coolers; others lean to passive stands
            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)
            if is_apple:
                # 🍎 Hard ban active fan coolers for MacBooks
                active_cooling_mask = pool['Title'].fillna('').str.lower().str.contains('cooler|fan|cooling|ανεμιστήρ', regex=True, na=False)
                b4_apple_coolers = len(pool)
                pool = pool[~active_cooling_mask]
                if b4_apple_coolers > len(pool):
                    notes.append(f"🍎 Apple: Hard banned active fan coolers ({b4_apple_coolers}→{len(pool)})")
                
                # Boost passive stands massively
                stand_mask = pool['Title'].fillna('').str.lower().str.contains('stand|βάση|aluminum|αλουμίνιο|ergonomic', regex=True, na=False)
                pool.loc[stand_mask, 'Final_Score'] += 200000
                notes.append("Premium/Apple: Passive ergonomic stand boost (+200k)")
            elif is_gaming:
                fan_mask = pool['Title'].fillna('').str.lower().str.contains('fan|cooler|ψύξη|rgb', regex=True, na=False)
                pool.loc[fan_mask, 'Final_Score'] += 40000
                notes.append("Gaming: Active cooler (fan) boost")
            elif is_premium:
                stand_mask = pool['Title'].fillna('').str.lower().str.contains('stand|βάση|aluminum|αλουμίνιο|ergonomic', regex=True, na=False)
                pool.loc[stand_mask, 'Final_Score'] += 40000
                notes.append("Premium: Passive ergonomic stand boost")


        # ── Logic: Storage (SSD for premium, HDD for budget) ──
        # A 1TB portable HDD on a €2849 MacBook Pro is embarrassing. Premium
        # laptops should pair with portable SSDs (speed + form factor match),
        # budget laptops with HDDs or high-capacity flash.
        elif logic_key == 'STORAGE_LOGIC':
            pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)

            # Cheap-trap: no €10 USB sticks with a €2k laptop
            pool, trap_note = apply_cheap_trap(pool, tprice, 'STORAGE')
            if trap_note: notes.append(trap_note)

            is_ssd = pool['Title'].fillna('').str.lower().str.contains(r'\bssd\b|portable ssd|nvme|t7|t5|sandisk extreme', regex=True, na=False)
            is_hdd = pool['Title'].fillna('').str.lower().str.contains(r'\bhdd\b|hard drive|elements|my passport|canvio', regex=True, na=False)

            if laptop_tier >= 3:
                # Premium/Pro: SSDs only. If catalog has none, penalise HDDs
                # (-150k) instead of filtering — flash drives at least win over HDDs.
                pool, note = filter_or_penalize(pool, is_ssd, f"Tier {laptop_tier}: SSD-only")
                notes.append(note)
                # Recompute is_ssd/is_hdd on possibly-filtered pool
                is_ssd = pool['Title'].fillna('').str.lower().str.contains(r'\bssd\b|portable ssd|nvme|t7|t5|sandisk extreme', regex=True, na=False)
                pool.loc[pool['_p'] >= 100, 'Final_Score'] += 100000
                notes.append("Tier 3+: Boost ≥€100 SSDs (speed + capacity match)")
            elif laptop_tier == 2:
                # Mid-range: prefer SSD but don't ban HDD
                pool.loc[is_ssd, 'Final_Score'] += 80000
                pool.loc[is_hdd, 'Final_Score'] -= 20000
                notes.append("Tier 2: SSD preferred over HDD")
            else:
                # Budget: HDDs fine, large flash drives fine
                pool.loc[(pool['_p'] >= 25) & (pool['_p'] <= 60), 'Final_Score'] += 40000
                notes.append("Tier 1: Value storage (€25–€60 range)")

            # Apple users: boost Mac-compatible portable SSDs only (not HDDs!)
            # LaCie makes BOTH the "Mobile Drive" (HDD) and the "Rugged/Mobile SSD",
            # so we only match LaCie products whose title contains SSD indicators.
            if is_apple:
                lacie_ssd = pool['Title'].fillna('').str.lower().str.contains(r'lacie', regex=True, na=False) & is_ssd
                other_mac_ssd = pool['Title'].fillna('').str.lower().str.contains(
                    r'samsung t7|samsung t9|sandisk extreme (portable )?ssd',
                    regex=True, na=False
                )
                mac_ssd_mask = lacie_ssd | other_mac_ssd
                pool.loc[mac_ssd_mask, 'Final_Score'] += 50000
                if mac_ssd_mask.any():
                    notes.append(f"🍎 Apple: Mac-friendly SSDs boosted +50k ({mac_ssd_mask.sum()} items)")

        # ── GENERIC: just sales + availability ──
        # logic_key == 'GENERIC' — no extra filtering needed
 
        # ══════════════════════════════════════════════════════
        # PICK BEST ITEM
        # ══════════════════════════════════════════════════════
        if pool.empty:
            notes.append("❌ No items after logic")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Empty after logic"))
            continue
 
        pool = pool.sort_values('Final_Score', ascending=False)
 
        # Hierarchy cap: max 2 per hierarchy across all slots
        chosen = None
        for _, row in pool.iterrows():
            h = row['Hierarchy']
            if used_hierarchies_count.get(h, 0) < 2:
                chosen = row
                break
 
        if chosen is None:
            notes.append("❌ Hierarchy cap blocks all")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Hier cap"))
            continue
 
        row_copy = chosen.copy()
        row_copy['Assigned_Slot'] = slot_num
        row_copy['Slot_Role'] = role
        # --- NEW: Tier-Aware "Performance Pairing" Copy ---
        if logic_key == 'MONITOR_LOGIC':
            if laptop_tier == 4:   row_copy['Marketing_Copy'] = "4K/Pro panel — built to match your workstation's color & speed."
            elif laptop_tier == 3: row_copy['Marketing_Copy'] = "QHD/144Hz+ — unlock your GPU, no screen tearing."
            elif laptop_tier == 2: row_copy['Marketing_Copy'] = "144Hz IPS — perfect pairing for your AI-ready laptop."
            else:                  row_copy['Marketing_Copy'] = "Entry FHD — extra workspace at the right price."
        elif logic_key == 'MOUSE_LOGIC':
            if laptop_tier == 4:   row_copy['Marketing_Copy'] = "Top-tier sensor — keeps up with your machine's response time."
            elif laptop_tier == 3: row_copy['Marketing_Copy'] = "8K+ DPI — cursor as smooth as your high-refresh screen."
            elif laptop_tier == 2: row_copy['Marketing_Copy'] = "High-DPI sensor — matched to your laptop's display speed."
            else:                  row_copy['Marketing_Copy'] = "Reliable wireless — clean, no-fuss daily driver."
        elif logic_key == 'CHARGER_PORT':
            if tb and str(chosen.get('Κατασκευαστής','')).strip().upper() == tb:
                row_copy['Marketing_Copy'] = f"Original {tb.title()} — guaranteed fit and full wattage."
            else:
                row_copy['Marketing_Copy'] = "Compatible PD charger — matches your laptop's port and wattage."
        elif logic_key == 'BAG_SIZE' or logic_key == 'SLEEVE_SIZE':
            if laptop_tier >= 3: row_copy['Marketing_Copy'] = "Premium protection sized exactly to your laptop."
            else:                row_copy['Marketing_Copy'] = "Right-sized carry, comfortable every day."
        elif logic_key == 'MOUSEPAD_LOGIC':
            row_copy['Marketing_Copy'] = "Smooth glide, stable base — ideal for any setup."
        else:
            row_copy['Marketing_Copy'] = LAPTOP_MARKETING_COPY.get(role, "Ιδανική επιλογή!")
        row_copy['Item_Rank'] = 1
        all_recs.append(row_copy)
        used_materials.add(chosen['Material'])
        used_hierarchies_count[chosen['Hierarchy']] = used_hierarchies_count.get(chosen['Hierarchy'], 0) + 1
        notes.append(f"✅ {str(chosen.get('Title',''))[:60]}")
        slot_notes[slot_num] = notes
        if logic_key == 'MOUSE_LOGIC':
            selected_mouse_row = chosen
        diag.append((f"Slot {slot_num} ({role})", 1, f"Score: {chosen.get('Final_Score', 0):.0f}"))
 
    diag.append(("TOTAL", len(all_recs), f"out of {len(LAPTOP_MAINSTREAM_SLOTS)}"))
 
    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()
 



# ═══════════════════════════════════════════════════════════════════════════════
# CLIMA ENGINE
# ═══════════════════════════════════════════════════════════════════════════════
def run_climatism_engine(trigger, df_air, df_products, df_history):
    diag, slot_notes, all_recs = [], {}, []
    
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    
    # 1. Έξυπνη Εξαγωγή BTU & Προσδιορισμός Tier
    btu_match = re.search(r'(\d{1,2})[\s\.]?000', tt)
    if not btu_match:
        btu_match = re.search(r'\b(9|12|18|24)\b', tt)
        t_btu = int(btu_match.group(1)) * 1000 if btu_match else 12000
    else:
        t_btu = int(btu_match.group(0).replace('.', '').replace(' ', ''))
        
    ptier = get_clima_tier_by_btu(tprice, t_btu)
    t_area = BTU_AREA_MAP.get(t_btu, 25)
    
    import datetime
    current_month = datetime.datetime.now().month
    season = 'SUMMER' if 5 <= current_month <= 10 else 'WINTER'
    active_slots = CLIMA_SUMMER_SLOTS if season == 'SUMMER' else CLIMA_WINTER_SLOTS
    
    # Slot-1 helper: εντόπισε σειρά για Συμβατότητα-driven αξεσουάρ
    compat_series = detect_clima_compat_series(trigger)
    
    diag.append(("0. Context", f"BTU: {t_btu}, Tier: {ptier}", f"Season: {season}, Area: {t_area}m²"))
    diag.append(("0b. Compat", f"Series: {compat_series}", f"Brand: {tb}"))

    # --- ΣΥΝΕΝΩΣΗ ΠΗΓΩΝ ΔΕΔΟΜΕΝΩΝ ---
    # Ενώνουμε το sheet Air με το sheet Products για να έχουμε πρόσβαση σε μπαταρίες/surge protectors
    full_pool = pd.concat([df_air, df_products], ignore_index=True)
    c = full_pool[full_pool['Material'] != tm].copy()
    
    c['Sales_Tiebreaker'] = pd.to_numeric(c.get('Sum of Sales', 0), errors='coerce').fillna(0)
    c['_p'] = pd.to_numeric(c.get('LIST PRICE', 0), errors='coerce').fillna(0)
    
    used_materials = {tm}

    for slot_num, role, hierarchies, logic_key in active_slots:
        notes = [f"Logic: {logic_key}"]
        
        # AC αξεσουάρ ζουν στο Level 2 (όχι Hierarchy) — βλ. schema note στα config
        if logic_key == 'AC_ACCESSORY_COMPAT':
            if 'Level 2' not in c.columns:
                notes.append("⚠ Δεν υπάρχει στήλη 'Level 2' στο pool")
                slot_notes[slot_num] = notes
                continue
            l2 = c['Level 2'].fillna('').astype(str).str.strip()
            pool = c[l2 == hierarchies[0]].copy()
        else:
            # Default: φιλτράρισμα με βάση το Hierarchy (όπως όλα τα άλλα slots)
            pool = c[c['Hierarchy'].fillna('').astype(str).isin(hierarchies)].copy()
        
        pool = pool[~pool['Material'].isin(used_materials)]
        
        if pool.empty:
            # Slot 1 (AC_ACCESSORY_COMPAT): make the empty state visible in the
            # funnel so it's obvious whether accessory data is missing.
            if logic_key == 'AC_ACCESSORY_COMPAT':
                notes.append(f"⚠ Δεν βρέθηκαν rows με Level 2='{hierarchies[0]}' στο pool (df_air + df_products)")
                slot_notes[slot_num] = notes
            continue

        # ── Slot 1: Συμβατότητα-driven αξεσουάρ κλιματιστικού ──
        # Φιλτράρει το pool βάσει στήλης 'Συμβατότητα'. Αν το trigger ανήκει σε
        # συγκεκριμένη σειρά (π.χ. JURO-PRO ECO II) προσπαθούμε πρώτα να βρούμε
        # specific match· αλλιώς fallback στο 'Universal'.
        if logic_key == 'AC_ACCESSORY_COMPAT':
            if 'Συμβατότητα' not in pool.columns:
                notes.append("⚠ Δεν υπάρχει στήλη 'Συμβατότητα' στο pool")
                slot_notes[slot_num] = notes
                continue
            
            compat_norm = pool['Συμβατότητα'].fillna('').astype(str).str.strip().str.lower()
            universal_norm = CLIMA_COMPAT_UNIVERSAL_LABEL.lower()
            
            if compat_series != CLIMA_COMPAT_UNIVERSAL_LABEL:
                series_norm = compat_series.lower()
                specific_pool = pool[compat_norm == series_norm]
                if not specific_pool.empty:
                    pool = specific_pool.copy()
                    notes.append(f"Series match: {compat_series} → {len(pool)} candidates")
                else:
                    pool = pool[compat_norm == universal_norm].copy()
                    notes.append(f"Δεν βρέθηκε '{compat_series}' → fallback σε Universal → {len(pool)}")
            else:
                pool = pool[compat_norm == universal_norm].copy()
                notes.append(f"Δεν εντοπίστηκε σειρά → Universal → {len(pool)}")
            
            if pool.empty:
                slot_notes[slot_num] = notes
                continue
            
            # Ranking: sales-first, μετά χαμηλότερη τιμή ως tiebreaker
            pool['Final_Score'] = pool['Sales_Tiebreaker'].astype(float)
            pool = pool.sort_values(['Final_Score', '_p'], ascending=[False, True])
            
            chosen = pool.iloc[0]
            rc = chosen.copy()
            rc['Assigned_Slot'] = slot_num
            rc['Slot_Role'] = role
            chosen_compat = str(chosen.get('Συμβατότητα', '')).strip()
            rc['Marketing_Copy'] = f"Συμβατό αξεσουάρ ({chosen_compat}) για το κλιματιστικό σου."
            all_recs.append(rc)
            used_materials.add(chosen['Material'])
            slot_notes[slot_num] = notes
            continue  # skip το γενικό scoring loop

        pool['Final_Score'] = 0.0
        caps = CLIMA_ACCESSORY_BUDGET[ptier]
        
        # --- Ειδικό Φιλτράρισμα για Μπαταρίες AAA ---
        if logic_key == 'BATTERY_AAA':
            aaa_mask = pool['Title'].str.contains('AAA', case=False, na=False)
            if aaa_mask.any(): pool = pool[aaa_mask]
        
        # --- Scoring Loop ---
        for idx, item in pool.iterrows():
            score = 0.0
            iprice = item['_p']
            
            # 1. Brand Match
            if str(item.get('Κατασκευαστής', '')).upper() == tb: score += 50000
            
            # 2. Budget Scaling
            current_cap = 9999
            hier_str = str(item['Hierarchy'])
            if 'Ανεμιστήρες' in hier_str: current_cap = caps['fan']
            elif 'Αφυγραντήρες' in hier_str: current_cap = caps['dehum']
            elif 'Καθαριστές' in hier_str: current_cap = caps['purifier']
            elif 'SURGE' in hier_str: current_cap = 45 # Default cap για πολύπριζα
            elif 'ΑΛΚΑΛΙΚΕΣ' in hier_str: current_cap = 15 # Default cap για μπαταρίες
            
            if iprice > current_cap: score -= 500000
            elif iprice >= (current_cap * 0.6): score += 30000
            
            # 3. Area Match (Μόνο για Air Treatment συσκευές)
            if any(x in hier_str for x in ['Αφυγραντήρες', 'Καθαριστές']):
                item_area_raw = str(item.get('Για χώρους έως', ''))
                a_match = re.search(r'(\d+)', item_area_raw)
                if a_match:
                    item_m2 = int(a_match.group(1))
                    if abs(item_m2 - t_area) <= 15: score += 40000
            
            pool.at[idx, 'Final_Score'] = score

        pool = pool.sort_values(['Final_Score', 'Sales_Tiebreaker'], ascending=[False, False])
        
        if not pool.empty:
            chosen = pool.iloc[0]
            rc = chosen.copy()
            rc['Assigned_Slot'] = slot_num
            rc['Slot_Role'] = role
            rc['Marketing_Copy'] = "Απαραίτητο συμπλήρωμα για τη νέα σου συσκευή."
            all_recs.append(rc)
            used_materials.add(chosen['Material'])
            slot_notes[slot_num] = notes

    return pd.DataFrame(all_recs), diag, slot_notes, pd.DataFrame(all_recs)


# ═══════════════════════════════════════════════════════════════
# 🟢 DEHUMIDIFIERS & IONIZERS — helpers (Air Treatment family)
# ═══════════════════════════════════════════════════════════════
# Self-contained helpers (brand is parsed from Title because the
# Κατασκευαστής column is empty on Καθαριστές Αέρα / Ιονιστές). Six pool
# builders feed a WM-style round-robin engine.

# Known multi-word brands in this family (first-token parsing would split them).
_DH_MULTIWORD_BRANDS = [
    'OLIMPIA SPLENDID', 'JURO-PRO', 'JURO PRO', 'PURE CLEAN', 'BERLINGER HAUS',
]
# Generic leading tokens that are NOT brands (defensive — title-first-token can
# occasionally start with a descriptor for weather gadgets / odd SKUs).
_DH_NON_BRAND_TOKENS = {
    'ΨΗΦΙΑΚΟ', 'ΨΗΦΙΑΚΟΣ', 'ΜΕΤΕΩΡΟΛΟΓΙΚΟΣ', 'ΘΕΡΜΟΜΕΤΡΟ', 'ΥΓΡΟΜΕΤΡΟ',
    'ΑΝΕΜΙΣΤΗΡΑΣ', 'ΑΦΥΓΡΑΝΤΗΡΑΣ', 'ΚΑΘΑΡΙΣΤΗΣ', 'ΙΟΝΙΣΤΗΣ', 'ΣΕΤ',
}


def _dh_parse_brand(title: str) -> str:
    """Uppercase brand from the Title. Handles multi-word brands and skips
    generic leading descriptors. Returns '' when no plausible brand is found."""
    t = str(title or '').strip()
    if not t:
        return ''
    up = t.upper()
    for m in _DH_MULTIWORD_BRANDS:
        if up.startswith(m):
            return m
    first = up.split()[0] if up.split() else ''
    # Strip stray punctuation
    first = first.strip('.,&/').strip()
    if not first or first in _DH_NON_BRAND_TOKENS:
        return ''
    return first


def _dh_price_tier(price: float) -> int:
    """0 = Entry (<€150), 1 = Mid (€150-350), 2 = Premium (>€350)."""
    try:
        p = float(price)
    except (TypeError, ValueError):
        return 0
    if p >= DH_TIER_THRESHOLDS['Premium']:
        return 2
    if p >= DH_TIER_THRESHOLDS['Mid']:
        return 1
    return 0


def _dh_is_combo(title: str) -> bool:
    """True when the device already bundles an ioniser / air purifier
    (e.g. a dehumidifier 'με Ιονιστή' / 'με Καθαριστή Αέρα')."""
    return bool(re.search(r'ιονιστ|καθαριστ|purif|ioniz', str(title or ''), re.I))


def _dh_trigger_type(hierarchy: str) -> str:
    """Classify the trigger: 'DEHUM' / 'PURIFIER' / 'IONIZER'."""
    h = str(hierarchy or '').strip().lower()
    if 'αφυγρα' in h:
        return 'DEHUM'
    if 'ιονιστ' in h:
        return 'IONIZER'
    return 'PURIFIER'  # 'Καθαριστές Αέρα'


def _dh_parse_water_tank(val) -> float:
    """Parse the 'Χωρητικότητα δοχείου νερού' bucket to a representative litre
    value. Handles '3.1 - 4 L' (→ 3.55 midpoint), '4.1 L και άνω' (→ 4.1),
    '2.1 - 3 Lt', '5 L', '8 L'. Returns 0.0 when unparseable."""
    s = str(val or '').replace('\xa0', ' ').strip().lower()
    if not s or s in ('nan', 'none'):
        return 0.0
    nums = re.findall(r'\d+(?:[.,]\d+)?', s)
    nums = [float(n.replace(',', '.')) for n in nums]
    if not nums:
        return 0.0
    if len(nums) >= 2:        # range → midpoint
        return (nums[0] + nums[1]) / 2.0
    return nums[0]            # single value / "X L και άνω"


def _dh_marketing(role_label: str, trigger_type: str, trigger_is_combo: bool) -> str:
    """Trigger-aware marketing copy for the two 'smart' slots; static copy
    elsewhere. Reframes the clean-air slot as an UPGRADE (not a duplicate)
    when the trigger is a combo dehumidifier, and as an ALTERNATIVE when the
    trigger is itself a purifier/ioniser."""
    if role_label == 'Καθαριστής Αέρα':
        if trigger_type in ('PURIFIER', 'IONIZER'):
            return "Δες κι άλλους καθαριστές αέρα — σύγκρινε ισχύ και κάλυψη χώρου."
        if trigger_is_combo:
            return "Αναβάθμισε σε αποκλειστικό καθαριστή αέρα — ισχυρότερος καθαρισμός με φίλτρο HEPA."
        return "Πρόσθεσε καθαρισμό αέρα — λιγότερη σκόνη, γύρη και αλλεργιογόνα."
    if role_label == 'Αφυγραντήρας':
        if trigger_type in ('PURIFIER', 'IONIZER'):
            return "Συμπλήρωσε με αφυγραντήρα — υγρασία υπό έλεγχο και καθαρός αέρας μαζί."
        return "Άλλη επιλογή αφυγραντήρα — διαφορετική χωρητικότητα δοχείου και κάλυψη χώρου."
    return DH_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")


# ── Pool builder: humidity monitor (slot 1) ───────────────────────────────
def _dh_build_hygrometer_pool(c_pool, notes):
    """WEATHER GADGETS filtered to thermometer/hygrometer titles (excludes
    full weather stations). Cheap high-attach monitor — ranked by in-stock then
    sales. The price ceiling is applied centrally via the budget table
    ('monitor' category) before this builder runs."""
    if c_pool.empty:
        return c_pool
    pool = c_pool.copy()
    title_l = pool['Title'].fillna('').astype(str)
    hygro_mask = title_l.str.contains(r'υγρ|υγρασ|θερμόμετρ|hygro', case=False, na=False)
    pool = pool[hygro_mask].copy()
    if pool.empty:
        notes.append("  ⚠ No hygrometer-type titles in WEATHER GADGETS")
        return pool
    notes.append(f"  Hygrometer pool: {len(pool)}")
    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += DH_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * DH_S_SALES_FACTOR
    return pool.sort_values('Final_Score', ascending=False)


def _dh_build_gadget_generic_pool(c_pool, notes):
    """WEATHER GADGETS that are NOT bare thermo/hygrometers — i.e. actual
    weather stations — so the 'Μετεωρολογικός Σταθμός' slot matches its label
    (the cheap hygrometers already lead at slot 1). Sales-ranked. If no true
    stations survive the budget cap, falls back to any remaining gadget so the
    slot can still be filled."""
    if c_pool.empty:
        return c_pool
    pool = c_pool.copy()
    title_l = pool['Title'].fillna('').astype(str)
    hygro_mask = title_l.str.contains(r'υγρ|υγρασ|θερμόμετρ|hygro', case=False, na=False)
    stations = pool[~hygro_mask].copy()
    if stations.empty:
        notes.append("  No dedicated weather stations after cap — using any gadget")
        stations = pool.copy()
    else:
        notes.append(f"  Weather-station pool: {len(stations)} (hygrometers excluded)")
    stations['Final_Score'] = 0.0
    if 'AVAILABILITY' in stations.columns:
        stations.loc[stations['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += DH_S_AVAILABILITY
    stations['Final_Score'] += stations['Sales_Tiebreaker'].fillna(0) * DH_S_SALES_FACTOR
    return stations.sort_values('Final_Score', ascending=False)


# ── Pool builder: clean-air sibling (slot 2) ───────────────────────────────
def _dh_build_clean_air_pool(c_pool, tbrand, ttier, trigger_type,
                              trigger_is_combo, tm, notes):
    """Καθαριστές Αέρα + Ιονιστές. Brand-affinity (title-parsed) + price-tier
    proximity + in-stock + sales. Combo-aware: for a combo-dehumidifier trigger
    the pool is steered toward DEDICATED purifiers that are a genuine upgrade
    (tier ≥ trigger) and away from bare ionisers (the trigger already ionises)."""
    if c_pool.empty:
        return c_pool
    pool = c_pool[c_pool['Material'] != tm].copy()
    if pool.empty:
        return pool
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += DH_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * DH_S_SALES_FACTOR

    # Brand affinity (parsed from Title — Κατασκευαστής is empty here)
    if tbrand:
        cand_brand = pool['Title'].fillna('').astype(str).apply(_dh_parse_brand)
        same_brand = cand_brand == tbrand
        pool.loc[same_brand, 'Final_Score'] += DH_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand affinity ({tbrand}): {int(same_brand.sum())} (+{DH_S_BRAND_MATCH:,})")

    # Price-tier proximity
    cand_tier = pool['_p'].apply(_dh_price_tier)
    same_t = cand_tier == ttier
    near_t = (cand_tier - ttier).abs() == 1
    pool.loc[same_t, 'Final_Score'] += DH_S_PRICE_SAME_TIER
    pool.loc[near_t, 'Final_Score'] += DH_S_PRICE_ONE_OFF

    # Combo-dehumidifier trigger → upgrade-steering
    if trigger_type == 'DEHUM' and trigger_is_combo:
        is_ionizer = pool['Hierarchy'].fillna('').astype(str).str.strip() == 'Ιονιστές'
        is_dedicated_upgrade = (~is_ionizer) & (cand_tier >= ttier)
        pool.loc[is_ionizer, 'Final_Score'] += DH_S_COMBO_REDUNDANT
        pool.loc[is_dedicated_upgrade, 'Final_Score'] += DH_S_PRICE_SAME_TIER
        notes.append(f"  ✓ Combo trigger → steer to dedicated purifier upgrade "
                     f"(demote {int(is_ionizer.sum())} ioniser(s), boost "
                     f"{int(is_dedicated_upgrade.sum())} upgrade(s))")

    return pool.sort_values('Final_Score', ascending=False)


# ── Pool builder: dehumidifier (slot 3) ────────────────────────────────────
def _dh_build_dehum_pool(c_pool, tbrand, ttier, t_tank, trigger_type, tm, notes):
    """Αφυγραντήρες. For a purifier/ioniser trigger this is the humidity-control
    COMPLEMENT (brand + price + sales). For a dehumidifier trigger it surfaces a
    comparable ALTERNATIVE (water-tank-proximity boost so it reads as a peer)."""
    if c_pool.empty:
        return c_pool
    pool = c_pool[c_pool['Material'] != tm].copy()
    if pool.empty:
        return pool
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += DH_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * DH_S_SALES_FACTOR

    # Brand affinity — dehumidifiers DO carry Κατασκευαστής, but parse Title too
    # for consistency (combo SKUs sometimes list a sub-brand in the title).
    if tbrand:
        col_brand = (pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
                     if 'Κατασκευαστής' in pool.columns else pd.Series('', index=pool.index))
        title_brand = pool['Title'].fillna('').astype(str).apply(_dh_parse_brand)
        same_brand = (col_brand == tbrand) | (title_brand == tbrand)
        pool.loc[same_brand, 'Final_Score'] += DH_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand affinity ({tbrand}): {int(same_brand.sum())} (+{DH_S_BRAND_MATCH:,})")

    # Price-tier proximity
    cand_tier = pool['_p'].apply(_dh_price_tier)
    same_t = cand_tier == ttier
    near_t = (cand_tier - ttier).abs() == 1
    pool.loc[same_t, 'Final_Score'] += DH_S_PRICE_SAME_TIER
    pool.loc[near_t, 'Final_Score'] += DH_S_PRICE_ONE_OFF

    # Water-tank proximity — only meaningful dehumidifier ↔ dehumidifier
    if trigger_type == 'DEHUM' and t_tank > 0 and 'Χωρητικότητα\xa0δοχείου\xa0νερού ≡' in pool.columns:
        cand_tank = pool['Χωρητικότητα\xa0δοχείου\xa0νερού ≡'].apply(_dh_parse_water_tank)
        near_tank = (cand_tank > 0) & ((cand_tank - t_tank).abs() <= 1.0)
        diff_tank = (cand_tank > 0) & ((cand_tank - t_tank).abs() > 1.0)
        pool.loc[near_tank, 'Final_Score'] += DH_S_TANK_NEAR
        pool.loc[diff_tank, 'Final_Score'] += DH_S_TANK_DIFF
        if near_tank.any():
            notes.append(f"  ✓ Water-tank proximity (trigger ≈{t_tank:.1f}L): "
                         f"{int(near_tank.sum())} comparable")

    return pool.sort_values('Final_Score', ascending=False)


# ── Pool builder: heating / generic companions (slots 4-8, 10) ─────────────
def _dh_build_companion_pool(c_pool, ttier, notes, role_label):
    """Generic companion scoring for heaters, blankets, fans, portable AC:
    in-stock + sales + a light price-tier proximity so the suggested scale
    matches the trigger (a €150 dehumidifier buyer isn't shown an €800 fan)."""
    if c_pool.empty:
        return c_pool
    pool = c_pool.copy()
    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += DH_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * DH_S_SALES_FACTOR
    cand_tier = pool['_p'].apply(_dh_price_tier)
    same_t = cand_tier == ttier
    near_t = (cand_tier - ttier).abs() == 1
    pool.loc[same_t, 'Final_Score'] += DH_S_PRICE_SAME_TIER
    pool.loc[near_t, 'Final_Score'] += DH_S_PRICE_ONE_OFF
    notes.append(f"  Companion pool ({role_label}): {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 DEHUMIDIFIERS & IONIZERS ENGINE — Αφυγραντήρες / Ιονιστές / Καθαριστές
# ═══════════════════════════════════════════════════════════════

def run_dehumidifier_engine(trigger, df_air, df_history):
    """Build exactly 10 cross-sell slots for an air-treatment trigger
    (Αφυγραντήρες / Ιονιστές / Καθαριστές Αέρα). All pools live in the Air sheet.

    Hybrid scoring (availability + sales + price-tier proximity, with brand
    affinity / combo-awareness / water-tank proximity layered on). The humidity
    monitor leads at slot 1. The comfort slots are SEASONAL — fans + portable AC
    in summer, heaters + electric blanket in winter (the air-treatment core is
    shown year-round). Per-tier budget caps drop price-inappropriate companions.
    Round-robin loop fills 10 slots, skipping empty pools and over-filling
    survivors so the carousel never under-fills — even for the tiny Ιονιστές
    trigger (3 SKUs)."""
    import datetime
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    thier = str(trigger.get('Hierarchy', ''))
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _dh_price_tier(tprice)
    tier_name = DH_TIER_NAMES[ttier]
    trigger_type = _dh_trigger_type(thier)
    trigger_is_combo = _dh_is_combo(tt)
    # Brand: dehumidifiers carry Κατασκευαστής; purifiers/ionisers don't → parse Title.
    # NB: an empty Κατασκευαστής arrives as a float NaN whose str() is 'nan'
    # (truthy), so normalise it to '' before falling back to the Title parser.
    _tb_col = str(trigger.get('Κατασκευαστής', '') or '').strip()
    if _tb_col.lower() in ('', 'nan', 'none'):
        _tb_col = ''
    tbrand = (_tb_col or _dh_parse_brand(tt)).upper().strip()
    t_tank = _dh_parse_water_tank(trigger.get('Χωρητικότητα\xa0δοχείου\xa0νερού ≡', ''))

    # ── Season → which comfort slots to show ──────────────────────────────
    if DH_SEASON_OVERRIDE in ('SUMMER', 'WINTER'):
        season = DH_SEASON_OVERRIDE
        season_src = 'override'
    else:
        season = 'SUMMER' if datetime.datetime.now().month in DH_SUMMER_MONTHS else 'WINTER'
        season_src = f"month={datetime.datetime.now().month}"
    priority = DH_SUMMER_PRIORITY if season == 'SUMMER' else DH_WINTER_PRIORITY

    diag.append(("0. Trigger",
                 f"{tbrand or '—'} €{tprice:.0f}",
                 f"type={trigger_type} | combo={trigger_is_combo} | "
                 f"tier={tier_name} | tank≈{t_tank:.1f}L"))
    diag.append(("0b. Season",
                 season,
                 f"({season_src}) → "
                 f"{'fans + portable AC' if season == 'SUMMER' else 'heaters + electric blanket'}, "
                 f"no {'heaters/blankets' if season == 'SUMMER' else 'fans/portable AC'}"))

    if df_air is None or df_air.empty:
        diag.append(("ERROR", 0, "Air sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # Base pool: everything in Air except the trigger itself.
    c = df_air[df_air['Material'] != tm].copy()
    c['Sales_Tiebreaker'] = pd.to_numeric(c.get('Sum of Sales', 0), errors='coerce').fillna(0)
    c['_p'] = pd.to_numeric(c.get('LIST PRICE', 0), errors='coerce').fillna(0)
    diag.append(("1. Base pool", len(c), "Air sheet minus trigger"))

    # ── Pre-build & score every pool ──────────────────────────────────────
    pools = {}  # rank → (role_label, scored_df, logic_key, max_r1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total, budget_cat in priority:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_set = {h.strip() for h in hiers}
        base_pool = c[c['Hierarchy'].fillna('').astype(str).str.strip().isin(hier_set)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        # ── Budget cap: drop price-inappropriate companions for this tier ──
        cap = DH_BUDGET.get(tier_name, {}).get(budget_cat)
        if cap is not None and not base_pool.empty:
            before = len(base_pool)
            base_pool = base_pool[base_pool['_p'] <= cap]
            notes.append(f"  Budget cap [{budget_cat} @ {tier_name}]: ≤€{cap} "
                         f"→ {len(base_pool)}/{before} survive")

        if base_pool.empty:
            notes.append("  ⚠ Pool empty (missing hierarchy or all over budget) "
                         "— slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        if logic_key == 'DH_HYGROMETER':
            scored = _dh_build_hygrometer_pool(base_pool, notes)
        elif logic_key == 'DH_GADGET_GENERIC':
            scored = _dh_build_gadget_generic_pool(base_pool, notes)
        elif logic_key == 'DH_CLEAN_AIR':
            scored = _dh_build_clean_air_pool(base_pool, tbrand, ttier, trigger_type,
                                              trigger_is_combo, tm, notes)
        elif logic_key == 'DH_DEHUM':
            scored = _dh_build_dehum_pool(base_pool, tbrand, ttier, t_tank,
                                          trigger_type, tm, notes)
        else:  # DH_HEATING / DH_SALES
            scored = _dh_build_companion_pool(base_pool, ttier, notes, role_label)

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})",
                     len(scored) if scored is not None else 0, logic_key))

    # ── Round-robin fill until 10 slots or all pools exhausted ────────────
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < DH_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= DH_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                    and slot_num < DH_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = _dh_marketing(role_label, trigger_type, trigger_is_combo)
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {float(row.get('Final_Score', 0)):,.0f} | "
                    f"{str(row.get('Title', ''))[:70]}"
                )
            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0 ─────────────────────────────────────
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / "
            f"{len(scored) if scored is not None else 0} from this pool{cap_note}")
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{DH_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═════════════════════════════════════════════════════════════
# 🟢 DESKTOPS ENGINE — Basic / Gaming / Professional / Apple
# ═════════════════════════════════════════════════════════════
# Persona-routed hybrid engine: persona detection picks the slot list,
# then per slot we score on brand-ecosystem + availability + tier-budget
# sweet-spot + sales tiebreaker, with monitor-specific Χρήση spec filter
# and forced Apple originals on the Apple-KB/Mouse/AirPods slots.
#
# Pattern mirrors run_laptops_engine() to keep the codebase consistent.

def run_desktops_engine(trigger, df_products, df_history):
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    tusage = str(trigger.get('Προτεινόμενη χρήση', ''))
    tos = str(trigger.get('Λειτουργικό σύστημα', ''))

    # 1. Persona routing — picks slot list (the BIG signal for desktops)
    persona = get_desktop_persona(trigger)
    persona_label = DESKTOP_PERSONA_NAMES[persona]
    slot_list = get_desktop_slot_list(persona)
    is_apple_persona = persona in ('apple', 'imac')  # both get Apple-ecosystem treatment
    is_gaming_persona = (persona == 'gaming')
    is_pro_persona   = (persona == 'professional')

    # 2. Tier (reuse laptop brackets)
    desktop_tier = get_desktop_tier(tprice)
    tier_names = {1: "Budget/Entry", 2: "Mid-Range", 3: "High-End/Pro", 4: "Extreme"}
    tier_label = tier_names.get(desktop_tier, "Sub-Entry")

    diag.append((
        "0. Trigger",
        f"Brand={tb}, €{tprice:.0f}, persona={persona_label}",
        f"Tier {desktop_tier} ({tier_label}), OS={tos[:40]}, Usage={tusage[:30]}"
    ))

    # 3. Build candidate pool — strip desktops + laptops + smartphones + appliances
    c = df_products[df_products['Material'] != tm].copy()

    b4 = len(c)
    c = c[~((c['Level 1'] == 'IT') & (c['Level 2'].isin(DESKTOP_L2_VALUES | LAPTOP_L2_VALUES)))]
    diag.append(("1. Excl desktops/laptops", len(c), f"Removed {b4 - len(c)}"))

    b4 = len(c)
    c = c[~((c['Level 2'] == 'Mobiles') & (c['Hierarchy'] == 'Smartphones'))]
    diag.append(("1b. Excl phones", len(c), f"Removed {b4 - len(c)}"))

    # Apple-ban for non-Apple personas (mirror laptops): AirPods / Magic Mouse
    # / Apple chargers shouldn't appear on a Windows desktop. Apple-persona
    # gets the FULL Apple catalog so the Magic KB/Mouse slots have stock.
    if not is_apple_persona:
        b4 = len(c)
        c = c[c['Κατασκευαστής'].fillna('').astype(str).str.strip().str.upper() != 'APPLE']
        diag.append(("1c. Apple ban", len(c), f"Removed {b4 - len(c)} Apple items (non-Apple persona)"))

    # Stock filter (same pattern as laptops — skip if <10% have stock)
    if 'CW Stock Units' in c.columns:
        stv = pd.to_numeric(c['CW Stock Units'], errors='coerce').fillna(0)
        pct = (stv > 0).sum() / len(c) if len(c) > 0 else 0
        if pct >= 0.10:
            c = c[stv > 0]
            diag.append(("2. Stock filter", len(c), f"Applied ({pct:.0%})"))
        else:
            diag.append(("2. Stock filter", len(c), f"⚠ SKIPPED ({pct:.0%})"))
    else:
        diag.append(("2. Stock filter", len(c), "⚠ SKIPPED (no col)"))

    # Macro wall — no appliances on a desktop setup
    b4 = len(c)
    if 'Level 1' in c.columns:
        c = c[~c['Level 1'].isin(APPL_CATS)]
    diag.append(("3. Macro wall", len(c), f"Removed {b4 - len(c)}"))

    # Sales tiebreaker
    if 'Sum of Sales' in c.columns:
        c['Sales_Tiebreaker'] = pd.to_numeric(c['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c['Sales_Tiebreaker'] = 0

    # 4. Iterate persona-specific slots
    used_materials = {tm}
    used_hierarchies_count = {}

    for slot_num, role, hierarchies, logic_key in slot_list:
        notes = [
            f"Persona: {persona}",
            f"Logic: {logic_key}",
            f"Target: {hierarchies}",
        ]

        # Per-slot pool (case-sensitive exact match on Hierarchy, just like laptops)
        pool = c[c['Hierarchy'].fillna('').astype(str).str.strip().isin(hierarchies)].copy()
        # Dedupe by Material — combined sheets often repeat the same SKU across files
        pool = pool.drop_duplicates(subset='Material', keep='first')
        pool = pool[~pool['Material'].isin(used_materials)]
        notes.append(f"Pool size: {len(pool)}")

        if pool.empty:
            notes.append("❌ Empty pool (hierarchy may not be in data yet)")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Empty"))
            continue

        # Price column
        pool['_p'] = pool['LIST PRICE'].apply(parse_euro_price)

        # ─── Initialise score and apply boosts ───
        pool['Final_Score'] = 0.0

        # Brand-ecosystem (same Κατασκευαστής as the desktop)
        if tb:
            same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.strip().str.upper() == tb
            pool.loc[same_brand, 'Final_Score'] += 400_000
            n_same = int(same_brand.sum())
            if n_same > 0:
                notes.append(f"Brand boost ({tb}): {n_same} items +400k")

        # Availability boost
        if 'AVAILABILITY' in pool.columns:
            avail = pool['AVAILABILITY'].fillna('').astype(str).str.contains('Άμεσα', na=False)
            pool.loc[avail, 'Final_Score'] += 100_000

        # Tier-budget sweet-spot
        bmin, bmax = get_desktop_accessory_budget(logic_key, desktop_tier)
        bucket = DESKTOP_LOGIC_TO_BUDGET.get(logic_key)
        in_range = (pool['_p'] >= bmin) & (pool['_p'] <= bmax)
        boost = 80_000 if bucket in DESKTOP_BUDGET_SOFT_SLOTS else 200_000
        pool.loc[in_range, 'Final_Score'] += boost
        notes.append(f"Budget €{bmin:.0f}-€{bmax:.0f}: {int(in_range.sum())} in range (+{boost//1000}k)")

        # ─── Monitor persona-specific Χρήση filter (the one deep spec match) ───
        if logic_key in ('DESKTOP_MONITOR_BASIC', 'DESKTOP_MONITOR_GAMING',
                          'DESKTOP_MONITOR_PRO', 'DESKTOP_MONITOR_APPLE'):
            if 'Χρήση' in pool.columns:
                use_str = pool['Χρήση'].fillna('').astype(str).str.lower()
                if logic_key == 'DESKTOP_MONITOR_GAMING':
                    mask = use_str.str.contains('gaming', na=False)
                    pool, fnote = filter_or_penalize(pool, mask, "Monitor: Χρήση=Gaming")
                    notes.append(fnote)
                elif logic_key == 'DESKTOP_MONITOR_BASIC':
                    mask = use_str.str.contains('mainstream|business', regex=True, na=False)
                    pool, fnote = filter_or_penalize(pool, mask, "Monitor: Χρήση=Mainstream/Business")
                    notes.append(fnote)
                elif logic_key == 'DESKTOP_MONITOR_PRO':
                    mask = use_str.str.contains('business', na=False)
                    pool, fnote = filter_or_penalize(pool, mask, "Monitor: Χρήση=Business")
                    notes.append(fnote)
                elif logic_key == 'DESKTOP_MONITOR_APPLE':
                    # Apple users tend toward color-accurate / premium displays;
                    # filter to Business/Mainstream (avoid gaming-only) and boost hi-res.
                    mask = use_str.str.contains('business|mainstream', regex=True, na=False)
                    pool, fnote = filter_or_penalize(pool, mask, "Monitor: Χρήση=Business/Mainstream (Apple)")
                    notes.append(fnote)
                    if 'Ανάλυση Οθόνης' in pool.columns:
                        res_str = pool['Ανάλυση Οθόνης'].fillna('').astype(str).str.lower()
                        hi_res = res_str.str.contains('4κ|5κ|quad', regex=True, na=False)
                        pool.loc[hi_res, 'Final_Score'] += 150_000
                        notes.append(f"Hi-res (QHD/4K/5K) Apple boost: {int(hi_res.sum())} items +150k")

        # ─── Force Apple originals on Apple persona Apple-branded slots ───
        if is_apple_persona and logic_key in ('DESKTOP_APPLE_KB', 'DESKTOP_APPLE_MOUSE', 'DESKTOP_APPLE_AUDIO'):
            apple_mask = pool['Κατασκευαστής'].fillna('').astype(str).str.strip().str.upper() == 'APPLE'
            pool, fnote = filter_or_penalize(pool, apple_mask, "Apple-only", penalty=1_000_000)
            notes.append(fnote)

        # ─── Gaming-persona reinforcement: same brand-house bias for peripherals ───
        # On a gaming rig we lightly prefer mainstream gaming peripheral brands
        # (Logitech / Razer / Corsair / SteelSeries / HyperX) when same-brand
        # doesn't apply (most gaming desktops are CORSAIR / MSI / generic).
        if is_gaming_persona and logic_key in ('DESKTOP_GAMING_KB', 'DESKTOP_GAMING_MOUSE',
                                                'DESKTOP_GAMING_AUDIO', 'DESKTOP_GAMING_PAD'):
            gaming_brands = {'LOGITECH', 'RAZER', 'CORSAIR', 'STEELSERIES', 'HYPERX',
                             'COOLER MASTER', 'ROCCAT', 'ASUS', 'MSI'}
            gb_mask = pool['Κατασκευαστής'].fillna('').astype(str).str.strip().str.upper().isin(gaming_brands)
            pool.loc[gb_mask, 'Final_Score'] += 50_000

        # Sales tiebreaker — modest weight so it never overrides ecosystem
        pool['Final_Score'] += pool['Sales_Tiebreaker'] * 0.5

        # Sort and pick top
        pool = pool.sort_values(['Final_Score', 'Sales_Tiebreaker'], ascending=[False, False])
        if pool.empty:
            notes.append("❌ Empty after scoring")
            slot_notes[slot_num] = notes
            diag.append((f"Slot {slot_num} ({role})", 0, "Empty"))
            continue

        chosen = pool.iloc[0]
        rc = chosen.copy()
        rc['Assigned_Slot'] = slot_num
        rc['Slot_Role'] = role
        rc['Marketing_Copy'] = DESKTOP_MARKETING_COPY.get(role, "Ιδανική επιλογή.")
        rc['Item_Rank'] = 1
        all_recs.append(rc)
        used_materials.add(chosen['Material'])
        used_hierarchies_count[chosen['Hierarchy']] = used_hierarchies_count.get(chosen['Hierarchy'], 0) + 1
        notes.append(f"✅ {str(chosen.get('Title',''))[:60]} — €{chosen['_p']:.0f}, score={chosen['Final_Score']:.0f}")
        slot_notes[slot_num] = notes
        diag.append((f"Slot {slot_num} ({role})", 1, f"Score: {chosen['Final_Score']:.0f}, €{chosen['_p']:.0f}"))

    diag.append(("TOTAL", len(all_recs), f"out of {len(slot_list)} (persona: {persona_label})"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 ROBOT VACUUMS ENGINE — Σκούπες Ρομπότ (Μικρές Συσκευές)
# ═══════════════════════════════════════════════════════════════
# Per user spec (non-negotiable):
#   • Accessories (Εξαρτήματα για σκούπες): STRICT match —
#       Για μάρκες ηλεκτρικής σκούπας == trigger.Κατασκευαστής
#       AND Συμβατό μοντέλο == trigger.Μοντέλο
#     Universal types (αρωματικά / πέρλες) allowed as fallback because
#     they genuinely work on any vacuum.
#   • Companion devices (Stick/Σκουπάκια/Ηλεκτρικές/Ατμοκαθαριστές):
#       sales-based, with brand boost (+50K same Κατασκευαστής as trigger)
#       and price-tier proximity (+40K same tier, +15K ±1 tier).
#   • PET CARE: sales-only, GATED on trigger.Κατάλληλη για κατοικίδια == Ναι.
#
# LOOPING: round-robin through priority list. Round 1 honors max_in_round_1
# (Εξαρτήματα can take up to 3); subsequent rounds take 1 per pool until
# ROBOT_VAC_SLOT_TARGET (10) is reached or all pools are exhausted.

def _rv_build_accessory_pool(c_acc, trigger_brand, trigger_model, notes):
    """Score the accessory pool. STRICT eligibility — per user spec:

        first spec of the accessories to match exactly the spec of the
        vacuum template:
          • Για μάρκες ηλεκτρικής σκούπας == Κατασκευαστής of the vacuum
          • AND Συμβατό μοντέλο == Model of the vacuum

    Anything that fails either condition is EXCLUDED — no aftermarket
    stick-vacuum accessories falsely labeled as Dyson-compatible robot
    accessories, no cross-brand specialty items.

    Universal types (αρωματικά sticks / πέρλες) survive as a soft fallback
    because they genuinely work on any vacuum brand/model. When the strict
    pool is empty and universal is too small, the round-robin loop will
    pull extra companion-device items into the slots instead.

    Returns sorted DataFrame ready for round-robin consumption."""
    if c_acc.empty:
        return c_acc

    pool = c_acc.copy()

    # ── STRICT MATCH: brand AND model both required ────────────────────
    brand_mask = pd.Series(False, index=pool.index)
    if trigger_brand:
        brand_col = 'Για μάρκες ηλεκτρικής σκούπας'
        if brand_col in pool.columns:
            brand_mask = pool[brand_col].fillna('').astype(str).str.upper().str.contains(
                re.escape(trigger_brand), regex=True, na=False
            )

    model_mask = pd.Series(False, index=pool.index)
    if trigger_model and trigger_model.lower() not in ('n/a', 'nan', '', '0'):
        tm_norm = trigger_model.upper().strip()
        # ROHNSON quirk: "RΜ-05" uses Greek Μ; data may use Latin M
        tm_alt = tm_norm.replace('Μ', 'M')
        for mcol in ['Συμβατό μοντέλο', 'Συμβατό μοντέλο.1']:
            if mcol in pool.columns:
                col_vals = pool[mcol].fillna('').astype(str).str.upper()
                col_alt = col_vals.str.replace('Μ', 'M', regex=False)
                model_mask |= col_vals.str.contains(re.escape(tm_norm), regex=True, na=False) | \
                              col_alt.str.contains(re.escape(tm_alt), regex=True, na=False)

    strict_mask = brand_mask & model_mask
    notes.append(f"  Brand pass: {brand_mask.sum()} | Model pass: {model_mask.sum()} "
                 f"| STRICT brand AND model: {strict_mask.sum()}")

    # ── UNIVERSAL fallback (always allowed — αρωματικά work on any vacuum)
    universal_mask = pd.Series(False, index=pool.index)
    if 'Τύπος συσκευής' in pool.columns:
        types_lower = pool['Τύπος συσκευής'].fillna('').astype(str).str.lower().str.strip()
        universal_mask = types_lower.isin(ROBOT_VAC_UNIVERSAL_TYPES)
        notes.append(f"  Universal types (αρωματικά/πέρλες): {universal_mask.sum()}")

    eligible = strict_mask | universal_mask
    pool = pool[eligible].copy()
    notes.append(f"  → After STRICT filter (strict_AND OR universal): {len(pool)} accessories")

    if pool.empty:
        notes.append(f"  ❌ Zero eligible accessories — loop will redirect slots to companion pools")
        return pool

    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY

    # ── Sales tiebreaker (small weight)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR

    # ── Tag the source mask back onto the surviving rows so we can score
    is_strict     = strict_mask.reindex(pool.index, fill_value=False)
    is_universal  = universal_mask.reindex(pool.index, fill_value=False)

    # Strict matches always score above universal fallbacks
    pool.loc[is_strict,    'Final_Score'] += RV_S_MODEL_EXACT
    pool.loc[is_universal, 'Final_Score'] += RV_S_UNIVERSAL_TYPE

    return pool.sort_values('Final_Score', ascending=False)


def _rv_build_companion_pool(c_pool, trigger_brand, trigger_tier,
                              is_pet, role_label, notes):
    """Score a companion-device pool with sales + brand boost + price tier."""
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY

    # ── Sales is the base signal
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR

    # ── Brand boost (ecosystem sell): Xiaomi trigger → Xiaomi stick first
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += RV_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand boost ({trigger_brand}): {same_brand.sum()} (+{RV_S_BRAND_MATCH:,})")

    # ── Price-tier proximity: prefer same tier, then ±1, no bonus for ±2+
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_robot_vac_price_tier)
        same_tier = tiers == trigger_tier
        near_tier = (tiers - trigger_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += RV_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += RV_S_PRICE_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Price-tier match (tier {trigger_tier}): "
                         f"same={same_tier.sum()}, near={near_tier.sum()}")

    # ── Pet-friendly bonus: if trigger is pet, prefer pet-friendly companions
    if is_pet and 'Κατάλληλη για κατοικίδια' in pool.columns:
        pet_mask = pool['Κατάλληλη για κατοικίδια'].fillna('').astype(str).str.lower().str.strip().isin(
            {'ναι', 'yes', 'true', '1'}
        )
        pool.loc[pet_mask, 'Final_Score'] += RV_S_PET_FLAG_BONUS
        if pet_mask.any():
            notes.append(f"  ✓ Pet-friendly companion bonus: {pet_mask.sum()}")

    return pool.sort_values('Final_Score', ascending=False)


def run_robot_vacuums_engine(trigger, df_floor, df_history):
    """Build up to 10 cross-sell slots for a robot vacuum trigger.

    Round-robin loop through Εξαρτήματα → Stick → Σκουπάκια → Ηλ. Σκούπες
    → Ατμοκαθαριστές → PET CARE (if pet). Round 1 lets Εξαρτήματα take up
    to 3; later rounds take 1 per pool until the slot target is hit."""
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _robot_vac_price_tier(tprice)

    is_pet = False
    if 'Κατάλληλη για κατοικίδια' in trigger.index:
        pet_val = str(trigger.get('Κατάλληλη για κατοικίδια', '')).lower().strip()
        is_pet = pet_val in ('ναι', 'yes', 'true', '1')

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Pet={is_pet}"))

    if df_floor is None or df_floor.empty:
        diag.append(("ERROR", 0, "Floor sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + any other robot vacuums (these are competitors)
    c = df_floor[df_floor['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in ROBOT_VAC_TRIGGER_HIERARCHIES}
    b4 = len(c)
    c = c[~c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl robot vacuums", len(c), f"Removed {b4 - len(c)} competitors"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c.columns:
        c['Sales_Tiebreaker'] = pd.to_numeric(c['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c['Sales_Tiebreaker'] = 0

    # ── Build a sorted pool per priority entry (in advance, so the loop is cheap)
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_round_1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total in ROBOT_VAC_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        # PET CARE gate: skip entirely for non-pet triggers
        if logic_key == 'PET_CARE' and not is_pet:
            notes.append("🚫 Trigger NOT pet-friendly → skipping PET CARE pool")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c[c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        # ── Drop stick-titled "handhelds" from the Σκουπάκι slot to prevent
        # visual duplication with the Σκούπα Stick slot. Some products in
        # Ηλεκτρικά Σκουπάκια are slim stick-style hybrids (e.g. SHARK WANDVAC)
        # whose title literally contains "Stick" — surfacing them next to a
        # real stick vacuum looks like two stick recommendations.
        if role_label == 'Σκουπάκι' and not base_pool.empty:
            before = len(base_pool)
            mask = ~base_pool['Title'].fillna('').astype(str).str.contains(
                r'stick', case=False, regex=True, na=False
            )
            base_pool = base_pool[mask]
            dropped = before - len(base_pool)
            if dropped > 0:
                notes.append(f"  ⚙ Dropped {dropped} stick-titled handheld(s) to avoid visual duplication with Σκούπα Stick slot")

        if base_pool.empty:
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Score the pool based on its logic key
        if logic_key == 'ACCESSORY_MATCH':
            scored = _rv_build_accessory_pool(base_pool, tb, tmodel, notes)
        elif logic_key == 'COMPANION':
            scored = _rv_build_companion_pool(base_pool, tb, ttier, is_pet, role_label, notes)
        elif logic_key == 'PET_CARE':
            # PET CARE: pure sales, no brand boost (pet brands don't overlap
            # with vacuum brands), no price tier (cat litter robots aren't
            # priced like robot vacuums)
            scored = base_pool.copy()
            scored['Final_Score'] = 0.0
            if 'AVAILABILITY' in scored.columns:
                scored.loc[scored['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY
            scored['Final_Score'] += scored['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR
            scored = scored.sort_values('Final_Score', ascending=False)
            notes.append(f"  ✓ PET CARE: sales-ranked, {len(scored)} candidates")
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}  # next index to consume per pool
    pool_taken    = {rank: 0 for rank in pools}  # count of items actually added (enforces max_total)
    slot_num = 0
    round_idx = 0

    while slot_num < ROBOT_VAC_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= ROBOT_VAC_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue

            # Hard cap: skip this pool if max_total already reached
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            # Round 1 allows the priority's max_round_1 items in a single pass
            # (Εξαρτήματα = 3). Rounds 2+ take 1 per pool.
            take_n = max_r1 if round_idx == 1 else 1
            # And never let take_n push past max_total
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < ROBOT_VAC_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = ROBOT_VAC_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                # Per-slot detailed note (using same slot_notes dict the UI reads)
                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Append pool diagnostics under slot 0 for inspection
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{ROBOT_VAC_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 TRADITIONAL VACUUMS ENGINE — Ηλεκτρικές Σκούπες (Μικρές Συσκευές)
# ═══════════════════════════════════════════════════════════════
# Same non-negotiable rules as Robot Vacuums:
#   • STRICT accessory match — Για μάρκες ηλεκτρικής σκούπας AND Συμβατό μοντέλο
#     both must match the trigger. Used for Σακούλες and Εξαρτήματα slots.
#   • UNIVERSAL αρωματικά / πέρλες in their own dedicated slot.
#   • Companions (Σκουπάκι/Stick/Robot/Ατμοκαθαριστής): sales + brand boost
#     + price-tier proximity. Σκούπες Stick and Σκούπες ρομπότ capped at 1
#     slot each.
#   • PET CARE gated on Κατάλληλη για κατοικίδια == Ναι.

def _tv_normalize_model(s):
    """Normalize a model/compat string for substring matching.

    Handles the real-world dirt that lives in this data:
      • Uppercase everything for case-insensitive compare.
      • Greek Μ (U+039C) → Latin M (the ROHNSON 'RΜ-05' / 'RM-05' case).
      • Strip ™ ® © symbols. The DYSON accessory compat strings carry
        'V11™' tokens which never match a trigger model 'V11 ADVANCED'
        until the ™ is removed.
      • Strip trailing TM after digits (e.g. 'V10TM' → 'V10').
      • Collapse multiple whitespace.
    """
    s = str(s).upper()
    s = s.replace('Μ', 'M')        # Greek Μ → Latin M
    s = re.sub(r'[™®©]', '', s)    # trademark / registered / copyright
    s = re.sub(r'(\d)TM\b', r'\1', s)  # 'V10TM' → 'V10'
    s = re.sub(r'\s+', ' ', s).strip()
    return s


def _tv_build_strict_accessory_pool(base, trigger_brand, trigger_model,
                                     exclude_universal_types, notes):
    """STRICT-match-only accessory pool for Σακούλες and Εξαρτήματα.

    Eligibility: Για μάρκες ηλεκτρικής σκούπας contains trigger.brand
                 AND Συμβατό μοντέλο matches trigger.model BIDIRECTIONALLY
                 (after normalization).

    The bidirectional match handles a real-world data quirk: bag/accessory
    compatibility strings often name a SERIES (e.g. "GUARD M1"), while
    vacuum.Μοντέλο may name a specific VARIANT (e.g. "GUARD M1 STANDARD
    FLEX"). A pure substring match in either direction misses one of the
    cases — bidirectional catches both:

        Direction A (forward):  trigger_model is substring of bag_compat
                                e.g. trigger "GUARD M1" ∈ bag "GUARD M1"          ✓
        Direction B (reverse):  any bag_compat token (≥3 chars, split on ; ,)
                                is substring of trigger_model
                                e.g. bag token "GUARD M1" ∈ trigger "GUARD M1 STANDARD FLEX"  ✓
                                e.g. bag token "V11" ∈ trigger "V11 ADVANCED"     ✓

    BOTH sides are passed through `_tv_normalize_model` first so that
    trademark symbols (™ ® ©), Greek Μ vs Latin M, trailing TM and
    duplicate whitespace don't block legitimate matches.

    The ≥3-char guard on tokens prevents short codes like "G" or "M1" from
    over-matching. The brand filter is the primary safety net — within a
    brand-matched pool, 3-char tokens are virtually always model identifiers
    (V11, V12, M15, etc.).

    Ideally vacuums would carry a `Τύπος Σακούλας` field saying which bag
    family they accept (e.g. BOSCH BGL8BA3S → "G ALL"), enabling
    Τύπος Σακούλας ↔ bag.Μοντέλο direct match. That field does not
    currently exist in the Floor sheet; this bidirectional substring is
    the next-best approach without data enrichment.

    Unlike the robot-vacuum accessory pool, there is NO universal fallback
    in this pool — universal αρωματικά live in their own dedicated slot
    (UNIVERSAL_AROMA). The `exclude_universal_types` flag is used by the
    Εξαρτήματα slot to drop αρωματικά so they don't appear twice."""
    if base.empty:
        return base

    pool = base.copy()

    # ── BRAND filter (Για μάρκες ηλεκτρικής σκούπας) ─────────────────
    brand_mask = pd.Series(False, index=pool.index)
    if trigger_brand and 'Για μάρκες ηλεκτρικής σκούπας' in pool.columns:
        brand_mask = pool['Για μάρκες ηλεκτρικής σκούπας'].fillna('').astype(str).str.upper().str.contains(
            re.escape(trigger_brand), regex=True, na=False
        )

    # ── BIDIRECTIONAL MODEL match (with normalization) ───────────────
    model_mask = pd.Series(False, index=pool.index)
    if trigger_model and trigger_model.lower() not in ('n/a', 'nan', '', '0'):
        tm_norm = _tv_normalize_model(trigger_model)

        # Forward direction: normalized trigger model is substring of normalized compat
        forward_mask = pd.Series(False, index=pool.index)
        for mcol in ['Συμβατό μοντέλο', 'Συμβατό μοντέλο.1']:
            if mcol in pool.columns:
                normalized = pool[mcol].apply(_tv_normalize_model)
                forward_mask |= normalized.str.contains(re.escape(tm_norm), regex=True, na=False)

        # Reverse direction: any normalized compat token (≥3 chars) is substring of trigger model
        # Split on , and ; to handle multi-model compat strings.
        def _reverse_match(compat_str):
            if not isinstance(compat_str, str) or not compat_str.strip():
                return False
            normalized = _tv_normalize_model(compat_str)
            for token in re.split(r'[;,]', normalized):
                t = token.strip()
                if len(t) >= 3 and t in tm_norm:
                    return True
            return False

        reverse_mask = pd.Series(False, index=pool.index)
        for mcol in ['Συμβατό μοντέλο', 'Συμβατό μοντέλο.1']:
            if mcol in pool.columns:
                reverse_mask |= pool[mcol].apply(_reverse_match)

        model_mask = forward_mask | reverse_mask
        notes.append(f"  Forward (model ⊆ compat): {forward_mask.sum()} "
                     f"| Reverse (compat token ⊆ model, ≥3 chars): {reverse_mask.sum()} "
                     f"| Combined model_mask: {model_mask.sum()}")

    strict_mask = brand_mask & model_mask
    notes.append(f"  Brand pass: {brand_mask.sum()} "
                 f"| STRICT brand AND model (bidirectional, normalized): {strict_mask.sum()}")

    # ── Drop universal αρωματικά from the Εξαρτήματα slot
    if exclude_universal_types and 'Τύπος συσκευής' in pool.columns:
        types_lower = pool['Τύπος συσκευής'].fillna('').astype(str).str.lower().str.strip()
        strict_mask &= ~types_lower.isin(ROBOT_VAC_UNIVERSAL_TYPES)
        notes.append(f"  After dropping universal αρωματικά: {strict_mask.sum()}")

    pool = pool[strict_mask].copy()
    notes.append(f"  → Final strict pool: {len(pool)}")

    if pool.empty:
        notes.append(f"  ❌ Zero strict-match accessories — loop will redirect to companions")
        notes.append(f"  💡 If the vacuum carries a `Τύπος Σακούλας` field listing the bag-family")
        notes.append(f"     designation (e.g. 'G ALL' for BOSCH), wire it to bag.Μοντέλο for a")
        notes.append(f"     stronger Tier-1 match — currently that field is missing from the data.")
        return pool

    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR
    pool['Final_Score'] += RV_S_MODEL_EXACT  # all rows here are strict matches

    return pool.sort_values('Final_Score', ascending=False)


def _tv_build_universal_aroma_pool(base, notes):
    """Pull only universal αρωματικά (sticks + πέρλες) from Εξαρτήματα.
    These work on any vacuum brand, no compatibility check needed."""
    if base.empty:
        return base
    pool = base.copy()
    if 'Τύπος συσκευής' not in pool.columns:
        notes.append("  ❌ No Τύπος συσκευής column — cannot identify αρωματικά")
        return pd.DataFrame()

    types_lower = pool['Τύπος συσκευής'].fillna('').astype(str).str.lower().str.strip()
    mask = types_lower.isin(ROBOT_VAC_UNIVERSAL_TYPES)
    pool = pool[mask].copy()
    notes.append(f"  Universal αρωματικά/πέρλες available: {len(pool)}")

    if pool.empty:
        return pool

    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR
    pool['Final_Score'] += RV_S_UNIVERSAL_TYPE
    return pool.sort_values('Final_Score', ascending=False)


def run_traditional_vacuums_engine(trigger, df_floor, df_history):
    """Build up to 10 cross-sell slots for a traditional vacuum trigger.

    Priority order follows the user spec:
      1. Σακούλες (strict brand+model)        2. Αρωματικά (universal)
      3. Σκουπάκι (companion)                  4. Σκούπα Stick (companion, cap=1)
      5. Εξαρτήματα (strict brand+model)       6. Σκούπα Ρομπότ (companion, cap=1)
      7. Ατμοκαθαριστής (companion)            8. PET CARE (sales, pet-gated)

    Round-robin loop: round 1 honors max_in_round_1 (Σακούλες & Εξαρτήματα
    each up to 2); subsequent rounds take 1 per pool until target hit."""
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _robot_vac_price_tier(tprice)

    is_pet = False
    if 'Κατάλληλη για κατοικίδια' in trigger.index:
        pet_val = str(trigger.get('Κατάλληλη για κατοικίδια', '')).lower().strip()
        is_pet = pet_val in ('ναι', 'yes', 'true', '1')

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Pet={is_pet}"))

    if df_floor is None or df_floor.empty:
        diag.append(("ERROR", 0, "Floor sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger + other traditional vacuums (these are competitors)
    c = df_floor[df_floor['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in TRAD_VAC_TRIGGER_HIERARCHIES}
    b4 = len(c)
    c = c[~c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl traditional vacuums", len(c), f"Removed {b4 - len(c)} competitors"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c.columns:
        c['Sales_Tiebreaker'] = pd.to_numeric(c['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c['Sales_Tiebreaker'] = 0

    # ── Build a sorted pool per priority entry
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_r1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total in TRAD_VAC_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        # PET CARE gate
        if logic_key == 'PET_CARE' and not is_pet:
            notes.append("🚫 Trigger NOT pet-friendly → skipping PET CARE pool")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c[c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        # ── Drop stick-titled "handhelds" from the Σκουπάκι slot to prevent
        # visual duplication with the Σκούπα Stick slot. Some products in
        # Ηλεκτρικά Σκουπάκια are slim stick-style hybrids (e.g. SHARK WANDVAC)
        # whose title literally contains "Stick" — surfacing them next to a
        # real stick vacuum looks like two stick recommendations.
        if role_label == 'Σκουπάκι' and not base_pool.empty:
            before = len(base_pool)
            mask = ~base_pool['Title'].fillna('').astype(str).str.contains(
                r'stick', case=False, regex=True, na=False
            )
            base_pool = base_pool[mask]
            dropped = before - len(base_pool)
            if dropped > 0:
                notes.append(f"  ⚙ Dropped {dropped} stick-titled handheld(s) to avoid visual duplication with Σκούπα Stick slot")

        if base_pool.empty:
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Score the pool based on its logic key
        if logic_key == 'STRICT_ACCESSORY':
            # Εξαρτήματα slot must exclude universal types (those have their own slot);
            # Σακούλες doesn't have universal types so the flag is harmless either way.
            exclude_univ = (role_label == 'Εξαρτήματα')
            scored = _tv_build_strict_accessory_pool(base_pool, tb, tmodel, exclude_univ, notes)
        elif logic_key == 'UNIVERSAL_AROMA':
            scored = _tv_build_universal_aroma_pool(base_pool, notes)
        elif logic_key == 'COMPANION':
            scored = _rv_build_companion_pool(base_pool, tb, ttier, is_pet, role_label, notes)
        elif logic_key == 'PET_CARE':
            scored = base_pool.copy()
            scored['Final_Score'] = 0.0
            if 'AVAILABILITY' in scored.columns:
                scored.loc[scored['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY
            scored['Final_Score'] += scored['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR
            scored = scored.sort_values('Final_Score', ascending=False)
            notes.append(f"  ✓ PET CARE: sales-ranked, {len(scored)} candidates")
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored) if scored is not None else 0, logic_key))

    # ── LOOPING: round-robin with max_total enforcement
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < TRAD_VAC_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= TRAD_VAC_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < TRAD_VAC_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = TRAD_VAC_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Append pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{TRAD_VAC_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 STICK VACUUMS ENGINE — Σκούπες Stick (Μικρές Συσκευές)
# ═══════════════════════════════════════════════════════════════
# Same non-negotiable rules as the other two vacuum engines:
#   • STRICT brand+model accessory match (bidirectional substring on Συμβατό
#     μοντέλο) for Εξαρτήματα and Σακούλες.
#   • Universal αρωματικά / πέρλες in their own dedicated slot (last priority).
#   • Companions: sales + brand boost + price-tier proximity.
#   • Σκουπάκι slot drops stick-titled handhelds (e.g. SHARK WANDVAC) so we
#     don't show a stick-shaped handheld next to an actual stick.
#   • Σκούπες ρομπότ and Ηλεκτρικές Σκούπες capped at 1 (premium / alt-form).
#   • PET CARE gated on Κατάλληλη για κατοικίδια == Ναι.
#
# All three vacuum engines share the same helper functions
# (_tv_build_strict_accessory_pool, _tv_build_universal_aroma_pool,
#  _rv_build_companion_pool) — only the priority config differs.

def run_stick_vacuums_engine(trigger, df_floor, df_history):
    """Build up to 10 cross-sell slots for a stick-vacuum trigger.

    Priority order follows the user spec:
      1. Εξαρτήματα (strict brand+model)   2. Σκούπες ρομπότ (companion, cap 1)
      3. Σακούλες (strict brand+model)      4. Ηλεκτρικές Σκούπες (companion, cap 1)
      5. Σκουπάκι (companion)               6. Ατμοκαθαριστές (companion)
      7. PET CARE (sales, pet-gated)        8. Αρωματικά (universal)

    Round-robin loop: round 1 honors max_in_round_1 (Εξαρτήματα & Σακούλες
    each up to 2 → round 1 fits exactly 10 if all pools deliver); subsequent
    rounds take 1 per pool until target hit or pools exhausted."""
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _robot_vac_price_tier(tprice)

    is_pet = False
    if 'Κατάλληλη για κατοικίδια' in trigger.index:
        pet_val = str(trigger.get('Κατάλληλη για κατοικίδια', '')).lower().strip()
        is_pet = pet_val in ('ναι', 'yes', 'true', '1')

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Pet={is_pet}"))

    if df_floor is None or df_floor.empty:
        diag.append(("ERROR", 0, "Floor sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger + other stick vacuums (these are competitors)
    c = df_floor[df_floor['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in STICK_VAC_TRIGGER_HIERARCHIES}
    b4 = len(c)
    c = c[~c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl stick vacuums", len(c), f"Removed {b4 - len(c)} competitors"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c.columns:
        c['Sales_Tiebreaker'] = pd.to_numeric(c['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c['Sales_Tiebreaker'] = 0

    # ── Build a sorted pool per priority entry
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_r1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total in STICK_VAC_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        # PET CARE gate
        if logic_key == 'PET_CARE' and not is_pet:
            notes.append("🚫 Trigger NOT pet-friendly → skipping PET CARE pool")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c[c['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        # ── Drop stick-titled "handhelds" from the Σκουπάκι slot to prevent
        # visual duplication. (Stick vacuum buyers especially don't want to
        # see another stick-shaped product right next to the trigger family.)
        if role_label == 'Σκουπάκι' and not base_pool.empty:
            before = len(base_pool)
            mask = ~base_pool['Title'].fillna('').astype(str).str.contains(
                r'stick', case=False, regex=True, na=False
            )
            base_pool = base_pool[mask]
            dropped = before - len(base_pool)
            if dropped > 0:
                notes.append(f"  ⚙ Dropped {dropped} stick-titled handheld(s)")

        if base_pool.empty:
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Score the pool based on its logic key (helpers shared with TV engine)
        if logic_key == 'STRICT_ACCESSORY':
            # Εξαρτήματα slot must exclude universal types (those have their own slot)
            exclude_univ = (role_label == 'Εξαρτήματα')
            scored = _tv_build_strict_accessory_pool(base_pool, tb, tmodel, exclude_univ, notes)
        elif logic_key == 'UNIVERSAL_AROMA':
            scored = _tv_build_universal_aroma_pool(base_pool, notes)
        elif logic_key == 'COMPANION':
            scored = _rv_build_companion_pool(base_pool, tb, ttier, is_pet, role_label, notes)
        elif logic_key == 'PET_CARE':
            scored = base_pool.copy()
            scored['Final_Score'] = 0.0
            if 'AVAILABILITY' in scored.columns:
                scored.loc[scored['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += RV_S_AVAILABILITY
            scored['Final_Score'] += scored['Sales_Tiebreaker'].fillna(0) * RV_S_SALES_FACTOR
            scored = scored.sort_values('Final_Score', ascending=False)
            notes.append(f"  ✓ PET CARE: sales-ranked, {len(scored)} candidates")
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored) if scored is not None else 0, logic_key))

    # ── LOOPING: round-robin with max_total enforcement
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < STICK_VAC_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= STICK_VAC_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < STICK_VAC_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = STICK_VAC_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{STICK_VAC_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 AIR FRYERS HELPERS — Φριτέζες (Small Kitchen Appliances)
# ═══════════════════════════════════════════════════════════════
# Three pool builders + one keyword-relevance helper. The engine itself
# follows the same looping pattern as Robot/Traditional/Stick Vacuums:
# pre-build & score every pool, then round-robin fill until 10 slots filled
# or all pools exhausted.

def _af_is_relevant_accessory(title: str, desc: str = '') -> bool:
    """Tier A: title or description contains an air-fryer-relevant keyword."""
    blob = f"{title or ''} {desc or ''}".lower()
    return any(kw in blob for kw in AIR_FRYER_ACCESSORY_RELEVANCE_KW)


def _af_build_accessory_pool(c_acc, trigger_brand, trigger_subtype, notes):
    """Score the Αξεσουάρ Συσκευών Μαγειρικής pool with multiple tiers:

    Tier A — Title/desc mentions φριτέζα/αέρος/etc.    →  +1,500,000
    Tier B — Same brand as trigger (ecosystem)         →  +400,000
    Tier B' — Brand-prefix MISMATCH (different brand's SKU code in title,
              e.g. 'ROHNSON AF01D' shown to a NINJA fryer — physically
              sized for ROHNSON's basket)              →  -400,000
    Tier B'' — Universal item (no brand prefix in title, fits any basket)
                                                       →  +150,000
    Tier C — Pure sales fallback (base score only)

    Plus subtype nudge: oil-fryer accessories prefer OIL/BOTH triggers, AIR-only
    accessories prefer AIR/BOTH triggers (small +60k).

    Tags each row with `_af_type` for downstream diversity-cap enforcement.
    """
    if c_acc.empty:
        return c_acc

    pool = c_acc.copy()
    pool['Final_Score'] = 0.0

    # ── Type tagging (used later by the loop's diversity guard)
    pool['_af_type'] = pool['Title'].fillna('').astype(str).apply(_af_classify_accessory_type)

    # ── Brand-prefix detection per row
    pool['_af_brand_prefix'] = pool['Title'].fillna('').astype(str).apply(_af_extract_brand_prefix)

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AF_S_AVAILABILITY

    # ── Base sales score
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * AF_S_SALES_FACTOR

    # ── Tier A: keyword relevance
    title_col = pool['Title'].fillna('').astype(str)
    desc_col = pool['Περιγραφή προϊόντος'].fillna('').astype(str) if 'Περιγραφή προϊόντος' in pool.columns else pd.Series([''] * len(pool), index=pool.index)
    rel_mask = pd.Series([_af_is_relevant_accessory(t, d) for t, d in zip(title_col, desc_col)], index=pool.index)
    pool.loc[rel_mask, 'Final_Score'] += AF_S_ACCESSORY_RELEVANT
    if rel_mask.any():
        notes.append(f"  ✓ Tier A — air-fryer-relevant accessories: {rel_mask.sum()} (+{AF_S_ACCESSORY_RELEVANT:,})")

    # ── Tier A.1: subtype-specific nudge
    if trigger_subtype in ('AIR', 'BOTH') and rel_mask.any():
        air_kw_mask = title_col.str.lower().str.contains('αέρος|αερος|αέρα|air fry|airfry|hot air|καλάθ|σχάρα|σχαρα|parchment|περγαμ', regex=True, na=False) | \
                       desc_col.str.lower().str.contains('αέρος|αερος|αέρα|air fry|airfry|hot air|καλάθ|σχάρα|σχαρα', regex=True, na=False)
        pool.loc[air_kw_mask, 'Final_Score'] += AF_S_SUBTYPE_MATCH
        if air_kw_mask.any():
            notes.append(f"  ✓ Subtype nudge ({trigger_subtype}): {air_kw_mask.sum()} air-style accessories (+{AF_S_SUBTYPE_MATCH:,})")
    if trigger_subtype in ('OIL', 'BOTH') and rel_mask.any():
        oil_kw_mask = title_col.str.lower().str.contains('λαδιού|λαδιου|λάδι', regex=True, na=False) | \
                       desc_col.str.lower().str.contains('λαδιού|λαδιου|λάδι', regex=True, na=False)
        pool.loc[oil_kw_mask, 'Final_Score'] += AF_S_SUBTYPE_MATCH
        if oil_kw_mask.any():
            notes.append(f"  ✓ Subtype nudge ({trigger_subtype}): {oil_kw_mask.sum()} oil-style accessories (+{AF_S_SUBTYPE_MATCH:,})")

    # ── Tier B: same-brand boost (ecosystem cross-sell)
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += AF_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Tier B — brand match ({trigger_brand}): {same_brand.sum()} (+{AF_S_BRAND_MATCH:,})")

    # ── Tier B': brand-prefix MISMATCH penalty (cross-brand SKU)
    # Item title starts with "<BRAND> <SKU>" where <BRAND> ≠ trigger brand
    # → physically sized for that brand's basket, won't fit the trigger.
    if trigger_brand:
        mismatch_mask = (pool['_af_brand_prefix'] != '') & (pool['_af_brand_prefix'] != trigger_brand)
    else:
        # No trigger brand → anything brand-coded is suspect (penalize all
        # brand-prefixed items so universal items rise to the top)
        mismatch_mask = pool['_af_brand_prefix'] != ''
    pool.loc[mismatch_mask, 'Final_Score'] += AF_S_BRAND_PREFIX_MISMATCH
    if mismatch_mask.any():
        notes.append(f"  ✗ Tier B' — brand-prefix MISMATCH penalty: {mismatch_mask.sum()} cross-brand SKU items ({AF_S_BRAND_PREFIX_MISMATCH:+,})")

    # ── Tier B'': universal boost — no brand prefix in title, fits any basket
    universal_mask = pool['_af_brand_prefix'] == ''
    pool.loc[universal_mask & rel_mask, 'Final_Score'] += AF_S_UNIVERSAL_BOOST
    if (universal_mask & rel_mask).any():
        notes.append(f"  ✓ Tier B'' — universal-fitment boost: {(universal_mask & rel_mask).sum()} items (+{AF_S_UNIVERSAL_BOOST:,})")

    notes.append(f"  Pool size after scoring: {len(pool)}")

    return pool.sort_values('Final_Score', ascending=False)


def _af_build_companion_pool(c_pool, trigger_brand, trigger_tier, trigger_rating,
                              role_label, notes):
    """Score a companion-appliance pool (Τοστιέρες, Βραστήρες, Σίδερα, Πολυκόπτης).

    Mix of sales + brand-ecosystem boost + price-tier proximity + expert
    rating mirror. Mirrors the _rv_build_companion_pool signature.
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AF_S_AVAILABILITY

    # ── Base sales signal
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * AF_S_SALES_FACTOR

    # ── Brand-ecosystem boost (e.g. IZZY fryer → IZZY toaster)
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += AF_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}): {same_brand.sum()} (+{AF_S_BRAND_MATCH:,})")

    # ── Price-tier proximity
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_af_price_tier)
        same_tier = tiers == trigger_tier
        near_tier = (tiers - trigger_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += AF_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += AF_S_PRICE_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Price-tier match (tier {trigger_tier}): "
                         f"same={same_tier.sum()}, near={near_tier.sum()}")

    # ── Quality mirror — keep recommendations at the trigger's quality level.
    # "Best Value" trigger should not surface "Economy" companions; "Top
    # Quality" trigger gets "Top Quality" / "Excellent" companions boosted.
    rating_col = None
    for cand in ('Experts Rating ≡', 'Experts Rating', 'Experts rating'):
        if cand in pool.columns:
            rating_col = cand
            break
    if rating_col and trigger_rating:
        rating_clean = pool[rating_col].fillna('').astype(str).str.strip()
        if trigger_rating in ('Top Quality', 'Excellent'):
            top_mask = rating_clean.isin(['Top Quality', 'Excellent'])
            pool.loc[top_mask, 'Final_Score'] += AF_S_RATING_TOP
            if top_mask.any():
                notes.append(f"  ✓ Quality mirror (trigger={trigger_rating}): {top_mask.sum()} Top/Excellent companions (+{AF_S_RATING_TOP:,})")
        elif trigger_rating == 'Best Value':
            bv_mask = rating_clean.isin(['Best Value', 'Excellent', 'Top Quality'])
            pool.loc[bv_mask, 'Final_Score'] += AF_S_RATING_BEST_VALUE
            if bv_mask.any():
                notes.append(f"  ✓ Quality mirror (trigger=Best Value): {bv_mask.sum()} Best Value+ (+{AF_S_RATING_BEST_VALUE:,})")
        # Economy triggers get no rating boost — let sales decide

    return pool.sort_values('Final_Score', ascending=False)


def _af_build_microwave_pool(c_pool, trigger_tier, trigger_brand, notes):
    """Score the MDA Φούρνοι Μικροκυμάτων pool.

    Microwave brands (SAMSUNG, LG, ELECTROLUX, SINGER, INVENTOR, MIDEA) do
    NOT overlap with the major fryer brands (IZZY, NINJA, ROHNSON, TEFAL)
    — so the brand boost rarely fires here. Falls back to price-tier +
    sales. If, against expectations, the trigger brand IS present (e.g.
    SAMSUNG, LG, IQ, IZZY), the brand boost applies.
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += AF_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * AF_S_SALES_FACTOR

    # Same-brand boost (rare but valuable when it fires — e.g. SAMSUNG fryer
    # ↔ SAMSUNG microwave, IZZY ↔ IZZY, etc.)
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += AF_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Microwave brand match ({trigger_brand}): {same_brand.sum()}")

    # Price-tier proximity matters more here — a €450 microwave next to a €100 fryer looks wrong
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_af_price_tier)
        same_tier = tiers == trigger_tier
        near_tier = (tiers - trigger_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += AF_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += AF_S_PRICE_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Microwave price-tier match: same={same_tier.sum()}, near={near_tier.sum()}")

    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 AIR FRYERS ENGINE — Φριτέζες (Small Kitchen Appliances)
# ═══════════════════════════════════════════════════════════════

def run_air_fryer_engine(trigger, df_sda, df_mda, df_history):
    """Build up to 10 cross-sell slots for an air-fryer trigger.

    Round-robin loop through Αξεσουάρ Συσκευών Μαγειρικής → Τοστιέρες →
    Βραστήρες → Σίδερα → Πολυκόπτης → Φούρνοι Μικροκυμάτων → Τηγάνια-Wok.
    Round 1 lets Αξεσουάρ take up to 2; later rounds take 1 per pool, with
    Αξεσουάρ capped at 4 total (per the user's slot layout).

    Pools with empty data (e.g. Πολυκόπτης, Τηγάνια-Wok before their data
    files are uploaded) are silently skipped and the loop over-fills other
    slots to keep the carousel at 10.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _af_price_tier(tprice)
    trating = str(trigger.get('Experts Rating ≡', '') or trigger.get('Experts Rating', '')).strip()
    tsubtype = _af_detect_subtype(trigger)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Rating={trating} | Subtype={tsubtype}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + any other fryers (these are competitors)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in AIR_FRYER_TRIGGER_HIERARCHIES}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl fryers", len(c_sda), f"Removed {b4 - len(c_sda)} competitor fryers"))

    # ── Prep MDA pool (for the microwave slot only)
    if df_mda is not None and not df_mda.empty:
        c_mda = df_mda.copy()
        diag.append(("1b. MDA pool", len(c_mda), "Loaded for Φούρνοι Μικροκυμάτων slot"))
    else:
        c_mda = pd.DataFrame()
        diag.append(("1b. MDA pool", 0, "MDA sheet empty — Microwave slot will be skipped"))

    # ── Sales tiebreaker prep (on both pools)
    for _df in (c_sda, c_mda):
        if not _df.empty:
            if 'Sum of Sales' in _df.columns:
                _df['Sales_Tiebreaker'] = pd.to_numeric(_df['Sum of Sales'], errors='coerce').fillna(0)
            else:
                _df['Sales_Tiebreaker'] = 0

    # ── Build a sorted pool per priority entry
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_round_1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total in AIR_FRYER_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper = {h.upper().strip() for h in hiers}

        # Pick the right base pool (SDA for everything except microwaves)
        if logic_key == 'COMPANION_MDA':
            source_pool = c_mda
        else:
            source_pool = c_sda

        if source_pool.empty:
            notes.append(f"  ⚠ Source sheet empty — skipping pool")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        base_pool = source_pool[source_pool['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            # ΠΟΛΥΚΟΠΤΗΣ / Τηγάνια-Wok currently land here. Graceful skip — the
            # looping engine will pull extra items from accessories/toasters/kettles
            # to keep the slot count at 10.
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Score the pool based on its logic key
        if logic_key == 'ACCESSORY_KITCHEN':
            scored = _af_build_accessory_pool(base_pool, tb, tsubtype, notes)
        elif logic_key in ('COMPANION_APPL', 'COMPANION_COOK'):
            scored = _af_build_companion_pool(base_pool, tb, ttier, trating, role_label, notes)
        elif logic_key == 'COMPANION_MDA':
            scored = _af_build_microwave_pool(base_pool, ttier, tb, notes)
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    # Type-diversity guard: track how many of each _af_type have been taken
    # from each accessory-style pool. Caps at AF_TYPE_DIVERSITY_CAP per type
    # so the carousel doesn't fill with 4 parchment papers in a row.
    pool_type_counts = {rank: {} for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < AIR_FRYER_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= AIR_FRYER_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue

            # Hard cap: skip this pool if max_total already reached
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            # Type-diversity applies only to accessory-style pools (multiple
            # items expected). Companion pools take 1 item total → no
            # diversity guard needed there.
            apply_type_diversity = (logic_key == 'ACCESSORY_KITCHEN')

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < AIR_FRYER_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                # Type-diversity guard for accessories
                if apply_type_diversity:
                    row_type = row.get('_af_type', 'other')
                    if pool_type_counts[rank].get(row_type, 0) >= AF_TYPE_DIVERSITY_CAP:
                        # Skip this candidate — too many of its type already taken
                        continue

                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = AIR_FRYER_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                if apply_type_diversity:
                    row_type = row.get('_af_type', 'other')
                    pool_type_counts[rank][row_type] = pool_type_counts[rank].get(row_type, 0) + 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                type_hint = f" | type={row.get('_af_type','')}" if apply_type_diversity else ""
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f}{type_hint} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{AIR_FRYER_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 COFFEE MACHINES HELPERS — Καφετιέρες (v28.44)
# ═══════════════════════════════════════════════════════════════
# Pool builders for the round-robin coffee engine. Config + subtype/
# classification helpers live in the COFFEE MACHINES CONFIGURATION block
# near the top of the file (they're needed at sidebar load time).
#
# Pools 1-4 are typed slices of Αξεσουάρ Καφέ (SDA); pools 5-6 come from
# the Spare sheet (Συσκευές Φραπέ / Ελληνικού Καφέ); pools 7-10 are SDA
# kitchen companions scored with the standard brand × price-tier × sales mix.

def _cm_prep_accessory_frame(df_sda):
    """Slice + dedup + type-tag the Αξεσουάρ Καφέ hierarchy once; every
    accessory pool is a type-filter over this frame. The SDA sheet carries
    duplicate rows per Material (price snapshots) — keep the first."""
    acc = df_sda[df_sda['Hierarchy'].fillna('').astype(str).str.strip() == 'Αξεσουάρ Καφέ'].copy()
    if acc.empty:
        return acc
    acc = acc.drop_duplicates(subset=['Material'])
    eidos = acc['Είδος'].fillna('').astype(str) if 'Είδος' in acc.columns else pd.Series([''] * len(acc), index=acc.index)
    kateg = acc['Κατηγορία'].fillna('').astype(str) if 'Κατηγορία' in acc.columns else pd.Series([''] * len(acc), index=acc.index)
    acc['_cm_type'] = [
        _cm_classify_coffee_acc(t, e, k)
        for t, e, k in zip(acc['Title'].fillna('').astype(str), eidos, kateg)
    ]
    # Stray machines filed under accessories are never recommendable here
    acc = acc[acc['_cm_type'] != 'machine']
    return acc


def _cm_base_score(pool):
    """Availability + sales — the common floor of every pool's score."""
    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += CM_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * CM_S_SALES_FACTOR
    return pool


def _cm_brand_layer(pool, trigger_brand, notes, label=''):
    """Soft same-brand ecosystem boost shared by all pools."""
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += CM_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand ecosystem {label}({trigger_brand}): {same_brand.sum()} (+{CM_S_BRAND_MATCH:,})")
    return pool


def _cm_build_frother_pool(acc, trigger_brand, notes):
    """Slot 1 — standalone milk frothers (Αφρογαλιέρα / Συσκευή για Αφρόγαλα).
    Brand boost + sales. ~16 SKUs, IZZY/ROHNSON dominate."""
    pool = acc[acc['_cm_type'] == 'frother'].copy()
    if pool.empty:
        notes.append("  ⚠ No frothers in Αξεσουάρ Καφέ")
        return pool
    pool = _cm_base_score(pool)
    pool.loc[:, 'Final_Score'] += CM_S_TYPE_RELEVANT
    pool = _cm_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


# Brands whose cleaners are machine-line-specific — showing them against a
# DIFFERENT trigger brand is misleading (BOSCH TASIMO cleaner on a DELONGHI).
# Generic chemistry houses (BELLA CUCINA, URNEX) are universal.
_CM_BRAND_SPECIFIC_CARE = {'BOSCH', 'SIEMENS', 'DELONGHI', 'JURA', 'KRUPS', 'PHILIPS', 'SAECO', 'SINGER'}

def _cm_build_care_pool(acc, trigger_brand, notes):
    """Slots 2-3 — descalers, cleaning sets, tablets, water filters.

    Water filters are MACHINE-SPECIFIC cartridges (SIEMENS TZ70003 only fits
    BSH bean-to-cup, SINGER SGR19400 is for SINGER's own line) — same logic
    as printer cartridges: HARD brand-family gate, never a soft penalty.
    Cleaning chemistry is softer:
      Tier A  same-brand consumable          → +CM_S_BRAND_MATCH
      Tier A' OTHER brand-specific consumable → CM_S_BRAND_SPECIFIC_MISMATCH
      Tier B  universal/generic consumable    → +CM_S_UNIVERSAL_BOOST
    The loop's per-type diversity cap (1 per type) plus the 3-way cleaner
    split (set/tablets/liquid) guarantees slots 2-3 hold two DIFFERENT
    cleaning forms.
    """
    pool = acc[acc['_cm_type'].isin(['cleaner', 'cleaner_set', 'cleaner_tabs', 'water_filter'])].copy()
    if pool.empty:
        notes.append("  ⚠ No cleaning/descaling items in Αξεσουάρ Καφέ")
        return pool

    brand_col = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()

    # ── HARD gate: water filters only within the trigger's brand family ──
    wf_mask = pool['_cm_type'] == 'water_filter'
    if wf_mask.any():
        fam = _cm_brand_family(trigger_brand)
        wf_drop = wf_mask & ~brand_col.isin(fam)
        if wf_drop.any():
            notes.append(f"  ✗ HARD-dropped {wf_drop.sum()} machine-specific water filters (brand family ≠ {trigger_brand or '—'})")
        pool = pool[~wf_drop]
        brand_col = brand_col[~wf_drop]
    if pool.empty:
        notes.append("  ⚠ Care pool empty after water-filter gating")
        return pool

    pool = _cm_base_score(pool)
    pool.loc[:, 'Final_Score'] += CM_S_TYPE_RELEVANT

    same_brand = brand_col.isin(_cm_brand_family(trigger_brand)) if trigger_brand else pd.Series(False, index=pool.index)
    other_specific = brand_col.isin(_CM_BRAND_SPECIFIC_CARE) & ~same_brand
    universal = ~brand_col.isin(_CM_BRAND_SPECIFIC_CARE)

    pool.loc[same_brand, 'Final_Score'] += CM_S_BRAND_MATCH
    pool.loc[other_specific, 'Final_Score'] += CM_S_BRAND_SPECIFIC_MISMATCH
    pool.loc[universal, 'Final_Score'] += CM_S_UNIVERSAL_BOOST
    if same_brand.any():
        notes.append(f"  ✓ Same-brand care ({trigger_brand}): {same_brand.sum()} (+{CM_S_BRAND_MATCH:,})")
    if other_specific.any():
        notes.append(f"  ✗ Other-brand-specific care penalized: {other_specific.sum()} ({CM_S_BRAND_SPECIFIC_MISMATCH:+,})")
    if universal.any():
        notes.append(f"  ✓ Universal care: {universal.sum()} (+{CM_S_UNIVERSAL_BOOST:,})")
    notes.append(f"  Pool size: {len(pool)} | care mix: {pool['_cm_type'].value_counts().to_dict()}")
    return pool.sort_values('Final_Score', ascending=False)


def _cm_build_grind_or_hold_pool(acc, subtype, capsule_system, takes_beans,
                                  trigger_brand, notes):
    """Slot 4 — subtype-dependent:

    CAPSULE  → capsule racks, system-matched: a Dolce Gusto rack physically
               can't hold Vertuo pods. Exact-system boost / mismatch penalty.
    ESPRESSO/FILTER without built-in grinder → coffee grinders (Μύλοι Άλεσης).
    Bean-to-cup (built-in grinder) → EMPTY pool; the redundant grinder slot
               is absorbed by EXTRAS where beans get CM_S_BEANS_FOR_GRINDER.
    """
    if subtype == 'CAPSULE':
        pool = acc[acc['_cm_type'] == 'capsule_holder'].copy()
        if pool.empty:
            notes.append("  ⚠ No capsule racks in Αξεσουάρ Καφέ")
            return pool
        # v28.45.2 — system compatibility is a HARD filter (strict filters
        # before scoring): a Dolce Gusto rack can't hold Nespresso pods, and
        # — user-confirmed — 'Nespresso'-labelled racks are ORIGINAL-sized;
        # Vertuo's dome pods do NOT fit them. Vertuo therefore keeps only
        # system-UNLABELLED (universal) racks until Vertuo-specific racks
        # reach the catalog.
        titles_norm = pool['Title'].fillna('').astype(str).map(_cm_norm)
        is_nes = titles_norm.str.contains('NESPRESSO', na=False)
        is_dg  = titles_norm.str.contains('DOLCE', na=False)
        is_universal = ~is_nes & ~is_dg
        if capsule_system == 'NESPRESSO ORIGINAL':
            drop_mask, match_mask = is_dg, is_nes
        elif capsule_system == 'DOLCE GUSTO':
            drop_mask, match_mask = is_nes, is_dg
        elif capsule_system == 'NESPRESSO VERTUO':
            drop_mask = is_nes | is_dg
            match_mask = pd.Series(False, index=pool.index)
        else:
            drop_mask = pd.Series(False, index=pool.index)
            match_mask = pd.Series(False, index=pool.index)
        if drop_mask.any():
            notes.append(f"  ✗ HARD-dropped {drop_mask.sum()} system-incompatible racks (system={capsule_system or '—'})")
        pool = pool[~drop_mask]
        match_mask = match_mask[~drop_mask]
        is_universal = is_universal[~drop_mask]
        if pool.empty:
            notes.append("  ⚠ No compatible racks for this capsule system — slot backfills")
            return pool
        pool = _cm_base_score(pool)
        pool.loc[:, 'Final_Score'] += CM_S_TYPE_RELEVANT
        pool.loc[match_mask, 'Final_Score'] += CM_S_SYSTEM_MATCH
        pool.loc[is_universal, 'Final_Score'] += CM_S_UNIVERSAL_BOOST
        if match_mask.any():
            notes.append(f"  ✓ System match {capsule_system}: {match_mask.sum()} racks (+{CM_S_SYSTEM_MATCH:,})")
        if is_universal.any():
            notes.append(f"  ✓ Universal (unlabelled) racks: {is_universal.sum()} (+{CM_S_UNIVERSAL_BOOST:,})")
        if capsule_system == 'NESPRESSO VERTUO':
            notes.append("  ℹ Vertuo → only universal racks eligible (Original-sized 'Nespresso' racks don't fit Vertuo pods)")
        notes.append(f"  Pool size: {len(pool)} (capsule racks)")
        return pool.sort_values('Final_Score', ascending=False)

    # ESPRESSO / FILTER → grinder, unless the machine grinds its own beans
    if takes_beans:
        notes.append("  ℹ Bean-to-cup trigger (built-in grinder) — grinder slot skipped, EXTRAS pool carries beans instead")
        return pd.DataFrame()
    pool = acc[acc['_cm_type'] == 'grinder'].copy()
    if pool.empty:
        notes.append("  ⚠ No grinders in Αξεσουάρ Καφέ")
        return pool
    pool = _cm_base_score(pool)
    pool.loc[:, 'Final_Score'] += CM_S_TYPE_RELEVANT
    pool = _cm_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)} (grinders)")
    return pool.sort_values('Final_Score', ascending=False)


def _cm_build_extras_pool(acc, subtype, capsule_system, takes_beans,
                           has_steam, trigger_brand, trigger_price, notes):
    """Slot 5 (+1 overflow) — pitcher / beans / storage / cup-warmer / capsules.

    v28.44.2 — usefulness GATES (drop, not just score) so a capsule buyer
    never sees dead-weight extras:
      • storage canister → only machines that take ground/beans (CAPSULE drops it)
      • pitcher          → only machines with a steam wand
      • beans            → only takes_beans (built-in grinder)
      • branded capsules → only same-brand trigger (machine-locked)
      • PRICE CAP        → an extra costing more than the machine itself is
        dropped (€219 JURA cup-warmer next to a €90 Inissia looks absurd).
    If the gates empty the pool, the slot backfills from care/companions —
    better an extra companion than a wrong accessory.
    """
    pool = acc[acc['_cm_type'].isin(['pitcher', 'beans', 'storage', 'cup_warmer', 'capsules'])].copy()
    if pool.empty:
        notes.append("  ⚠ No extras in Αξεσουάρ Καφέ")
        return pool

    # Branded capsules: keep only if their brand matches the trigger brand
    caps_mask = pool['_cm_type'] == 'capsules'
    if caps_mask.any():
        brand_col = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        drop_mask = caps_mask & (brand_col != trigger_brand)
        if drop_mask.any():
            notes.append(f"  ✗ Dropped {drop_mask.sum()} machine-locked capsule packs (brand ≠ {trigger_brand or '—'})")
        pool = pool[~drop_mask]

    # Storage canister: pointless for capsule machines (no loose coffee)
    if subtype == 'CAPSULE' and not pool.empty:
        st_mask = pool['_cm_type'] == 'storage'
        if st_mask.any():
            notes.append(f"  ✗ Dropped {st_mask.sum()} coffee-storage canisters (capsule machine — no loose coffee)")
        pool = pool[~st_mask]

    # Pitcher: pairs with a steam wand; useless without one
    if not has_steam and not pool.empty:
        p_mask = pool['_cm_type'] == 'pitcher'
        if p_mask.any():
            notes.append(f"  ✗ Dropped {p_mask.sum()} milk pitchers (no steam nozzle on trigger)")
        pool = pool[~p_mask]

    # Beans: dead weight on a machine that only takes ground/capsules
    if not takes_beans and not pool.empty:
        b_mask = pool['_cm_type'] == 'beans'
        pool = pool[~b_mask]

    # Price sanity: an "extra" priced above the machine itself is dropped
    if not pool.empty and trigger_price and trigger_price > 0 and 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        over_mask = prices > trigger_price
        if over_mask.any():
            notes.append(f"  ✗ Dropped {over_mask.sum()} extras priced above the trigger (€{trigger_price:.0f})")
        pool = pool[~over_mask]

    if pool.empty:
        notes.append("  ⚠ Extras pool empty after usefulness gating — slot backfills from care/companions")
        return pool

    pool = _cm_base_score(pool)
    if takes_beans:
        beans = pool['_cm_type'] == 'beans'
        pool.loc[beans, 'Final_Score'] += CM_S_BEANS_FOR_GRINDER
        if beans.any():
            notes.append(f"  ✓ Bean-to-cup trigger → Κόκκοι Καφέ boost: {beans.sum()} (+{CM_S_BEANS_FOR_GRINDER:,})")
    if has_steam:
        pitcher = pool['_cm_type'] == 'pitcher'
        pool.loc[pitcher, 'Final_Score'] += CM_S_PITCHER_FOR_STEAM
        if pitcher.any():
            notes.append(f"  ✓ Steam nozzle → Γαλατιέρα boost: {pitcher.sum()} (+{CM_S_PITCHER_FOR_STEAM:,})")
    pool = _cm_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)} | extras mix: {pool['_cm_type'].value_counts().to_dict()}")
    return pool.sort_values('Final_Score', ascending=False)


def _cm_build_companion_pool(c_pool, trigger_brand, trigger_tier, notes, apply_tier=True):
    """Slots 6-10 — companion appliances. No compatibility constraint →
    sales × brand-ecosystem × price-tier, same recipe as the AF engine.

    apply_tier=False for IMPULSE companions (Φραπέ, Μπρίκι): these are €25-45
    add-ons people buy regardless of machine price — tier mirroring there
    pushed a €299 OKKA over the €35 IZZY bestseller next to a €178 Dedica
    (v28.44.2). Big-ticket companions (toaster/kettle/waffle) keep the tier
    mirror so a SMEG filter machine still pulls the SMEG line.
    """
    if c_pool.empty:
        return c_pool
    pool = c_pool.copy()
    pool = _cm_base_score(pool)
    pool = _cm_brand_layer(pool, trigger_brand, notes)
    if apply_tier and 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_cm_price_tier)
        same_tier = tiers == trigger_tier
        near_tier = (tiers - trigger_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += CM_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += CM_S_PRICE_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Price-tier match (tier {trigger_tier}): same={same_tier.sum()}, near={near_tier.sum()}")
    elif not apply_tier:
        notes.append("  ℹ Impulse companion — tier mirroring OFF (sales + brand + availability decide)")
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 COFFEE MACHINES ENGINE — Καφετιέρες (v28.44)
# ═══════════════════════════════════════════════════════════════

def run_coffee_machine_engine(trigger, df_sda, df_spare, df_history):
    """Build up to 10 cross-sell slots for a coffee-machine trigger.

    Round-robin loop through Αφρόγαλα → Καθαρισμός (×2, type-diverse) →
    Μύλος/Θήκη Καψουλών (subtype-routed) → Extras → Φραπέ → Μπρίκι →
    Βάφλα/Κρέπα → Φρυγανιέρα, with Βραστήρες → Τοστιέρες → accessory
    overflow as the backfill chain that guarantees 10/10 filled slots.

    Data sources: Αξεσουάρ Καφέ + kitchen companions from SDA; Συσκευές
    Φραπέ + Συσκευές Ελληνικού Καφέ from the Spare sheet (same Level 2 as
    the trigger machines — only the 3 trigger hierarchies are excluded as
    competitors).
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _cm_price_tier(tprice)
    tsubtype = _cm_detect_subtype(trigger)
    tsystem = _cm_capsule_system(trigger)
    t_beans = _cm_takes_beans(trigger)
    t_steam = _cm_has_steam_nozzle(trigger)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Subtype={tsubtype} | System={tsystem or '—'} | Tier={ttier} | "
                 f"Beans={'✓' if t_beans else '✗'} | Steam={'✓' if t_steam else '✗'}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── SDA universe minus the trigger itself
    c_sda = df_sda[df_sda['Material'] != tm].copy()

    # ── Spare universe: drop the trigger + ALL competitor machines (any
    # Καφετιέρες hierarchy, accent-insensitive), keep Συσκευές Φραπέ +
    # Συσκευές Ελληνικού Καφέ.
    if df_spare is not None and not df_spare.empty:
        c_spare = df_spare[df_spare['Material'] != tm].copy()
        b4 = len(c_spare)
        sp_hier_norm = c_spare['Hierarchy'].fillna('').astype(str).map(_cm_norm) \
            if 'Hierarchy' in c_spare.columns else pd.Series([''] * len(c_spare), index=c_spare.index)
        trigger_norm = {_cm_norm(h) for h in COFFEE_TRIGGER_HIERARCHIES}
        comp_mask = sp_hier_norm.isin(trigger_norm) | sp_hier_norm.str.contains('ΚΑΦΕΤΙΕΡ', na=False)
        c_spare = c_spare[~comp_mask]
        c_spare = c_spare.drop_duplicates(subset=['Material'])
        diag.append(("1. Spare pool", len(c_spare), f"Removed {b4 - len(c_spare)} competitor machines / dupes"))
    else:
        c_spare = pd.DataFrame()
        diag.append(("1. Spare pool", 0, "Spare sheet empty — Φραπέ/Μπρίκι slots will backfill"))

    # ── Sales tiebreaker prep
    for _df in (c_sda, c_spare):
        if not _df.empty:
            if 'Sum of Sales' in _df.columns:
                _df['Sales_Tiebreaker'] = pd.to_numeric(_df['Sum of Sales'], errors='coerce').fillna(0)
            else:
                _df['Sales_Tiebreaker'] = 0

    # ── Type-tagged accessory frame (basis of pools 1-4 + overflow)
    acc = _cm_prep_accessory_frame(c_sda)
    diag.append(("2. Αξεσουάρ Καφέ", len(acc),
                 f"Type mix: {acc['_cm_type'].value_counts().to_dict() if not acc.empty else '—'}"))

    def _sda_hier_slice(hiers):
        hn = {_cm_norm(h) for h in hiers}
        sda_norm = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
        return c_sda[sda_norm.isin(hn)].drop_duplicates(subset=['Material']).copy()

    def _spare_hier_slice(pattern):
        """Accent-insensitive CONTAINS slice over the Spare frame — survives
        spelling drift in live hierarchy names ('Συσκευές Φραπέ' vs 'ΦΡΑΠΕ')."""
        if c_spare.empty:
            return pd.DataFrame()
        sp_norm = c_spare['Hierarchy'].fillna('').astype(str).map(_cm_norm)
        return c_spare[sp_norm.str.contains(pattern, regex=True, na=False)].copy()

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, logic_key, max_r1, max_total in COFFEE_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        if logic_key == 'CM_FROTHER':
            scored = _cm_build_frother_pool(acc, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CM_CARE':
            scored = _cm_build_care_pool(acc, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CM_GRIND_OR_HOLD':
            scored = _cm_build_grind_or_hold_pool(acc, tsubtype, tsystem, t_beans, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CM_EXTRAS':
            scored = _cm_build_extras_pool(acc, tsubtype, tsystem, t_beans, t_steam, tb, tprice, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CM_FRAPPE':
            scored = _cm_build_companion_pool(_spare_hier_slice('ΦΡΑΠΕ'), tb, ttier, notes, apply_tier=False)
        elif logic_key == 'CM_BRIKI':
            scored = _cm_build_companion_pool(_spare_hier_slice('ΕΛΛΗΝΙΚΟΥ ΚΑΦΕ|ΜΠΡΙΚΙ'), tb, ttier, notes, apply_tier=False)
        elif logic_key == 'CM_WAFFLE_CREPE':
            wc = _sda_hier_slice(['Ειδικές Συσκευές'])
            if not wc.empty:
                eid = wc['Είδος'].fillna('').astype(str) if 'Είδος' in wc.columns else pd.Series([''] * len(wc), index=wc.index)
                kat = wc['Κατηγορία'].fillna('').astype(str) if 'Κατηγορία' in wc.columns else pd.Series([''] * len(wc), index=wc.index)
                blob = (eid + ' ' + kat + ' ' + wc['Title'].fillna('').astype(str)).str.upper()
                wc = wc[blob.str.contains('ΒΑΦΛ|ΚΡΕΠ|WAFFLE|CREPE', regex=True, na=False)]
                notes.append(f"  Filtered Ειδικές Συσκευές → Βαφλιέρες/Κρεπιέρες: {len(wc)}")
            scored = _cm_build_companion_pool(wc, tb, ttier, notes)
        elif logic_key == 'CM_TOASTER':
            scored = _cm_build_companion_pool(_sda_hier_slice(['Φρυγανιέρες']), tb, ttier, notes)
        elif logic_key == 'CM_FRYER':
            # attach 2,164 — top-3 kitchen co-purchase with coffee machines
            scored = _cm_build_companion_pool(_sda_hier_slice(['Φριτέζες']), tb, ttier, notes)
        elif logic_key == 'CM_IRON':
            # attach 1,899 — household-bundle co-purchase
            scored = _cm_build_companion_pool(_sda_hier_slice(['Σίδερα']), tb, ttier, notes)
        elif logic_key == 'CM_KETTLE':
            scored = _cm_build_companion_pool(_sda_hier_slice(['Βραστήρες']), tb, ttier, notes)
        elif logic_key == 'CM_SANDWICH':
            scored = _cm_build_companion_pool(_sda_hier_slice(['Τοστιέρες']), tb, ttier, notes)
        elif logic_key == 'CM_ACC_OVERFLOW':
            # Last-resort backfill — but with the SAME usefulness gates as
            # the typed pools, so backfill never reintroduces junk: no
            # other-brand capsules, no grinder/beans/storage for capsule
            # machines, no pitcher without a steam wand, no brand-mismatched
            # water filters, nothing priced above the trigger.
            scored = acc.copy() if not acc.empty else pd.DataFrame()
            if not scored.empty:
                excl_types = {'capsules'}  # machine-locked unless brand match (handled below)
                if tsubtype == 'CAPSULE':
                    excl_types |= {'grinder', 'beans', 'storage'}
                if not t_steam:
                    excl_types |= {'pitcher'}
                if not t_beans:
                    excl_types |= {'beans'}
                ov_brand = scored['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
                keep = ~scored['_cm_type'].isin(excl_types - {'capsules'})
                keep &= ~((scored['_cm_type'] == 'capsules') & (ov_brand != tb))
                keep &= ~((scored['_cm_type'] == 'water_filter') & ~ov_brand.isin(_cm_brand_family(tb)))
                if 'LIST PRICE' in scored.columns and tprice and tprice > 0:
                    keep &= scored['LIST PRICE'].apply(parse_euro_price) <= tprice
                dropped = len(scored) - keep.sum()
                scored = scored[keep]
                if dropped:
                    notes.append(f"  ✗ Overflow usefulness gate dropped {dropped} items")
            if not scored.empty:
                scored = _cm_base_score(scored)
                scored = _cm_brand_layer(scored, tb, notes, label='(overflow) ')
                scored = scored.sort_values('Final_Score', ascending=False)
                notes.append(f"  Overflow pool size: {len(scored)}")
        else:
            scored = pd.DataFrame()

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", 0 if scored is None or scored.empty else len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken = {rank: 0 for rank in pools}
    # CARE diversity guard: max CM_TYPE_DIVERSITY_CAP per care type ('cleaner'
    # vs 'water_filter') so slots 2-3 never show two liquid descalers.
    pool_type_counts = {rank: {} for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < COFFEE_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= COFFEE_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            apply_type_diversity = (logic_key in ('CM_CARE', 'CM_EXTRAS', 'CM_ACC_OVERFLOW'))

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored)                   and slot_num < COFFEE_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                if apply_type_diversity:
                    row_type = row.get('_cm_type', 'other')
                    if pool_type_counts[rank].get(row_type, 0) >= CM_TYPE_DIVERSITY_CAP:
                        continue

                slot_num += 1
                rc = row.copy()
                rc['Slot_Position'] = slot_num
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = COFFEE_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                if apply_type_diversity:
                    row_type = row.get('_cm_type', 'other')
                    pool_type_counts[rank][row_type] = pool_type_counts[rank].get(row_type, 0) + 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                type_hint = f" | type={row.get('_cm_type', '')}" if apply_type_diversity else ""
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f}{type_hint} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{COFFEE_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 IRONING HELPERS — Σιδέρωμα (v28.47)
# ═══════════════════════════════════════════════════════════════
# Pool builders for the round-robin ironing engine. Config + subtype/
# classification helpers live in the IRONING CONFIGURATION block near the
# top of the file (needed at sidebar load time).
#
# All pools come from the SDA sheet: Σιδερώστρες + Αξεσουάρ hold the
# type-classified accessory universe (boards / covers / lint / racks /
# descalers); Συστήματα ατμού, Ραπτομηχανή and Πρέσες ατμού are whole-
# hierarchy companion pools. One descaler (TEFAL XD9030E0) is misfiled in
# Πρέσες ατμού and one (SINGER SGR19400) in Αξεσουάρ Καφέ — the descaler
# pool is built by TITLE hunt across SDA, then hard brand-gated.

def _ir_prep_accessory_frame(c_sda):
    """Slice + dedup + type-tag the Σιδερώστρες + Αξεσουάρ hierarchies once;
    board/cover/lint/rack/overflow pools are type-filters over this frame."""
    hn = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    acc = c_sda[hn.isin({_cm_norm('Σιδερώστρες'), _cm_norm('Αξεσουάρ')})].copy()
    if acc.empty:
        return acc
    acc = acc.drop_duplicates(subset=['Material'])
    acc['_ir_type'] = acc['Title'].fillna('').astype(str).map(_ir_classify_acc)
    return acc


def _ir_base_score(pool):
    """Availability + sales — the common floor of every pool's score."""
    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += IR_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * IR_S_SALES_FACTOR
    return pool


def _ir_brand_layer(pool, trigger_brand, notes, boost=IR_S_BRAND_MATCH, label=''):
    """Same-brand ecosystem boost shared by all pools (boost is the
    STATION-board value when the caller passes IR_S_STATION_BOARD_BRAND)."""
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += boost
        if same_brand.any():
            notes.append(f"  ✓ Brand ecosystem {label}({trigger_brand}): {same_brand.sum()} (+{boost:,})")
    return pool


def _ir_tier_layer(pool, trigger_tier, notes):
    """Price-tier proximity for big-ticket companions (boards, steamers)."""
    if 'LIST PRICE' in pool.columns:
        tiers = pool['LIST PRICE'].apply(parse_euro_price).apply(_ir_price_tier)
        same_tier = tiers == trigger_tier
        near_tier = (tiers - trigger_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += IR_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += IR_S_PRICE_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Price-tier match (tier {trigger_tier}): same={same_tier.sum()}, near={near_tier.sum()}")
    return pool


def _ir_build_board_pool(acc, subtype, trigger_brand, trigger_tier, notes):
    """Slots for Σιδερώστρα ×2 (hero + tail alternative, brand-diverse).

    STATION → HARD drop board_compact: a €13 tabletop mini physically can't
    host a steam generator's boiler. Brand match gets the STRONG boost —
    BRAUN IB3001 / PHILIPS GC221 / STIROPLUS PRESTIGE 2 are the boards
    designed around their own stations' rests, and that pairing is the
    closest thing to "system-compatible" the catalog can express.
    IRON / PRESS → both board types eligible, standard brand boost +
    tier proximity (cheap iron → cheaper board first).
    """
    pool = acc[acc['_ir_type'].isin(['board', 'board_compact'])].copy()
    if pool.empty:
        notes.append("  ⚠ No ironing boards in Σιδερώστρες/Αξεσουάρ")
        return pool
    if subtype == 'STATION':
        compact = pool['_ir_type'] == 'board_compact'
        if compact.any():
            notes.append(f"  ✗ HARD-dropped {compact.sum()} compact/tabletop boards (steam-station trigger needs a full board)")
        pool = pool[~compact]
        if pool.empty:
            notes.append("  ⚠ Board pool empty after compact gating")
            return pool
    pool = _ir_base_score(pool)
    pool.loc[:, 'Final_Score'] += IR_S_TYPE_RELEVANT
    brand_boost = IR_S_STATION_BOARD_BRAND if subtype == 'STATION' else IR_S_BRAND_MATCH
    pool = _ir_brand_layer(pool, trigger_brand, notes, boost=brand_boost,
                           label='(station board) ' if subtype == 'STATION' else '')
    pool = _ir_tier_layer(pool, trigger_tier, notes)
    notes.append(f"  Pool size: {len(pool)} | board mix: {pool['_ir_type'].value_counts().to_dict()}")
    return pool.sort_values('Final_Score', ascending=False)


def _ir_build_descaler_pool(c_sda, trigger_brand, notes):
    """Slot — Φίλτρο Κατά των Αλάτων. HARD brand-family gate, printer-
    cartridge style: these are machine-specific cartridges (TEFAL XD9030E0
    fits Tefal generators, SINGER SGΕ-19700/SGR19400 fit SINGER's line).
    Brands without a filter in the catalog cleanly EMPTY the slot — the
    backfill chain absorbs it; no cross-brand bleed, ever.

    Built by TITLE hunt across the whole SDA frame because the three
    filters live in three different hierarchies (Αξεσουάρ, Πρέσες ατμού,
    Αξεσουάρ Καφέ — the last is a steam-generator filter misfiled with
    coffee). Coffee-specific descaler chemistry (DECALK liquids, tablets,
    balls) is excluded by keyword so a hypothetical brand match can never
    pull a coffee consumable into the ironing carousel.
    """
    tnorm = c_sda['Title'].fillna('').astype(str).map(_cm_norm)
    is_filter = tnorm.str.contains('ΚΑΤΑ ΤΩΝ ΑΛΑΤΩΝ', na=False)
    is_coffee_chem = tnorm.str.contains('DECALK|ΥΓΡΟ ΑΦΑΛΑΤΩΣΗΣ|ΤΑΜΠΛΕΤΕΣ|ΜΠΙΛΙΕΣ', regex=True, na=False)
    pool = c_sda[is_filter & ~is_coffee_chem].drop_duplicates(subset=['Material']).copy()
    if pool.empty:
        notes.append("  ⚠ No anti-scale filters in SDA")
        return pool
    fam = _ir_brand_family(trigger_brand)
    brand_col = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
    drop = ~brand_col.isin(fam)
    if drop.any():
        notes.append(f"  ✗ HARD-dropped {drop.sum()} machine-specific filters (brand family ≠ {trigger_brand or '—'})")
    pool = pool[~drop]
    if pool.empty:
        notes.append(f"  ⚠ No {trigger_brand or '—'} anti-scale filter in catalog — slot backfills (correct behavior, no cross-brand bleed)")
        return pool
    pool = _ir_base_score(pool)
    pool.loc[:, 'Final_Score'] += IR_S_TYPE_RELEVANT + IR_S_BRAND_MATCH
    notes.append(f"  ✓ Brand-matched filters ({trigger_brand}): {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _ir_build_cover_pool(acc, trigger_brand, notes):
    """Slot — Σιδερόπανο. Impulse item (€9-23): sales × availability with
    a soft brand boost (STIROPLUS station → STIROPLUS σιδερόπανο). Covers
    are semi-universal board accessories, so no hard gate — but no tier
    mirror either."""
    pool = acc[acc['_ir_type'] == 'cover'].copy()
    if pool.empty:
        notes.append("  ⚠ No σιδερόπανα in Σιδερώστρες/Αξεσουάρ")
        return pool
    pool = _ir_base_score(pool)
    pool.loc[:, 'Final_Score'] += IR_S_TYPE_RELEVANT
    pool = _ir_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _ir_build_lint_pool(acc, trigger_brand, notes):
    """Slots — Αποχνουδωτής ×2 (option A + option B, different brand by
    the loop's brand-diversity cap). Impulse tier — sales-led."""
    pool = acc[acc['_ir_type'] == 'lint'].copy()
    if pool.empty:
        notes.append("  ⚠ No αποχνουδωτές in Αξεσουάρ")
        return pool
    pool = _ir_base_score(pool)
    pool.loc[:, 'Final_Score'] += IR_S_TYPE_RELEVANT
    pool = _ir_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)} | brands: {pool['Κατασκευαστής'].nunique()}")
    return pool.sort_values('Final_Score', ascending=False)


def _ir_build_steamer_pool(c_sda, trigger_brand, notes):
    """Slots — Σύστημα Ατμού ×2 (different brand via diversity cap).
    IMPULSE-style scoring: brand ecosystem + sales + availability, NO tier
    mirror — handheld steamers are €30-130 add-ons people buy regardless
    of trigger price. With the mirror ON, a tier-3 trigger (SINGER Divina
    press €349) pulled the €499 ROWENTA floor steam-cleaner over the
    8,081-sales TEFAL PURE POP — validated failure case, v28.47."""
    hn = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    pool = c_sda[hn == _cm_norm('Συστήματα ατμού')].drop_duplicates(subset=['Material']).copy()
    if pool.empty:
        notes.append("  ⚠ No Συστήματα ατμού in SDA")
        return pool
    pool = _ir_base_score(pool)
    pool.loc[:, 'Final_Score'] += IR_S_TYPE_RELEVANT
    pool = _ir_brand_layer(pool, trigger_brand, notes)
    notes.append("  ℹ Impulse companion — tier mirroring OFF (sales + brand + availability decide)")
    notes.append(f"  Pool size: {len(pool)} | brands: {pool['Κατασκευαστής'].nunique()}")
    return pool.sort_values('Final_Score', ascending=False)


def _ir_build_sewing_pool(c_sda, notes):
    """Slots — Ραπτομηχανή ×2: entry level FIRST (user spec), advanced or
    different brand second. Entry boost (<€120) puts the FIRST AUSTRIA
    €69.9 ahead of the higher-selling SINGER €169; the brand-diversity cap
    then makes pick #2 the best-selling SINGER — exactly the
    'entry → advanced/different brand' progression requested."""
    hn = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    pool = c_sda[hn == _cm_norm('Ραπτομηχανή')].drop_duplicates(subset=['Material']).copy()
    if pool.empty:
        notes.append("  ⚠ No Ραπτομηχανές in SDA")
        return pool
    pool = _ir_base_score(pool)
    pool.loc[:, 'Final_Score'] += IR_S_TYPE_RELEVANT
    prices = pool['LIST PRICE'].apply(parse_euro_price)
    entry = prices < 120
    pool.loc[entry, 'Final_Score'] += IR_S_ENTRY_FIRST
    if entry.any():
        notes.append(f"  ✓ Entry-level (<€120) leads: {entry.sum()} (+{IR_S_ENTRY_FIRST:,})")
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _ir_build_press_pool(c_sda, subtype, trigger_tier, trigger_brand, notes):
    """Backfill — Πρέσα Ατμού. Cross-sell upsell for IRON triggers; for
    PRESS triggers the whole hierarchy is COMPETITORS → pool empties.
    Title-guards out the misfiled TEFAL anti-scale filter."""
    if subtype == 'PRESS':
        notes.append("  ℹ PRESS trigger — Πρέσες ατμού are competitors, pool skipped")
        return pd.DataFrame()
    hn = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    pool = c_sda[hn == _cm_norm('Πρέσες ατμού')].drop_duplicates(subset=['Material']).copy()
    if not pool.empty:
        tn = pool['Title'].fillna('').astype(str).map(_cm_norm)
        misfiled = tn.str.contains('ΦΙΛΤΡΟ', na=False)
        if misfiled.any():
            notes.append(f"  ✗ Excluded {misfiled.sum()} misfiled accessory rows (ΦΙΛΤΡΟ in Πρέσες ατμού)")
        pool = pool[~misfiled]
    if pool.empty:
        notes.append("  ⚠ No πρέσες ατμού available")
        return pool
    pool = _ir_base_score(pool)
    pool = _ir_brand_layer(pool, trigger_brand, notes)
    pool = _ir_tier_layer(pool, trigger_tier, notes)
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 IRONING ENGINE — Σιδέρωμα (v28.47)
# ═══════════════════════════════════════════════════════════════

def run_ironing_engine(trigger, df_sda, df_history):
    """Build up to 10 cross-sell slots for an ironing trigger (steam iron /
    steam station / steam press).

    Round 1 lays the hero of each pool across slots 1-6 (Σιδερώστρα →
    Φίλτρο Αλάτων → Σιδερόπανο → Αποχνουδωτής → Steamer → Ραπτομηχανή);
    round 2 lays the B-options (different brand, enforced by the brand-
    diversity cap) of the 2-cap pools at slots 7-10. Backfill chain
    (Πρέσα → Απλώστρα → laundry-care overflow) guarantees 10/10.

    All data from the SDA sheet (Home file).
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _ir_price_tier(tprice)
    tsubtype = _ir_detect_subtype(trigger)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Subtype={tsubtype} | Tier={ttier} | Hierarchy={trigger.get('Hierarchy', '—')}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── SDA universe minus the trigger + ALL competitor triggers (any
    # ironing trigger hierarchy — an iron buyer shouldn't see other irons)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    hn = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    trig_norm = {_cm_norm(h) for h in IRONING_TRIGGER_HIERARCHIES} - {_cm_norm('Πρέσες ατμού')}
    b4 = len(c_sda)
    c_sda = c_sda[~hn.isin(trig_norm)]
    diag.append(("1. SDA pool", len(c_sda),
                 f"Removed {b4 - len(c_sda)} competitor irons/stations (Πρέσες kept for the backfill pool)"))

    # ── Sales tiebreaker prep (pandas-3.x safe: plain float64)
    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0.0).astype('float64')
    else:
        c_sda['Sales_Tiebreaker'] = 0.0

    # ── Type-tagged accessory frame (boards / covers / lint / racks / overflow)
    acc = _ir_prep_accessory_frame(c_sda)
    diag.append(("2. Σιδερώστρες+Αξεσουάρ", len(acc),
                 f"Type mix: {acc['_ir_type'].value_counts().to_dict() if not acc.empty else '—'}"))

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, logic_key, max_r1, max_total in IRONING_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        if logic_key == 'IR_BOARD':
            scored = _ir_build_board_pool(acc, tsubtype, tb, ttier, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'IR_DESCALER':
            scored = _ir_build_descaler_pool(c_sda, tb, notes)
        elif logic_key == 'IR_COVER':
            scored = _ir_build_cover_pool(acc, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'IR_LINT':
            scored = _ir_build_lint_pool(acc, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'IR_STEAMER':
            scored = _ir_build_steamer_pool(c_sda, tb, notes)
        elif logic_key == 'IR_SEWING':
            scored = _ir_build_sewing_pool(c_sda, notes)
        elif logic_key == 'IR_PRESS':
            scored = _ir_build_press_pool(c_sda, tsubtype, ttier, tb, notes)
        elif logic_key == 'IR_RACK':
            scored = acc[acc['_ir_type'] == 'rack'].copy() if not acc.empty else pd.DataFrame()
            if not scored.empty:
                scored = _ir_base_score(scored)
                scored = _ir_brand_layer(scored, tb, notes)
                scored = scored.sort_values('Final_Score', ascending=False)
                notes.append(f"  Pool size: {len(scored)} (απλώστρες)")
            else:
                notes.append("  ⚠ No απλώστρες in Σιδερώστρες/Αξεσουάρ")
        elif logic_key == 'IR_OVERFLOW':
            # Last-resort backfill — leftover laundry-care accessories
            # (extra covers/racks, shoe cleaner). Descalers are excluded
            # ENTIRELY: the dedicated hard-gated pool owns that slot, and a
            # second anti-scale filter in the same carousel is redundant
            # (validated v28.47: SINGER trigger surfaced both SGR19400 AND
            # SGΕ-19700 before this guard).
            scored = acc[~acc['_ir_type'].isin(['board', 'board_compact', 'descaler', 'other'])].copy() if not acc.empty else pd.DataFrame()
            if not scored.empty:
                scored = _ir_base_score(scored)
                scored = _ir_brand_layer(scored, tb, notes, label='(overflow) ')
                scored = scored.sort_values('Final_Score', ascending=False)
                notes.append(f"  Overflow pool size: {len(scored)}")
            else:
                notes.append("  ⚠ Overflow pool empty")
        else:
            scored = pd.DataFrame()

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", 0 if scored is None or scored.empty else len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken = {rank: 0 for rank in pools}
    # Brand-diversity guard: max IR_BRAND_DIVERSITY_CAP per brand inside
    # the 2-cap pools — guarantees option A ≠ option B brand (user spec:
    # 'lint remover option B — different brand', same for steamers/sewing).
    pool_brand_counts = {rank: {} for rank in pools}
    compact_boards_taken = 0  # board type-diversity: max 1 compact per carousel
    slot_num = 0
    round_idx = 0

    while slot_num < IRONING_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= IRONING_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            apply_brand_diversity = (logic_key in ('IR_BOARD', 'IR_LINT', 'IR_STEAMER', 'IR_SEWING'))

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < IRONING_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                row_brand = str(row.get('Κατασκευαστής', '')).strip().upper()
                if apply_brand_diversity:
                    if pool_brand_counts[rank].get(row_brand, 0) >= IR_BRAND_DIVERSITY_CAP:
                        continue
                # Compact-board cap: max ONE tabletop/compact board per
                # carousel — board #2 must be a FULL board ('large or
                # system-compatible level' per slot spec). Validated
                # v28.47: a tier-0 budget iron pulled TWO compacts (AFER
                # mini + LEIFHEIT table base) before this guard.
                if logic_key == 'IR_BOARD' and row.get('_ir_type', '') == 'board_compact':
                    if compact_boards_taken >= 1:
                        continue

                slot_num += 1
                rc = row.copy()
                rc['Slot_Position'] = slot_num
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = IRONING_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                if apply_brand_diversity:
                    pool_brand_counts[rank][row_brand] = pool_brand_counts[rank].get(row_brand, 0) + 1
                if logic_key == 'IR_BOARD' and row.get('_ir_type', '') == 'board_compact':
                    compact_boards_taken += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                type_hint = f" | type={row.get('_ir_type', '')}" if '_ir_type' in row.index else ""
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f}{type_hint} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{IRONING_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 PRINTERS HELPERS — Εκτυπωτές & Πολυμηχανήματα (v28.46)
# ═══════════════════════════════════════════════════════════════
# Pool sources span FOUR frames:
#   df_spare (Home):       triggers + OEM/compatible inks & toners & drums
#                          + papers (richest consumable specs: Χρώμα 97%,
#                          Συμβατό μοντέλο 93%, Συμβατό με.1 brand 99%)
#   df_peripherals (Main): USB CABLES (USB-B), CLEANING PRODUCTS,
#                          ΚΑΤΑΣΤΡΟΦΕΙΣ ΕΓΓΡΑΦΩΝ, extra paper hierarchies
#   df_products (Main):    SURGE PROTECTORS (177 πολύπριζα)
#   df_stationery (Main):  ΚΛΑΣΕΡ / ΚΟΥΤΙΑ ΑΡΧΕΙΟΥ / ΝΤΟΣΙΕ (αρχειοθέτηση)
# Papers exist in BOTH Spare and Peripherals — concat + dedup on Material.

_PR_OEM_INK_HIERS    = {'INK CATRIDGES'}                       # sic — live spelling
_PR_OEM_TONER_HIERS  = {'TONER CATRIDGES'}
_PR_COMPAT_HIERS     = {'COMPATIBLE TONERS', 'COMPATIBLE INK CARTRIDGES'}
_PR_DRUM_HIERS       = {'DRUMS CATRIDGES'}
_PR_PLAIN_PAPER_HIERS = {'COPIERS PAPER'}
_PR_PHOTO_PAPER_HIERS = {'INKJET PAPER', 'SPECIAL PAPERS', 'THERMAL PAPER'}


def _pr_hier_slice(df, hier_set):
    if df is None or df.empty or 'Hierarchy' not in df.columns:
        return pd.DataFrame()
    h = df['Hierarchy'].fillna('').astype(str).str.upper().str.strip()
    return df[h.isin({x.upper() for x in hier_set})].copy()


def _pr_base_score(pool):
    """Availability + sales tiebreaker. pandas-3.x safe: all arithmetic on
    plain float64 NumPy arrays (Arrow-backed dtypes refuse mixed adds)."""
    pool = pool.copy()
    avail = pool['AVAILABILITY'].fillna('').astype(str).str.contains(
        'Άμεσα|Αμεσα', regex=True, na=False) if 'AVAILABILITY' in pool.columns \
        else pd.Series(False, index=pool.index)
    sales = pd.to_numeric(pool.get('Sum of Sales', 0), errors='coerce').fillna(0.0)
    score = np.asarray(avail, dtype='float64') * PR_S_AVAILABILITY \
        + np.asarray(sales, dtype='float64') * PR_S_SALES_FACTOR
    pool['Final_Score'] = score
    return pool


def _pr_match_consumables(df_spare, hier_set, trigger_brand, codes, mtokens,
                          notes, label=''):
    """The core spec gate. Returns ONLY consumables that pass:
      HARD 1 — brand: 'Συμβατό με.1' (or Κατασκευαστής) ∈ trigger brand
               family. No cross-brand bleed, ever.
      HARD 2 — model: DIRECT code hit (word-bounded, vs Title+Μοντέλο+
               Material) OR COMPAT hit (trigger model tokens vs the
               semicolon 'Συμβατό μοντέλο' list, normalized). Neither →
               row dropped — an unmatched cartridge is landfill, no score
               can redeem it.
    Scoring inside the survivors: DIRECT 3M > COMPAT 2M, + availability +
    sales tiebreaker."""
    pool = _pr_hier_slice(df_spare, hier_set)
    if pool.empty:
        notes.append(f"  {label}pool: source hierarchy empty")
        return pool
    b4 = len(pool)

    fam = _pr_brand_family(trigger_brand)

    def _norm_col(frame, col):
        if col in frame.columns:
            return frame[col].fillna('').astype(str).map(_cm_norm).str.strip()
        return pd.Series([''] * len(frame), index=frame.index)

    compat_brand = _norm_col(pool, 'Συμβατό με.1')
    maker = _norm_col(pool, 'Κατασκευαστής')
    brand_ok = compat_brand.isin(fam) | maker.isin(fam)
    # Compatible-toner rows: Κατασκευαστής = Office Log etc., the printer
    # brand lives ONLY in 'Συμβατό με.1' — the isin pair above covers both.
    pool = pool[brand_ok]
    notes.append(f"  {label}brand gate ({trigger_brand}): {b4} → {len(pool)}")
    if pool.empty:
        return pool

    blob = (pool['Title'].fillna('').astype(str) + ' '
            + pool.get('Μοντέλο', pd.Series('', index=pool.index)).fillna('').astype(str) + ' '
            + pool['Material'].fillna('').astype(str)).map(_cm_norm)
    compat_list = _norm_col(pool, 'Συμβατό μοντέλο')

    direct = blob.apply(lambda s: _pr_wb_match(codes, s)) if codes \
        else pd.Series(False, index=pool.index)
    compat = compat_list.apply(lambda s: _pr_wb_match(mtokens, s)) if mtokens \
        else pd.Series(False, index=pool.index)

    keep = direct | compat
    dropped = int((~keep).sum())
    pool = pool[keep].copy()
    notes.append(f"  {label}model gate: dropped {dropped} brand-matched but "
                 f"model-incompatible items → {len(pool)}")
    if pool.empty:
        return pool

    pool = _pr_base_score(pool)
    pool['Final_Score'] = (
        np.asarray(pool['Final_Score'], dtype='float64')
        + np.asarray(direct[pool.index], dtype='float64') * PR_S_DIRECT_CODE
        + np.asarray(compat[pool.index], dtype='float64') * PR_S_COMPAT_LIST
    )
    pool['_pr_match'] = np.where(direct[pool.index], 'direct',
                                 np.where(compat[pool.index], 'compat', '—'))
    return pool.sort_values('Final_Score', ascending=False).drop_duplicates(subset=['Material'])


def _pr_split_by_color(pool, notes, label=''):
    """{K,C,M,Y,MULTI} sub-pools from a matched cartridge frame."""
    out = {k: pd.DataFrame() for k in ('K', 'C', 'M', 'Y', 'MULTI')}
    if pool is None or pool.empty:
        return out
    tags = pool.apply(_pr_cart_color, axis=1)
    for key in out:
        out[key] = pool[tags == key].copy()
    mix = {k: len(v) for k, v in out.items()}
    notes.append(f"  {label}color split: {mix} (OTHER dropped: {int((tags=='OTHER').sum())})")
    return out


def _pr_build_thermal_media_pool(df_spare, df_peripherals, trigger_brand,
                                 codes, media_kw, notes):
    """Thermal/Zink media: the trigger's own pack (Selphy KP-36IP sits in
    INK CATRIDGES as an ink+paper bundle; Zink sheets sit in SPECIAL
    PAPERS) — so we scan consumables + papers across BOTH sheets for a
    DIRECT code hit or a media keyword hit ('ZINK'). Brand here is a SOFT
    boost, not a gate: Zink is a licensed cross-brand format and the
    catalog's 2x3" packs (HP/Xiaomi) feed Canon Zoeminis too."""
    frames = []
    for src in (df_spare, df_peripherals):
        sl = _pr_hier_slice(src, _PR_OEM_INK_HIERS | _PR_PHOTO_PAPER_HIERS)
        if not sl.empty:
            frames.append(sl)
    if not frames:
        notes.append("  thermal media: no source rows")
        return pd.DataFrame()
    pool = pd.concat(frames, ignore_index=True).drop_duplicates(subset=['Material'])
    blob = pool['Title'].fillna('').astype(str).map(_cm_norm)
    hit = blob.apply(lambda s: _pr_wb_match(codes, s)) if codes \
        else pd.Series(False, index=pool.index)
    if media_kw:
        hit = hit | blob.apply(lambda s: _pr_wb_match(media_kw, s))
    pool = pool[hit].copy()
    notes.append(f"  thermal media: {len(pool)} code/keyword matches")
    if pool.empty:
        return pool
    pool = _pr_base_score(pool)
    fam = _pr_brand_family(trigger_brand)
    maker = pool.get('Κατασκευαστής', pd.Series('', index=pool.index)) \
        .fillna('').astype(str).map(_cm_norm).str.strip()
    pool['Final_Score'] = (
        np.asarray(pool['Final_Score'], dtype='float64')
        + np.asarray(maker.isin(fam), dtype='float64') * PR_S_BRAND_MEDIA
        + PR_S_DIRECT_CODE  # matched media ranks like a direct consumable
    )
    return pool.sort_values('Final_Score', ascending=False)


def _pr_build_paper_pool(df_spare, df_peripherals, trigger_brand, kind, notes):
    """kind='plain' → COPIERS PAPER (A4 80gr boost); kind='photo' →
    INKJET/SPECIAL/THERMAL papers (glossy/photo boost, ZINK packs excluded
    — those belong to the thermal media pool, not to an EcoTank). Brand is
    a soft boost only — paper is universal."""
    hiers = _PR_PLAIN_PAPER_HIERS if kind == 'plain' else _PR_PHOTO_PAPER_HIERS
    frames = []
    for src in (df_spare, df_peripherals):
        sl = _pr_hier_slice(src, hiers)
        if not sl.empty:
            frames.append(sl)
    if not frames:
        notes.append(f"  {kind} paper: no source rows")
        return pd.DataFrame()
    pool = pd.concat(frames, ignore_index=True).drop_duplicates(subset=['Material'])
    blob = pool['Title'].fillna('').astype(str).map(_cm_norm)
    if kind == 'photo':
        b4 = len(pool)
        pool = pool[~blob.str.contains('ZINK', na=False)].copy()
        blob = blob[pool.index]
        if b4 - len(pool):
            notes.append(f"  photo paper: excluded {b4 - len(pool)} ZINK packs (thermal-only media)")
    pool = _pr_base_score(pool)
    fam = _pr_brand_family(trigger_brand)
    maker = pool.get('Κατασκευαστής', pd.Series('', index=pool.index)) \
        .fillna('').astype(str).map(_cm_norm).str.strip()
    if kind == 'plain':
        fit = blob.str.contains('A4', na=False) & blob.str.contains('80', na=False)
    else:
        fit = blob.str.contains('ΦΩΤΟΓΡΑΦΙΚ|GLOSSY|PHOTO|MATTE', regex=True, na=False)
    pool['Final_Score'] = (
        np.asarray(pool['Final_Score'], dtype='float64')
        + np.asarray(maker.isin(fam), dtype='float64') * PR_S_BRAND_MEDIA
        + np.asarray(fit, dtype='float64') * PR_S_FORMAT_FIT
    )
    notes.append(f"  {kind} paper pool: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _pr_build_cable_pool(df_peripherals, notes):
    """USB CABLES hard-filtered to USB-B (the printer plug). A USB-C or
    micro-USB cable in this slot is a categorization error, so non-B
    cables are DROPPED, not demoted — empty pool backfills instead."""
    pool = _pr_hier_slice(df_peripherals, {'USB CABLES'})
    if pool.empty:
        notes.append("  cable: USB CABLES hierarchy empty")
        return pool
    blob = pool['Title'].fillna('').astype(str).map(_cm_norm)
    keep = blob.str.contains('USB-B|USB B |TYPE-B|TYPE B|ΕΚΤΥΠΩΤ|PRINTER',
                             regex=True, na=False)
    pool = pool[keep].copy()
    notes.append(f"  cable: hard USB-B filter → {len(pool)}")
    if pool.empty:
        return pool
    return _pr_base_score(pool).sort_values('Final_Score', ascending=False)


def _pr_build_simple_pool(df, hier_set, notes, label):
    pool = _pr_hier_slice(df, hier_set)
    if pool.empty:
        notes.append(f"  {label}: hierarchy empty")
        return pool
    pool = _pr_base_score(pool).drop_duplicates(subset=['Material'])
    notes.append(f"  {label}: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 PRINTERS ENGINE — Εκτυπωτές & Πολυμηχανήματα (v28.46)
# ═══════════════════════════════════════════════════════════════

def run_printers_engine(trigger, df_spare, df_peripherals, df_products,
                        df_stationery, df_history):
    """Build up to 10 cross-sell slots for a printer / MFP trigger.

    Persona = tech (INKJET/TANK/LASER/THERMAL) × color (Έγχρωμη/Ασπρόμαυρη)
    × form (Πολυμηχάνημα/Εκτυπωτής) → each persona gets its own priority
    list; pools are spec-gated (brand + model compatibility HARD filters)
    and the round-robin loop with per-pool caps guarantees variety and
    10/10 filled slots via the office/paper backfill chain.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    tech = _pr_tech(trigger)
    is_color = _pr_is_color(trigger, tech)
    is_mfp = _pr_is_mfp(trigger)
    codes = _pr_consumable_codes(trigger)
    mtokens = _pr_model_tokens(trigger)
    media_kw = _pr_media_keywords(trigger)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Tech={tech} | {'Έγχρωμη' if is_color else 'Ασπρόμαυρη'} | "
                 f"{'Πολυμηχάνημα' if is_mfp else 'Εκτυπωτής'} | "
                 f"Codes={sorted(codes) or '—'} | ModelTokens={len(mtokens)}"))

    if df_spare is None or df_spare.empty:
        diag.append(("ERROR", 0, "Spare sheet empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    c_spare = df_spare[df_spare['Material'] != tm].copy()
    # Competitor printers out of every pool (the consumable hierarchies
    # never collide with Level 2 = Printers triggers, but belt+braces):
    if 'Level 2' in c_spare.columns:
        l2 = c_spare['Level 2'].fillna('').astype(str).str.strip().str.lower()
        c_spare = c_spare[l2 != 'printers']

    # ── Consumable pools (spec-gated) ──
    pool_notes = {}

    def _notes(key):
        pool_notes.setdefault(key, [])
        return pool_notes[key]

    cart_colors = {k: pd.DataFrame() for k in ('K', 'C', 'M', 'Y', 'MULTI')}
    drum_pool = pd.DataFrame()
    budget_pool = pd.DataFrame()
    media_pool = pd.DataFrame()

    if tech in ('INKJET', 'TANK'):
        oem = _pr_match_consumables(c_spare, _PR_OEM_INK_HIERS, tb, codes,
                                    mtokens, _notes('ink'), 'OEM ink ')
        cart_colors = _pr_split_by_color(oem, _notes('ink'), 'ink ')
        budget_pool = _pr_match_consumables(c_spare, _PR_COMPAT_HIERS, tb,
                                            codes, mtokens, _notes('budget'),
                                            'compat-budget ')
    elif tech == 'LASER':
        oem = _pr_match_consumables(c_spare, _PR_OEM_TONER_HIERS, tb, codes,
                                    mtokens, _notes('toner'), 'OEM toner ')
        cart_colors = _pr_split_by_color(oem, _notes('toner'), 'toner ')
        drum_pool = _pr_match_consumables(c_spare, _PR_DRUM_HIERS, tb, codes,
                                          mtokens, _notes('drum'), 'drum ')
        budget_pool = _pr_match_consumables(c_spare, _PR_COMPAT_HIERS, tb,
                                            codes, mtokens, _notes('budget'),
                                            'compat-budget ')
    else:  # THERMAL / ZINK — no ink, no toner, media packs instead
        media_pool = _pr_build_thermal_media_pool(c_spare, df_peripherals, tb,
                                                  codes, media_kw,
                                                  _notes('media'))

    # ── Companion pools ──
    plain_paper = _pr_build_paper_pool(c_spare, df_peripherals, tb, 'plain',
                                       _notes('paper'))
    photo_paper = _pr_build_paper_pool(c_spare, df_peripherals, tb, 'photo',
                                       _notes('photo'))
    cable_pool = _pr_build_cable_pool(df_peripherals, _notes('cable'))
    surge_pool = _pr_build_simple_pool(df_products, {'SURGE PROTECTORS'},
                                       _notes('surge'), 'πολύπριζα')
    shredder_pool = _pr_build_simple_pool(df_peripherals,
                                          {'ΚΑΤΑΣΤΡΟΦΕΙΣ ΕΓΓΡΑΦΩΝ'},
                                          _notes('shredder'), 'καταστροφείς')
    organizer_pool = _pr_build_simple_pool(df_stationery,
                                           {'ΚΛΑΣΕΡ', 'ΚΟΥΤΙΑ ΑΡΧΕΙΟΥ', 'ΝΤΟΣΙΕ'},
                                           _notes('organizer'), 'αρχειοθέτηση')
    cleaner_pool = _pr_build_simple_pool(df_peripherals, {'CLEANING PRODUCTS'},
                                         _notes('cleaner'), 'καθαρισμός')

    # ── Persona-routed priority list ──
    ink_word = 'Μελάνι' if tech in ('INKJET', 'TANK') else 'Toner'
    pri = []  # (role_label, pool, max_round_1, max_total)

    if tech == 'THERMAL':
        pri = [
            ('Thermal Media Pack',   media_pool,     1, 2),
            ('Φωτογραφικό Χαρτί',    photo_paper,    1, 2),
            ('Καλώδιο USB-B',        cable_pool,     1, 2),
            ('Πολύπριζο Ασφαλείας',  surge_pool,     1, 2),
            ('Αρχειοθέτηση',         organizer_pool, 1, 3),
            ('Καθαρισμός',           cleaner_pool,   1, 2),
            ('Χαρτί Α4',             plain_paper,    1, None),
        ]
    elif is_color:
        # The user's canonical 10-slot OEM spec — K/C/M/Y consumables 1-4.
        # Tri-color systems (Canon PG+CL): C/M/Y pools come back empty and
        # the MULTI pack is PROMOTED to slot 2 so the carousel still opens
        # with the complete consumable story instead of three holes.
        cmy_empty = all(cart_colors[k].empty for k in ('C', 'M', 'Y'))
        multi_promoted = cmy_empty and not cart_colors['MULTI'].empty
        pri = [(f'Μαύρο {ink_word}', cart_colors['K'], 1, 1)]
        if multi_promoted:
            pri.append((f'Σετ {"Μελανιών" if ink_word == "Μελάνι" else "Toner"}',
                        cart_colors['MULTI'], 1, 1))
        else:
            pri += [
                (f'Κυανό {ink_word}',    cart_colors['C'], 1, 1),
                (f'Ματζέντα {ink_word}', cart_colors['M'], 1, 1),
                (f'Κίτρινο {ink_word}',  cart_colors['Y'], 1, 1),
            ]
        if tech == 'LASER':
            pri.append(('Drum / Τύμπανο', drum_pool, 1, 1))
            pri.append(('Χαρτί Α4', plain_paper, 1, 2))
            # NO photo paper on laser — toner can't print glossy stock
        else:
            pri.append(('Χαρτί Α4', plain_paper, 1, 2))
            pri.append(('Φωτογραφικό Χαρτί', photo_paper, 1, 2))
        pri += [
            ('Καλώδιο USB-B',       cable_pool,     1, 1),
            ('Πολύπριζο Ασφαλείας', surge_pool,     1, 1),
            ('Αρχειοθέτηση',        organizer_pool, 1, 2),
            ('Καθαρισμός',          cleaner_pool,   1, 1),
        ]
        # Backfill chain — value pack (if not promoted), budget compatibles,
        # office gear; paper overflow is already covered by the ×2 caps.
        if not multi_promoted:
            pri.append((f'Σετ {"Μελανιών" if ink_word == "Μελάνι" else "Toner"}',
                        cart_colors['MULTI'], 1, 1))
        pri.append((f'Συμβατό {ink_word} (Budget)', budget_pool, 1, 1))
        pri.append(('Καταστροφέας Εγγράφων', shredder_pool, 1, 1))
    else:
        # Ασπρόμαυρη — black consumable only, NO C/M/Y, NO photo paper.
        # Mono buyers are document-volume buyers: doubled paper slots, the
        # budget compatible alternative in the main list, and (for MFPs)
        # the shredder joins the office workflow chain.
        pri = [(f'Μαύρο {ink_word}', cart_colors['K'], 1, 2)]
        if tech == 'LASER':
            pri.append(('Drum / Τύμπανο', drum_pool, 1, 1))
        pri.append((f'Συμβατό {ink_word} (Budget)', budget_pool, 1, 1))
        pri.append(('Χαρτί Α4', plain_paper, 1, 2))
        pri += [
            ('Καλώδιο USB-B',       cable_pool, 1, 1),
            ('Πολύπριζο Ασφαλείας', surge_pool, 1, 1),
        ]
        if is_mfp:
            pri.append(('Καταστροφέας Εγγράφων', shredder_pool, 1, 1))
            pri.append(('Αρχειοθέτηση', organizer_pool, 1, 3))
        else:
            pri.append(('Αρχειοθέτηση', organizer_pool, 1, 3))
            pri.append(('Καταστροφέας Εγγράφων', shredder_pool, 1, 1))
        pri.append(('Καθαρισμός', cleaner_pool, 1, 2))

    pools = {}
    for rank, (role_label, scored, max_r1, max_total) in enumerate(pri, start=1):
        key_guess = {'Thermal Media Pack': 'media', 'Φωτογραφικό Χαρτί': 'photo',
                     'Χαρτί Α4': 'paper', 'Καλώδιο USB-B': 'cable',
                     'Πολύπριζο Ασφαλείας': 'surge', 'Αρχειοθέτηση': 'organizer',
                     'Καθαρισμός': 'cleaner', 'Καταστροφέας Εγγράφων': 'shredder',
                     'Drum / Τύμπανο': 'drum'}.get(role_label)
        if key_guess is None:
            key_guess = 'budget' if 'Budget' in role_label else (
                'ink' if tech in ('INKJET', 'TANK') else 'toner')
        notes = [f"=== Priority {rank}: {role_label} | max_round_1={max_r1} "
                 f"| max_total={max_total if max_total else '∞'} ==="]
        notes.extend(pool_notes.get(key_guess, []))
        pools[rank] = (role_label, scored, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})",
                     0 if scored is None or scored.empty else len(scored),
                     f"{'Έγχρωμη' if is_color else 'Mono'} {tech}"))

    # ── LOOPING: round-robin fill (same loop contract as the coffee engine) ──
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < PR_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, max_r1, max_total, notes) in pools.items():
            if slot_num >= PR_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                    and slot_num < PR_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                slot_num += 1
                rc = row.copy()
                rc['Slot_Position'] = slot_num
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = PR_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                match_hint = f" | match={row.get('_pr_match', '')}" if '_pr_match' in row.index else ""
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f}{match_hint} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    pool_diag_notes = [f"Persona: {tech} | {'Έγχρωμη' if is_color else 'Ασπρόμαυρη'} | "
                       f"{'Πολυμηχάνημα' if is_mfp else 'Εκτυπωτής'}",
                       f"Αναλώσιμο codes: {sorted(codes) or '—'} | media kw: {sorted(media_kw) or '—'}",
                       ""]
    for rank, (role_label, scored, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / "
            f"{len(scored) if scored is not None else 0} from this pool{cap_note}")
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{PR_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 SHARED HAIR-CARE IMPULSE HELPER — used by STR / HD / CB engines
# ═══════════════════════════════════════════════════════════════
# v28.23 — Defined at the top of STR HELPERS (the first engine in file
# order) so all subsequent hair-care engines can call this single shared
# function. Replaces the per-engine duplication that would otherwise be
# required (previously defined as _cb_build_impulse_accessory_pool in
# the CB helpers section in v28.22).
#
# Why a shared helper: FASHION ACCESSORIES + PERSONAL CARE Stationery
# impulse-buy pools have the SAME scoring logic regardless of which hair
# tool triggered them — the trigger's price/brand never matches the gift
# brands (Legami / Ban.Do / Hallmark), the price tiers are always 2-3
# steps below the trigger, and the scoring reduces to sales + availability
# + a soft color hint. The trigger-specific arguments (brand, price tier)
# are accepted for signature uniformity with the other pool builders but
# intentionally ignored inside.

# Shared scoring constants for the Personal Care impulse-buy pool.
# Calibrated to be slightly above the wellness floor so impulse items
# surface ahead of generic wellness when both are present.
PC_IMPULSE_S_AVAILABILITY = 100_000
PC_IMPULSE_S_COLOR_HINT   =  20_000  # Soft partial-color hint, no exact bonus
PC_IMPULSE_S_SALES_FACTOR =       0.5

# v28.27 — Premium-trigger signal weights. The default impulse pool ranking
# is sales-driven, which surfaces €5-10 top sellers (Legami scrunchies/
# hair towels/eye masks) regardless of trigger price. For a €549 DYSON
# Airwrap buyer, an €8 scrunchie feels stingy — the catalog has higher-
# quality gift items in the €13-25 range (Simple Pleasure body-care
# boxes at €17 with 1000 sales, Mad Beauty Harry Potter sets at €13-20)
# that better match a premium buyer's expectations.
#
# Magnitudes calibrated so:
#   • Sales tiebreaker (~500-750 per top item) is preserved as ranking
#     signal among items in the SAME price band
#   • PEAK bonus (+100k) elevates premium-band items above current top
#     sellers when the trigger is premium
#   • EDGE bonus (+30k) gives a partial nudge to items just outside the
#     peak range
#   • TRINKET penalty (-30k) demotes sub-€5 items for premium triggers
PC_IMPULSE_S_PREMIUM_PEAK    = 100_000
PC_IMPULSE_S_PREMIUM_EDGE    =  30_000
PC_IMPULSE_S_PREMIUM_PENALTY = -30_000


def _pc_impulse_price_signal(item_price: float, trigger_price: float) -> int:
    """v28.27 — Trigger-price-aware bonus for impulse items.

    Behavior tiers (chosen to match the 4 hair-engine trigger price profiles):
      • Budget trigger <€150  → returns 0. Current sales-driven behavior.
        Surfaces Legami €8 scrunchies for an IZZY €100 multistyler.
      • Mid trigger €150-300  → prefers €8-15 items (top: Hand Care €14).
        Surfaces Legami €10 hair towels for a BELLISSIMA €249 trigger.
      • Premium trigger €300-500 → prefers €10-20 items.
        Includes peak items like €17 Simple Pleasure Body Care.
      • Hero trigger ≥€500    → prefers €13-25 items.
        Pushes €17-20 gift boxes to top for DYSON Airwrap €549/€699.

    The premium signal complements (not replaces) the sales/availability
    scoring. Within each price band, sales remains the tiebreaker.
    """
    if item_price <= 0 or trigger_price <= 0:
        return 0

    # Budget triggers: no premium signal applied, keep sales-driven ranking
    if trigger_price < 150:
        return 0

    # Mid triggers (€150-€300): prefer €8-15
    if trigger_price < 300:
        if   8 <= item_price <= 15:                                 return PC_IMPULSE_S_PREMIUM_PEAK
        if   5 <= item_price <  8 or 15 < item_price <= 22:         return PC_IMPULSE_S_PREMIUM_EDGE
        if item_price > 25 or item_price < 3:                       return PC_IMPULSE_S_PREMIUM_PENALTY
        return 0

    # Premium triggers (€300-€500): prefer €10-20
    if trigger_price < 500:
        if  10 <= item_price <= 20:                                 return PC_IMPULSE_S_PREMIUM_PEAK
        if   7 <= item_price < 10 or 20 < item_price <= 28:         return PC_IMPULSE_S_PREMIUM_EDGE
        if item_price > 32 or item_price < 4:                       return PC_IMPULSE_S_PREMIUM_PENALTY
        return 0

    # Hero triggers (€500+): prefer €13-25
    if  13 <= item_price <= 25:                                     return PC_IMPULSE_S_PREMIUM_PEAK
    if   8 <= item_price < 13 or 25 < item_price <= 32:             return PC_IMPULSE_S_PREMIUM_EDGE
    if item_price > 35 or item_price < 6:                           return PC_IMPULSE_S_PREMIUM_PENALTY
    return 0


def _pc_build_impulse_accessory_pool(c_pool, trigger_brand, trigger_tier,
                                      trigger_colors, role_label, notes,
                                      trigger_price=0.0):
    """v28.23 — FASHION ACCESSORIES + PERSONAL CARE (Stationery sheet) pool.
    Shared by Straighteners / Hair Dryers / Curlers / Multistylers engines.

    These are gift / lifestyle impulse-buys in the €1-25 range — scrunchies,
    headbands, eye masks, hair towels, gift sets. Top sellers are by brands
    like Legami, Ban.Do, Mad Beauty which have ZERO overlap with appliance
    brands.

    Scoring shape — intentionally DIFFERENT from the standard pool builders:
      • Availability: standard boost (+PC_IMPULSE_S_AVAILABILITY)
      • Sales: standard tiebreaker (×PC_IMPULSE_S_SALES_FACTOR) — primary signal
      • Brand-match: SKIPPED entirely. Gift brands never match appliance
        brands; we don't want to imply Legami ≈ PHILIPS as same-brand pairing.
      • Price-tier proximity: SKIPPED (the standard tier system). A €7
        scrunchie is always 2-3 tiers below a €50 hair tool trigger — the
        normal penalty would knock these out entirely, defeating the
        impulse-buy purpose.
      • Color match: kept ONLY as soft partial hint (+PC_IMPULSE_S_COLOR_HINT).
      • v28.27 — NEW: trigger-price-aware premium signal. For premium and
        hero triggers, elevates €10-25 items so DYSON Airwrap buyers see
        aspirational gifts (€17 Simple Pleasure Body Care, €20 Harry Potter
        sets) instead of €8 scrunchies. Budget triggers unaffected.

    Net effect: ranking is sales-driven for budget triggers, sales-plus-
    price-band-aware for premium triggers. The shared helper is called by
    all 4 hair engines; trigger_price=0 (default) reverts to v28.23 behavior.

    Signature matches the other CB_* / HD_* / STR_* pool builders for
    uniformity (trigger_brand, trigger_tier accepted but ignored inside).
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        avail_mask = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail_mask, 'Final_Score'] += PC_IMPULSE_S_AVAILABILITY
        if avail_mask.any():
            notes.append(f"  ✓ Availability: {avail_mask.sum()} in stock (+{PC_IMPULSE_S_AVAILABILITY:,})")

    # ── Base sales score — primary signal since no brand/price boost
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * PC_IMPULSE_S_SALES_FACTOR

    # ── Color partial-match only (soft hint, no exact-match bonus)
    if trigger_colors and 'Χρώμα' in pool.columns:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        any_match_mask = pool_colors.apply(lambda g: bool(g & trigger_colors))
        pool.loc[any_match_mask, 'Final_Score'] += PC_IMPULSE_S_COLOR_HINT
        if any_match_mask.any():
            trigger_color_label = '/'.join(sorted(trigger_colors)) or 'none'
            notes.append(f"  ✓ Color hint ({trigger_color_label}): "
                         f"{any_match_mask.sum()} matched (+{PC_IMPULSE_S_COLOR_HINT:,})")

    # ── v28.27 — Trigger-price-aware premium signal
    if trigger_price > 0 and 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        premium_scores = prices.apply(lambda p: _pc_impulse_price_signal(p, trigger_price))
        pool['Final_Score'] += premium_scores
        peak_count = (premium_scores == PC_IMPULSE_S_PREMIUM_PEAK).sum()
        edge_count = (premium_scores == PC_IMPULSE_S_PREMIUM_EDGE).sum()
        pen_count  = (premium_scores == PC_IMPULSE_S_PREMIUM_PENALTY).sum()
        # Identify the active tier label for diagnostic clarity
        if trigger_price < 150:
            tier_lbl = "budget (<€150, no premium signal)"
        elif trigger_price < 300:
            tier_lbl = "mid (€150-300, prefer €8-15)"
        elif trigger_price < 500:
            tier_lbl = "premium (€300-500, prefer €10-20)"
        else:
            tier_lbl = "hero (€500+, prefer €13-25)"
        notes.append(f"  ✓ v28.27 Premium price signal (trigger €{trigger_price:.0f} → {tier_lbl}): "
                     f"peak={peak_count} (+{PC_IMPULSE_S_PREMIUM_PEAK:,}), "
                     f"edge={edge_count} (+{PC_IMPULSE_S_PREMIUM_EDGE:,}), "
                     f"penalty={pen_count} ({PC_IMPULSE_S_PREMIUM_PENALTY:+,})")

    notes.append(f"  (Impulse-buy pool: brand-match + standard price-tier scoring intentionally disabled)")
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 STRAIGHTENERS HELPERS — Ισιωτικά Μαλλιών (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Four pool builders, one per logic_key in STRAIGHTENER_PRIORITY:
#   STR_HAIRSTYLING       — Hair Dryers / Curlers / Multistylers
#   STR_PCARE_ACCESSORY   — Personal Care Accessories
#   STR_WOMENS_CARE       — Epilators (and future women's-care hierarchies)
#   STR_WELLNESS          — Toothbrushes / Scales / Massage
#
# All four share the same scoring spine: AVAILABILITY → SALES → BRAND_MATCH →
# PRICE_TIER → COLOR_GROUP. They differ in their weights (STR_HAIRSTYLING
# weights color higher because Hair Dryers/Curlers/Multistylers are
# fashion-coordinated; STR_WELLNESS de-emphasises color because a body scale
# in a different color doesn't feel mismatched). The multistyler-upsell
# nudge fires only inside STR_HAIRSTYLING when the trigger itself is a
# multi-function straightener.

def _str_apply_base_score(pool, trigger_brand, trigger_tier, trigger_colors, notes,
                          color_exact_weight=STR_S_COLOR_EXACT,
                          color_partial_weight=STR_S_COLOR_PARTIAL):
    """Apply the shared availability + sales + brand + price-tier + color scoring.
    Returns the pool with a Final_Score column added. Mutates `notes`.
    """
    if pool.empty:
        return pool

    pool = pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        avail_mask = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail_mask, 'Final_Score'] += STR_S_AVAILABILITY
        if avail_mask.any():
            notes.append(f"  ✓ Availability: {avail_mask.sum()} in stock (+{STR_S_AVAILABILITY:,})")

    # ── Base sales score (tiebreaker spine)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * STR_S_SALES_FACTOR

    # ── Brand-ecosystem boost (the strongest cross-sell signal)
    if trigger_brand and 'Κατασκευαστής' in pool.columns:
        same_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip() == trigger_brand
        pool.loc[same_brand, 'Final_Score'] += STR_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}): {same_brand.sum()} (+{STR_S_BRAND_MATCH:,})")

    # ── Price-tier proximity (same tier → boost, ≥2 away → penalty)
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_str_price_tier)
        diffs = (tiers - trigger_tier).abs()
        same_tier = diffs == 0
        near_tier = diffs == 1
        far_tier = diffs >= 2
        pool.loc[same_tier, 'Final_Score'] += STR_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += STR_S_PRICE_ONE_OFF
        pool.loc[far_tier, 'Final_Score'] += STR_S_PRICE_TWO_OFF
        if same_tier.any() or near_tier.any() or far_tier.any():
            notes.append(f"  ✓ Price-tier match (trigger tier {trigger_tier}): "
                         f"same={same_tier.sum()} (+{STR_S_PRICE_SAME_TIER:,}), "
                         f"near={near_tier.sum()} (+{STR_S_PRICE_ONE_OFF:,}), "
                         f"far={far_tier.sum()} ({STR_S_PRICE_TWO_OFF:+,})")

    # ── Color-group match (aesthetic coordination)
    if trigger_colors and 'Χρώμα' in pool.columns and color_exact_weight > 0:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        # Exact = identical group set (e.g. {'PINK'} == {'PINK'})
        exact_mask = pool_colors.apply(lambda g: g == trigger_colors and len(g) > 0)
        # Partial = any token overlap but not full equality
        partial_mask = pool_colors.apply(
            lambda g: bool(g & trigger_colors) and g != trigger_colors
        )
        pool.loc[exact_mask, 'Final_Score'] += color_exact_weight
        pool.loc[partial_mask, 'Final_Score'] += color_partial_weight
        if exact_mask.any() or partial_mask.any():
            trigger_color_label = '/'.join(sorted(trigger_colors)) or 'none'
            notes.append(f"  ✓ Color match ({trigger_color_label}): "
                         f"exact={exact_mask.sum()} (+{color_exact_weight:,}), "
                         f"partial={partial_mask.sum()} (+{color_partial_weight:,})")

    return pool


def _str_build_hairstyling_pool(c_pool, trigger_brand, trigger_tier,
                                 trigger_colors, is_multistyler_trigger,
                                 role_label, notes):
    """Score a hair-styling companion pool (Hair Dryers / Curlers / Multistylers).
    Color matters MOST here — these are coordinated styling tools women buy
    as a matching set. We also fire the multistyler-upsell nudge when the
    trigger is a multi-function straightener AND we're scoring the
    Πολυσυσκευή Styling slot.
    """
    if c_pool.empty:
        return c_pool

    pool = _str_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=STR_S_COLOR_EXACT,
        color_partial_weight=STR_S_COLOR_PARTIAL,
    )

    # ── Multistyler-upsell nudge: only fires when scoring the MULTISTYLERS slot
    # AND the trigger is already a multi-function straightener. The user has
    # signalled they want versatility — push the premium multistylers higher
    # so they see the pro-grade upgrade (Dyson Airwrap, BaByliss Big Hair, etc).
    if is_multistyler_trigger and role_label == 'Πολυσυσκευή Styling' and 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        premium_mask = prices >= 200  # Multistylers €200+ are the pro tier
        pool.loc[premium_mask, 'Final_Score'] += STR_S_MULTISTYLER_UPSELL
        if premium_mask.any():
            notes.append(f"  ✓ Multistyler upsell (trigger is multi-function): "
                         f"{premium_mask.sum()} premium multistylers (+{STR_S_MULTISTYLER_UPSELL:,})")

    return pool.sort_values('Final_Score', ascending=False)


def _str_build_accessory_pool(c_pool, trigger_brand, trigger_tier,
                               trigger_colors, notes):
    """Score the Personal Care ACCESSORIES pool.
    Color is irrelevant here (most accessories are utilitarian Inox/Πράσινο/
    no-color) so we zero out the color weight. Brand match still matters
    (DYSON brushes for DYSON straightener owners, PHILIPS brushes for PHILIPS).
    """
    if c_pool.empty:
        return c_pool

    pool = _str_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0,
        color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _str_build_womens_care_pool(c_pool, trigger_brand, trigger_tier,
                                  trigger_colors, notes):
    """Score the women's-care companions (Epilators today; future hierarchies
    can slot in here without changes).
    Color matters less than hair-styling — epilators are bathroom-shelf items,
    not part of the styling-set aesthetic — so we use the partial weight only.
    """
    if c_pool.empty:
        return c_pool

    pool = _str_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=STR_S_COLOR_PARTIAL,  # downgrade exact to partial
        color_partial_weight=STR_S_COLOR_PARTIAL,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _str_build_wellness_pool(c_pool, trigger_brand, trigger_tier,
                              trigger_colors, notes):
    """Score the wellness companions (Toothbrushes / Scales / Massage).
    These hierarchies are dominated by DIFFERENT brands (ORAL-B, BEURER,
    THERABODY) — straightener brand-match rarely fires here. Falls back to
    price-tier + sales. Color is muted: a body scale in a different color
    from your straightener doesn't read as a mismatch.
    """
    if c_pool.empty:
        return c_pool

    pool = _str_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0,
        color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 STRAIGHTENERS ENGINE — Ισιωτικά Μαλλιών (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Mirror of run_air_fryer_engine: pre-build & score every pool from
# STRAIGHTENER_PRIORITY, then round-robin fill until STRAIGHTENER_SLOT_TARGET
# (=10) slots filled or all pools exhausted.

def run_straighteners_engine(trigger, df_sda, df_history, df_stationery=None):
    """Build up to 10 cross-sell slots for a straightener trigger.

    Round-robin loop through Hair Dryers ×2 → Curlers ×2 → Multistylers →
    Epilator → Fashion Accessories → Personal Care Gifts ×2 → Scale →
    Toothbrush. Round 1 fills 9 slots (PERSONAL CARE takes 2 via max_r1=2).
    Round 2 fills slot 10 from HD overflow (max_total=2 priority-1).

    v28.23 — added df_stationery kwarg so the FASHION ACCESSORIES + PERSONAL
    CARE Stationery impulse-buy pools (slots 5-7) can fill from the
    Stationery sheet. None default keeps backward compat.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _str_price_tier(tprice)
    tcolor_raw = str(trigger.get('Χρώμα', '') or '').strip()
    tcolors = _str_color_group(tcolor_raw)
    is_multi = _str_is_multistyler_trigger(trigger)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Color={tcolor_raw} → {sorted(tcolors)} | Multistyler={is_multi}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + any other straighteners (competitors)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in STRAIGHTENER_TRIGGER_HIERARCHIES}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl straighteners", len(c_sda), f"Removed {b4 - len(c_sda)} competitor straighteners"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_sda['Sales_Tiebreaker'] = 0

    # ── v28.23 — Concatenate Stationery sheet for the impulse pools (slots 5-7).
    # Same pattern as run_curlers_engine. Stationery has Hierarchy/Material/
    # Title/Sales/Price/Availability/Κατασκευαστής but no Χρώμα column at
    # top level — we stub one so the color helper doesn't blow up.
    if df_stationery is not None and not df_stationery.empty:
        stat = df_stationery[df_stationery['Material'] != tm].copy()
        if 'Sum of Sales' in stat.columns:
            stat['Sales_Tiebreaker'] = pd.to_numeric(stat['Sum of Sales'], errors='coerce').fillna(0)
        else:
            stat['Sales_Tiebreaker'] = 0
        if 'Χρώμα' not in stat.columns:
            stat['Χρώμα'] = ''
        c_combined = pd.concat([c_sda, stat], ignore_index=True, sort=False)
        diag.append(("1b. + Stationery", len(c_combined), f"Added {len(stat)} stationery rows for impulse-buy pools"))
    else:
        c_combined = c_sda
        diag.append(("1b. Stationery", 0, "No Stationery sheet provided — impulse pools will be empty"))

    # ── Build a sorted pool per priority entry
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_round_1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total in STRAIGHTENER_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c_combined[c_combined['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Route to the right pool builder by logic_key
        if logic_key == 'STR_HAIRSTYLING':
            scored = _str_build_hairstyling_pool(
                base_pool, tb, ttier, tcolors, is_multi, role_label, notes
            )
        elif logic_key == 'STR_PCARE_ACCESSORY':
            scored = _str_build_accessory_pool(base_pool, tb, ttier, tcolors, notes)
        elif logic_key == 'STR_WOMENS_CARE':
            scored = _str_build_womens_care_pool(base_pool, tb, ttier, tcolors, notes)
        elif logic_key == 'STR_IMPULSE_ACCESSORY':                       # ← NEW v28.23
            scored = _pc_build_impulse_accessory_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,
            )
        elif logic_key == 'STR_WELLNESS':
            scored = _str_build_wellness_pool(base_pool, tb, ttier, tcolors, notes)
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < STRAIGHTENER_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= STRAIGHTENER_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue

            # Hard cap: skip this pool if max_total already reached
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < STRAIGHTENER_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = STRAIGHTENER_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{STRAIGHTENER_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 HAIR DRYERS HELPERS — Πιστολάκια Μαλλιών (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Four pool builders, one per logic_key in HAIR_DRYER_PRIORITY:
#   HD_HAIRSTYLING   — Straighteners / Curlers / Multistylers
#                       (use column brand directly; color matters most here)
#   HD_MENS_GROOMING — Grooming Set / Shaving Machines / Trimmers
#                       (parse brand from title; color match disabled)
#   HD_WELLNESS      — Body Scales / Electric Toothbrushes
#                       (column brand; color match disabled — utilitarian items)
#   HD_WOMENS_CARE   — Epilators
#                       (column brand; soft color hint only)
#
# All four share the _hd_apply_base_score scoring spine: availability → sales →
# brand-match (column OR parsed) → price-tier proximity → optional color.

def _hd_resolve_brand_series(pool):
    """Return a Series of uppercase brand strings for each row of `pool`.
    Uses Κατασκευαστής when populated; falls back to title-parsing for the
    male-grooming hierarchies where Κατασκευαστής is empty.
    Also returns a boolean mask `was_parsed` flagging rows that used the
    fallback (so the engine can apply the slightly smaller HD_S_BRAND_PARSED
    score instead of the full HD_S_BRAND_MATCH).
    """
    if 'Κατασκευαστής' in pool.columns:
        col_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
    else:
        col_brand = pd.Series([''] * len(pool), index=pool.index)

    needs_parse = col_brand == ''
    if needs_parse.any():
        parsed = pool.loc[needs_parse, 'Title'].fillna('').apply(
            lambda t: _str_parse_brand_from_title(t).upper()
        )
        col_brand.loc[needs_parse] = parsed

    return col_brand, needs_parse & (col_brand != '')


def _hd_apply_base_score(pool, trigger_brand, trigger_tier, trigger_colors, notes,
                         color_exact_weight=HD_S_COLOR_EXACT,
                         color_partial_weight=HD_S_COLOR_PARTIAL):
    """Shared scoring spine: availability + sales + brand + price + color.
    Brand-match resolution uses _hd_resolve_brand_series so men's-grooming
    pools (with empty Κατασκευαστής) score on title-parsed brands.
    """
    if pool.empty:
        return pool

    pool = pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        avail_mask = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail_mask, 'Final_Score'] += HD_S_AVAILABILITY
        if avail_mask.any():
            notes.append(f"  ✓ Availability: {avail_mask.sum()} in stock (+{HD_S_AVAILABILITY:,})")

    # ── Base sales score (tiebreaker spine)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * HD_S_SALES_FACTOR

    # ── Brand-ecosystem boost (column-derived OR title-parsed)
    if trigger_brand:
        brand_resolved, was_parsed_mask = _hd_resolve_brand_series(pool)
        same_brand = brand_resolved == trigger_brand
        # Column-derived brand matches → full boost
        col_match_mask = same_brand & ~was_parsed_mask
        # Title-parsed brand matches → slightly smaller boost (less trustworthy)
        parsed_match_mask = same_brand & was_parsed_mask
        pool.loc[col_match_mask,    'Final_Score'] += HD_S_BRAND_MATCH
        pool.loc[parsed_match_mask, 'Final_Score'] += HD_S_BRAND_PARSED
        if col_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, column): "
                         f"{col_match_mask.sum()} (+{HD_S_BRAND_MATCH:,})")
        if parsed_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, title-parsed): "
                         f"{parsed_match_mask.sum()} (+{HD_S_BRAND_PARSED:,})")

    # ── Price-tier proximity (same → boost, ≥2 away → penalty)
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_hd_price_tier)
        diffs = (tiers - trigger_tier).abs()
        same_tier = diffs == 0
        near_tier = diffs == 1
        far_tier = diffs >= 2
        pool.loc[same_tier, 'Final_Score'] += HD_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += HD_S_PRICE_ONE_OFF
        pool.loc[far_tier,  'Final_Score'] += HD_S_PRICE_TWO_OFF
        if same_tier.any() or near_tier.any() or far_tier.any():
            notes.append(f"  ✓ Price-tier match (trigger tier {trigger_tier}): "
                         f"same={same_tier.sum()} (+{HD_S_PRICE_SAME_TIER:,}), "
                         f"near={near_tier.sum()} (+{HD_S_PRICE_ONE_OFF:,}), "
                         f"far={far_tier.sum()} ({HD_S_PRICE_TWO_OFF:+,})")

    # ── Color-group match (only fires when caller asked for it)
    if trigger_colors and 'Χρώμα' in pool.columns and color_exact_weight > 0:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        exact_mask   = pool_colors.apply(lambda g: g == trigger_colors and len(g) > 0)
        partial_mask = pool_colors.apply(lambda g: bool(g & trigger_colors) and g != trigger_colors)
        pool.loc[exact_mask,   'Final_Score'] += color_exact_weight
        pool.loc[partial_mask, 'Final_Score'] += color_partial_weight
        if exact_mask.any() or partial_mask.any():
            trigger_color_label = '/'.join(sorted(trigger_colors)) or 'none'
            notes.append(f"  ✓ Color match ({trigger_color_label}): "
                         f"exact={exact_mask.sum()} (+{color_exact_weight:,}), "
                         f"partial={partial_mask.sum()} (+{color_partial_weight:,})")

    return pool


def _hd_build_hairstyling_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes):
    """STR/CURL/MULTI pool. Column-brand 100% populated → full brand boost.
    Color matters most here (coordinated styling set aesthetic)."""
    if c_pool.empty:
        return c_pool
    pool = _hd_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=HD_S_COLOR_EXACT,
        color_partial_weight=HD_S_COLOR_PARTIAL,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _hd_build_mens_grooming_pool(c_pool, trigger_brand, trigger_tier,
                                  trigger_colors, role_label, notes):
    """GROOMING/SHAVING/TRIMMERS/ΚΟΥΡΕΥΤΙΚΕΣ pool. Brand resolved from title
    (Κατασκευαστής is empty in these hierarchies). Color match disabled —
    male-grooming items skew Μαύρο/Ασημί and color-coordination with a Ροζ
    hair dryer isn't meaningful here."""
    if c_pool.empty:
        return c_pool
    pool = _hd_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0,
        color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _hd_build_womens_care_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes):
    """EPILATORS pool. Column-brand populated. Color match downgraded —
    epilators are bathroom-shelf items, not part of styling-set aesthetic."""
    if c_pool.empty:
        return c_pool
    pool = _hd_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=HD_S_COLOR_PARTIAL,  # downgrade exact to partial
        color_partial_weight=HD_S_COLOR_PARTIAL,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _hd_build_wellness_pool(c_pool, trigger_brand, trigger_tier,
                             trigger_colors, role_label, notes):
    """BODY SCALES / ELECTRIC TOOTHBRUSHES pool. Brand columns populated but
    overlap with HD brands is weak (BODY SCALES 30%, TOOTHBRUSHES 63%) so
    sales + price-tier do most of the work here. Color disabled."""
    if c_pool.empty:
        return c_pool
    pool = _hd_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0,
        color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 HAIR DRYERS ENGINE — Πιστολάκια Μαλλιών (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Mirror of run_straighteners_engine: pre-build & score every pool from
# HAIR_DRYER_PRIORITY, then round-robin fill until 10 slots filled.
# Round 1 fills 9 slots (one per pool). Round 2 overflows from the
# STRAIGHTENERS pool (max_total=2) to fill slot 10.

def run_hair_dryers_engine(trigger, df_sda, df_history, df_stationery=None):
    """Build up to 10 cross-sell slots for a hair-dryer trigger.

    v28.23 slot composition (10 slots / 8 pools):
      1. STR ×2  (max_total=2 — #1 cross-purchase 1399)
      2. CURLERS (hair-styling)
      3. MULTISTYLERS (hair-styling, 100% brand overlap)
      4. GROOMING SET (universal men's grooming, #4 cross-purchase 373)
      5. FASHION ACCESSORIES (impulse)         ← NEW v28.23
      6-7. PERSONAL CARE Stationery ×2 (impulse — max_r1=2 fills both slots)
      8. BODY SCALES (wellness)
      9. ELECTRIC TOOTHBRUSH (wellness)
      10. STR round 2 overflow

    Dropped from prior plan: TRIMMERS (dupe with GROOMING SET, cp 204),
    SHAVING MACHINES (same audience as GROOMING SET, cp 241), EPILATORS
    (weakest brand overlap 3/9, cp 198). Replaced by the 3 impulse slots.

    df_stationery (v28.23) — Stationery sheet from Recommendations
    GitHub.xlsx — contains FASHION ACCESSORIES (hair scrunchies/bands)
    and PERSONAL CARE (hair towels / eye masks) gift hierarchies routed
    through the HD_IMPULSE_ACCESSORY logic_key. None default keeps the
    impulse pools empty (and skipped) for backward compatibility.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _hd_price_tier(tprice)
    tcolor_raw = str(trigger.get('Χρώμα', '') or '').strip()
    tcolors = _str_color_group(tcolor_raw)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Color={tcolor_raw} → {sorted(tcolors)}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + every other hair dryer (competitors)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in HAIR_DRYER_TRIGGER_HIERARCHIES}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl hair dryers", len(c_sda), f"Removed {b4 - len(c_sda)} competitor hair dryers"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_sda['Sales_Tiebreaker'] = 0

    # ── v28.23 — Concatenate Stationery sheet for the impulse pools (slots 5-7)
    if df_stationery is not None and not df_stationery.empty:
        stat = df_stationery[df_stationery['Material'] != tm].copy()
        if 'Sum of Sales' in stat.columns:
            stat['Sales_Tiebreaker'] = pd.to_numeric(stat['Sum of Sales'], errors='coerce').fillna(0)
        else:
            stat['Sales_Tiebreaker'] = 0
        if 'Χρώμα' not in stat.columns:
            stat['Χρώμα'] = ''
        c_combined = pd.concat([c_sda, stat], ignore_index=True, sort=False)
        diag.append(("1b. + Stationery", len(c_combined), f"Added {len(stat)} stationery rows for impulse-buy pools"))
    else:
        c_combined = c_sda
        diag.append(("1b. Stationery", 0, "No Stationery sheet provided — impulse pools will be empty"))

    # ── Build a sorted pool per priority entry
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_round_1, max_total, notes)
    for rank, role_label, hiers, logic_key, max_r1, max_total in HAIR_DRYER_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c_combined[c_combined['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Route to the right pool builder by logic_key
        if logic_key == 'HD_HAIRSTYLING':
            scored = _hd_build_hairstyling_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'HD_MENS_GROOMING':
            scored = _hd_build_mens_grooming_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'HD_IMPULSE_ACCESSORY':                       # ← NEW v28.23
            scored = _pc_build_impulse_accessory_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,
            )
        elif logic_key == 'HD_WELLNESS':
            scored = _hd_build_wellness_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'HD_WOMENS_CARE':
            scored = _hd_build_womens_care_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < HAIR_DRYER_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= HAIR_DRYER_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < HAIR_DRYER_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = HAIR_DRYER_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{HAIR_DRYER_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 CURLERS & BRUSHES HELPERS — Ψαλίδια & Βούρτσες (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Four pool builders, one per logic_key in CURLER_PRIORITY:
#   CB_HAIRSTYLING   — Straighteners / Hair Dryers / Multistylers
#                       (column brand; color matters most; SUBTYPE BIAS on multistylers)
#   CB_MENS_GROOMING — Grooming Set / Shaving Machines
#                       (parse brand from title; color match disabled)
#   CB_WOMENS_CARE   — Epilators
#                       (column brand; soft color hint)
#   CB_WELLNESS      — Body Scales / Electric Toothbrushes
#                       (column brand; color disabled)
#
# All four share _cb_apply_base_score. The hairstyling pool ADDITIONALLY
# applies a multistyler subtype bias when role_label == 'Πολυσυσκευή Styling'.

def _cb_apply_base_score(pool, trigger_brand, trigger_tier, trigger_colors, notes,
                         color_exact_weight=CB_S_COLOR_EXACT,
                         color_partial_weight=CB_S_COLOR_PARTIAL):
    """Shared scoring spine for the curlers engine. Mirrors _hd_apply_base_score
    1:1 (avoiding cross-engine coupling) so future tuning of one category
    doesn't accidentally shift another. Brand resolution reuses the shared
    _hd_resolve_brand_series helper from v28.18 (column → title-parse fallback).
    """
    if pool.empty:
        return pool

    pool = pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        avail_mask = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail_mask, 'Final_Score'] += CB_S_AVAILABILITY
        if avail_mask.any():
            notes.append(f"  ✓ Availability: {avail_mask.sum()} in stock (+{CB_S_AVAILABILITY:,})")

    # ── Base sales score (tiebreaker spine)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * CB_S_SALES_FACTOR

    # ── Brand-ecosystem boost (column-derived OR title-parsed)
    if trigger_brand:
        brand_resolved, was_parsed_mask = _hd_resolve_brand_series(pool)
        same_brand = brand_resolved == trigger_brand
        col_match_mask    = same_brand & ~was_parsed_mask
        parsed_match_mask = same_brand & was_parsed_mask
        pool.loc[col_match_mask,    'Final_Score'] += CB_S_BRAND_MATCH
        pool.loc[parsed_match_mask, 'Final_Score'] += CB_S_BRAND_PARSED
        if col_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, column): "
                         f"{col_match_mask.sum()} (+{CB_S_BRAND_MATCH:,})")
        if parsed_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, title-parsed): "
                         f"{parsed_match_mask.sum()} (+{CB_S_BRAND_PARSED:,})")

    # ── Price-tier proximity
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_str_price_tier)
        diffs = (tiers - trigger_tier).abs()
        same_tier = diffs == 0
        near_tier = diffs == 1
        far_tier = diffs >= 2
        pool.loc[same_tier, 'Final_Score'] += CB_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += CB_S_PRICE_ONE_OFF
        pool.loc[far_tier,  'Final_Score'] += CB_S_PRICE_TWO_OFF
        if same_tier.any() or near_tier.any() or far_tier.any():
            notes.append(f"  ✓ Price-tier match (trigger tier {trigger_tier}): "
                         f"same={same_tier.sum()} (+{CB_S_PRICE_SAME_TIER:,}), "
                         f"near={near_tier.sum()} (+{CB_S_PRICE_ONE_OFF:,}), "
                         f"far={far_tier.sum()} ({CB_S_PRICE_TWO_OFF:+,})")

    # ── Color-group match
    if trigger_colors and 'Χρώμα' in pool.columns and color_exact_weight > 0:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        exact_mask   = pool_colors.apply(lambda g: g == trigger_colors and len(g) > 0)
        partial_mask = pool_colors.apply(lambda g: bool(g & trigger_colors) and g != trigger_colors)
        pool.loc[exact_mask,   'Final_Score'] += color_exact_weight
        pool.loc[partial_mask, 'Final_Score'] += color_partial_weight
        if exact_mask.any() or partial_mask.any():
            trigger_color_label = '/'.join(sorted(trigger_colors)) or 'none'
            notes.append(f"  ✓ Color match ({trigger_color_label}): "
                         f"exact={exact_mask.sum()} (+{color_exact_weight:,}), "
                         f"partial={partial_mask.sum()} (+{color_partial_weight:,})")

    return pool


def _cb_build_hairstyling_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, trigger_subtype_family,
                                role_label, notes):
    """STR / HD / MULTISTYLERS pool. Column-brand 100% populated, color
    matters most. NEW: subtype-bias on the MULTISTYLERS slot only — see
    config block docstring above for rationale.
    """
    if c_pool.empty:
        return c_pool

    pool = _cb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=CB_S_COLOR_EXACT,
        color_partial_weight=CB_S_COLOR_PARTIAL,
    )

    # ── SUBTYPE BIAS (multistyler slot only)
    # If the trigger is a hot-air brush, push brush-leaning multistylers up.
    # If the trigger is a curling iron, push curl-leaning multistylers up.
    # Combo "MULTI" triggers match both families with a half-boost.
    if (role_label == 'Πολυσυσκευή Styling'
            and trigger_subtype_family
            and 'Title' in pool.columns):
        pool_families = pool['Title'].apply(_cb_title_subtype_family)
        # Also fall back to Τύπος συσκευής for the few multistylers with
        # explicit descriptive subtypes in the column.
        if 'Τύπος συσκευής' in pool.columns:
            type_families = pool['Τύπος συσκευής'].apply(_cb_subtype_family)
            # If title classifier returned '' but column has a family, use it
            empty_mask = pool_families == ''
            pool_families.loc[empty_mask] = type_families.loc[empty_mask]

        if trigger_subtype_family == 'MULTI':
            # Combo trigger — gentle boost to anything brush-or-curl-leaning
            match_mask = pool_families.isin(['BRUSH', 'CURL', 'MULTI'])
            pool.loc[match_mask, 'Final_Score'] += CB_S_SUBTYPE_BIAS // 2
        else:
            # Match same family OR multi (combo multistylers fit either trigger)
            match_mask = pool_families.isin([trigger_subtype_family, 'MULTI'])
            pool.loc[match_mask, 'Final_Score'] += CB_S_SUBTYPE_BIAS

        if match_mask.any():
            notes.append(f"  ✓ Multistyler subtype-bias (trigger family={trigger_subtype_family}): "
                         f"{match_mask.sum()} matched (+{CB_S_SUBTYPE_BIAS:,})")

    return pool.sort_values('Final_Score', ascending=False)


def _cb_build_mens_grooming_pool(c_pool, trigger_brand, trigger_tier,
                                  trigger_colors, role_label, notes):
    """Grooming Set / Shaving Machines pool. Κατασκευαστής empty → brand
    resolved via title-parse. Color match disabled (male grooming skews
    Μαύρο/Ασημί and doesn't coordinate with women's curlers)."""
    if c_pool.empty:
        return c_pool
    pool = _cb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0, color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _cb_build_womens_care_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes):
    """EPILATORS pool. Column brand populated. Color match downgraded —
    epilators are bathroom-shelf items not part of styling-set aesthetic.

    v28.21 — Soft male-keyword penalty (CB_S_MALE_PENALTY = -300_000) applied
    to titles flagged by _cb_is_male_coded. Demotes male-marketed products
    (e.g. PHILIPS bodygroomers occasionally classified under EPILATORS) below
    legitimate women's products in the recommendation, without hard-filtering
    them out. Conservative — won't flag "body hair trimmer" or BRAUN BHT250
    style products that are actually women's. See _cb_is_male_coded docstring.
    """
    if c_pool.empty:
        return c_pool
    pool = _cb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=CB_S_COLOR_PARTIAL,
        color_partial_weight=CB_S_COLOR_PARTIAL,
    )

    # ── Male-keyword penalty (women's-care pool only)
    if 'Title' in pool.columns:
        male_mask = pool['Title'].apply(_cb_is_male_coded)
        if male_mask.any():
            pool.loc[male_mask, 'Final_Score'] += CB_S_MALE_PENALTY
            notes.append(f"  ⚠ Male-coded title penalty: {male_mask.sum()} product(s) "
                         f"flagged & demoted ({CB_S_MALE_PENALTY:+,})")

    return pool.sort_values('Final_Score', ascending=False)


def _cb_build_wellness_pool(c_pool, trigger_brand, trigger_tier,
                             trigger_colors, role_label, notes):
    """BODY SCALES / ELECTRIC TOOTHBRUSHES pool. Brand overlap with curlers
    is weak (Scales 13%, Toothbrushes 13%) so sales + price-tier do most of
    the work. Color disabled (utilitarian items)."""
    if c_pool.empty:
        return c_pool
    pool = _cb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0, color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


# v28.23 — _cb_build_impulse_accessory_pool was renamed to
# _pc_build_impulse_accessory_pool and relocated to the top of the
# STRAIGHTENERS HELPERS section above, where it's defined once and used by
# all three hair-care engines (STR, HD, CB). The CB engine still routes its
# CB_IMPULSE_ACCESSORY logic_key to the shared helper.


# ═══════════════════════════════════════════════════════════════
# 🟢 CURLERS & BRUSHES ENGINE — Ψαλίδια & Βούρτσες (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Mirror of run_hair_dryers_engine: pre-build & score every pool from
# CURLER_PRIORITY, then round-robin fill until 10 slots filled.
# Adds device-subtype detection on the trigger row, passed only into the
# hairstyling pool builder (where the multistyler-slot bias fires).

def run_curlers_engine(trigger, df_sda, df_history, df_stationery=None):
    """Build up to 10 cross-sell slots for a curler/brush trigger.

    Slot composition (v28.22): 5 styling-set slots (Straighteners×2, Hair
    Dryers×2, Multistyler ×1) + Epilator + Body Scale + Fashion Accessories
    + Personal Care Stationery gifts + Toothbrush + Massage. Round 1 fills
    9 slots, Round 2 takes 1 overflow from STR priority 1 → slot 10.

    df_stationery (v28.22) is the Stationery sheet from Recommendations
    GitHub.xlsx — contains the FASHION ACCESSORIES (hair scrunchies/bands)
    and PERSONAL CARE (hair towels / eye masks) gift hierarchies routed
    through the CB_IMPULSE_ACCESSORY logic_key. Passed as a kwarg with
    None default so callers that don't have the stationery sheet still
    work (the impulse pools will simply be empty and skipped).
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _str_price_tier(tprice)
    tcolor_raw = str(trigger.get('Χρώμα', '') or '').strip()
    tcolors = _str_color_group(tcolor_raw)
    # ── NEW: subtype family of the trigger (drives multistyler-slot bias)
    ttype_field = str(trigger.get('Τύπος συσκευής', '') or '').strip()
    tsubtype_family = _cb_subtype_family(ttype_field)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Color={tcolor_raw} → {sorted(tcolors)} | "
                 f"Subtype='{ttype_field}' → family={tsubtype_family or '(none)'}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + every other curler (competitors)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in CURLER_TRIGGER_HIERARCHIES}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl curlers", len(c_sda), f"Removed {b4 - len(c_sda)} competitor curlers"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_sda['Sales_Tiebreaker'] = 0

    # ── v28.22 — Concatenate the Stationery sheet for the impulse-accessory pools.
    # Stationery has 'Hierarchy', 'Material', 'Title', 'Sum of Sales', 'LIST PRICE',
    # 'AVAILABILITY', 'Κατασκευαστής' — same column names the engine needs.
    # It does NOT have 'Χρώμα' as a top-level column (it has product-type-specific
    # color columns like 'Χρώμα Γραφής' for pens). We add a stub 'Χρώμα' column
    # so the color-group helper doesn't blow up; partial color match in this pool
    # simply won't fire.
    if df_stationery is not None and not df_stationery.empty:
        stat = df_stationery[df_stationery['Material'] != tm].copy()
        if 'Sum of Sales' in stat.columns:
            stat['Sales_Tiebreaker'] = pd.to_numeric(stat['Sum of Sales'], errors='coerce').fillna(0)
        else:
            stat['Sales_Tiebreaker'] = 0
        if 'Χρώμα' not in stat.columns:
            stat['Χρώμα'] = ''
        # Concatenate — c_sda + stat. The pool filtering by Hierarchy will pick the
        # right rows for each pool regardless of which sheet they came from.
        c_combined = pd.concat([c_sda, stat], ignore_index=True, sort=False)
        diag.append(("1b. + Stationery", len(c_combined), f"Added {len(stat)} stationery rows for impulse-buy pools"))
    else:
        c_combined = c_sda
        diag.append(("1b. Stationery", 0, "No Stationery sheet provided — impulse pools will be empty"))

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, hiers, logic_key, max_r1, max_total in CURLER_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c_combined[c_combined['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        if logic_key == 'CB_HAIRSTYLING':
            scored = _cb_build_hairstyling_pool(
                base_pool, tb, ttier, tcolors, tsubtype_family, role_label, notes
            )
        elif logic_key == 'CB_MENS_GROOMING':
            scored = _cb_build_mens_grooming_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'CB_WELLNESS':
            scored = _cb_build_wellness_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'CB_WOMENS_CARE':
            scored = _cb_build_womens_care_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'CB_IMPULSE_ACCESSORY':                       # ← NEW v28.22
            scored = _pc_build_impulse_accessory_pool(                  # ← renamed v28.23
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,                                    # ← v28.27
            )
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < CURLER_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= CURLER_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < CURLER_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = CURLER_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{CURLER_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 MULTISTYLERS HELPERS — Πολυσυσκευές Styling (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Four pool builders, one per logic_key in MULTISTYLER_PRIORITY:
#   MS_HAIRSTYLING        — Hair Dryers / Straighteners / Curlers
#   MS_WOMENS_CARE        — Epilators
#   MS_WELLNESS           — Body Scales / Electric Toothbrushes
#   MS_IMPULSE_ACCESSORY  — Fashion Accessories / Personal Care Stationery
#                            → delegates to shared _pc_build_impulse_accessory_pool
#
# All four (except impulse) share _ms_apply_base_score scoring spine.
# Brand resolution uses the shared _hd_resolve_brand_series helper
# (column → title-parse fallback) — though for multistylers companions
# all have populated Κατασκευαστής, so title-parsing won't fire often.

def _ms_apply_base_score(pool, trigger_brand, trigger_tier, trigger_colors, notes,
                         trigger_price=0.0,
                         color_exact_weight=MS_S_COLOR_EXACT,
                         color_partial_weight=MS_S_COLOR_PARTIAL):
    """Shared scoring spine for the multistylers engine — availability +
    sales + brand-match + price-tier + color + (v28.26) price-proximity.
    Mirrors _cb_apply_base_score with MS_S_* constants. trigger_price
    needed for the continuous proximity bonus added in v28.26.
    """
    if pool.empty:
        return pool

    pool = pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        avail_mask = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail_mask, 'Final_Score'] += MS_S_AVAILABILITY
        if avail_mask.any():
            notes.append(f"  ✓ Availability: {avail_mask.sum()} in stock (+{MS_S_AVAILABILITY:,})")

    # ── Base sales score (tiebreaker spine)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * MS_S_SALES_FACTOR

    # ── Brand-ecosystem boost (column-derived OR title-parsed)
    if trigger_brand:
        brand_resolved, was_parsed_mask = _hd_resolve_brand_series(pool)
        same_brand = brand_resolved == trigger_brand
        col_match_mask    = same_brand & ~was_parsed_mask
        parsed_match_mask = same_brand & was_parsed_mask
        pool.loc[col_match_mask,    'Final_Score'] += MS_S_BRAND_MATCH
        pool.loc[parsed_match_mask, 'Final_Score'] += MS_S_BRAND_PARSED
        if col_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, column): "
                         f"{col_match_mask.sum()} (+{MS_S_BRAND_MATCH:,})")
        if parsed_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, title-parsed): "
                         f"{parsed_match_mask.sum()} (+{MS_S_BRAND_PARSED:,})")

    # ── Price-tier proximity (critical for multistylers — €549 DYSON
    # buyer must not see €15 IZZY epilators). Penalty is strong enough
    # to push 2+ tier-away items below brand-match candidates.
    # v28.26 — Uses the granular 8-bucket _ms_price_tier instead of the
    # shared 4-bucket _str_price_tier. Avoids the case where everything
    # >€250 was a single open-ended bucket and a €1398 massager looked
    # like a "same-tier" match for a €549 trigger.
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_ms_price_tier)
        diffs = (tiers - trigger_tier).abs()
        same_tier = diffs == 0
        near_tier = diffs == 1
        far_tier = diffs >= 2
        pool.loc[same_tier, 'Final_Score'] += MS_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += MS_S_PRICE_ONE_OFF
        pool.loc[far_tier,  'Final_Score'] += MS_S_PRICE_TWO_OFF
        if same_tier.any() or near_tier.any() or far_tier.any():
            notes.append(f"  ✓ Price-tier match (trigger tier {trigger_tier}, 8-bucket): "
                         f"same={same_tier.sum()} (+{MS_S_PRICE_SAME_TIER:,}), "
                         f"near={near_tier.sum()} (+{MS_S_PRICE_ONE_OFF:,}), "
                         f"far={far_tier.sum()} ({MS_S_PRICE_TWO_OFF:+,})")

        # ── v28.26 — Continuous price-proximity bonus (Gaussian).
        # The 8-tier system handles the coarse "expensive vs cheap" question,
        # but when an ENTIRE pool falls into one tier-distance bucket (e.g.
        # the CURLERS catalog tops out at €199, so for a €549 trigger ALL
        # curlers are "far tier" with the same -150k penalty), tier scoring
        # alone can't pick the best of bad options — sales tiebreaker wins
        # by default, surfacing high-volume budget items (BABYLISS Bouncy
        # Curles €59) instead of the catalog's most-price-appropriate option
        # (REMINGTON AIRV €159 or BELLISSIMA STEAM ELIXIR €138).
        #
        # Solution: a smooth Gaussian-shaped bonus peaking at exact-match
        # price, decaying with log-distance. Max +MS_S_PROXIMITY_MAX at
        # ratio=1.0, decays to near zero past 4x or 0.25x trigger price.
        # Small enough to NOT override brand-match (+500k) or same-tier
        # (+250k), but large enough to break ties when those don't
        # differentiate (e.g. all-far-tier pools).
        if trigger_price > 0:
            import math as _math
            def _ms_proximity_bonus(p):
                if p is None or p <= 0:
                    return 0
                try:
                    log_dist = abs(_math.log(p / trigger_price))
                    return int(MS_S_PROXIMITY_MAX * _math.exp(-(log_dist ** 2) / 1.0))
                except (ValueError, ZeroDivisionError):
                    return 0
            proximity_scores = prices.apply(_ms_proximity_bonus)
            pool['Final_Score'] += proximity_scores
            max_prox = proximity_scores.max() if not proximity_scores.empty else 0
            min_prox = proximity_scores.min() if not proximity_scores.empty else 0
            notes.append(f"  ✓ Price-proximity bonus (trigger €{trigger_price:.0f}, Gaussian): "
                         f"range +{min_prox:,} to +{max_prox:,} of max +{MS_S_PROXIMITY_MAX:,}")

    # ── Color-group match (only fires when caller asks for it)
    if trigger_colors and 'Χρώμα' in pool.columns and color_exact_weight > 0:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        exact_mask   = pool_colors.apply(lambda g: g == trigger_colors and len(g) > 0)
        partial_mask = pool_colors.apply(lambda g: bool(g & trigger_colors) and g != trigger_colors)
        pool.loc[exact_mask,   'Final_Score'] += color_exact_weight
        pool.loc[partial_mask, 'Final_Score'] += color_partial_weight
        if exact_mask.any() or partial_mask.any():
            trigger_color_label = '/'.join(sorted(trigger_colors)) or 'none'
            notes.append(f"  ✓ Color match ({trigger_color_label}): "
                         f"exact={exact_mask.sum()} (+{color_exact_weight:,}), "
                         f"partial={partial_mask.sum()} (+{color_partial_weight:,})")

    return pool


def _ms_build_hairstyling_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes,
                                trigger_price=0.0):
    """STR / HD / CURLERS pool. Column-brand populated 100% in all three.
    Color matters most — coordinated styling-set aesthetic (women buying
    a Dyson Airwrap in Strawberry Bronze may want a matching Dyson
    Supersonic in similar Pink/Bronze)."""
    if c_pool.empty:
        return c_pool
    pool = _ms_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        trigger_price=trigger_price,
        color_exact_weight=MS_S_COLOR_EXACT,
        color_partial_weight=MS_S_COLOR_PARTIAL,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _ms_build_womens_care_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes,
                                trigger_price=0.0):
    """EPILATORS pool. Brand overlap is weak (1/9), so sales + price-tier
    do most of the work. Color downgraded to soft partial — epilators
    aren't part of the styling-set aesthetic.

    Applies the same male-coded title penalty as the curlers engine, since
    the multistyler audience is also women-leaning (Dyson Airwrap class).
    """
    if c_pool.empty:
        return c_pool
    pool = _ms_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        trigger_price=trigger_price,
        color_exact_weight=MS_S_COLOR_PARTIAL,
        color_partial_weight=MS_S_COLOR_PARTIAL,
    )

    # ── Male-keyword penalty (reuse shared helper from CB)
    if 'Title' in pool.columns:
        male_mask = pool['Title'].apply(_cb_is_male_coded)
        if male_mask.any():
            pool.loc[male_mask, 'Final_Score'] += CB_S_MALE_PENALTY
            notes.append(f"  ⚠ Male-coded title penalty: {male_mask.sum()} product(s) "
                         f"flagged & demoted ({CB_S_MALE_PENALTY:+,})")

    return pool.sort_values('Final_Score', ascending=False)


def _ms_build_wellness_pool(c_pool, trigger_brand, trigger_tier,
                             trigger_colors, role_label, notes,
                             trigger_price=0.0):
    """BODY SCALES / ELECTRIC TOOTHBRUSHES pool. Near-zero brand overlap
    with multistyler brands (1/23 and 0/8 respectively) — pure sales +
    price-tier scoring. Color disabled (wellness items are utilitarian)."""
    if c_pool.empty:
        return c_pool
    pool = _ms_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        trigger_price=trigger_price,
        color_exact_weight=0, color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 MULTISTYLERS ENGINE — Πολυσυσκευές Styling (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Mirror of run_curlers_engine without the subtype-bias logic. Multistylers
# don't need subtype detection because they're already the all-in-one
# device — there's no functional axis along which one multistyler differs
# from another (unlike Curlers' brush-vs-iron split).

def run_multistylers_engine(trigger, df_sda, df_history, df_stationery=None):
    """Build up to 10 cross-sell slots for a multistyler trigger.

    Slot composition (v28.24, 10 slots / 9 pools):
      1. HD ×2  (max_total=2 — #1 cross-purchase 110)
      2. STR ×2 (max_total=2 — #2 cross-purchase 93)
      3. CURLERS — alternative hair-styling
      4. EPILATORS — women's care (male-coded title penalty applied)
      5-7. Impulse accessories from Stationery sheet (FASHION + PC×2)
      8. BODY SCALES (wellness)
      9. ELECTRIC TOOTHBRUSHES (wellness)
      10. HD round 2 overflow

    Excluded male-grooming categories (GROOMING SET, SHAVING MACHINES,
    TRIMMERS, ΚΟΥΡΕΥΤΙΚΕΣ ΜΗΧΑΝΕΣ) — multistyler audience is predominantly
    women's hair-styling, same as Curlers/Straighteners.

    Premium-price profile note: mean multistyler price is €373 (DYSON
    Airwrap class). Price-tier proximity scoring will keep budget items
    away from a €549 trigger and conversely keep premium items away from
    a €30 LEXICAL or €100 IZZY trigger.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _ms_price_tier(tprice)                              # v28.26 — 8-bucket
    tcolor_raw = str(trigger.get('Χρώμα', '') or '').strip()
    tcolors = _str_color_group(tcolor_raw)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier}/7 (8-bucket) | Color={tcolor_raw} → {sorted(tcolors)}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + every other multistyler (competitors)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in MULTISTYLER_TRIGGER_HIERARCHIES}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl multistylers", len(c_sda), f"Removed {b4 - len(c_sda)} competitor multistylers"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_sda['Sales_Tiebreaker'] = 0

    # ── Concatenate Stationery sheet for the impulse pools (slots 5-7)
    if df_stationery is not None and not df_stationery.empty:
        stat = df_stationery[df_stationery['Material'] != tm].copy()
        if 'Sum of Sales' in stat.columns:
            stat['Sales_Tiebreaker'] = pd.to_numeric(stat['Sum of Sales'], errors='coerce').fillna(0)
        else:
            stat['Sales_Tiebreaker'] = 0
        if 'Χρώμα' not in stat.columns:
            stat['Χρώμα'] = ''
        c_combined = pd.concat([c_sda, stat], ignore_index=True, sort=False)
        diag.append(("1b. + Stationery", len(c_combined), f"Added {len(stat)} stationery rows for impulse-buy pools"))
    else:
        c_combined = c_sda
        diag.append(("1b. Stationery", 0, "No Stationery sheet provided — impulse pools will be empty"))

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, hiers, logic_key, max_r1, max_total in MULTISTYLER_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c_combined[c_combined['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        if logic_key == 'MS_HAIRSTYLING':
            scored = _ms_build_hairstyling_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,
            )
        elif logic_key == 'MS_WOMENS_CARE':
            scored = _ms_build_womens_care_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,
            )
        elif logic_key == 'MS_WELLNESS':
            scored = _ms_build_wellness_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,
            )
        elif logic_key == 'MS_IMPULSE_ACCESSORY':
            scored = _pc_build_impulse_accessory_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,                                    # ← v28.27
            )
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < MULTISTYLER_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= MULTISTYLER_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < MULTISTYLER_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = MULTISTYLER_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{MULTISTYLER_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 ELECTRIC BRUSHES HELPERS — Ηλεκτρικές Βούρτσες (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Three pool builders, one per logic_key in ELECTRIC_BRUSH_PRIORITY:
#   EB_HAIRSTYLING        — Hair Dryers / Straighteners / Curlers & Brushes
#   EB_WOMENS_CARE        — Epilators (with male-coded title penalty)
#   EB_WELLNESS           — Body Scales / Electric Toothbrushes
#   EB_IMPULSE_ACCESSORY  — Fashion Accessories / Personal Care Stationery
#                            → delegates to shared _pc_build_impulse_accessory_pool
#
# Mirror of the Curlers / Multistylers helper pattern with EB_S_* constants.
# Brand resolution uses the shared _hd_resolve_brand_series helper since
# the EB brands (IQ, LEXICAL, REVLON, SOGO) are all populated in
# Κατασκευαστής column anyway — title-parsing rarely fires.

def _eb_apply_base_score(pool, trigger_brand, trigger_tier, trigger_colors, notes,
                         color_exact_weight=EB_S_COLOR_EXACT,
                         color_partial_weight=EB_S_COLOR_PARTIAL):
    """Shared scoring spine for the electric brushes engine — availability +
    sales + brand-match + price-tier + color. Mirrors _ms_apply_base_score
    using EB_S_* constants and the 4-bucket _str_price_tier.
    """
    if pool.empty:
        return pool

    pool = pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        avail_mask = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail_mask, 'Final_Score'] += EB_S_AVAILABILITY
        if avail_mask.any():
            notes.append(f"  ✓ Availability: {avail_mask.sum()} in stock (+{EB_S_AVAILABILITY:,})")

    # ── Base sales score (tiebreaker spine)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * EB_S_SALES_FACTOR

    # ── Brand-ecosystem boost (column-derived OR title-parsed via shared helper)
    if trigger_brand:
        brand_resolved, was_parsed_mask = _hd_resolve_brand_series(pool)
        same_brand = brand_resolved == trigger_brand
        col_match_mask    = same_brand & ~was_parsed_mask
        parsed_match_mask = same_brand & was_parsed_mask
        pool.loc[col_match_mask,    'Final_Score'] += EB_S_BRAND_MATCH
        pool.loc[parsed_match_mask, 'Final_Score'] += EB_S_BRAND_PARSED
        if col_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, column): "
                         f"{col_match_mask.sum()} (+{EB_S_BRAND_MATCH:,})")
        if parsed_match_mask.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, title-parsed): "
                         f"{parsed_match_mask.sum()} (+{EB_S_BRAND_PARSED:,})")

    # ── Price-tier proximity (4-bucket _str_price_tier, sufficient for
    # the €19-€204 EB price range)
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_str_price_tier)
        diffs = (tiers - trigger_tier).abs()
        same_tier = diffs == 0
        near_tier = diffs == 1
        far_tier = diffs >= 2
        pool.loc[same_tier, 'Final_Score'] += EB_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += EB_S_PRICE_ONE_OFF
        pool.loc[far_tier,  'Final_Score'] += EB_S_PRICE_TWO_OFF
        if same_tier.any() or near_tier.any() or far_tier.any():
            notes.append(f"  ✓ Price-tier match (trigger tier {trigger_tier}): "
                         f"same={same_tier.sum()} (+{EB_S_PRICE_SAME_TIER:,}), "
                         f"near={near_tier.sum()} (+{EB_S_PRICE_ONE_OFF:,}), "
                         f"far={far_tier.sum()} ({EB_S_PRICE_TWO_OFF:+,})")

    # ── Color-group match
    if trigger_colors and 'Χρώμα' in pool.columns and color_exact_weight > 0:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        exact_mask   = pool_colors.apply(lambda g: g == trigger_colors and len(g) > 0)
        partial_mask = pool_colors.apply(lambda g: bool(g & trigger_colors) and g != trigger_colors)
        pool.loc[exact_mask,   'Final_Score'] += color_exact_weight
        pool.loc[partial_mask, 'Final_Score'] += color_partial_weight
        if exact_mask.any() or partial_mask.any():
            trigger_color_label = '/'.join(sorted(trigger_colors)) or 'none'
            notes.append(f"  ✓ Color match ({trigger_color_label}): "
                         f"exact={exact_mask.sum()} (+{color_exact_weight:,}), "
                         f"partial={partial_mask.sum()} (+{color_partial_weight:,})")

    return pool


def _eb_build_hairstyling_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes):
    """HD / STR / CURLERS pool. EB brands (IQ, LEXICAL, REVLON, SOGO)
    have perfect overlap with HD (4/4), decent with STR (2/4) and
    CURLERS (3/4). Brand-match boost is the strongest signal.
    """
    if c_pool.empty:
        return c_pool
    pool = _eb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=EB_S_COLOR_EXACT,
        color_partial_weight=EB_S_COLOR_PARTIAL,
    )
    return pool.sort_values('Final_Score', ascending=False)


def _eb_build_womens_care_pool(c_pool, trigger_brand, trigger_tier,
                                trigger_colors, role_label, notes):
    """EPILATORS pool. Brand overlap weak (1/9 — only LEXICAL), so sales
    + price-tier do most of the work. Color downgraded to soft partial.

    Applies the same male-coded title penalty as the curlers/multistylers
    engines — the dominant EB audience is women's hair styling, so male
    products in the EPILATORS pool (e.g. "men's body trimmer") should be
    demoted.
    """
    if c_pool.empty:
        return c_pool
    pool = _eb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=EB_S_COLOR_PARTIAL,
        color_partial_weight=EB_S_COLOR_PARTIAL,
    )

    # ── Male-keyword penalty (reuse shared helper from CB)
    if 'Title' in pool.columns:
        male_mask = pool['Title'].apply(_cb_is_male_coded)
        if male_mask.any():
            pool.loc[male_mask, 'Final_Score'] += CB_S_MALE_PENALTY
            notes.append(f"  ⚠ Male-coded title penalty: {male_mask.sum()} product(s) "
                         f"flagged & demoted ({CB_S_MALE_PENALTY:+,})")

    return pool.sort_values('Final_Score', ascending=False)


def _eb_build_wellness_pool(c_pool, trigger_brand, trigger_tier,
                             trigger_colors, role_label, notes):
    """BODY SCALES / ELECTRIC TOOTHBRUSHES pool. Near-zero brand overlap
    with EB brands — pure sales + price-tier scoring. Color disabled."""
    if c_pool.empty:
        return c_pool
    pool = _eb_apply_base_score(
        c_pool, trigger_brand, trigger_tier, trigger_colors, notes,
        color_exact_weight=0, color_partial_weight=0,
    )
    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 ELECTRIC BRUSHES ENGINE — Ηλεκτρικές Βούρτσες (Personal Care)
# ═══════════════════════════════════════════════════════════════
# Mirror of run_curlers_engine without the subtype-bias logic (EB doesn't
# need it — it's a more uniform category than CURLERS & BRUSHES which
# heterogeneously mixes curling irons and hot-air brushes).

def run_electric_brushes_engine(trigger, df_sda, df_history, df_stationery=None):
    """Build up to 10 cross-sell slots for an electric brush trigger.

    Slot composition (v28.28, 10 slots / 8 pools):
      1. HAIR DRYERS ×2 (max_total=2 — perfect brand overlap 4/4)
      2. STRAIGHTENERS (alt hair-styling)
      3. CURLERS & BRUSHES (alt hair-styling — heated tools)
      4. EPILATORS (women's care, male-coded penalty applied)
      5-7. Impulse accessories from Stationery sheet (FASHION + PC×2)
      8. BODY SCALES (wellness)
      9. ELECTRIC TOOTHBRUSHES (wellness)
      10. HD round 2 overflow

    Excluded MULTISTYLERS and male-grooming categories. MULTI has only
    1/8 brand overlap (just LEXICAL) — weakest of all candidates. Male
    grooming categories have zero brand overlap with any EB brand.

    Note: With 11 SKUs and 4 brands total, this is the smallest of the 5
    hair-care engines. Trigger pool is intentionally restricted to 4 test
    SKUs (REVLON €80, SOGO €204, IQ €109, LEXICAL €19) via
    ELECTRIC_BRUSH_TEST_SKUS — clear the set to enable all 11.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tmodel = str(trigger.get('Μοντέλο', '')).strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _str_price_tier(tprice)                              # 4-bucket
    tcolor_raw = str(trigger.get('Χρώμα', '') or '').strip()
    tcolors = _str_color_group(tcolor_raw)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Model={tmodel} | Tier={ttier} | Color={tcolor_raw} → {sorted(tcolors)}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + every other electric brush (competitors)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trigger_hiers = {h.upper().strip() for h in ELECTRIC_BRUSH_TRIGGER_HIERARCHIES}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trigger_hiers)]
    diag.append(("1. Excl electric brushes", len(c_sda), f"Removed {b4 - len(c_sda)} competitor electric brushes"))

    # ── Sales tiebreaker prep
    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_sda['Sales_Tiebreaker'] = 0

    # ── Concatenate Stationery sheet for the impulse pools (slots 5-7)
    if df_stationery is not None and not df_stationery.empty:
        stat = df_stationery[df_stationery['Material'] != tm].copy()
        if 'Sum of Sales' in stat.columns:
            stat['Sales_Tiebreaker'] = pd.to_numeric(stat['Sum of Sales'], errors='coerce').fillna(0)
        else:
            stat['Sales_Tiebreaker'] = 0
        if 'Χρώμα' not in stat.columns:
            stat['Χρώμα'] = ''
        c_combined = pd.concat([c_sda, stat], ignore_index=True, sort=False)
        diag.append(("1b. + Stationery", len(c_combined), f"Added {len(stat)} stationery rows for impulse-buy pools"))
    else:
        c_combined = c_sda
        diag.append(("1b. Stationery", 0, "No Stationery sheet provided — impulse pools will be empty"))

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, hiers, logic_key, max_r1, max_total in ELECTRIC_BRUSH_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c_combined[c_combined['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        if logic_key == 'EB_HAIRSTYLING':
            scored = _eb_build_hairstyling_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'EB_WOMENS_CARE':
            scored = _eb_build_womens_care_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'EB_WELLNESS':
            scored = _eb_build_wellness_pool(
                base_pool, tb, ttier, tcolors, role_label, notes
            )
        elif logic_key == 'EB_IMPULSE_ACCESSORY':
            scored = _pc_build_impulse_accessory_pool(
                base_pool, tb, ttier, tcolors, role_label, notes,
                trigger_price=tprice,                                    # ← v28.27 premium scaling
            )
        else:
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < ELECTRIC_BRUSH_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= ELECTRIC_BRUSH_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < ELECTRIC_BRUSH_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue

                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = ELECTRIC_BRUSH_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{ELECTRIC_BRUSH_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 WASHING MACHINES HELPERS — Πλυντήρια Ρούχων (Μεγάλες Συσκευές)
# ═══════════════════════════════════════════════════════════════
# Five pool builders + one accessory subset filter. The engine follows the
# same looping pattern as Robot/Traditional/Stick Vacuums and Air Fryers:
# pre-build & score every pool, then round-robin fill until 10 slots filled
# or all pools exhausted.

def _wm_filter_accessory_subset(c_pool, subset_key, notes):
    """Filter the Αξεσουάρ Πλυντηρίου - Στεγνωτηρίου pool down to one of the
    four sub-slot keys defined in WM_ACC_KEYWORDS. Matching is on the Είδος
    column (case-insensitive substring).

    Special case: WM_ACC_BASE explicitly EXCLUDES rows where Είδος contains
    'σύνδεσ' or 'συνδετικ' — those belong to WM_ACC_STACK. Without that
    filter, the broad 'βάσ' stem would also match 'Βάσεις Σύνδεσης
    Πλυντηρίου - Στεγνωτηρίου' (32 rows) and steal them from the stacking
    slot.
    """
    if c_pool.empty:
        return c_pool

    keywords = WM_ACC_KEYWORDS.get(subset_key, ())
    if not keywords:
        notes.append(f"  ⚠ No keywords defined for {subset_key} — returning empty pool")
        return c_pool.iloc[0:0]

    if 'Είδος' not in c_pool.columns:
        notes.append(f"  ⚠ 'Είδος' column missing — accessory subset filter is a no-op")
        return c_pool.iloc[0:0]

    eidos_lower = c_pool['Είδος'].fillna('').astype(str).str.lower()
    match_mask = pd.Series(False, index=c_pool.index)
    for kw in keywords:
        match_mask = match_mask | eidos_lower.str.contains(kw, regex=False, na=False)

    # Subtract stacking keywords from the generic-base bucket so we don't
    # double-count "Βάσεις Σύνδεσης" under both WM_ACC_STACK and WM_ACC_BASE.
    if subset_key == 'WM_ACC_BASE':
        stack_kw = WM_ACC_KEYWORDS.get('WM_ACC_STACK', ())
        for kw in stack_kw:
            match_mask = match_mask & ~eidos_lower.str.contains(kw, regex=False, na=False)

    out = c_pool[match_mask].copy()
    notes.append(f"  ✓ Subset filter ({subset_key}): {len(out)} / {len(c_pool)} rows match Είδος keywords {list(keywords)}")
    return out


def _wm_build_dryer_pool(c_pool, trigger_specs, trigger_tier, notes):
    """Score the Στεγνωτήρια pool — the highest-cross-sell companion slot.

    Signals stacked (most important first):
      1. Brand match: same Κατασκευαστής as trigger → +600,000
         (matched pair is the #1 reason people buy dryer with washer)
      2. Capacity tier: dryer cap in same tier as washer → +400,000
         (a 9kg washer pairs with 8-10kg dryer, NOT 6kg)
      3. Price tier proximity: ±0 → +200,000, ±1 → +70,000
      4. Heat pump (for premium triggers): tier≥1 trigger → +80,000 if HP
         (heat-pump dryers are the modern, efficient type)
      5. Wi-Fi mirror: trigger has Wi-Fi → matched Wi-Fi dryer → +40,000
      6. Sales tiebreaker.
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += WM_S_AVAILABILITY

    # ── Sales baseline
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * WM_S_SALES_FACTOR

    # ── Parse dryer specs from title (no MDA spec columns to lean on)
    dryer_specs = pool['Title'].fillna('').astype(str).apply(_wm_parse_specs)
    pool['_wm_dryer_brand']    = dryer_specs.apply(lambda d: d['brand'])
    pool['_wm_dryer_cap']      = dryer_specs.apply(lambda d: d['capacity_kg'])
    pool['_wm_dryer_cap_tier'] = pool['_wm_dryer_cap'].apply(_wm_capacity_tier)
    pool['_wm_dryer_hp']       = dryer_specs.apply(lambda d: d['heat_pump'])
    pool['_wm_dryer_wifi']     = dryer_specs.apply(lambda d: d['wifi'])

    # ── 1. Brand match (matched pair)
    tbrand = (trigger_specs.get('brand') or '').upper().strip()
    if tbrand:
        same_brand = pool['_wm_dryer_brand'].str.upper().str.strip() == tbrand
        pool.loc[same_brand, 'Final_Score'] += WM_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Brand match ({tbrand}): {same_brand.sum()} matched-pair dryers (+{WM_S_BRAND_MATCH:,})")

    # ── 2. Capacity tier match (a 9kg washer pairs with 8-10kg dryer)
    t_cap_tier = _wm_capacity_tier(trigger_specs.get('capacity_kg'))
    if t_cap_tier >= 0:
        same_tier = pool['_wm_dryer_cap_tier'] == t_cap_tier
        near_tier = (pool['_wm_dryer_cap_tier'] - t_cap_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += WM_S_CAP_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += WM_S_CAP_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Capacity-tier match (trigger tier {t_cap_tier} / {trigger_specs.get('capacity_kg')}kg): "
                         f"same={same_tier.sum()}, ±1={near_tier.sum()}")

    # ── 3. Price-tier proximity
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_wm_price_tier)
        same_p = tiers == trigger_tier
        near_p = (tiers - trigger_tier).abs() == 1
        pool.loc[same_p, 'Final_Score'] += WM_S_PRICE_SAME_TIER
        pool.loc[near_p, 'Final_Score'] += WM_S_PRICE_ONE_OFF
        if same_p.any() or near_p.any():
            notes.append(f"  ✓ Price-tier match (tier {trigger_tier}): "
                         f"same={same_p.sum()}, near={near_p.sum()}")

    # ── 4. Heat pump preference (only for trigger tier ≥ 1)
    if trigger_tier >= 1:
        hp_mask = pool['_wm_dryer_hp'] == True
        pool.loc[hp_mask, 'Final_Score'] += WM_S_HEAT_PUMP_BOOST
        if hp_mask.any():
            notes.append(f"  ✓ Heat-pump preference (premium trigger): {hp_mask.sum()} HP dryers (+{WM_S_HEAT_PUMP_BOOST:,})")

    # ── 5. Wi-Fi mirror
    if trigger_specs.get('wifi'):
        wifi_mask = pool['_wm_dryer_wifi'] == True
        pool.loc[wifi_mask, 'Final_Score'] += WM_S_WIFI_MATCH
        if wifi_mask.any():
            notes.append(f"  ✓ Wi-Fi mirror (trigger has Wi-Fi): {wifi_mask.sum()} Wi-Fi dryers (+{WM_S_WIFI_MATCH:,})")

    notes.append(f"  Pool size after scoring: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _wm_build_accessory_brand_pool(c_pool, trigger_brand, notes, role_label):
    """Score an accessory pool where brand-match is preferred (stacking kits,
    pedestals). Logic:
      • Same brand as trigger        → +600,000  (matched-pair compatibility)
      • Universal accessory brand    → +180,000  (ROLLER/MELICONI fit anything)
      • Other branded items          → neutral (sales decides)
      • Wrong brand (stacking kits)  → -300,000  (physically incompatible)
        — only applied when subset is WM_ACC_STACK, since stacking kits are
          brand-specific by design.
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += WM_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * WM_S_SALES_FACTOR

    tb = (trigger_brand or '').upper().strip()
    if 'Κατασκευαστής' in pool.columns:
        cand_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        same_brand = (cand_brand == tb) if tb else pd.Series(False, index=pool.index)
        universal  = cand_brand.isin(WM_UNIVERSAL_ACC_BRANDS)

        pool.loc[same_brand, 'Final_Score'] += WM_S_BRAND_MATCH
        pool.loc[universal,  'Final_Score'] += WM_S_UNIVERSAL_ACC

        # Wrong-brand stacking kits: HARD drop (v28.49.4 — was a -300k
        # penalty, but penalties can still surface when the pool thins;
        # a BOSCH stacking kit physically won't fit an LG pair, so this
        # is a compatibility gate, not a preference).
        if role_label == 'Βάση Σύνδεσης' and tb:
            wrong_brand = (~same_brand) & (~universal) & (cand_brand != '')
            if wrong_brand.any():
                notes.append(f"  ✗ HARD-dropped {wrong_brand.sum()} stacking kits for other brands (physically incompatible)")
            pool = pool[~wrong_brand]
            same_brand = same_brand[pool.index]
            universal = universal[pool.index]
            if pool.empty:
                notes.append(f"  ⚠ No {tb}/universal stacking kit — slot backfills")
                return pool

        if same_brand.any():
            notes.append(f"  ✓ Brand match ({tb}): {same_brand.sum()} same-brand accessories (+{WM_S_BRAND_MATCH:,})")
        if universal.any():
            notes.append(f"  ✓ Universal accessory brands: {universal.sum()} fits-any items (+{WM_S_UNIVERSAL_ACC:,})")

    return pool.sort_values('Final_Score', ascending=False)


def _wm_build_accessory_universal_pool(c_pool, trigger_brand, notes):
    """Score a 'universal-need' accessory pool (anti-vibration pads,
    detergents, fragrance) — with one HARD exception (v28.49.4,
    user-reported): appliance-brand SYSTEM consumables are NOT universal.
    MIELE FA* flacons only slot into Miele dryers' FragranceDos socket,
    MIELE UltraPhase cartridges only into TwinDos W1 washers, CapDosing
    caps only into Miele drawers. The old 'soft brand kicker' wrongly let
    an LG trigger surface a MIELE flacon. Rule (same shape as the cookers
    rival filter): a row branded by an appliance manufacturer is kept ONLY
    when it matches the trigger brand; neutral consumer brands (ROLLER,
    SCANPART, CARE+PROTECT…) remain universal."""
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()

    tb_gate = (trigger_brand or '').upper().strip()
    if 'Κατασκευαστής' in pool.columns:
        cb = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        # _CK_APPLIANCE_BRANDS is the shared appliance-manufacturer set
        # defined in the COOKERS CONFIGURATION block (module-level, loads
        # before this helper) — same rival universe, same policy.
        system_locked = cb.isin(_CK_APPLIANCE_BRANDS) & (cb != tb_gate)
        if system_locked.any():
            notes.append(f"  ✗ HARD-dropped {system_locked.sum()} brand-system consumables ({sorted(cb[system_locked].unique())[:4]} — dosing/fragrance parts fit only their own machines)")
        pool = pool[~system_locked]
        if pool.empty:
            notes.append("  ⚠ No universal/own-brand consumables left — slot backfills")
            return pool

    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += WM_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * WM_S_SALES_FACTOR

    tb = (trigger_brand or '').upper().strip()
    pool['_wm_feature_locked'] = False
    if tb and 'Κατασκευαστής' in pool.columns:
        cand_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        same_brand = cand_brand == tb
        # Lighter boost than for stacking kits — these are universal-fit
        # consumables, the brand boost is just a small kicker.
        pool.loc[same_brand, 'Final_Score'] += WM_S_BRAND_NEIGHBOR
        if same_brand.any():
            notes.append(f"  ✓ Same-brand consumables ({tb}): {same_brand.sum()} (+{WM_S_BRAND_NEIGHBOR:,})")

        # FEATURE-LOCKED demotion (v28.50.1, user challenge): same brand is
        # NOT proof of fit for dosing/fragrance SYSTEM consumables — a MIELE
        # FA* flacon needs a FragranceDos slot, UltraPhase needs TwinDos,
        # and the catalog has no per-model feature flags to verify the
        # specific trigger has them. These items stay eligible for their
        # own brand, but demoted out of the carousel's head and tagged so
        # the brand-match promotion never lifts them into slots 1-3.
        tnorm = pool['Title'].fillna('').astype(str).map(_cm_norm)
        locked = same_brand & (tnorm.str.contains('ΑΡΩΜΑΤΙΚ|ULTRAPHASE|FRAGRANCE|TWINDOS|CAPS', regex=True, na=False))
        pool.loc[locked, '_wm_feature_locked'] = True
        pool.loc[locked, 'Final_Score'] -= 120_000
        if locked.any():
            notes.append(f"  ⚠ Feature-locked consumables demoted (-120,000): {locked.sum()} — require FragranceDos/TwinDos on the specific model, unverifiable from catalog data")

    return pool.sort_values('Final_Score', ascending=False)


def _wm_build_sda_companion_pool(c_pool, trigger_brand, trigger_tier,
                                  role_label, sales_only, notes):
    """Score an SDA-based companion pool (Σίδερα, Συστήματα Σιδερώματος,
    Σιδερώστρες, Συστήματα Ατμού).

    Brand crossover between washer brands and iron brands is minimal —
    only BOSCH and PHILIPS appear in both worlds. So the brand boost
    rarely fires; sales + price-tier proximity dominate.

    `sales_only=True` skips even the brand & price-tier boosts (used for
    Σιδερώστρες and Συστήματα Ατμού — pure sales).
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += WM_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * WM_S_SALES_FACTOR

    if sales_only:
        notes.append(f"  ✓ SALES-ONLY pool ({role_label}): {len(pool)} candidates, sorted by sales")
        return pool.sort_values('Final_Score', ascending=False)

    # ── Brand match (rare crossover — BOSCH, PHILIPS span both worlds)
    tb = (trigger_brand or '').upper().strip()
    if tb and 'Κατασκευαστής' in pool.columns:
        cand_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        same_brand = cand_brand == tb
        pool.loc[same_brand, 'Final_Score'] += WM_S_BRAND_MATCH
        if same_brand.any():
            notes.append(f"  ✓ Rare brand crossover ({tb}): {same_brand.sum()} (+{WM_S_BRAND_MATCH:,})")

    # ── Budget mirroring via WITHIN-POOL price percentile (v28.50.1).
    # The old check mapped companion prices through _wm_price_tier — the
    # WASHER scale — so every €30-150 iron was 'tier 0' and any tier-2/3
    # trigger saw zero signal, collapsing to pure sales: the same TEFAL
    # FV6840 led on a €398 CANDY, a €935 BOSCH and a €2,999 MIELE
    # (user-reported sameness). Instead, rank each companion by its price
    # percentile INSIDE its own pool and match the band to the trigger
    # tier: budget triggers pull from the cheap end, premium triggers
    # from the top end. Sales still break ties inside the band.
    if 'LIST PRICE' in pool.columns and len(pool) >= 4:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        pct = prices.rank(pct=True)
        bands = {0: (0.00, 0.35), 1: (0.20, 0.60), 2: (0.45, 0.85), 3: (0.65, 1.01)}
        lo, hi = bands.get(trigger_tier, (0.20, 0.60))
        in_band = (pct >= lo) & (pct <= hi)
        near_band = (~in_band) & (pct >= lo - 0.15) & (pct <= hi + 0.15)
        pool.loc[in_band, 'Final_Score'] += WM_S_PRICE_SAME_TIER
        pool.loc[near_band, 'Final_Score'] += WM_S_PRICE_ONE_OFF
        notes.append(f"  ✓ Budget band ({role_label}, trigger tier {trigger_tier} → price pct {lo:.0%}-{min(hi,1):.0%}): "
                     f"in-band={in_band.sum()}, near={near_band.sum()}")

    return pool.sort_values('Final_Score', ascending=False)



# ═══════════════════════════════════════════════════════════════
# 🟢 FACE CARE HELPERS + ENGINE — Περιποίηση Προσώπου (Personal Care)  [v28.52]
# ═══════════════════════════════════════════════════════════════
# One parametrized engine (run_face_care_engine) drives all four clusters via
# FACE_CARE_CLUSTERS[cluster_key]. Mirrors the run_straighteners_engine spine
# (pre-build & score every pool, then round-robin fill to 10). Brand is
# resolved column-OR-title (SHAVING/TRIMMERS have 0% column), and the
# ACCESSORIES pool applies the cross-brand replacement-part HARD GATE.

def _fc_resolve_brand_series(pool):
    """Uppercase brand per row: Κατασκευαστής when present, else title-parse.
    Returns (brand_series, was_parsed_mask) so the engine can award the
    slightly smaller FC_S_BRAND_PARSED for title-derived matches."""
    if 'Κατασκευαστής' in pool.columns:
        col = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
    else:
        col = pd.Series([''] * len(pool), index=pool.index)
    needs = col == ''
    if needs.any():
        col.loc[needs] = pool.loc[needs, 'Title'].fillna('').apply(
            lambda t: _fc_parse_brand_from_title(t).upper()
        )
    return col, needs & (col != '')


def _fc_apply_base_score(pool, trigger_brand, trigger_tier, trigger_colors, notes,
                         color_exact_weight=0, color_partial_weight=0):
    """Shared scoring spine: availability + sales + brand(col/parsed) + price-tier
    + optional color. No face boost here (applied separately by device pools)."""
    if pool.empty:
        return pool
    pool = pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        avail = pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο'
        pool.loc[avail, 'Final_Score'] += FC_S_AVAILABILITY
        if avail.any():
            notes.append(f"  ✓ Availability: {avail.sum()} in stock (+{FC_S_AVAILABILITY:,})")

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * FC_S_SALES_FACTOR

    if trigger_brand:
        brand_resolved, was_parsed = _fc_resolve_brand_series(pool)
        same = brand_resolved == trigger_brand
        col_match    = same & ~was_parsed
        parsed_match = same & was_parsed
        pool.loc[col_match,    'Final_Score'] += FC_S_BRAND_MATCH
        pool.loc[parsed_match, 'Final_Score'] += FC_S_BRAND_PARSED
        if col_match.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, column): {col_match.sum()} (+{FC_S_BRAND_MATCH:,})")
        if parsed_match.any():
            notes.append(f"  ✓ Brand ecosystem ({trigger_brand}, title-parsed): {parsed_match.sum()} (+{FC_S_BRAND_PARSED:,})")

    if 'LIST PRICE' in pool.columns:
        tiers = pool['LIST PRICE'].apply(parse_euro_price).apply(_str_price_tier)
        diffs = (tiers - trigger_tier).abs()
        same_t = diffs == 0; near_t = diffs == 1; far_t = diffs >= 2
        pool.loc[same_t, 'Final_Score'] += FC_S_PRICE_SAME_TIER
        pool.loc[near_t, 'Final_Score'] += FC_S_PRICE_ONE_OFF
        pool.loc[far_t,  'Final_Score'] += FC_S_PRICE_TWO_OFF
        if same_t.any() or near_t.any() or far_t.any():
            notes.append(f"  ✓ Price-tier (trigger tier {trigger_tier}): "
                         f"same={same_t.sum()} (+{FC_S_PRICE_SAME_TIER:,}), "
                         f"near={near_t.sum()} (+{FC_S_PRICE_ONE_OFF:,}), "
                         f"far={far_t.sum()} ({FC_S_PRICE_TWO_OFF:+,})")

    if trigger_colors and 'Χρώμα' in pool.columns and color_exact_weight > 0:
        pool_colors = pool['Χρώμα'].apply(_str_color_group)
        exact   = pool_colors.apply(lambda g: g == trigger_colors and len(g) > 0)
        partial = pool_colors.apply(lambda g: bool(g & trigger_colors) and g != trigger_colors)
        pool.loc[exact,   'Final_Score'] += color_exact_weight
        pool.loc[partial, 'Final_Score'] += color_partial_weight
        if exact.any() or partial.any():
            notes.append(f"  ✓ Color match ({'/'.join(sorted(trigger_colors))}): "
                         f"exact={exact.sum()} (+{color_exact_weight:,}), partial={partial.sum()} (+{color_partial_weight:,})")

    return pool


def _fc_face_relevance_boost(pool, trigger_is_face, notes):
    """Soft boost: if the trigger is a FACE device, lift companions whose title
    signals face/beard/nose grooming. Soft (not a gate) because the structured
    Περιοχή Χρήσης discriminator is 0% filled for shavers/trimmers."""
    if not trigger_is_face or pool.empty or 'Title' not in pool.columns:
        return pool
    t = pool['Title'].fillna('').astype(str).str.lower()
    m = t.apply(lambda x: any(term in x for term in _FC_FACE_TERMS))
    pool.loc[m, 'Final_Score'] += FC_S_FACE_RELEVANCE
    if m.any():
        notes.append(f"  ✓ Face-relevance (face trigger): {m.sum()} face/grooming companions (+{FC_S_FACE_RELEVANCE:,})")
    return pool


def _fc_build_device_pool(c_pool, tb, ttier, tcolors, trigger_is_face, notes, use_color=False):
    """Same-family + cross-device companions (shavers/trimmers/sets/clippers,
    or hair-styling for epilators). Color only for women's-care (use_color)."""
    if c_pool.empty:
        return c_pool
    pool = _fc_apply_base_score(
        c_pool, tb, ttier, tcolors, notes,
        color_exact_weight=(FC_S_COLOR_EXACT if use_color else 0),
        color_partial_weight=(FC_S_COLOR_PARTIAL if use_color else 0),
    )
    pool = _fc_face_relevance_boost(pool, trigger_is_face, notes)
    return pool.sort_values('Final_Score', ascending=False)


def _fc_build_accessory_pool(c_pool, tb, ttier, tcolors, notes, trigger_title=''):
    """ACCESSORIES with a strict compatibility gate (see _fc_accessory_compatible):
    same-brand only, no off-category (yoga/fitness/spray), and replacement parts
    must match the trigger's shaver system (OneBlade-QP vs rotary-SH/HQ). When the
    gate empties the pool, the slot backfills from the device pools — a 3rd device
    beats a wrong-system blade or a cross-brand yoga mat."""
    if c_pool.empty:
        return c_pool
    pool = c_pool.copy()
    brand_resolved, _ = _fc_resolve_brand_series(pool)
    keep = pd.Series(
        [_fc_accessory_compatible(trigger_title, tb, t, brand_resolved.loc[i])
         for i, t in pool['Title'].fillna('').items()],
        index=pool.index,
    )
    dropped = int((~keep).sum())
    if dropped:
        notes.append(f"  ⛔ ACCESSORY GATE: dropped {dropped} incompatible "
                     f"(cross-brand / off-category / wrong-system) — trigger brand {tb or '∅'}")
    pool = pool[keep].copy()
    if pool.empty:
        notes.append("  ⚠ Accessory pool empty after gate — slot backfills from devices")
        return pool
    pool = _fc_apply_base_score(pool, tb, ttier, tcolors, notes, color_exact_weight=0, color_partial_weight=0)
    return pool.sort_values('Final_Score', ascending=False)


def _fc_build_massage_pool(c_pool, tb, ttier, tcolors, notes):
    """MASSAGE DEVICES filtered to real devices (drops sleep masks, starter
    accessory kits, cases). Backfills from devices if empty after the filter."""
    if c_pool.empty:
        return c_pool
    pool = c_pool.copy()
    t = pool['Title'].fillna('').astype(str).str.lower()
    drop = t.apply(lambda x: any(k in x for k in _FC_MASSAGE_DROP_TERMS))
    if drop.any():
        notes.append(f"  ⛔ MASSAGE GATE: dropped {int(drop.sum())} non-device items (masks/accessories/cases)")
    pool = pool[~drop].copy()
    if pool.empty:
        notes.append("  ⚠ Massage pool empty after gate — slot backfills from devices")
        return pool
    pool = _fc_apply_base_score(pool, tb, ttier, tcolors, notes, color_exact_weight=0, color_partial_weight=0)
    return pool.sort_values('Final_Score', ascending=False)


def _fc_build_wellness_pool(c_pool, tb, ttier, tcolors, notes):
    """Toothbrushes / scales — utilitarian wellness cross-sell.
    Brand match still fires (rare), price+sales carry it; no color."""
    if c_pool.empty:
        return c_pool
    pool = _fc_apply_base_score(c_pool, tb, ttier, tcolors, notes, color_exact_weight=0, color_partial_weight=0)
    return pool.sort_values('Final_Score', ascending=False)


def run_face_care_engine(trigger, df_sda, df_history, df_stationery=None, cluster_key="Face Shavers"):
    """Build up to 10 cross-sell slots for a face-care trigger.
    Parametrized by cluster_key over FACE_CARE_CLUSTERS. Round-robin fill:
    device pools (some max_total=2) → brand-gated accessories → wellness →
    Stationery impulse (×2) → wellness filler. Round 1 fills 9, round 2 takes
    one device-pool overflow → 10/10."""
    cfg = FACE_CARE_CLUSTERS[cluster_key]
    PRIORITY    = cfg['priority']
    SLOT_TARGET = cfg['slot_target']
    MARKETING   = cfg['marketing']
    use_color   = cfg.get('use_color', False)

    diag = []; slot_notes = {}; all_recs = []

    tm = trigger['Material']
    _tb_raw = trigger.get('Κατασκευαστής', '')
    tb = '' if pd.isna(_tb_raw) else str(_tb_raw).strip().upper()   # guard: str(NaN)→'NAN' is truthy
    if not tb or tb == 'NAN':
        tb = _fc_parse_brand_from_title(trigger.get('Title', '')).upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _str_price_tier(tprice)
    tcolor_raw = str(trigger.get('Χρώμα', '') or '').strip()
    tcolors = _str_color_group(tcolor_raw)

    # Trigger face-ness: NBSP-tolerant Περιοχή Χρήσης lookup, OR title signal.
    tarea = ''
    for k in trigger.index:
        if str(k).replace('\xa0', ' ').strip().startswith('Περιοχή Χρήσης'):
            tarea = str(trigger.get(k, '') or ''); break
    tt_low = str(trigger.get('Title', '')).lower()
    trigger_is_face = ('πρόσωπ' in tarea.lower()) or ('προσωπ' in tarea.lower()) \
                      or any(term in tt_low for term in _FC_FACE_TERMS)

    diag.append(("0. Trigger", f"{tb or '∅'} €{tprice:.0f}",
                 f"Tier={ttier} | Color={tcolor_raw}→{sorted(tcolors)} | Face={trigger_is_face} | cluster={cluster_key}"))

    if df_sda is None or df_sda.empty:
        diag.append(("ERROR", 0, "SDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # Drop the trigger itself + same-hierarchy competitors (no same-hierarchy rule)
    c_sda = df_sda[df_sda['Material'] != tm].copy()
    trig_hiers = {h.upper().strip() for h in cfg['trigger_hiers']}
    b4 = len(c_sda)
    c_sda = c_sda[~c_sda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(trig_hiers)]
    diag.append(("1. Excl same-hierarchy", len(c_sda), f"Removed {b4 - len(c_sda)} same-hierarchy competitors"))

    if 'Sum of Sales' in c_sda.columns:
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_sda['Sales_Tiebreaker'] = 0

    # + Stationery for the impulse pool (PERSONAL CARE gifts), same as hair engines
    if df_stationery is not None and not df_stationery.empty:
        stat = df_stationery[df_stationery['Material'] != tm].copy()
        if 'Sum of Sales' in stat.columns:
            stat['Sales_Tiebreaker'] = pd.to_numeric(stat['Sum of Sales'], errors='coerce').fillna(0)
        else:
            stat['Sales_Tiebreaker'] = 0
        if 'Χρώμα' not in stat.columns:
            stat['Χρώμα'] = ''
        c_combined = pd.concat([c_sda, stat], ignore_index=True, sort=False)
        diag.append(("1b. + Stationery", len(c_combined), f"Added {len(stat)} stationery rows for impulse pool"))
    else:
        c_combined = c_sda
        diag.append(("1b. Stationery", 0, "No Stationery sheet — impulse pool will be empty"))

    # Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, hiers, logic_key, max_r1, max_total in PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]
        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = c_combined[c_combined['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append("  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        if logic_key == 'FC_DEVICE':
            scored = _fc_build_device_pool(base_pool, tb, ttier, tcolors, trigger_is_face, notes, use_color=use_color)
        elif logic_key == 'FC_ACCESSORY':
            scored = _fc_build_accessory_pool(base_pool, tb, ttier, tcolors, notes, trigger_title=str(trigger.get('Title', '')))
        elif logic_key == 'FC_WELLNESS':
            scored = _fc_build_wellness_pool(base_pool, tb, ttier, tcolors, notes)
        elif logic_key == 'FC_MASSAGE':
            scored = _fc_build_massage_pool(base_pool, tb, ttier, tcolors, notes)
        elif logic_key == 'FC_IMPULSE':
            scored = _pc_build_impulse_accessory_pool(base_pool, tb, ttier, tcolors, role_label, notes, trigger_price=tprice)
        else:
            scored = base_pool.copy(); scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", len(scored), logic_key))

    # Round-robin fill
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken   = {rank: 0 for rank in pools}
    slot_num = 0; round_idx = 0

    while slot_num < SLOT_TARGET:
        progress = False; round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue
            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])
            cursor = pool_cursors[rank]; taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) and slot_num < SLOT_TARGET:
                row = scored.iloc[cursor]; cursor += 1
                if row['Material'] in used_materials:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot']  = slot_num
                rc['Slot_Role']      = role_label
                rc['Marketing_Copy'] = MARKETING.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank']      = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1; pool_taken[rank] += 1; progress = True
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {float(row.get('Final_Score', 0)):,.0f} | {str(row.get('Title', ''))[:70]}"
                )
            pool_cursors[rank] = cursor
        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}")
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


# ═══════════════════════════════════════════════════════════════
# 🟢 WASHING MACHINES ENGINE — Πλυντήρια Ρούχων (Μεγάλες Συσκευές)
# ═══════════════════════════════════════════════════════════════

def run_washing_machine_engine(trigger, df_mda, df_sda, df_history,
                                priority_list=None, exclude_hiers_extra=None,
                                slot_target=None, promote_brand_acc=False):
    """Build up to 10 cross-sell slots for a washing-machine trigger.

    v28.50: parameterized so the washer-dryer combo engine can reuse it —
    priority_list overrides WM_PRIORITY, exclude_hiers_extra extends the
    competitor exclusion (combos also exclude Στεγνωτήρια: the combo IS
    the dryer), slot_target overrides WM_SLOT_TARGET. Defaults = classic
    WM behavior, so existing callers are untouched.

    Pools span TWO sheets:
      • MDA  →  Στεγνωτήρια  +  Αξεσουάρ Πλυντηρίου - Στεγνωτηρίου
                (split into 4 sub-slots by Είδος keyword)
      • SDA  →  Σίδερα, Συστήματα Σιδερώματος, Σιδερώστρες, Συστήματα Ατμού

    Round 1 lets Στεγνωτήρια take 2 (the matched-pair carousel hero); every
    other slot takes 1 per round. Empty pools are silently skipped — the
    looping engine over-fills surviving pools to keep the carousel at 10.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes (parsed from Title since MDA has no spec columns)
    tm = trigger['Material']
    tt = str(trigger.get('Title', ''))
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _wm_price_tier(tprice)
    tspecs = _wm_parse_specs(tt)
    tbrand = tspecs['brand']

    diag.append(("0. Trigger",
                 f"{tbrand} €{tprice:.0f}",
                 f"cap={tspecs['capacity_kg']}kg | rpm={tspecs['rpm']} | "
                 f"wifi={tspecs['wifi']} | slim={tspecs['slim']} | "
                 f"price_tier={ttier} | cap_tier={_wm_capacity_tier(tspecs['capacity_kg'])}"))

    if df_mda is None or df_mda.empty:
        diag.append(("ERROR", 0, "MDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + any other washing machines (competitors).
    # Also drop washer-dryer combos (Πλυντήρια - Στεγνωτήρια) — those are
    # alternative purchases, not companions.
    c_mda = df_mda[df_mda['Material'] != tm].copy()
    trigger_hiers_norm = {h.upper().strip() for h in WM_TRIGGER_HIERARCHIES}
    combo_hiers = {'ΠΛΥΝΤΗΡΙΑ - ΣΤΕΓΝΩΤΗΡΙΑ', 'ΕΝΤΟΙΧΙΖΟΜΕΝΑ ΠΛΥΝΤΗΡΙΑ ΡΟΥΧΩΝ'}
    exclude = trigger_hiers_norm | combo_hiers
    if exclude_hiers_extra:
        exclude = exclude | {h.upper().strip() for h in exclude_hiers_extra}
    b4 = len(c_mda)
    c_mda = c_mda[~c_mda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(exclude)]
    diag.append(("1. Excl washers/combos", len(c_mda),
                 f"Removed {b4 - len(c_mda)} competitors + combos"))

    # ── Prep SDA pool (irons, steam stations, boards, garment steamers)
    if df_sda is not None and not df_sda.empty:
        c_sda = df_sda.copy()
        diag.append(("1b. SDA pool", len(c_sda),
                     "Loaded for Σίδερα / Σιδερώματος / Σιδερώστρες / Ατμού slots"))
    else:
        c_sda = pd.DataFrame()
        diag.append(("1b. SDA pool", 0,
                     "SDA sheet empty — iron-side slots will be skipped"))

    # ── Sales-tiebreaker prep on both pools
    for _df in (c_mda, c_sda):
        if not _df.empty:
            if 'Sum of Sales' in _df.columns:
                _df['Sales_Tiebreaker'] = pd.to_numeric(_df['Sum of Sales'], errors='coerce').fillna(0)
            else:
                _df['Sales_Tiebreaker'] = 0

    # ── Build a sorted pool per priority entry
    pools = {}  # rank → (role_label, sorted_DataFrame, logic_key, max_round_1, max_total, notes)
    active_priority = priority_list if priority_list is not None else WM_PRIORITY
    active_target = slot_target if slot_target is not None else WM_SLOT_TARGET
    for rank, role_label, hiers, logic_key, max_r1, max_total in active_priority:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        # Pick the right base pool (MDA for dryers + accessories; SDA for iron-side)
        if logic_key in ('WM_COMPANION_SDA', 'WM_COMPANION_SDA_SALES'):
            source_pool = c_sda
        else:
            source_pool = c_mda

        if source_pool.empty:
            notes.append(f"  ⚠ Source sheet empty — skipping pool")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        hier_upper = {h.upper().strip() for h in hiers}
        base_pool = source_pool[source_pool['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Score the pool based on its logic key
        if logic_key == 'WM_DRYER':
            scored = _wm_build_dryer_pool(base_pool, tspecs, ttier, notes)

        elif logic_key in ('WM_ACC_STACK', 'WM_ACC_ANTIVIB', 'WM_ACC_DETERGENT', 'WM_ACC_BASE'):
            # First narrow Αξεσουάρ pool down to this Είδος subset, then score
            subset = _wm_filter_accessory_subset(base_pool, logic_key, notes)
            if subset.empty:
                notes.append(f"  ⚠ No Είδος matches for {logic_key} — pool empty")
                pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
                continue
            # Stacking kits + pedestals → brand-preferred scoring;
            # antivib + detergents → universal-need scoring.
            if logic_key == 'WM_ACC_DETERGENT':
                # Dishwasher-detergent leak guard (v28.50.1): the Είδος
                # keyword 'ταμπλέτ' also matches MIELE UltraTabs (πλυντηρίου
                # ΠΙΑΤΩΝ) rows misfiled under laundry accessories. Drop any
                # title naming ΠΙΑΤΩΝ unless it also names ΡΟΥΧΩΝ (the AEG
                # Super Care descaler is dual-purpose and stays).
                dt = subset['Title'].fillna('').astype(str).map(_cm_norm)
                dish_only = dt.str.contains('ΠΙΑΤΩΝ', na=False) & ~dt.str.contains('ΡΟΥΧΩΝ', na=False)
                if dish_only.any():
                    notes.append(f"  ✗ HARD-dropped {dish_only.sum()} dishwasher-only detergents misfiled in laundry accessories")
                subset = subset[~dish_only]
                if subset.empty:
                    notes.append("  ⚠ Detergent subset empty after dishwasher-leak guard")
                    pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
                    continue
            if logic_key in ('WM_ACC_STACK', 'WM_ACC_BASE'):
                scored = _wm_build_accessory_brand_pool(subset, tbrand, notes, role_label)
            else:
                scored = _wm_build_accessory_universal_pool(subset, tbrand, notes)

        elif logic_key == 'WM_COMPANION_SDA':
            scored = _wm_build_sda_companion_pool(base_pool, tbrand, ttier,
                                                   role_label, sales_only=False, notes=notes)

        elif logic_key == 'WM_COMPANION_SDA_SALES':
            scored = _wm_build_sda_companion_pool(base_pool, tbrand, ttier,
                                                   role_label, sales_only=True, notes=notes)

        else:
            # Unknown logic → fall back to pure sales
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})",
                     len(scored) if scored is not None else 0, logic_key))

    # ── BRAND-MATCH PROMOTION (v28.50.1, user spec): when an accessory
    # pool's TOP candidate is the trigger's own brand, that pool jumps to
    # the head of the carousel (slots 1-3), then the regular order
    # follows. Feature-locked consumables (FragranceDos/TwinDos parts,
    # tagged by the universal-pool builder) never promote — same-brand is
    # not proof of fit for those, so they stay mid-carousel.
    if promote_brand_acc and tbrand:
        acc_keys = {'WM_ACC_ANTIVIB', 'WM_ACC_DETERGENT', 'WM_ACC_BASE', 'WM_ACC_STACK'}
        promoted, rest = [], []
        for rank, entry in pools.items():
            role_label, scored, logic_key, *_ = entry
            is_brand_top = False
            if logic_key in acc_keys and scored is not None and not scored.empty:
                top = scored.iloc[0]
                top_brand = str(top.get('Κατασκευαστής', '') or '').strip().upper()
                if top_brand == tbrand and not bool(top.get('_wm_feature_locked', False)):
                    is_brand_top = True
            (promoted if is_brand_top and len(promoted) < 3 else rest).append((rank, entry))
        if promoted:
            diag.append(("Brand-match promotion",
                         len(promoted),
                         "Own-brand accessory pools lead the carousel: " +
                         ", ".join(e[1][0] for e in promoted)))
            pools = dict(promoted + rest)

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < active_target:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= active_target:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < active_target:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = WM_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{WM_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()



def run_washer_dryer_engine(trigger, df_mda, df_sda, df_history):
    """Πλυντήρια - Στεγνωτήρια (washer-dryer combos): the WM engine with
    the WD_PRIORITY slot map. Differences from a plain washer (v28.50):
      • no Στεγνωτήριο slot AND Στεγνωτήρια excluded outright — the combo
        IS the dryer, a standalone dryer is an alternative purchase
      • no Βάση Σύνδεσης slot — nothing to stack
      • ironing chain promoted (combo buyers are the laundry-completion
        persona) with Σίδερο + Σύστημα Σιδερώματος each capped at 2
    Spec parsing, rival-gated consumables (v28.49.4), antivib/base logic
    and the round-robin loop are inherited unchanged."""
    return run_washing_machine_engine(
        trigger, df_mda, df_sda, df_history,
        priority_list=WD_PRIORITY,
        exclude_hiers_extra={'ΣΤΕΓΝΩΤΗΡΙΑ'},
        slot_target=WD_SLOT_TARGET,
        promote_brand_acc=True,   # own-brand accessories lead (slots 1-3)
    )


# ═══════════════════════════════════════════════════════════════
# 🟢 REFRIGERATORS HELPERS — Ψυγειοκαταψύκτες (Μεγάλες Συσκευές)
# ═══════════════════════════════════════════════════════════════
# Four pool builders: panel-series, universal care, kitchen-package
# (colored variant) and kitchen-package (parsed-brand variant). The
# engine itself follows the same round-robin pattern as Washing Machines
# / Air Fryers / Vacuums — pre-build & score every pool, then loop until
# 10 slots filled or all pools exhausted.

def _fridge_build_panel_pool(c_pool, trigger_series, trigger_brand,
                              trigger_color, trigger_color_group, notes):
    """Score the Αξεσουάρ Ψυγείων pool restricted to door panels (Είδος = 'Πάνελ').

    HARD BRAND LOCK — door panels are physically brand-specific because each
    manufacturer uses a proprietary mounting mechanism. A BOSCH KSZ Vario
    panel will NOT fit a SAMSUNG / LIEBHERR / HISENSE / LG / SMEG / MIELE
    fridge (and vice versa). So step 1 is a hard filter by
    Κατασκευαστής match; only after that does the rest of the scoring
    fire. If the trigger brand has no panels in the catalog (e.g. MIELE,
    LIEBHERR, HISENSE, LG, SMEG), the slot stays empty and the
    care-pool overflow (max_total=2) fills the 10th slot instead.

    Logic stack on the brand-filtered pool (most important first):
      1. Series match (BESPOKE↔BESPOKE, Vario↔Vario) → +1,000,000
         The whole point of BESPOKE is panel-swap aesthetics; matched-series
         panels are the highest-cross-sell product in the catalog for that
         specific buyer.
      2. Series match + same color group → +400,000 extra
         A Μαύρο BESPOKE fridge buyer's #1 want is a Μαύρο or Γκρι panel
         (so they can swap to dark variants); a Λευκό buyer wants Λευκό/Μπεζ.
      3. Wrong-series penalty (same brand, different series): -500,000
         Defensive — currently all SAMSUNG panels in catalog ARE BESPOKE,
         so this rarely fires, but it'd kick in if e.g. a SAMSUNG
         "Family Hub" panel were added that doesn't fit BESPOKE fridges.
      4. Sales tiebreaker (panels typically have 0 sales — so this barely
         matters; the brand + series + color signals dominate).
    """
    if c_pool.empty:
        return c_pool

    # Restrict to Είδος = 'Πάνελ' (drop cleaning/filter/shelf rows here —
    # those belong to the care pool, not the panel pool).
    if 'Είδος' in c_pool.columns:
        eidos_lower = c_pool['Είδος'].fillna('').astype(str).str.lower()
        panels = c_pool[eidos_lower.str.contains('πάνελ', regex=False, na=False)].copy()
    else:
        notes.append("  ⚠ 'Είδος' column missing — panel pool will be empty")
        return c_pool.iloc[0:0]

    if panels.empty:
        notes.append("  ⚠ No 'Πάνελ' rows in Αξεσουάρ Ψυγείων — pool empty")
        return panels

    # ── HARD BRAND-COMPATIBILITY FILTER ──
    # Panels are physically brand-locked. Drop everything that isn't the
    # trigger's exact brand. If trigger brand isn't represented among the
    # panel manufacturers, the pool empties out and the slot is skipped.
    tb_upper = (trigger_brand or '').upper().strip()
    if not tb_upper:
        notes.append("  ⚠ No trigger brand identified — panel slot stays empty (panels are brand-locked)")
        return panels.iloc[0:0]

    if 'Κατασκευαστής' not in panels.columns:
        notes.append("  ⚠ 'Κατασκευαστής' column missing — cannot enforce brand-lock, returning empty pool")
        return panels.iloc[0:0]

    panel_brand = panels['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
    before_n = len(panels)
    panels = panels[panel_brand == tb_upper].copy()
    notes.append(f"  ✓ Brand-compatibility filter: kept {len(panels)}/{before_n} '{tb_upper}'-branded panels (panels are brand-locked)")
    if panels.empty:
        notes.append(f"  ⚠ No '{tb_upper}' panels in catalog — slot stays empty; care-pool overflow will fill the 10th slot")
        return panels

    pool = panels
    pool['Final_Score'] = 0.0

    # ── Availability boost
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += FRIDGE_S_AVAILABILITY

    # ── Sales baseline (mostly zeros for panels — series boost dominates)
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * FRIDGE_S_SALES_FACTOR

    # ── Series detection on each candidate (per-panel)
    cand_series = pool['Title'].fillna('').astype(str).apply(_fridge_detect_series)
    pool['_fridge_panel_series'] = cand_series

    # ── HARD SERIES GATE (v28.49.3, user-reported incompatibility).
    # Door panels are SERIES parts, not brand parts: BOSCH KSZ1*/KSZ2*
    # Vario Style fronts only clip onto Vario Style doors (KGN39IJ/
    # KGN36IJ…), SAMSUNG RA-B23* only onto BESPOKE. A same-brand fridge
    # with a fixed door (the KGN49XIEA Brushed Steel case) physically
    # cannot mount ANY panel. Therefore:
    #   • trigger has NO detected series → pool EMPTIES, slot backfills
    #     (printer-cartridge philosophy — same as rails in the cookers
    #     engine). The old fallback that sorted same-brand panels by
    #     color was built on the wrong assumption that brand = fit.
    #   • trigger HAS a series → candidates of any OTHER (or no
    #     detectable) series are HARD-dropped, not merely penalized.
    if not trigger_series:
        notes.append("  ✗ Trigger has no panel-compatible series (fixed door) — pool emptied, slot backfills. No same-brand fallback: panels are series-locked, not brand-locked.")
        return pool.iloc[0:0]

    same_series = cand_series == trigger_series
    dropped = (~same_series).sum()
    if dropped:
        notes.append(f"  ✗ HARD-dropped {dropped} panels of other/undetected series (≠ {trigger_series})")
    pool = pool[same_series].copy()
    if pool.empty:
        notes.append(f"  ⚠ No {trigger_series} panels in catalog — slot backfills")
        return pool
    pool['Final_Score'] += FRIDGE_S_SERIES_MATCH
    notes.append(f"  ✓ Series match ({trigger_series}): {len(pool)} panels (+{FRIDGE_S_SERIES_MATCH:,})")

    # Color group match within series — boosts Μαύρο/Γκρι panels for a Μαύρο fridge
    if trigger_color_group:
        cand_colors = pool['Χρώμα'].fillna('').astype(str).apply(_fridge_color_group)
        same_group = cand_colors == trigger_color_group
        pool.loc[same_group, 'Final_Score'] += FRIDGE_S_SERIES_COLOR
        if same_group.any():
            notes.append(f"  ✓ Series + color group ({trigger_color_group}): {same_group.sum()} panels (+{FRIDGE_S_SERIES_COLOR:,})")

    # ── Sort by score. Every surviving row is series-verified compatible
    # (v28.49.3) — there is no penalty/negative-score signalling anymore.
    return pool.sort_values('Final_Score', ascending=False)


def _fridge_build_care_pool(c_pool, trigger_brand, notes):
    """Score the universal-care pool: cleaning supplies + water filter +
    shelves. These items work for any fridge regardless of brand or color.

    Logic:
      • Universal-care brands (BOSCH cleaning, SCANPART filter) → big boost
        — these are designed to work on any stainless or any fridge
      • Same-brand bonus for specialty parts (AEG shelf for AEG buyer,
        MIELE wine set for MIELE buyer)
      • Sales matters more here than in the panel pool (cleaning supplies
        actually have sales — 91 units for the fridge-specific cleaner)
    """
    if c_pool.empty:
        return c_pool

    # Restrict to non-Πάνελ rows (Είδος ∈ {Καθαριστικά, Φίλτρα, Αξεσουάρ-Εξαρτήματα})
    # AND require Είδος to be populated — this filters out promo-bundle rows
    # that occasionally land in Αξεσουάρ Ψυγείων with empty Είδος (e.g.
    # LAURA ASHLEY LA-STCR2 toaster sold as a gift-with-fridge).
    if 'Είδος' in c_pool.columns:
        eidos_raw = c_pool['Είδος'].fillna('').astype(str).str.strip()
        eidos_lower = eidos_raw.str.lower()
        valid_eidos = (eidos_raw != '') & (eidos_lower != 'nan')
        care = c_pool[valid_eidos & ~eidos_lower.str.contains('πάνελ', regex=False, na=False)].copy()
    else:
        care = c_pool.copy()

    if care.empty:
        notes.append("  ⚠ No non-panel rows in Αξεσουάρ Ψυγείων — care pool empty")
        return care

    pool = care
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += FRIDGE_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * FRIDGE_S_SALES_FACTOR

    # Universal-care brand boost — these are the only accessories in our
    # catalog that genuinely "fit anything". BOSCH cleaning supplies work
    # on any stainless steel; SCANPART filter is a universal-fit water filter.
    universal_brands = {'BOSCH', 'SCANPART'}  # eidos restricts to cleaning/filter
    if 'Κατασκευαστής' in pool.columns and 'Είδος' in pool.columns:
        cand_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        eidos = pool['Είδος'].fillna('').astype(str).str.lower()

        # Cleaning supplies (Καθαριστικά) + Filter (Φίλτρα) from universal brands
        is_universal = cand_brand.isin(universal_brands) & (
            eidos.str.contains('καθαριστικ', regex=False, na=False) |
            eidos.str.contains('φίλτρα',     regex=False, na=False)
        )
        pool.loc[is_universal, 'Final_Score'] += FRIDGE_S_UNIVERSAL_CARE
        if is_universal.any():
            notes.append(f"  ✓ Universal care ({list(universal_brands)}): {is_universal.sum()} items (+{FRIDGE_S_UNIVERSAL_CARE:,})")

        # Same-brand specialty parts (AEG shelf for AEG fridge owner)
        if trigger_brand:
            same_brand = cand_brand == trigger_brand.upper().strip()
            # Avoid double-counting the universal-care rows
            same_brand_specialty = same_brand & ~is_universal
            pool.loc[same_brand_specialty, 'Final_Score'] += FRIDGE_S_BRAND_EXACT
            if same_brand_specialty.any():
                notes.append(f"  ✓ Same-brand specialty parts ({trigger_brand}): {same_brand_specialty.sum()} (+{FRIDGE_S_BRAND_EXACT:,})")

    return pool.sort_values('Final_Score', ascending=False)


def _fridge_build_kitchen_pool_colored(c_pool, trigger_brand, trigger_family,
                                        trigger_color, trigger_color_group,
                                        trigger_tier, trigger_specs, notes):
    """Kitchen-package pool with full multi-spec scoring. Used for hierarchies
    where Κατασκευαστής AND Χρώμα are populated (Φούρνοι Άνω Πάγκου,
    Απορροφητήρες, Φούρνοι Μικροκυμάτων, Κουζίνες Ηλεκτρικές).

    Full signal stack:
      • Brand exact match → +600,000
      • Brand family match (BSH: BOSCH↔PITSOS↔SIEMENS↔NEFF) → +250,000
      • Color exact match → +300,000
      • Color group match (DARK: Μαύρο↔Ανθρακί↔Γκρι) → +150,000
      • Price tier same → +200,000, ±1 → +70,000
      • Wi-Fi mirror → +50,000 if trigger has Wi-Fi
      • Sales tiebreaker
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += FRIDGE_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * FRIDGE_S_SALES_FACTOR

    # ── Brand match (exact + family)
    if 'Κατασκευαστής' in pool.columns and trigger_brand:
        cand_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        tb = trigger_brand.upper().strip()
        same_brand = cand_brand == tb
        pool.loc[same_brand, 'Final_Score'] += FRIDGE_S_BRAND_EXACT
        if same_brand.any():
            notes.append(f"  ✓ Brand exact ({tb}): {same_brand.sum()} (+{FRIDGE_S_BRAND_EXACT:,})")

        # Family match (BOSCH ↔ PITSOS within BSH)
        if trigger_family:
            family_members = FRIDGE_BRAND_FAMILIES.get(trigger_family, set())
            in_family = cand_brand.isin(family_members) & (~same_brand)
            pool.loc[in_family, 'Final_Score'] += FRIDGE_S_BRAND_FAMILY
            if in_family.any():
                notes.append(f"  ✓ Brand family ({trigger_family}: {sorted(family_members)}): "
                             f"{in_family.sum()} neighbor-brand items (+{FRIDGE_S_BRAND_FAMILY:,})")

    # ── Color match (exact + group)
    if 'Χρώμα' in pool.columns and trigger_color:
        cand_color = pool['Χρώμα'].fillna('').astype(str).str.strip()
        same_color = cand_color == trigger_color
        pool.loc[same_color, 'Final_Score'] += FRIDGE_S_COLOR_EXACT
        if same_color.any():
            notes.append(f"  ✓ Color exact ({trigger_color}): {same_color.sum()} (+{FRIDGE_S_COLOR_EXACT:,})")

        if trigger_color_group:
            cand_group = cand_color.apply(_fridge_color_group)
            same_group = (cand_group == trigger_color_group) & (~same_color)
            pool.loc[same_group, 'Final_Score'] += FRIDGE_S_COLOR_GROUP
            if same_group.any():
                notes.append(f"  ✓ Color group ({trigger_color_group}): {same_group.sum()} (+{FRIDGE_S_COLOR_GROUP:,})")

    # ── Price tier proximity
    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_fridge_price_tier)
        same_p = tiers == trigger_tier
        near_p = (tiers - trigger_tier).abs() == 1
        pool.loc[same_p, 'Final_Score'] += FRIDGE_S_PRICE_SAME_TIER
        pool.loc[near_p, 'Final_Score'] += FRIDGE_S_PRICE_NEAR_TIER
        if same_p.any() or near_p.any():
            notes.append(f"  ✓ Price tier (trigger {trigger_tier}): "
                         f"same={same_p.sum()}, near={near_p.sum()}")

    # ── Wi-Fi mirror — premium fridges with Wi-Fi often paired with Wi-Fi ovens
    if trigger_specs.get('wifi') and 'Συνδεσιμότητα' in pool.columns:
        cand_wifi = pool['Συνδεσιμότητα'].fillna('').astype(str).str.lower().str.contains('wi-fi|wifi', regex=True, na=False)
        pool.loc[cand_wifi, 'Final_Score'] += FRIDGE_S_WIFI_MATCH
        if cand_wifi.any():
            notes.append(f"  ✓ Wi-Fi mirror (trigger has Wi-Fi): {cand_wifi.sum()} Wi-Fi candidates (+{FRIDGE_S_WIFI_MATCH:,})")

    notes.append(f"  Pool size after scoring: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _fridge_build_kitchen_pool_basic(c_pool, trigger_brand, trigger_family,
                                      trigger_tier, notes):
    """Kitchen-package pool for hierarchies where color barely varies
    (Εστίες — 95%+ are Μαύρο, so color match is meaningless). Uses brand +
    family + price-tier scoring only.
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += FRIDGE_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * FRIDGE_S_SALES_FACTOR

    if 'Κατασκευαστής' in pool.columns and trigger_brand:
        cand_brand = pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
        tb = trigger_brand.upper().strip()
        same_brand = cand_brand == tb
        pool.loc[same_brand, 'Final_Score'] += FRIDGE_S_BRAND_EXACT
        if same_brand.any():
            notes.append(f"  ✓ Brand exact ({tb}): {same_brand.sum()} (+{FRIDGE_S_BRAND_EXACT:,})")

        if trigger_family:
            family_members = FRIDGE_BRAND_FAMILIES.get(trigger_family, set())
            in_family = cand_brand.isin(family_members) & (~same_brand)
            pool.loc[in_family, 'Final_Score'] += FRIDGE_S_BRAND_FAMILY
            if in_family.any():
                notes.append(f"  ✓ Brand family ({trigger_family}): {in_family.sum()} (+{FRIDGE_S_BRAND_FAMILY:,})")

    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_fridge_price_tier)
        same_p = tiers == trigger_tier
        near_p = (tiers - trigger_tier).abs() == 1
        pool.loc[same_p, 'Final_Score'] += FRIDGE_S_PRICE_SAME_TIER
        pool.loc[near_p, 'Final_Score'] += FRIDGE_S_PRICE_NEAR_TIER
        if same_p.any() or near_p.any():
            notes.append(f"  ✓ Price tier (trigger {trigger_tier}): "
                         f"same={same_p.sum()}, near={near_p.sum()}")

    return pool.sort_values('Final_Score', ascending=False)


def _fridge_build_kitchen_pool_parsed_brand(c_pool, trigger_brand, trigger_family,
                                             trigger_tier, notes):
    """Kitchen-package pool for hierarchies where Κατασκευαστής column is
    empty in the MDA sheet (Πλυντήρια Πιάτων, Πλυντήρια Ρούχων,
    Στεγνωτήρια — all have data quality issues on the brand column).
    Brand is parsed from the Title's first token instead.
    """
    if c_pool.empty:
        return c_pool

    pool = c_pool.copy()
    pool['Final_Score'] = 0.0

    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += FRIDGE_S_AVAILABILITY

    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * FRIDGE_S_SALES_FACTOR

    # Parse brand from title for every candidate
    cand_brand = pool['Title'].fillna('').astype(str).apply(_fridge_parse_brand_from_title)
    pool['_fridge_cand_brand_parsed'] = cand_brand

    if trigger_brand:
        tb = trigger_brand.upper().strip()
        same_brand = cand_brand == tb
        pool.loc[same_brand, 'Final_Score'] += FRIDGE_S_BRAND_EXACT
        if same_brand.any():
            notes.append(f"  ✓ Brand exact (parsed from title, {tb}): {same_brand.sum()} (+{FRIDGE_S_BRAND_EXACT:,})")

        if trigger_family:
            family_members = FRIDGE_BRAND_FAMILIES.get(trigger_family, set())
            in_family = cand_brand.isin(family_members) & (~same_brand)
            pool.loc[in_family, 'Final_Score'] += FRIDGE_S_BRAND_FAMILY
            if in_family.any():
                notes.append(f"  ✓ Brand family (parsed, {trigger_family}): {in_family.sum()} (+{FRIDGE_S_BRAND_FAMILY:,})")

    if 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        tiers = prices.apply(_fridge_price_tier)
        same_p = tiers == trigger_tier
        near_p = (tiers - trigger_tier).abs() == 1
        pool.loc[same_p, 'Final_Score'] += FRIDGE_S_PRICE_SAME_TIER
        pool.loc[near_p, 'Final_Score'] += FRIDGE_S_PRICE_NEAR_TIER
        if same_p.any() or near_p.any():
            notes.append(f"  ✓ Price tier (trigger {trigger_tier}): "
                         f"same={same_p.sum()}, near={near_p.sum()}")

    return pool.sort_values('Final_Score', ascending=False)


# ═══════════════════════════════════════════════════════════════
# 🟢 REFRIGERATORS ENGINE — Ψυγειοκαταψύκτες (Μεγάλες Συσκευές)
# ═══════════════════════════════════════════════════════════════

def run_fridge_engine(trigger, df_mda, df_history):
    """Build up to 10 cross-sell slots for a refrigerator trigger.

    Single sheet only (MDA). Pools span 8 hierarchies inside MDA:
      • Αξεσουάρ Ψυγείων (split into Πάνελ vs care/cleaning/filter)
      • Φούρνοι Άνω Πάγκου, Πλυντήρια Πιάτων, Εντοιχιζόμενα Πλυντήρια Πιάτων
      • Εστίες Επαγωγικές, Εστίες Κεραμικές
      • Απορροφητήρες Καμινάδες - τζάκια, Απορροφητήρες Συρόμενοι
      • Φούρνοι Μικροκυμάτων, Πλυντήρια Ρούχων, Στεγνωτήρια, Κουζίνες Ηλεκτρικές

    Round 1 fills every slot once; the panel slot's max_total=3 lets round 2+3
    backfill more BESPOKE panels for a BESPOKE-series buyer (the one case
    where multiple instances of the same role is the correct UX).
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes — pulled from spec columns (no title parsing
    # needed here; the spec data is rich).
    tm     = trigger['Material']
    tt     = str(trigger.get('Title', ''))
    tbrand = str(trigger.get('Κατασκευαστής', '') or '').upper().strip()
    tcolor = str(trigger.get('Χρώμα', '') or '').strip()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier  = _fridge_price_tier(tprice)
    tfam   = _fridge_brand_family(tbrand)
    tseries = _fridge_detect_series(tt)
    tcolor_grp = _fridge_color_group(tcolor)
    tcap = _fridge_parse_capacity(trigger.get('Συνολική καθαρή χωρητικότητα', '')
                                   or trigger.get('Χωρητικότητα', ''))
    twifi = ('Wi-Fi' in str(trigger.get('Συνδεσιμότητα', '') or '')) or \
            ('WiFi'  in str(trigger.get('Συνδεσιμότητα', '') or ''))
    tspecs = {'wifi': twifi, 'capacity_lt': tcap}

    diag.append(("0. Trigger",
                 f"{tbrand} €{tprice:.0f}",
                 f"color={tcolor} | color_group={tcolor_grp} | "
                 f"family={tfam} | series={tseries or '—'} | "
                 f"cap={tcap:.0f}Lt | wifi={twifi} | price_tier={ttier}"))

    if df_mda is None or df_mda.empty:
        diag.append(("ERROR", 0, "MDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── Drop the trigger itself + competing fridges (would be cannibalistic).
    # Note: Πλυντήρια - Στεγνωτήρια (washer-dryer combos) live in MDA but
    # they're a valid cross-sell for fridge buyers, so don't exclude them.
    c_mda = df_mda[df_mda['Material'] != tm].copy()
    trigger_hiers_norm = {h.upper().strip() for h in FRIDGE_TRIGGER_HIERARCHIES}
    # Also exclude Ψυγεία (single-door fridges) and Καταψύκτες if they ever
    # appear — they're alternative purchases, not companions.
    competitor_hiers = trigger_hiers_norm | {
        'ΨΥΓΕΙΑ', 'ΚΑΤΑΨΥΚΤΕΣ', 'ΨΥΓΕΙΑ NIDIDE', 'SIDE BY SIDE'
    }
    b4 = len(c_mda)
    hier_upper = c_mda['Hierarchy'].fillna('').astype(str).str.upper().str.strip()
    c_mda = c_mda[~hier_upper.isin(competitor_hiers)]
    diag.append(("1. Excl competitors", len(c_mda),
                 f"Removed {b4 - len(c_mda)} other fridges/single-door units"))

    # ── Sales-tiebreaker prep
    if 'Sum of Sales' in c_mda.columns:
        c_mda['Sales_Tiebreaker'] = pd.to_numeric(c_mda['Sum of Sales'], errors='coerce').fillna(0)
    else:
        c_mda['Sales_Tiebreaker'] = 0

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, hiers, logic_key, max_r1, max_total in FRIDGE_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        hier_upper_set = {h.upper().strip() for h in hiers}
        base_pool = c_mda[c_mda['Hierarchy'].fillna('').astype(str).str.upper().str.strip().isin(hier_upper_set)].copy()
        notes.append(f"  Base pool size: {len(base_pool)} (hierarchies={hiers})")

        if base_pool.empty:
            notes.append(f"  ⚠ Hierarchy not present in data — slot will be filled from other pools")
            pools[rank] = (role_label, pd.DataFrame(), logic_key, max_r1, max_total, notes)
            continue

        # ── Score the pool based on its logic key
        if logic_key == 'FRIDGE_PANEL_SERIES':
            scored = _fridge_build_panel_pool(base_pool, tseries, tbrand,
                                               tcolor, tcolor_grp, notes)

        elif logic_key == 'FRIDGE_CARE_UNIVERSAL':
            scored = _fridge_build_care_pool(base_pool, tbrand, notes)

        elif logic_key == 'FRIDGE_KITCHEN_COLORED':
            scored = _fridge_build_kitchen_pool_colored(
                base_pool, tbrand, tfam, tcolor, tcolor_grp,
                ttier, tspecs, notes
            )

        elif logic_key == 'FRIDGE_KITCHEN_BASIC':
            scored = _fridge_build_kitchen_pool_basic(
                base_pool, tbrand, tfam, ttier, notes
            )

        elif logic_key == 'FRIDGE_KITCHEN_PARSED':
            scored = _fridge_build_kitchen_pool_parsed_brand(
                base_pool, tbrand, tfam, ttier, notes
            )

        else:
            # Unknown logic key — fall back to pure sales (safety net)
            scored = base_pool.copy()
            scored['Final_Score'] = scored['Sales_Tiebreaker']
            notes.append(f"  ⚠ Unknown logic key '{logic_key}' — falling back to pure sales")

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})",
                     len(scored) if scored is not None else 0, logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted.
    # IMPORTANT: rows with Final_Score < 0 are skipped (wrong-series penalty
    # zone — we never want to show a Vario panel to a BESPOKE buyer).
    used_materials = {tm}
    pool_cursors  = {rank: 0 for rank in pools}
    pool_taken    = {rank: 0 for rank in pools}
    slot_num = 0
    round_idx = 0

    while slot_num < FRIDGE_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= FRIDGE_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < FRIDGE_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                # Skip rows with negative scores (wrong-series penalty zone)
                if float(row.get('Final_Score', 0)) < 0:
                    continue
                slot_num += 1
                rc = row.copy()
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = FRIDGE_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs),
                 f"Filled {slot_num}/{FRIDGE_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()




# ═════════════════════════════════════════════════════════════
# 🟢 COOKERS HELPERS — Κουζίνες (v28.48)
# ═════════════════════════════════════════════════════════════
# Pool builders for the round-robin cookers engine. Config + hob/brand/
# classification helpers live in the COOKERS CONFIGURATION block near the
# top of the file (needed at sidebar load time).
#
# Pools span BOTH Home-file sheets: MDA Αξεσουάρ Κουζινών + Αξεσουάρ
# Φούρνων hold the type-classified accessory universe (care / regulator /
# cookware / trays / rails / probes); SDA contributes Ζυγαριές, Φριτέζες,
# Ψηστιέρες-Γκριλιέρες as whole hierarchies plus a TITLE-hunted prep pool
# (Κρεατομηχανές / Πολυμάγειρες / μηχανές ζυμαρικών inside Ειδικές
# Συσκευές) and the one universal kitchen thermometer (PROFICOOK, also
# misfiled-adjacent in Ειδικές Συσκευές).

def _ck_prep_kitchen_acc_frame(c_mda):
    """Slice + dedup + type-tag Αξεσουάρ Κουζινών + Αξεσουάρ Φούρνων once;
    care/regulator/cookware/tray/rail/thermo/overflow pools are
    type-filters over this frame."""
    hn = c_mda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    acc = c_mda[hn.isin({_cm_norm('Αξεσουάρ Κουζινών'), _cm_norm('Αξεσουάρ Φούρνων')})].copy()
    if acc.empty:
        return acc
    acc = acc.drop_duplicates(subset=['Material'])
    acc['_ck_type'] = acc['Title'].fillna('').astype(str).map(_ck_classify_kitchen_acc)
    acc['_ck_brand'] = acc.apply(_ck_row_brand, axis=1)
    return acc


def _ck_rival_filter(pool, trigger_brand, notes):
    """HARD rival-brand gate for MDA accessory pools (v28.48.3, user
    policy: no rival appliance brand's accessories in the carousel).
    Keeps: trigger brand family (BSH / Electrolux group counted as one
    house) + neutral non-appliance brands. Drops: every other appliance
    manufacturer. EXEMPT pools: gas regulator (standardized 29-30 mbar
    EN-16129 fitting — generic hardware despite the label), rails
    (already exact-brand), thermo (universal-only) and all SDA pools
    (standalone products, not accessories)."""
    if pool.empty:
        return pool
    fam = _ck_brand_family(trigger_brand)
    bcol = pool['_ck_brand'] if '_ck_brand' in pool.columns else \
        pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
    rival = bcol.isin(_CK_APPLIANCE_BRANDS) & ~bcol.isin(fam)
    if rival.any():
        notes.append(f"  ✗ HARD-dropped {rival.sum()} RIVAL-brand accessories ({sorted(bcol[rival].unique())[:5]} ∉ family of {trigger_brand or '—'})")
    return pool[~rival]


def _ck_base_score(pool):
    """Availability + sales — the common floor of every pool's score."""
    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += CK_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * CK_S_SALES_FACTOR
    return pool


def _ck_brand_layer(pool, trigger_brand, notes, label=''):
    """Soft ecosystem layer: exact brand +400k, BSH-family sibling +250k.
    Uses the parsed _ck_brand when present (NaN-Κατασκευαστής rows),
    falling back to the raw column for SDA pools."""
    if not trigger_brand:
        return pool
    fam = _CK_BSH_FAMILY if trigger_brand in _CK_BSH_FAMILY else set()
    bcol = pool['_ck_brand'] if '_ck_brand' in pool.columns else \
        pool['Κατασκευαστής'].fillna('').astype(str).str.upper().str.strip()
    exact = bcol == trigger_brand
    family = bcol.isin(fam) & ~exact if fam else pd.Series(False, index=pool.index)
    pool.loc[exact, 'Final_Score'] += CK_S_BRAND_MATCH
    pool.loc[family, 'Final_Score'] += CK_S_BRAND_FAMILY
    if exact.any() or family.any():
        notes.append(f"  ✓ Brand ecosystem {label}({trigger_brand}): exact={exact.sum()} (+{CK_S_BRAND_MATCH:,}), family={family.sum()} (+{CK_S_BRAND_FAMILY:,})")
    return pool


def _ck_price_ratio_layer(pool, trigger_price, notes):
    """Budget-proportionality guard for the appliance-grade companion
    pools (cookware, prep machines). The cooker tier scale (<€450 = tier
    0) can't discriminate between a €45 and a €319 companion, so instead:
    anything costing more than CK_PRICE_RATIO_CAP × trigger price gets
    CK_S_OVERPRICED_PEN. Demotion, not a drop — a deep premium trigger
    still surfaces premium companions, a €419 cooker leads with the €108
    BOSCH κρεατομηχανή instead of the €319 NINJA."""
    if trigger_price and trigger_price > 0 and 'LIST PRICE' in pool.columns:
        prices = pool['LIST PRICE'].apply(parse_euro_price)
        over = prices > trigger_price * CK_PRICE_RATIO_CAP
        pool.loc[over, 'Final_Score'] += CK_S_OVERPRICED_PEN
        if over.any():
            notes.append(f"  ✗ Over-priced demotion (>{CK_PRICE_RATIO_CAP:.0%} of trigger €{trigger_price:.0f}): {over.sum()} ({CK_S_OVERPRICED_PEN:,})")
    return pool


def _ck_tier_layer(pool, trigger_tier, notes):
    """Price-tier proximity — appliance-grade companions only (cookware,
    prep). Impulse pools (care, scale, tray, rail, thermo, regulator)
    skip it, same split as the coffee + ironing engines."""
    if 'LIST PRICE' in pool.columns:
        tiers = pool['LIST PRICE'].apply(parse_euro_price).apply(_ck_price_tier)
        same_tier = tiers == trigger_tier
        near_tier = (tiers - trigger_tier).abs() == 1
        pool.loc[same_tier, 'Final_Score'] += CK_S_PRICE_SAME_TIER
        pool.loc[near_tier, 'Final_Score'] += CK_S_PRICE_ONE_OFF
        if same_tier.any() or near_tier.any():
            notes.append(f"  ✓ Price-tier match (tier {trigger_tier}): same={same_tier.sum()}, near={near_tier.sum()}")
    return pool


def _ck_build_care_pool(acc, hob, trigger_brand, notes):
    """Slots — Καθαρισμός ×2 (brand-diverse pair, e.g. MIELE κρέμα +
    BOSCH τζελ φούρνου).

    HOB GATE: care_ceramic (ξύστρες, λεπίδες, καθαριστικό κεραμικών) is
    ONLY eligible on CERAMIC / INDUCTION hobs — a scraper against a gas or
    enamel cooker is a physical mismatch, HARD-dropped. care_oven
    (καθαριστικά/τζελ φούρνου) and care_surface (κρέμες/σκόνες/πανιά/σετ
    καθαρισμού) are universal.

    BRAND DOMINATES (v28.48.2, user spec): an exact trigger-brand care
    item gets +CK_S_CARE_BRAND (1.2M) which outranks the hob boost — when
    the brand sells its own care line (AEG, BOSCH, MIELE), the pair leads
    with it and competitor consumables only fill what's left. On ceramic/
    induction triggers the ceramic-specific items still get
    +CK_S_HOB_SPECIFIC as the secondary signal."""
    pool = acc[acc['_ck_type'].isin(['care_ceramic', 'care_oven', 'care_surface'])].copy()
    pool = _ck_rival_filter(pool, trigger_brand, notes)
    if pool.empty:
        notes.append("  ⚠ No own-family/neutral cleaning products — slot backfills (no rival-brand bleed)")
        return pool
    ceramic_ok = hob in ('CERAMIC', 'INDUCTION')
    if not ceramic_ok:
        drop = pool['_ck_type'] == 'care_ceramic'
        if drop.any():
            notes.append(f"  ✗ HARD-dropped {drop.sum()} ceramic-hob care items (hob={hob} — no glass surface to scrape)")
        pool = pool[~drop]
        if pool.empty:
            notes.append("  ⚠ Care pool empty after hob gating")
            return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT
    if ceramic_ok:
        cer = pool['_ck_type'] == 'care_ceramic'
        pool.loc[cer, 'Final_Score'] += CK_S_HOB_SPECIFIC
        if cer.any():
            notes.append(f"  ✓ Ceramic-hob care leads the pair: {cer.sum()} (+{CK_S_HOB_SPECIFIC:,})")
    spare = pool['Title'].fillna('').astype(str).map(_cm_norm).str.contains('ΑΝΤΑΛΛΑΚΤΙΚ', na=False)
    pool.loc[spare, 'Final_Score'] += CK_S_SPARE_PART_PEN
    if spare.any():
        notes.append(f"  ✗ Spare-part demotion (ΑΝΤΑΛΛΑΚΤΙΚ): {spare.sum()} ({CK_S_SPARE_PART_PEN:,})")
    if trigger_brand:
        exact = pool['_ck_brand'] == trigger_brand
        fam = pool['_ck_brand'].isin(_CK_BSH_FAMILY) & ~exact if trigger_brand in _CK_BSH_FAMILY \
            else pd.Series(False, index=pool.index)
        pool.loc[exact, 'Final_Score'] += CK_S_CARE_BRAND
        pool.loc[fam, 'Final_Score'] += CK_S_BRAND_FAMILY
        if exact.any() or fam.any():
            notes.append(f"  ✓ Own-brand care DOMINATES ({trigger_brand}): exact={exact.sum()} (+{CK_S_CARE_BRAND:,}), family={fam.sum()} (+{CK_S_BRAND_FAMILY:,})")
    notes.append(f"  Pool size: {len(pool)} | mix: {pool['_ck_type'].value_counts().to_dict()}")
    return pool.sort_values('Final_Score', ascending=False)


def _ck_build_gas_reg_pool(acc, hob, trigger_brand, notes):
    """Slot — Ρυθμιστής Πίεσης Υγραερίου. HARD hob gate: GAS / MIXED
    triggers only — the inverse of the ceramic-scraper gate. One SKU in
    the catalog (LA GERMANIA 3kg/h 29mbar) and 51% of all cooker triggers
    ARE LA GERMANIA gas models → brand boost usually fires too. Electric
    triggers cleanly skip the slot."""
    if hob not in ('GAS', 'MIXED'):
        notes.append(f"  ℹ Electric trigger (hob={hob}) — gas regulator slot skipped")
        return pd.DataFrame()
    pool = acc[acc['_ck_type'] == 'gas_regulator'].copy()
    if pool.empty:
        notes.append("  ⚠ No gas-pressure regulators in Αξεσουάρ Κουζινών")
        return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT
    pool = _ck_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)} (gas trigger — regulator eligible)")
    return pool.sort_values('Final_Score', ascending=False)


def _ck_build_cookware_pool(acc, hob, trigger_brand, trigger_price, notes):
    """Slots — Μαγειρικά Σκεύη ×2 (substitutes the spec's pan/pot/mitts
    slots — no standalone cookware hierarchies exist).

    INDUCTION GATE (user spec: 'induction-compatible if induction hob'):
    aluminium-bodied items (ΑΛΟΥΜΙΝΙ in title — the AEG Fusion Wok) are
    HARD-dropped for INDUCTION triggers — no ferromagnetic base, the hob
    won't even detect them. Inox sets (BOSCH HEZ9SE030 / AEG A3SS / NEFF
    Z943SE0) and the FISSLER χύτρα are all-hob. Appliance-grade pool →
    price-ratio guard ON (a €419 FISSLER χύτρα shouldn't lead against a
    €339 OMNYS — demoted whenever it costs >50% of the trigger)."""
    pool = acc[acc['_ck_type'] == 'cookware'].copy()
    pool = _ck_rival_filter(pool, trigger_brand, notes)
    if pool.empty:
        notes.append("  ⚠ No own-family/neutral cookware — slot backfills (no rival-brand bleed)")
        return pool
    if hob == 'INDUCTION':
        tn = pool['Title'].fillna('').astype(str).map(_cm_norm)
        alu = tn.str.contains('ΑΛΟΥΜΙΝΙ', na=False)
        if alu.any():
            notes.append(f"  ✗ HARD-dropped {alu.sum()} aluminium cookware (induction hob — no ferromagnetic base)")
        pool = pool[~alu]
        if pool.empty:
            notes.append("  ⚠ Cookware pool empty after induction gating")
            return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT
    pool = _ck_brand_layer(pool, trigger_brand, notes)
    pool = _ck_price_ratio_layer(pool, trigger_price, notes)
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _ck_build_tray_pool(acc, trigger_brand, notes):
    """Slots — Ταψί & Σκεύη Φούρνου ×2 (brand-diverse). Trays mount on
    oven side rails — rival appliance brands are HARD-dropped by the
    rival filter (v28.48.3); within the surviving family+neutral pool the
    exact brand still gets the soft boost. Impulse-adjacent → no tier
    mirror; sales lead."""
    pool = acc[acc['_ck_type'] == 'tray'].copy()
    pool = _ck_rival_filter(pool, trigger_brand, notes)
    if pool.empty:
        notes.append("  ⚠ No own-family/neutral trays — slot backfills (no rival-brand bleed)")
        return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT
    pool = _ck_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)} | brands: {pool['_ck_brand'].replace('', pd.NA).nunique()}")
    return pool.sort_values('Final_Score', ascending=False)


def _ck_build_rail_pool(acc, trigger_brand, notes):
    """Slot — Τηλεσκοπικός Μηχανισμός. HARD brand-FAMILY gate (user spec:
    'same brand'; printer-cartridge philosophy): rails bolt onto
    model-specific side-rack mounts. BSH marques share the platform
    (HEZ538000 ↔ PZ11TI15X0 ↔ Z11TI15X0 are the same part rebranded —
    same family precedent as the fridge engine), MIELE FlexiClip and LG
    are strict same-brand. LA GERMANIA / BERTAZZONI have no rails in the
    catalog → the slot cleanly EMPTIES and the backfill chain absorbs it.
    No cross-brand bleed, ever."""
    pool = acc[acc['_ck_type'] == 'rail'].copy()
    if pool.empty:
        notes.append("  ⚠ No telescopic rails in Αξεσουάρ Κουζινών/Φούρνων")
        return pool
    # v28.48.1 — tightened from BSH-FAMILY to EXACT brand. The family
    # gate let a PITSOS trigger pull BOSCH/NEFF/SIEMENS rails; even if
    # the BSH platform shares the part internally, mounting is published
    # per model line and the user spec says 'same brand' — strict-filter
    # principle wins. Brands without their own rail SKU (LA GERMANIA,
    # BERTAZZONI, GORENJE…) cleanly EMPTY the slot.
    keep = (pool['_ck_brand'] == trigger_brand) if trigger_brand else pd.Series(False, index=pool.index)
    dropped = (~keep).sum()
    if dropped:
        notes.append(f"  ✗ HARD-dropped {dropped} rails (brand ≠ {trigger_brand or '—'} — model-specific mounts, exact-brand gate)")
    pool = pool[keep]
    if pool.empty:
        notes.append(f"  ⚠ No {trigger_brand or '—'} rail in catalog — slot backfills (correct behavior, no cross-brand bleed)")
        return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT + CK_S_BRAND_MATCH
    notes.append(f"  ✓ Same-brand rails ({trigger_brand}): {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _ck_build_thermo_pool(acc, c_sda, trigger_brand, notes):
    """Slot — Θερμόμετρο Μαγειρικής. UNIVERSAL thermometers ONLY.

    The three MDA 'thermo' rows (NEFF Z1365WX0, BOSCH HEZ32WA00, BOSCH
    HEZ39050) are NOT standalone thermometers — they are plug-in roast
    probes / PerfectCook hob sensors that require a probe SOCKET on a
    premium BUILT-IN oven or hob. Freestanding cookers (this engine's
    entire trigger set) carry no socket, so even a same-brand match is a
    physical incompatibility — the v28.48.0 BSH-family gate was the
    WRONG test (family ≠ model capability; validated failure: NEFF
    Z1365WX0 €129 offered against a PITSOS PAF003D20 €419 gas cooker).
    They are excluded ENTIRELY (v28.48.1).

    The pool is the title-hunted universal kitchen thermometer(s) from
    SDA (PROFICOOK PC-DHT 1039) — exactly the user's slot-10 alternative
    ('…or kitchen thermometer')."""
    tn = c_sda['Title'].fillna('').astype(str).map(_cm_norm)
    pool = c_sda[tn.str.contains('ΘΕΡΜΟΜΕΤΡΟ ΚΟΥΖΙΝΑΣ', na=False)].drop_duplicates(subset=['Material']).copy()
    n_probes = int((acc['_ck_type'] == 'thermo').sum()) if not acc.empty else 0
    if n_probes:
        notes.append(f"  ✗ HARD-excluded {n_probes} built-in oven probes/sensors (socket parts — no freestanding cooker has a probe socket)")
    if pool.empty:
        notes.append("  ⚠ No universal kitchen thermometer — slot backfills")
        return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT
    notes.append(f"  ✓ Universal kitchen thermometer(s): {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


def _ck_build_hierarchy_pool(c_sda, hier_name, trigger_brand, notes, label):
    """Shared builder for the whole-hierarchy SDA pools (Ζυγαριές,
    Φριτέζες, Ψηστιέρες-Γκριλιέρες). Impulse pattern: availability +
    sales + soft brand boost, NO tier mirror — a €17 LAICA scale sells
    against any cooker."""
    hn = c_sda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    pool = c_sda[hn == _cm_norm(hier_name)].drop_duplicates(subset=['Material']).copy()
    if pool.empty:
        notes.append(f"  ⚠ No {label} in SDA")
        return pool
    pool = _ck_base_score(pool)
    pool.loc[:, 'Final_Score'] += CK_S_TYPE_RELEVANT
    pool = _ck_brand_layer(pool, trigger_brand, notes)
    notes.append(f"  ℹ Impulse companion — tier mirroring OFF (sales + availability decide)")
    notes.append(f"  Pool size: {len(pool)}")
    return pool.sort_values('Final_Score', ascending=False)


# ═════════════════════════════════════════════════════════════
# 🟢 COOKERS ENGINE — Κουζίνες (v28.48)
# ═════════════════════════════════════════════════════════════

def run_cookers_engine(trigger, df_mda, df_sda, df_history):
    """Build up to 10 cross-sell slots for a cooker trigger (Κουζίνα
    Αερίου / Ηλεκτρική).

    Round 1 lays the hero of each live pool across slots 1-9 (Καθαρισμός
    ×2 → Ρυθμιστής → Σκεύη → Ταψί → Τηλεσκοπικός → Θερμόμετρο → Τοστιέρα →
    Βραστήρας → Ζυγαριά); the hob + rival gates mean a typical trigger
    has 6-9 live pools. Round 2 lays the B-options (different brand, enforced by
    the brand-diversity cap) of the 2-cap pools; the backfill chain
    (Φριτέζα → Ψηστιέρα → kitchen-accessory overflow) guarantees 10/10.

    Trigger + MDA accessory pools come from the MDA sheet; Ζυγαριές /
    Φριτέζες / Ψηστιέρες / prep machines / the universal thermometer come
    from the SDA sheet.
    """
    diag = []
    slot_notes = {}
    all_recs = []

    # ── Trigger attributes
    tm = trigger['Material']
    tb = str(trigger.get('Κατασκευαστής', '')).strip().upper()
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    ttier = _ck_price_tier(tprice)
    thob = _ck_detect_hob(trigger)

    diag.append(("0. Trigger", f"{tb} €{tprice:.0f}",
                 f"Hob={thob} | Tier={ttier} | Hierarchy={trigger.get('Hierarchy', '—')} | "
                 f"Τύπος εστίας={_cm_attr(trigger, 'Τύπος εστίας ≡', '—')}"))

    if df_mda is None or df_mda.empty:
        diag.append(("ERROR", 0, "MDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # ── MDA universe minus the trigger + ALL competitor cookers (plus the
    # adjacent built-in cooking hierarchies — a freestanding-cooker buyer
    # shouldn't see hobs/ovens/built-in sets, they solve the same problem)
    c_mda = df_mda[df_mda['Material'] != tm].copy()
    hn = c_mda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    competitor_hiers = {_cm_norm(h) for h in COOKER_TRIGGER_HIERARCHIES}
    competitor_prefixes = ('ΕΣΤΙΕΣ', 'ΦΟΥΡΝΟΙ', 'ΕΝΤΟΙΧΙΖΟΜΕΝ')
    is_comp = hn.isin(competitor_hiers) | hn.str.startswith(competitor_prefixes)
    b4 = len(c_mda)
    c_mda = c_mda[~is_comp]
    diag.append(("1. MDA pool", len(c_mda),
                 f"Removed {b4 - len(c_mda)} competitor cookers/hobs/ovens/built-in sets"))

    # ── Sales tiebreaker prep (pandas-3.x safe: plain float64)
    for frame in (c_mda,):
        if 'Sum of Sales' in frame.columns:
            frame['Sales_Tiebreaker'] = pd.to_numeric(frame['Sum of Sales'], errors='coerce').fillna(0.0).astype('float64')
        else:
            frame['Sales_Tiebreaker'] = 0.0

    c_sda = pd.DataFrame()
    if df_sda is not None and not df_sda.empty:
        c_sda = df_sda[df_sda['Material'] != tm].copy()
        if 'Sum of Sales' in c_sda.columns:
            c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda['Sum of Sales'], errors='coerce').fillna(0.0).astype('float64')
        else:
            c_sda['Sales_Tiebreaker'] = 0.0

    # ── Type-tagged kitchen-accessory frame (care/regulator/cookware/tray/rail/thermo)
    acc = _ck_prep_kitchen_acc_frame(c_mda)
    diag.append(("2. Αξεσουάρ Κουζινών+Φούρνων", len(acc),
                 f"Type mix: {acc['_ck_type'].value_counts().to_dict() if not acc.empty else '—'}"))

    # ── Build a sorted pool per priority entry
    pools = {}
    for rank, role_label, logic_key, max_r1, max_total in COOKER_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]

        if logic_key == 'CK_CARE':
            scored = _ck_build_care_pool(acc, thob, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CK_GAS_REG':
            scored = _ck_build_gas_reg_pool(acc, thob, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CK_COOKWARE':
            scored = _ck_build_cookware_pool(acc, thob, tb, tprice, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CK_TRAY':
            scored = _ck_build_tray_pool(acc, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CK_RAIL':
            scored = _ck_build_rail_pool(acc, tb, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'CK_THERMO':
            scored = _ck_build_thermo_pool(acc, c_sda, tb, notes) if (not acc.empty or not c_sda.empty) else pd.DataFrame()
        elif logic_key == 'CK_TOASTER':
            scored = _ck_build_hierarchy_pool(c_sda, 'Τοστιέρες', tb, notes, 'τοστιέρες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'CK_KETTLE':
            scored = _ck_build_hierarchy_pool(c_sda, 'Βραστήρες', tb, notes, 'βραστήρες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'CK_SCALE':
            scored = _ck_build_hierarchy_pool(c_sda, 'Ζυγαριές', tb, notes, 'ζυγαριές') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'CK_AIRFRYER':
            scored = _ck_build_hierarchy_pool(c_sda, 'Φριτέζες', tb, notes, 'φριτέζες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'CK_GRILL':
            scored = _ck_build_hierarchy_pool(c_sda, 'Ψηστιέρες, Γκριλιέρες', tb, notes, 'ψηστιέρες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'CK_OVERFLOW':
            # Last-resort backfill — leftover kitchen/oven accessories
            # (ROLLER appliance bases, σακούλες, MIELE καπάκι σκεύους…).
            # The typed pools own their slots; hood parts and steam-oven
            # tablets are already classified 'other' BUT hood parts are
            # excluded again here by title — they're for a different
            # appliance, never recommendable against a cooker.
            scored = acc[acc['_ck_type'] == 'other'].copy() if not acc.empty else pd.DataFrame()
            if not scored.empty:
                tnn = scored['Title'].fillna('').astype(str).map(_cm_norm)
                scored = scored[~tnn.str.contains('ΑΠΟΡΡΟΦΗΤΗΡ|ΦΙΛΤΡΟ ΑΝΘΡΑΚΑ|ΦΟΥΡΝΟ ΑΤΜΟΥ|ΚΑΠΑΚΙ ΓΙΑ|ΘΕΡΜΑΙΝΟΜΕΝΟ ΣΥΡΤΑΡΙ|ΕΝΤΟΙΧΙΖΟΜΕΝ|TWIST PAD', regex=True, na=False)]
                scored = _ck_rival_filter(scored, tb, notes)
            if not scored.empty:
                scored = _ck_base_score(scored)
                scored = _ck_brand_layer(scored, tb, notes, label='(overflow) ')
                scored = scored.sort_values('Final_Score', ascending=False)
                notes.append(f"  Overflow pool size: {len(scored)}")
            else:
                notes.append("  ⚠ Overflow pool empty")
        else:
            scored = pd.DataFrame()

        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", 0 if scored is None or scored.empty else len(scored), logic_key))

    # ── LOOPING: round-robin fill until target hit or all pools exhausted
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken = {rank: 0 for rank in pools}
    # Brand-diversity guard: max CK_BRAND_DIVERSITY_CAP per brand inside the
    # 2-cap pools — guarantees pair A ≠ pair B brand (MIELE κρέμα + BOSCH
    # τζελ, BOSCH κρεατομηχανή + NINJA πολυμάγειρας, never two MIELE).
    pool_brand_counts = {rank: {} for rank in pools}
    care_types_taken = set()   # care type-diversity tracker (v28.48.2)
    diversity_relaxed = False  # one-shot relaxation pass flag (v28.48.3)
    slot_num = 0
    round_idx = 0

    while slot_num < COOKER_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= COOKER_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue

            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])

            # CK_CARE left the brand-diversity list in v28.48.2: a same-
            # brand care PAIR is the desired outcome (AEG cream + AEG
            # scraper blade at slots 1-2). Variety inside care is enforced
            # by TYPE instead — pick #2 must be a different _ck_type, so
            # two near-identical oven gels can never sit in one carousel.
            # CK_OVERFLOW added v28.48.3: with rivals excluded, brands
            # without an own accessory line backfill heavily from overflow
            # — without the cap a BERTAZZONI carousel ended with THREE
            # ROLLER appliance bases in a row.
            apply_brand_diversity = (logic_key in ('CK_COOKWARE', 'CK_TRAY', 'CK_OVERFLOW'))

            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < COOKER_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                row_brand = str(row.get('_ck_brand', '') or row.get('Κατασκευαστής', '') or '').strip().upper()
                if apply_brand_diversity and not diversity_relaxed:
                    if pool_brand_counts[rank].get(row_brand, 0) >= CK_BRAND_DIVERSITY_CAP:
                        continue
                if logic_key == 'CK_CARE' and not diversity_relaxed \
                        and row.get('_ck_type', '') in care_types_taken:
                    continue  # care type-diversity: no two gels / two creams

                slot_num += 1
                rc = row.copy()
                rc['Slot_Position'] = slot_num
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = COOKER_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                if apply_brand_diversity:
                    pool_brand_counts[rank][row_brand] = pool_brand_counts[rank].get(row_brand, 0) + 1
                if logic_key == 'CK_CARE':
                    care_types_taken.add(row.get('_ck_type', ''))
                progress = True

                title_preview = str(row.get('Title', ''))[:70]
                score_val = float(row.get('Final_Score', 0))
                type_hint = f" | type={row.get('_ck_type', '')}" if '_ck_type' in row.index else ""
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {score_val:,.0f}{type_hint} | {title_preview}"
                )

            pool_cursors[rank] = cursor

        if not progress:
            if not diversity_relaxed and slot_num < COOKER_SLOT_TARGET:
                # Relaxation pass (v28.48.3): the rival-brand exclusion can
                # starve non-family triggers' tails (e.g. GORENJE enamel —
                # neutral overflow is 3× ROLLER + 1× LEIFHEIT, but the
                # brand-diversity cap allows one ROLLER). Slot fill is
                # non-negotiable, so lift ONLY the diversity caps and keep
                # looping. Every HARD gate (hob, rival, exact-brand rail)
                # already shaped the pools and stays intact — a second
                # ROLLER base is the correct lesser evil vs. a 9-slot
                # carousel or a rival's accessory.
                diversity_relaxed = True
                pool_cursors = {rank: 0 for rank in pools}  # rescan skipped rows
                diag.append(("Loop", round_idx, "Diversity caps relaxed — backfilling remaining slots (hard gates unchanged)"))
                continue
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    # ── Pool diagnostics under slot 0
    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(
            f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}"
        )
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes

    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{COOKER_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()



# ═════════════════════════════════════════════════════════════
# 🟢 BUILT-IN DISHWASHERS HELPERS + ENGINE (Εντοιχιζόμενα Πλυντήρια Πιάτων, v28.49)
# ═════════════════════════════════════════════════════════════
# Pool builders + round-robin engine. Config and title-parsing helpers
# live in the DISHWASHERS CONFIGURATION block (sidebar load-time needs
# them). Reuses the cookers infrastructure deliberately: _CK_KNOWN_BRANDS
# for title parsing, _ck_brand_family / _CK_APPLIANCE_BRANDS for the
# no-rival policy, and the cookers' SDA backfill builders' philosophy.

def _dwash_prep_acc_frame(c_mda):
    """Combined, type-tagged DW accessory universe: the dedicated
    Αξεσουάρ Πλυντηρίων Πιάτων hierarchy PLUS dishwasher items cross-filed
    in Αξεσουάρ Πλυντηρίου - Στεγνωτηρίου (MIELE UltraTabs, AEG Super
    Care / 3-σε-1 / Neocal — title must reference ΠΙΑΤΩΝ or be the
    Neocal water-line device)."""
    hn = c_mda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    own = c_mda[hn == _cm_norm('Αξεσουάρ Πλυντηρίων Πιάτων')]
    laundry = c_mda[hn == _cm_norm('Αξεσουάρ Πλυντηρίου - Στεγνωτηρίου')]
    if not laundry.empty:
        lt = laundry['Title'].fillna('').astype(str).map(_cm_norm)
        laundry = laundry[lt.str.contains('ΠΙΑΤΩΝ|ΔΙΑΣΠΑΣΗΣ ΑΛΑΤΩΝ', regex=True, na=False)]
    acc = pd.concat([own, laundry], ignore_index=False)
    if acc.empty:
        return acc
    acc = acc.drop_duplicates(subset=['Material']).copy()
    acc['_dw_type'] = acc['Title'].fillna('').astype(str).map(_dwash_classify)
    acc['_dw_brand'] = acc.apply(_dwash_row_brand, axis=1)
    return acc


def _dwash_score(pool, trigger_brand, notes, brand_dominant=True):
    """Availability + sales + type relevance + own-brand boost. The rival
    filter runs BEFORE this, so the boost only separates own-brand from
    neutral items."""
    pool['Final_Score'] = 0.0
    if 'AVAILABILITY' in pool.columns:
        pool.loc[pool['AVAILABILITY'] == 'Άμεσα Διαθέσιμο', 'Final_Score'] += DWASH_S_AVAILABILITY
    pool['Final_Score'] += pool['Sales_Tiebreaker'].fillna(0) * DWASH_S_SALES_FACTOR
    pool.loc[:, 'Final_Score'] += DWASH_S_TYPE_RELEVANT
    if trigger_brand and brand_dominant:
        fam = _ck_brand_family(trigger_brand)
        exact = pool['_dw_brand'].isin(fam)
        pool.loc[exact, 'Final_Score'] += DWASH_S_BRAND_MATCH
        if exact.any():
            notes.append(f"  ✓ Own-family boost ({trigger_brand}): {exact.sum()} (+{DWASH_S_BRAND_MATCH:,})")
    return pool.sort_values('Final_Score', ascending=False)


def _dwash_rival_filter(pool, trigger_brand, notes):
    """No-rival-brands policy (v28.48.3, user) applied to the DW pools:
    keep trigger family + neutral (FAIRY, FINISH, AQUASAN, '' from the
    title parse); drop rival appliance brands' branded items. A BOSCH
    trigger does not get MIELE salt; the slot backfills instead."""
    if pool.empty:
        return pool
    fam = _ck_brand_family(trigger_brand)
    rival = pool['_dw_brand'].isin(_CK_APPLIANCE_BRANDS) & ~pool['_dw_brand'].isin(fam)
    if rival.any():
        notes.append(f"  ✗ HARD-dropped {rival.sum()} RIVAL-brand items ({sorted(pool.loc[rival, '_dw_brand'].unique())[:4]} ∉ family of {trigger_brand or '—'})")
    return pool[~rival]


def _dwash_build_type_pool(acc, dw_type, trigger_brand, notes, label):
    """Shared builder for the consumable slots (detergent / salt / rinse /
    cleaner / freshener / antiscale): type slice → rival filter → score."""
    pool = acc[acc['_dw_type'] == dw_type].copy()
    pool = _dwash_rival_filter(pool, trigger_brand, notes)
    if pool.empty:
        notes.append(f"  ⚠ No own-family/neutral {label} — slot backfills")
        return pool
    pool = _dwash_score(pool, trigger_brand, notes)
    notes.append(f"  Pool size: {len(pool)}")
    return pool


def _dwash_build_door_pool(acc, trigger_brand, trigger_width, notes):
    """Slot — Πόρτα / Μετόπη Inox. DOUBLE HARD GATE:
      1. EXACT brand family — door fronts mount on brand-specific hinge
         and fixing systems (BOSCH SMZ/SPZ, SIEMENS SZ7, MIELE GFV);
         printer-cartridge philosophy, no cross-brand bleed, brands
         without doors (LG, WHIRLPOOL, MIDEA, AEG…) cleanly EMPTY.
      2. WIDTH — a 60 cm front on a 45 cm SlimLine cannot mount.
         Width parsed per _dwash_acc_widths (45/60 tokens + SPZ/SMZ/SZ7
         code prefixes; MIELE 'GFV 45/60' fits both)."""
    pool = acc[acc['_dw_type'] == 'door'].copy()
    if pool.empty:
        notes.append("  ⚠ No door fronts in catalog")
        return pool
    fam = _ck_brand_family(trigger_brand)
    keep_brand = pool['_dw_brand'].isin(fam)
    if (~keep_brand).any():
        notes.append(f"  ✗ HARD-dropped {(~keep_brand).sum()} doors (brand family ≠ {trigger_brand or '—'})")
    pool = pool[keep_brand]
    if not pool.empty:
        widths = pool['Title'].fillna('').astype(str).map(_dwash_acc_widths)
        keep_w = widths.apply(lambda ws: trigger_width in ws)
        if (~keep_w).any():
            notes.append(f"  ✗ HARD-dropped {(~keep_w).sum()} doors (width ≠ {trigger_width} cm)")
        pool = pool[keep_w]
    if pool.empty:
        notes.append(f"  ⚠ No {trigger_brand or '—'} {trigger_width} cm door — slot backfills (correct, no incompatible fronts)")
        return pool
    pool = _dwash_score(pool, trigger_brand, notes)
    notes.append(f"  ✓ Compatible doors ({trigger_brand}, {trigger_width} cm): {len(pool)}")
    return pool


def _dwash_build_basket_pool(acc, trigger_brand, trigger_width, notes):
    """Slot — Θήκη Μπουκαλιών (PITSOS Blue clip DZP4BH00/DZP6BH00). The
    clips snap onto BSH rack tines → HARD BSH-family gate + width gate
    (45 vs 60 in the titles)."""
    pool = acc[acc['_dw_type'] == 'basket'].copy()
    if pool.empty:
        notes.append("  ⚠ No bottle holders in catalog")
        return pool
    fam = _ck_brand_family(trigger_brand) & _CK_BSH_FAMILY
    keep = pool['_dw_brand'].isin(fam)
    if (~keep).any():
        notes.append(f"  ✗ HARD-dropped {(~keep).sum()} holders (BSH rack part, family ≠ {trigger_brand or '—'})")
    pool = pool[keep]
    if not pool.empty:
        widths = pool['Title'].fillna('').astype(str).map(_dwash_acc_widths)
        keep_w = widths.apply(lambda ws: trigger_width in ws)
        if (~keep_w).any():
            notes.append(f"  ✗ HARD-dropped {(~keep_w).sum()} holders (width ≠ {trigger_width} cm)")
        pool = pool[keep_w]
    if pool.empty:
        notes.append("  ⚠ No compatible bottle holder — slot backfills")
        return pool
    pool = _dwash_score(pool, trigger_brand, notes)
    notes.append(f"  ✓ Compatible holders: {len(pool)}")
    return pool


def run_dishwasher_engine(trigger, df_mda, df_sda, df_history):
    """Up to 10 cross-sell slots for a built-in dishwasher trigger.

    Round 1: consumables first (detergent → salt → rinse → cleaner), then
    the hard-gated hardware (door front, bottle holder), freshener,
    anti-scale. Rival policy means brands without an accessory line (LG,
    WHIRLPOOL, MIDEA, TEKA, GORENJE) ride on neutral consumables (FAIRY/
    FINISH) and the SDA backfill chain (ζυγαριά → φριτέζα → ψηστιέρα →
    neutral kitchen overflow). One-shot diversity relaxation guarantees
    10/10 (hard gates never relax)."""
    diag = []
    slot_notes = {}
    all_recs = []

    tm = trigger['Material']
    tb = _dwash_row_brand(trigger)          # Κατασκευαστής is blank — title parse
    tprice = parse_euro_price(trigger.get('LIST PRICE', 0))
    tw = _dwash_trigger_width(trigger.get('Title', ''))
    tset = _dwash_settings(trigger.get('Title', ''))
    tfull = 'ΠΛΗΡΩΣ' in _cm_norm(trigger.get('Title', ''))

    diag.append(("0. Trigger", f"{tb or '—'} €{tprice:.0f}",
                 f"Width={tw}cm | Σερβίτσια={tset if tset is not None else '—'} | "
                 f"{'Πλήρως εντοιχιζόμενο' if tfull else 'Εντοιχιζόμενο (semi)'} | brand TITLE-parsed (Κατασκευαστής blank)"))

    if df_mda is None or df_mda.empty:
        diag.append(("ERROR", 0, "MDA sheet is empty — engine cannot run"))
        return pd.DataFrame(), diag, slot_notes, pd.DataFrame()

    # competitor removal: both DW hierarchies (built-in + freestanding)
    c_mda = df_mda[df_mda['Material'] != tm].copy()
    hn = c_mda['Hierarchy'].fillna('').astype(str).map(_cm_norm)
    comp = hn.isin({_cm_norm('Εντοιχιζόμενα Πλυντήρια Πιάτων'), _cm_norm('Πλυντήρια Πιάτων')})
    b4 = len(c_mda)
    c_mda = c_mda[~comp]
    diag.append(("1. MDA pool", len(c_mda), f"Removed {b4 - len(c_mda)} competitor dishwashers"))

    c_mda['Sales_Tiebreaker'] = pd.to_numeric(c_mda.get('Sum of Sales'), errors='coerce').fillna(0.0).astype('float64')
    c_sda = pd.DataFrame()
    if df_sda is not None and not df_sda.empty:
        c_sda = df_sda[df_sda['Material'] != tm].copy()
        c_sda['Sales_Tiebreaker'] = pd.to_numeric(c_sda.get('Sum of Sales'), errors='coerce').fillna(0.0).astype('float64')

    acc = _dwash_prep_acc_frame(c_mda)
    diag.append(("2. DW accessory universe", len(acc),
                 f"Type mix: {acc['_dw_type'].value_counts().to_dict() if not acc.empty else '—'}"))

    pools = {}
    for rank, role_label, logic_key, max_r1, max_total in DWASH_PRIORITY:
        notes = [f"=== Priority {rank}: {role_label} ({logic_key}) "
                 f"| max_round_1={max_r1} | max_total={max_total if max_total else '∞'} ==="]
        if logic_key == 'DWASH_DETERGENT':
            scored = _dwash_build_type_pool(acc, 'detergent', tb, notes, 'detergent') if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_SALT':
            scored = _dwash_build_type_pool(acc, 'salt', tb, notes, 'salt') if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_RINSE':
            scored = _dwash_build_type_pool(acc, 'rinse', tb, notes, 'rinse aid') if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_CLEANER':
            scored = _dwash_build_type_pool(acc, 'cleaner', tb, notes, 'machine cleaner') if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_DOOR':
            scored = _dwash_build_door_pool(acc, tb, tw, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_BASKET':
            scored = _dwash_build_basket_pool(acc, tb, tw, notes) if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_FRESHENER':
            scored = _dwash_build_type_pool(acc, 'freshener', tb, notes, 'freshener') if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_ANTISCALE':
            scored = _dwash_build_type_pool(acc, 'antiscale', tb, notes, 'anti-scale device') if not acc.empty else pd.DataFrame()
        elif logic_key == 'DWASH_SCALE':
            scored = _ck_build_hierarchy_pool(c_sda, 'Ζυγαριές', tb, notes, 'ζυγαριές') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'DWASH_AIRFRYER':
            scored = _ck_build_hierarchy_pool(c_sda, 'Φριτέζες', tb, notes, 'φριτέζες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'DWASH_GRILL':
            scored = _ck_build_hierarchy_pool(c_sda, 'Ψηστιέρες, Γκριλιέρες', tb, notes, 'ψηστιέρες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'DWASH_KETTLE':
            scored = _ck_build_hierarchy_pool(c_sda, 'Βραστήρες', tb, notes, 'βραστήρες') if not c_sda.empty else pd.DataFrame()
        elif logic_key == 'DWASH_OVERFLOW':
            # neutral kitchen-accessory overflow — same source as the
            # cookers engine; the cooker classifier's 'other' bucket plus
            # its exclusion list and the rival filter keep it sane.
            kacc = _ck_prep_kitchen_acc_frame(c_mda)
            scored = kacc[kacc['_ck_type'] == 'other'].copy() if not kacc.empty else pd.DataFrame()
            if not scored.empty:
                tnn = scored['Title'].fillna('').astype(str).map(_cm_norm)
                scored = scored[~tnn.str.contains('ΑΠΟΡΡΟΦΗΤΗΡ|ΦΙΛΤΡΟ ΑΝΘΡΑΚΑ|ΦΟΥΡΝΟ ΑΤΜΟΥ|ΚΑΠΑΚΙ ΕΣΤΙΩΝ|ΚΑΠΑΚΙ ΓΙΑ|ΘΕΡΜΑΙΝΟΜΕΝΟ ΣΥΡΤΑΡΙ|ΕΝΤΟΙΧΙΖΟΜΕΝ|TWIST PAD', regex=True, na=False)]
                scored = _ck_rival_filter(scored, tb, notes)
            if not scored.empty:
                scored = scored.rename(columns={'_ck_brand': '_dw_brand'})
                scored = _dwash_score(scored, tb, notes, brand_dominant=False)
                notes.append(f"  Overflow pool size: {len(scored)}")
            else:
                notes.append("  ⚠ Overflow pool empty")
        else:
            scored = pd.DataFrame()
        pools[rank] = (role_label, scored, logic_key, max_r1, max_total, notes)
        diag.append((f"Pool {rank} ({role_label})", 0 if scored is None or scored.empty else len(scored), logic_key))

    # ── round-robin loop with diversity caps + one-shot relaxation
    used_materials = {tm}
    pool_cursors = {rank: 0 for rank in pools}
    pool_taken = {rank: 0 for rank in pools}
    pool_brand_counts = {rank: {} for rank in pools}
    diversity_relaxed = False
    slot_num = 0
    round_idx = 0

    while slot_num < DWASH_SLOT_TARGET:
        progress = False
        round_idx += 1
        for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
            if slot_num >= DWASH_SLOT_TARGET:
                break
            if scored is None or scored.empty:
                continue
            if max_total is not None and pool_taken[rank] >= max_total:
                continue
            take_n = max_r1 if round_idx == 1 else 1
            if max_total is not None:
                take_n = min(take_n, max_total - pool_taken[rank])
            apply_brand_diversity = (logic_key in ('DWASH_DETERGENT', 'DWASH_OVERFLOW'))
            cursor = pool_cursors[rank]
            taken_this_pass = 0
            while taken_this_pass < take_n and cursor < len(scored) \
                  and slot_num < DWASH_SLOT_TARGET:
                row = scored.iloc[cursor]
                cursor += 1
                if row['Material'] in used_materials:
                    continue
                row_brand = str(row.get('_dw_brand', '') or '').strip().upper()
                if apply_brand_diversity and not diversity_relaxed:
                    if pool_brand_counts[rank].get(row_brand, 0) >= DWASH_BRAND_DIVERSITY_CAP:
                        continue
                slot_num += 1
                rc = row.copy()
                rc['Slot_Position'] = slot_num
                rc['Assigned_Slot'] = slot_num
                rc['Slot_Role'] = role_label
                rc['Marketing_Copy'] = DWASH_MARKETING_COPY.get(role_label, "Ιδανική επιλογή!")
                rc['Item_Rank'] = round_idx
                all_recs.append(rc)
                used_materials.add(row['Material'])
                taken_this_pass += 1
                pool_taken[rank] += 1
                if apply_brand_diversity:
                    pool_brand_counts[rank][row_brand] = pool_brand_counts[rank].get(row_brand, 0) + 1
                progress = True
                if slot_num not in slot_notes:
                    slot_notes[slot_num] = []
                type_hint = f" | type={row.get('_dw_type', '')}" if '_dw_type' in row.index else ""
                slot_notes[slot_num].append(
                    f"Round {round_idx} | Pool '{role_label}' | "
                    f"Score: {float(row.get('Final_Score', 0)):,.0f}{type_hint} | {str(row.get('Title', ''))[:70]}"
                )
            pool_cursors[rank] = cursor

        if not progress:
            if not diversity_relaxed and slot_num < DWASH_SLOT_TARGET:
                diversity_relaxed = True
                pool_cursors = {rank: 0 for rank in pools}
                diag.append(("Loop", round_idx, "Diversity caps relaxed — backfilling remaining slots (hard gates unchanged)"))
                continue
            diag.append(("Loop", round_idx, "All pools exhausted or capped — stopping"))
            break

    pool_diag_notes = []
    for rank, (role_label, scored, logic_key, max_r1, max_total, notes) in pools.items():
        pool_diag_notes.extend(notes)
        cap_note = f" (capped at {max_total})" if max_total is not None else ""
        pool_diag_notes.append(f"  → consumed {pool_taken[rank]} / {len(scored) if scored is not None else 0} from this pool{cap_note}")
        pool_diag_notes.append("")
    slot_notes[0] = pool_diag_notes
    diag.append(("TOTAL", len(all_recs), f"Filled {slot_num}/{DWASH_SLOT_TARGET} slots in {round_idx} rounds"))

    if all_recs:
        recs_df = pd.DataFrame(all_recs)
        recs_df['Draft_Score'] = recs_df['Assigned_Slot']
        return recs_df, diag, slot_notes, recs_df
    return pd.DataFrame(), diag, slot_notes, pd.DataFrame()


